import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.round_num = 0
        self.gen_num = 0
        # Reputation tracking: dict of agent_id -> [coop_count, defect_count]
        self.reputation = {}
        # Track my own action history
        self.my_actions = []
        # Track opponent actions for all agents
        self.opponent_actions = {}
        # Track cooperation rates for each opponent (smoothed)
        self.coop_rates = {}
        # Track forgiveness and trust levels
        self.trust = {}
        # Track recent interactions for pattern detection
        self.interaction_history = {}
        # Track my own cooperation rate
        self.my_coop_rate = 0.5
        # Track overall environment cooperation
        self.env_coop_rate = 0.5
        # Track cooperation after defection (forgiveness)
        self.forgiveness = 0.3
        # Track retaliation threshold
        self.retaliation_threshold = 0.3
        # Track reputation threshold for cooperation
        self.reputation_threshold = 0.4
        # Track whether I am currently in a "nice" or "tough" mode
        self.mode = 'nice'
        # Track last few interactions with each opponent
        self.last_interactions = {}
        # Track total observations
        self.obs_count = 0
        # Track defection frequency in environment
        self.defection_count = 0
        self.total_obs = 0

    def decide(self) -> bool:
        # Determine opponent's reputation
        opp_id = self._ctx_opponent_id
        if opp_id is None:
            return True
        self.opponent_id = opp_id

        # Get opponent's reputation
        opp_rep = self.reputation.get(opp_id, [0, 0])
        coop_count, defect_count = opp_rep
        total = coop_count + defect_count
        if total > 0:
            opp_coop_rate = coop_count / total
        else:
            # No prior info: assume average
            opp_coop_rate = self.env_coop_rate

        # Get my trust level for this opponent
        trust = self.trust.get(opp_id, 0.5)

        # Get my recent interaction pattern with this opponent
        recent = self.last_interactions.get(opp_id, [])
        if len(recent) >= 3:
            # Check if opponent defected recently
            recent_defections = sum(1 for a in recent[-3:] if a == 'defect')
            recent_coops = sum(1 for a in recent[-3:] if a == 'cooperate')
        else:
            recent_defections = 0
            recent_coops = 0

        # Adjust cooperation probability based on reputation, trust, and recent behavior
        base_prob = 0.5
        # Reputation influence
        reputation_influence = (opp_coop_rate - 0.5) * 0.4
        # Trust influence
        trust_influence = (trust - 0.5) * 0.3
        # Recent behavior influence
        recent_influence = 0
        if len(recent) >= 3:
            recent_rate = recent_coops / len(recent)
            recent_influence = (recent_rate - 0.5) * 0.3

        # Mode adjustments
        if self.mode == 'nice':
            base_prob += 0.1
        elif self.mode == 'tough':
            base_prob -= 0.1

        # Environmental influence
        env_influence = (self.env_coop_rate - 0.5) * 0.2

        coop_prob = base_prob + reputation_influence + trust_influence + recent_influence + env_influence

        # Clamp between 0.1 and 0.9 to avoid extremes
        coop_prob = max(0.1, min(0.9, coop_prob))

        # Decision with slight randomness to break ties
        if random.random() < coop_prob:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.obs_count += 1
        self.total_obs += 1

        # Update reputation for donor
        if donor_id not in self.reputation:
            self.reputation[donor_id] = [0, 0]
        if donor_action == 'cooperate':
            self.reputation[donor_id][0] += 1
        else:
            self.reputation[donor_id][1] += 1

        # Update reputation for recipient
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = [0, 0]
        if recipient_action == 'cooperate':
            self.reputation[recipient_id][0] += 1
        else:
            self.reputation[recipient_id][1] += 1

        # Update environment cooperation rate
        total_actions = 2
        coop_actions = (1 if donor_action == 'cooperate' else 0) + (1 if recipient_action == 'cooperate' else 0)
        self.env_coop_rate = 0.95 * self.env_coop_rate + 0.05 * (coop_actions / total_actions)

        # Update defection count
        if donor_action == 'defect':
            self.defection_count += 1
        if recipient_action == 'defect':
            self.defection_count += 1

        # If I was involved, update my trust and interaction history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action

            # Update my own action history
            self.my_actions.append(my_action)
            if len(self.my_actions) > 30:
                self.my_actions.pop(0)
            # Update my coop rate
            if self.my_actions:
                self.my_coop_rate = sum(1 for a in self.my_actions if a == 'cooperate') / len(self.my_actions)

            # Update trust based on other's action
            if other_action == 'cooperate':
                self.trust[other_id] = min(1.0, self.trust.get(other_id, 0.5) + 0.1)
            else:
                self.trust[other_id] = max(0.0, self.trust.get(other_id, 0.5) - 0.15)

            # Update last interactions
            if other_id not in self.last_interactions:
                self.last_interactions[other_id] = []
            self.last_interactions[other_id].append(other_action)
            if len(self.last_interactions[other_id]) > 10:
                self.last_interactions[other_id].pop(0)

            # Adapt mode based on recent interactions
            if other_id in self.last_interactions:
                recent = self.last_interactions[other_id][-5:]
                if len(recent) >= 5:
                    defect_rate = sum(1 for a in recent if a == 'defect') / len(recent)
                    if defect_rate > 0.6:
                        self.mode = 'tough'
                    elif defect_rate < 0.3:
                        self.mode = 'nice'
                    else:
                        # Stay in current mode unless extreme
                        pass
        else:
            # Third-party observation: update opponent actions tracking
            if donor_id not in self.opponent_actions:
                self.opponent_actions[donor_id] = []
            self.opponent_actions[donor_id].append(donor_action)
            if len(self.opponent_actions[donor_id]) > 30:
                self.opponent_actions[donor_id].pop(0)

            if recipient_id not in self.opponent_actions:
                self.opponent_actions[recipient_id] = []
            self.opponent_actions[recipient_id].append(recipient_action)
            if len(self.opponent_actions[recipient_id]) > 30:
                self.opponent_actions[recipient_id].pop(0)

            # Update cooperation rates for these agents
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.coop_rates:
                    self.coop_rates[agent_id] = 0.5
                if action == 'cooperate':
                    self.coop_rates[agent_id] = 0.95 * self.coop_rates[agent_id] + 0.05 * 1.0
                else:
                    self.coop_rates[agent_id] = 0.95 * self.coop_rates[agent_id] + 0.05 * 0.0

        # Periodically adjust reputation threshold based on overall environment
        if self.total_obs % 50 == 0:
            # If defection is high, be more forgiving
            if self.defection_count / self.total_obs > 0.5:
                self.reputation_threshold = max(0.2, self.reputation_threshold - 0.05)
            else:
                self.reputation_threshold = min(0.6, self.reputation_threshold + 0.02)
            # Reset defection count periodically
            if self.total_obs % 200 == 0:
                self.defection_count = 0

    # Helper to set opponent (called by framework before decide)
    @property
    def _ctx_opponent_id(self):
        return self.opponent_id

    @_ctx_opponent_id.setter
    def _ctx_opponent_id(self, value):
        self.opponent_id = value

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_history = []
        self.opponent_history = {}
        self.round_num = 0
        self.total_score = 0
        self.generosity = 0.7
        self.trust_threshold = 0.3
        self.cooperation_count = 0
        self.defection_count = 0
        self.partner_history = {}
        self.witnessed_actions = {}
        self.own_actions = []
        self.opponent_actions = []
        self.last_opponent_id = None
        self.last_my_action = None
        self.last_opponent_action = None
        self.coop_with_partner = {}
        self.defect_with_partner = {}
        self.partners_seen = set()

    def decide(self) -> bool:
        self.round_num += 1
        opp_id = self._ctx_opponent_id
        self.last_opponent_id = opp_id

        if opp_id not in self.reputation:
            self.reputation[opp_id] = 0.5

        # Track partner interaction history
        if opp_id not in self.coop_with_partner:
            self.coop_with_partner[opp_id] = 0
            self.defect_with_partner[opp_id] = 0

        # Adaptive strategy based on reputation and history
        rep = self.reputation.get(opp_id, 0.5)

        # If we've interacted before, use that history
        if opp_id in self.opponent_history:
            opp_actions = self.opponent_history[opp_id]
            if len(opp_actions) > 0:
                coop_rate = opp_actions.count('cooperate') / len(opp_actions)
                # Tit-for-tat with forgiveness based on reputation
                if coop_rate >= 0.5:
                    # Cooperate if they've been mostly cooperative
                    decision = True
                else:
                    # Defect if they've been mostly defecting
                    decision = False
            else:
                decision = rep >= self.trust_threshold
        else:
            # First encounter: cooperate with probability based on reputation
            decision = rep >= self.trust_threshold

        # Add some randomness to avoid being exploited
        if decision and random.random() < 0.05:
            decision = False

        self.last_my_action = decision
        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation based on observed actions
        if donor_id == self.agent_id:
            # Self observation
            self.own_actions.append(donor_action)
            self.last_my_action = donor_action == 'cooperate'
            if donor_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
        else:
            # Update reputation of donor based on their action
            if donor_id not in self.reputation:
                self.reputation[donor_id] = 0.5
            if donor_action == 'cooperate':
                self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.1)
            else:
                self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.1)

        if recipient_id == self.agent_id:
            # Self as recipient
            self.own_actions.append(recipient_action)
            if recipient_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
        else:
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = 0.5
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.1)
            else:
                self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.1)

        # Track interactions with specific partners
        if donor_id == self.agent_id and recipient_id != self.agent_id:
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = []
            self.opponent_history[recipient_id].append(recipient_action)
            if recipient_action == 'cooperate':
                self.coop_with_partner[recipient_id] += 1
            else:
                self.defect_with_partner[recipient_id] += 1
            self.partners_seen.add(recipient_id)

        if recipient_id == self.agent_id and donor_id != self.agent_id:
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_action)
            if donor_action == 'cooperate':
                self.coop_with_partner[donor_id] += 1
            else:
                self.defect_with_partner[donor_id] += 1
            self.partners_seen.add(donor_id)

        # Record witnessed third-party actions for possible future use
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            key = (donor_id, recipient_id)
            if key not in self.witnessed_actions:
                self.witnessed_actions[key] = []
            self.witnessed_actions[key].append((donor_action, recipient_action))

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation scores for all agents, initialized to neutral (0)
        self.reputation = {}
        # Track cooperation history: for each agent, count of cooperative and total interactions observed
        self.coop_count = {}
        self.total_count = {}
        # Track interactions with each specific opponent: (coop, defect) counts
        self.opponent_stats = {}
        # Track recent actions for pattern detection (last 10 rounds per opponent)
        self.my_actions = []
        self.opponent_actions = []
        # Parameters
        self.epsilon = 0.05  # exploration rate
        self.forgiveness = 0.1  # forgiveness for past defections
        self.retaliation_threshold = 0.3  # fraction of defections to trigger retaliation
        self.trust_threshold = 0.6  # reputation threshold to cooperate with strangers

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.0
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        self.reputation[agent_id] = self._get_reputation(agent_id) + delta

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If no reputation data, cooperate initially with a slight bias
        if opponent not in self.reputation:
            # Cooperate with high probability if we haven't interacted much
            if opponent not in self.total_count or self.total_count[opponent] < 3:
                return random.random() > self.epsilon
            else:
                # For known but no reputation, use default threshold
                return random.random() > self.epsilon

        # Analyze opponent's history
        opp_rep = self._get_reputation(opponent)
        opp_coop_rate = self._get_coop_rate(opponent)

        # Check for specific opponent stats
        opp_stats = self.opponent_stats.get(opponent, (0, 0))
        coop_vs_opp, defect_vs_opp = opp_stats
        total_interactions = coop_vs_opp + defect_vs_opp

        # If we have interacted with this opponent before, use direct experience
        if total_interactions > 0:
            opp_defect_rate = defect_vs_opp / total_interactions
            # Tit-for-tat with forgiveness: if opponent defected recently, retaliate
            if self.opponent_actions and self.opponent_actions[-1] == 'defect':
                # But sometimes forgive
                if random.random() < self.forgiveness:
                    return True
                else:
                    return False
            # If opponent has high defection rate, defect
            if opp_defect_rate > self.retaliation_threshold:
                return False
            # Otherwise cooperate
            return True
        else:
            # No direct interaction, use reputation
            if opp_rep > self.trust_threshold:
                return True
            elif opp_rep < -self.trust_threshold:
                return False
            else:
                # Uncertain, cooperate with probability based on reputation
                prob = 0.5 + opp_rep / 2
                return random.random() < prob

    def _get_coop_rate(self, agent_id: int) -> float:
        total = self.total_count.get(agent_id, 0)
        if total == 0:
            return 0.5
        return self.coop_count.get(agent_id, 0) / total

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts for donor
        self.total_count[donor_id] = self.total_count.get(donor_id, 0) + 1
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
            # Positive reputation for cooperation
            self._update_reputation(donor_id, 0.1)
        else:
            # Negative reputation for defection
            self._update_reputation(donor_id, -0.1)

        # Update counts for recipient (if recipient is not the same)
        if recipient_id != donor_id:
            self.total_count[recipient_id] = self.total_count.get(recipient_id, 0) + 1
            if recipient_action == 'cooperate':
                self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
                self._update_reputation(recipient_id, 0.1)
            else:
                self._update_reputation(recipient_id, -0.1)

        # If we are involved, update opponent-specific stats and action history
        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            # Track opponent's action
            self.opponent_actions.append(recipient_action)
            opp_id = recipient_id
            stats = self.opponent_stats.get(opp_id, [0, 0])
            if donor_action == 'cooperate':
                stats[0] += 1
            else:
                stats[1] += 1
            self.opponent_stats[opp_id] = stats
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_action)
            self.opponent_actions.append(donor_action)
            opp_id = donor_id
            stats = self.opponent_stats.get(opp_id, [0, 0])
            if recipient_action == 'cooperate':
                stats[0] += 1
            else:
                stats[1] += 1
            self.opponent_stats[opp_id] = stats

        # Limit history length to avoid memory growth
        if len(self.my_actions) > 100:
            self.my_actions = self.my_actions[-100:]
            self.opponent_actions = self.opponent_actions[-100:]

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = 0.5
        self.memory = {}
        self.opponent_history = {}
        self.cooperation_count = 0
        self.defection_count = 0
        self.round_num = 0
        self.generation = 0
        self.trust_threshold = 0.3
        self.alpha = 0.1
        self.beta = 0.2
        self.gamma = 0.05

    def decide(self) -> bool:
        self.round_num += 1
        opponent_id = getattr(self, "_ctx_opponent_id", None)
        if opponent_id is None:
            return True

        # Check direct history with this opponent
        history = self.opponent_history.get(opponent_id, [])
        if history:
            recent = history[-3:]
            coop_ratio = sum(1 for a in recent if a == "cooperate") / len(recent)
            if coop_ratio >= 0.5:
                return True
            else:
                return False

        # Use reputation if no direct history
        opp_rep = self.memory.get(opponent_id, 0.5)
        if opp_rep > self.trust_threshold:
            return True
        else:
            return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation based on observed actions
        if donor_id != self.agent_id:
            self._update_reputation(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_reputation(recipient_id, recipient_action)

        # If we are involved in this interaction, record direct history
        if self.agent_id in (donor_id, recipient_id):
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action

            if other_id not in self.opponent_history:
                self.opponent_history[other_id] = []
            self.opponent_history[other_id].append(other_action)

            # Update own counts
            if my_action == "cooperate":
                self.cooperation_count += 1
            else:
                self.defection_count += 1

            # Adjust trust based on interaction
            if other_action == "cooperate" and my_action == "cooperate":
                self._adjust_trust(other_id, self.alpha)
            elif other_action == "cooperate" and my_action == "defect":
                self._adjust_trust(other_id, -self.beta)
            elif other_action == "defect" and my_action == "cooperate":
                self._adjust_trust(other_id, -self.gamma)
            # mutual defection: slight decrease

        # Periodic decay to avoid permanent grudges
        if self.round_num % 30 == 0:
            self.generation += 1
            self._decay_reputations()

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.memory.get(agent_id, 0.5)
        if action == "cooperate":
            current += 0.1
        else:
            current -= 0.1
        current = max(0.0, min(1.0, current))
        self.memory[agent_id] = current

    def _adjust_trust(self, agent_id: int, delta: float) -> None:
        current = self.memory.get(agent_id, 0.5)
        current += delta
        current = max(0.0, min(1.0, current))
        self.memory[agent_id] = current

    def _decay_reputations(self) -> None:
        # Slightly decay all reputations toward 0.5 to adapt to changing behavior
        decay_factor = 0.05
        for agent in list(self.memory.keys()):
            current = self.memory[agent]
            self.memory[agent] = current + (0.5 - current) * decay_factor
        # Also decay opponent history by keeping only last 10 actions
        for opp in self.opponent_history:
            if len(self.opponent_history[opp]) > 10:
                self.opponent_history[opp] = self.opponent_history[opp][-10:]

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores: {agent_id: score}
        self.reputation = {}
        # Track cooperation/defection counts
        self.coop_count = {}
        self.defect_count = {}
        # Track interactions with each agent
        self.interactions = {}
        # Overall generation memory for adaptive threshold
        self.gen_coop_rate = []
        self.current_gen_coops = 0
        self.current_gen_actions = 0
        # Forgetting factor for reputation
        self.forget = 0.95
        # Cooperation threshold
        self.base_threshold = 0.5
        self.threshold = self.base_threshold
        # Strategy parameters
        self.self_coop_count = 0
        self.self_defect_count = 0
        # Track who we've seen recently
        self.recent_actions = {}

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # default to cooperate if no opponent
        # Get opponent's reputation
        opp_rep = self.reputation.get(opponent, 0.5)
        # Check recent interaction history
        hist = self.interactions.get(opponent, [])
        # If we have history, adjust based on last response
        if hist:
            last_my, last_opp = hist[-1]
            if last_opp == 'defect':
                # Tit-for-tat: retaliate if they defected last time
                return False
        # Otherwise, cooperate if reputation above threshold
        return opp_rep >= self.threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both parties
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                # Third-party observation
                self._update_reputation(agent_id, action)
            else:
                # Self-judgment
                if action == 'cooperate':
                    self.self_coop_count += 1
                else:
                    self.self_defect_count += 1
                # Update own reputation based on our action
                self._update_reputation(self.agent_id, action)

        # Track interaction if it involves us
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            if other not in self.interactions:
                self.interactions[other] = []
            self.interactions[other].append((my_action, other_action))
            # Keep only last 5 interactions
            if len(self.interactions[other]) > 5:
                self.interactions[other] = self.interactions[other][-5:]

        # Update generation stats for adaptive threshold
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation: count as action seen
            self.current_gen_actions += 2
            if donor_action == 'cooperate':
                self.current_gen_coops += 1
            if recipient_action == 'cooperate':
                self.current_gen_coops += 1
