        # Simple heuristic: cooperate with known cooperators, defect against known defectors
        opp = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        if opp is None:
            return True  # safety

        # Get historical data for this opponent
        coop_count = self.cooperation_history.get(opp, 0)
        def_count = self.defection_history.get(opp, 0)
        total = coop_count + def_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            # No history: use third-party reputation
            third_coop = self.third_party_cooperations.get(opp, 0)
            third_def = self.third_party_defections.get(opp, 0)
            third_total = third_coop + third_def
