        # Each entry is a tuple (my_action, their_action) where actions are bool (True for cooperate)
        self.recent_interactions = {}
        self.recent_window = 5

    def decide(self) -> bool:
        if self.opponent_id is None:
            return True
        opp = self.opponent_id
        # Use direct history
        my_coop, their_coop = self.partner_history.get(opp, (0,0))
        total_direct = my_coop + their_coop
        if total_direct > 0:
            their_coop_rate = their_coop / total_direct
            # Use recent interactions if available
            recent = self.recent_interactions.get(opp, deque())
            if len(recent) > 0:
                # Check if they have been consistently cooperative in the recent window
                recent_their_coop = sum(1 for _, their in recent if their)
                recent_rate = recent_their_coop / len(recent)
                # Combine long-term and recent rates
                combined_rate = 0.5 * their_coop_rate + 0.5 * recent_rate
                # If recent rate is low, defect more aggressively
                if recent_rate < 0.4:
                    return False
                elif combined_rate >= 0.6:
                    return True
                elif combined_rate >= 0.3:
                    # Tit-for-tat: match their last action if we have it
                    if opp in self.their_last_actions and self.their_last_actions[opp]:
                        return self.their_last_actions[opp][-1]
                    else:
                        return True
                else:
                    return False
            else:
                # No recent history, use long-term rate
                if their_coop_rate >= 0.6:
                    return True
                elif their_coop_rate >= 0.3:
                    if opp in self.their_last_actions and self.their_last_actions[opp]:
                        return self.their_last_actions[opp][-1]
                    else:
                        return True
                else:
                    return False
        # No direct history, use reputation
        rep = self.reputation.get(opp, 0.5)
        coop_count, defect_count = self.personal_memory.get(opp, (0,0))
        if coop_count + defect_count > 0:
            direct_rate = coop_count / (coop_count + defect_count)
            combined = 0.7 * direct_rate + 0.3 * rep
        else:
            combined = rep
        if combined >= 0.6:
            return True
        elif combined >= 0.4:
            return (self.round_num % 3) != 0
        else:
            return False

