        # Reputation tracking: for each other agent, track cooperation counts
        self.coop_counts = {}
        self.total_obs = {}
        # Track direct interactions with each agent
        self.interaction_outcomes = {}  # opponent_id -> list of (my_action, opp_action)
        self.round_num = 0
        self.my_coop_count = 0
        self.my_defect_count = 0
        self._ctx_opponent_id = None
        # Memory of recent actions for forgiveness
        self.recent_opp_coop = {}  # opponent_id -> deque of actions (True for coop)
        self.memory_size = 10
        # Global cooperation rate
        self.global_coop = 0.5
        self.global_total = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        # Get reputation of opponent
        coop_count = self.coop_counts.get(opp, 0)
        total = self.total_obs.get(opp, 0)
        reputation = coop_count / total if total > 0 else 0.5

        # Direct interaction history
        history = self.interaction_outcomes.get(opp, [])
        if not history:
            # No history: use global reputation
            if reputation > 0.6:
                return True
            elif reputation < 0.4:
                return False
            else:
                # Uncertain: cooperate initially
                return True
        else:
            # Analyze last few interactions
            recent = history[-5:]
            my_coop = sum(1 for a, b in recent if a)
            opp_coop = sum(1 for a, b in recent if b)
            if opp_coop / len(recent) > 0.5:
                # Opponent cooperates often, be cooperative
                return True
            else:
                # Opponent defects often, be more cautious
                # But use reputation to adjust
                if reputation > 0.6:
                    return True
                else:
                    return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global stats
        self.global_total += 1
        if donor_action == 'cooperate':
            self.global_coop = (self.global_coop * (self.global_total - 1) + 1) / self.global_total
        else:
            self.global_coop = (self.global_coop * (self.global_total - 1)) / self.global_total

        # Update reputation for donor
        if donor_id != self.agent_id:
            self.total_obs[donor_id] = self.total_obs.get(donor_id, 0) + 1
            if donor_action == 'cooperate':
                self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + 1

        # Update reputation for recipient
        if recipient_id != self.agent_id:
            self.total_obs[recipient_id] = self.total_obs.get(recipient_id, 0) + 1
            if recipient_action == 'cooperate':
                self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + 1

        # If this is our own interaction, record direct history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opp_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            self.interaction_outcomes.setdefault(opp_id, []).append((my_action == 'cooperate', opp_action == 'cooperate'))
            # Update own stats
            if my_action == 'cooperate':
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1
            # Update recent memory
            if opp_id not in self.recent_opp_coop:
                self.recent_opp_coop[opp_id] = []
            self.recent_opp_coop[opp_id].append(opp_action == 'cooperate')
            if len(self.recent_opp_coop[opp_id]) > self.memory_size:
                self.recent_opp_coop[opp_id].pop(0)

