        self.personal_reputation = 0.5
        self.third_party_reputation = {}
        self.rounds_played = 0
        self.partner_history = {}
        self.adaptation_rate = 0.1
        # New mechanism: adaptive threshold based on emotional memory
        self.emotional_memory = {}  # agent_id -> deque of interaction outcomes (1=positive, -1=negative)
        self.threshold_adjustment = 0.05
        self.base_trust_threshold = 0.5
        self.trust_threshold = self.base_trust_threshold

    def decide(self) -> bool:
        if self._ctx_opponent_id is not None:
            self.opponent_id = self._ctx_opponent_id
        else:
            self.opponent_id = -1

        if self.opponent_id == -1:
            return True

        trust = self._get_trust(self.opponent_id)

        # Personal history factor
        personal_factor = 0.0
        if self.opponent_id in self.personal_grudges:
            grudges = self.personal_grudges[self.opponent_id]
            favors = self.personal_favors.get(self.opponent_id, 0)
            net = favors - grudges
            personal_factor = math.tanh(net * 0.5) * 0.5

        # Third-party reputation factor
        third_party_factor = 0.0
        if self.opponent_id in self.third_party_trust:
            third_party_factor = (self.third_party_trust[self.opponent_id] - 0.5) * 0.3

        # Adaptive threshold: if recent interactions with this opponent have been negative, lower threshold
        # to be more cautious; if positive, raise threshold to be more trusting.
        if self.opponent_id in self.emotional_memory:
            recent = list(self.emotional_memory[self.opponent_id])[-10:]
            if recent:
                avg_emotion = sum(recent) / len(recent)
                # Adjust threshold: negative emotions lower threshold (more likely to defect)
                self.trust_threshold = self.base_trust_threshold - avg_emotion * self.threshold_adjustment
                # Clamp threshold
                self.trust_threshold = max(0.2, min(0.8, self.trust_threshold))

        # Combine factors, but compare against adaptive threshold
        cooperation_probability = trust - self.trust_threshold + 0.5 + personal_factor + third_party_factor
        cooperation_probability = max(0.1, min(0.9, cooperation_probability))

        seed = self.agent_id * 1000 + self.opponent_id * 10 + self.rounds_played
        rng = random.Random(seed)
        return rng.random() < cooperation_probability

