        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Simple adaptive strategy: if opponent has cooperated more than defected historically, cooperate
        opp_coop = self.opponent_coop.get(opponent, 0)
        opp_def = self.opponent_defect.get(opponent, 0)
        if opp_coop + opp_def > 0:
            return opp_coop >= opp_def
        else:
            # No history: cooperate initially but be slightly cautious
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
