            self.my_last_action = donor_action
            self.my_last_opponent = recipient_id
        if recipient_id == self.agent_id:
            self.coop_count += 1 if recipient_action == 'cooperate' else 0
            self.defect_count += 1 if recipient_action == 'defect' else 0
            # Note: if both are self, we count both actions, but that's rare

