        all_ids = set(self.opponent_coop.keys()) | set(self.opponent_defect.keys()) | set(self.third_party_coop.keys()) | set(self.third_party_defect.keys())
        all_ids.add(self.agent_id)
        for aid in all_ids:
            coop = self.opponent_coop.get(aid, 0) + self.third_party_coop.get(aid, 0)
            defec = self.opponent_defect.get(aid, 0) + self.third_party_defect.get(aid, 0)
            total = coop + defec
            if total > 0:
                self.reputation[aid] = coop / total
            else:
                self.reputation[aid] = 0.5  # neutral

        # Update trust based on recent interactions (simple version)
        # Not used heavily, but can be extended
        self.trust = self.reputation.copy()

