import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, we store
        # a score between 0 and 1, initialised to 0.5 (neutral).
        self.reputation = {}
        # Track cooperation and defection counts for each agent
        self.coop_count = {}
        self.defect_count = {}
        # Track interactions with each agent: number of times we cooperated
        # when they cooperated, etc. For conditional strategies.
        self.interaction_history = {}
        # Own recent actions for context
        self.own_recent_actions = []
        # Generational memory: simple forget factor
        self.forget_factor = 0.95

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str) -> None:
        # Simple Bayesian update: cooperate raises, defect lowers
        current = self._get_reputation(agent_id)
        if action == 'cooperate':
            new = current + (1 - current) * 0.1
        else:
            new = current - current * 0.1
        self.reputation[agent_id] = new

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both actors based on their actions
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        # Track counts
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            # Always record third-party observations
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action)
            # If we are one of the actors, record our own interaction
            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
                if len(self.own_recent_actions) > 10:
                    self.own_recent_actions.pop(0)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
                if len(self.own_recent_actions) > 10:
                    self.own_recent_actions.pop(0)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            # Get opponent's reputation
            rep = self._get_reputation(opponent)
            # Count interactions with this opponent
            total_interactions = 0
            coop_when_opp_coop = 0
            coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate' and my == 'cooperate':
                        coop_when_opp_coop += count
                    if their == 'defect' and my == 'cooperate':
                        coop_when_opp_defect += count
            # If we have interacted, use conditional probability
            if total_interactions > 0:
                # P(opp cooperates) from history
                opp_coop_count = sum(count for (opp, my, their), count in self.interaction_history.items()
                                     if opp == opponent and their == 'cooperate')
                p_opp_coop = opp_coop_count / total_interactions
                # Our cooperation rate when they cooperated
                p_my_coop_given_opp_coop = (coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
                # If they cooperated often and we cooperated back, likely cooperate
                # But also consider reputation
                # Simple strategy: cooperate if reputation > 0.5 and we have positive history
                if rep > 0.6:
                    return True
                elif rep < 0.4:
                    return False
                else:
                    # Use history to break ties
                    if total_interactions >= 3:
                        # Tit-for-tat-like: cooperate if opponent cooperated more than 50% of time
                        return p_opp_coop > 0.5
                    else:
                        # With limited history, lean on reputation
                        return rep > 0.5
            else:
                # No direct history, use reputation
                # Slightly more cooperative initially, but not naive
                return rep > 0.45
        except Exception:
            # Default to cooperate if any error
            return True

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = [0.5] * 15
        self.interactions = {}
        self.coop_count = {}
        self.total_count = {}
        self.recent_change = {}
        self.last_actions = {}
        self.generosity = 0.1
        self.adaptability = 0.2
        self._ctx_opponent_id = None
        self.round_count = 0
        self.self_reputation = 0.0
        # New: track a sliding window of overall cooperation rate
        self.recent_coop_rates = []
        self.window_size = 5

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        opp_rep = self.reputation[opp] if opp < len(self.reputation) else 0.5

        # Base threshold with generosity
        threshold = 0.5 - self.generosity

        # Adjust based on interaction history (same as parent)
        if opp in self.interactions:
            history = self.interactions[opp]
            if len(history) >= 2:
                if all(a == 'defect' for (my_a, opp_a) in history[-2:]):
                    threshold += 0.2
                elif all(a == 'cooperate' for (my_a, opp_a) in history[-2:]):
                    threshold -= 0.1

        # New mechanism: if recent cooperation rate is declining, be more cautious
        if self.recent_coop_rates:
            recent_avg = sum(self.recent_coop_rates) / len(self.recent_coop_rates)
            if recent_avg < 0.4:
                threshold += 0.1  # more selective when environment is harsh

        # Probabilistic exploration
        if random.random() < 0.02:
            return random.random() < 0.5

        return opp_rep > threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round_count += 1

        max_id = max(donor_id, recipient_id)
        if max_id >= len(self.reputation):
            self.reputation.extend([0.5] * (max_id + 1 - len(self.reputation)))
        if max_id >= len(self.recent_change):
            self.recent_change.extend([0.0] * (max_id + 1 - len(self.recent_change)))

        # Reputation updates (same as parent)
        if donor_action == 'cooperate':
            change = 0.05
        else:
            change = -0.1
        if recipient_action == 'defect' and donor_action == 'cooperate':
            change -= 0.02
        self.reputation[donor_id] = max(0, min(1, self.reputation[donor_id] + change))
        self.recent_change[donor_id] = change

        if recipient_action == 'cooperate':
            change = 0.05
        else:
            change = -0.1
        if donor_action == 'defect' and recipient_action == 'cooperate':
            change -= 0.02
        self.reputation[recipient_id] = max(0, min(1, self.reputation[recipient_id] + change))
        self.recent_change[recipient_id] = change

        # Self-reputation update
        if donor_id == self.agent_id:
            self.self_reputation = 0.5 * self.self_reputation + 0.5 * (1 if donor_action == 'cooperate' else 0)
        elif recipient_id == self.agent_id:
            self.self_reputation = 0.5 * self.self_reputation + 0.5 * (1 if recipient_action == 'cooperate' else 0)

        # Update interactions if we are one of the pair
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opp = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opp = donor_id
                my_action = recipient_action
                opp_action = donor_action

            if opp not in self.interactions:
                self.interactions[opp] = []
                self.coop_count[opp] = 0
                self.total_count[opp] = 0
            self.interactions[opp].append((my_action, opp_action))
            if len(self.interactions[opp]) > 10:
                self.interactions[opp].pop(0)
            if my_action == 'cooperate':
                self.coop_count[opp] += 1
            self.total_count[opp] += 1

            # Update recent cooperation rate window (new mechanism)
            if self.total_count[opp] > 0:
                current_rate = self.coop_count[opp] / self.total_count[opp]
                self.recent_coop_rates.append(current_rate)
                if len(self.recent_coop_rates) > self.window_size:
                    self.recent_coop_rates.pop(0)

        # Adapt generosity (same as parent)
        if self.total_count:
            total_coop = sum(self.coop_count.values())
            total = sum(self.total_count.values())
            if total > 0:
                my_coop_rate = total_coop / total
                if my_coop_rate > 0.7:
                    self.generosity = max(0, self.generosity - 0.01)
                elif my_coop_rate < 0.3:
                    self.generosity = min(0.3, self.generosity + 0.01)

        # Forgive occasional defections (same as parent)
        for agent_id in range(len(self.reputation)):
            if agent_id in self.recent_change and abs(self.recent_change[agent_id]) < 0.01:
                self.reputation[agent_id] = max(0, min(1, self.reputation[agent_id] + 0.005))

