        self.reputation_decay = 0.9
        self.recent_reputation = {}
        self.recent_interactions_count = {}
        # New: memory of opponent's last 3 actions for pattern detection
        self.opponent_recent_actions = {}

    def decide(self) -> bool:
        if self.opponent_id is None:
            return True
        opp = self.opponent_id
        # Direct history
        my_coop, their_coop = self.partner_history.get(opp, (0,0))
        total_direct = my_coop + their_coop
        if total_direct > 0:
            their_coop_rate = their_coop / total_direct
            if their_coop_rate >= 0.6:
                return True
            elif their_coop_rate >= 0.3:
                if opp in self.their_last_actions and self.their_last_actions[opp]:
                    return self.their_last_actions[opp][-1]
                else:
                    return True
            else:
                return False
        # Use decayed reputation
        rep = self.recent_reputation.get(opp, 0.5)
        coop_count, defect_count = self.personal_memory.get(opp, (0,0))
        if coop_count + defect_count > 0:
            direct_rate = coop_count / (coop_count + defect_count)
            combined = 0.7 * direct_rate + 0.3 * rep
        else:
            combined = rep
        # Pattern detection: if opponent recently defected twice in a row, be more cautious
        recent = self.opponent_recent_actions.get(opp, [])
        if len(recent) >= 2 and recent[-1] == 'defect' and recent[-2] == 'defect':
            combined *= 0.8
        if combined >= 0.6:
            return True
        elif combined >= 0.4:
            return (self.round_num % 3) != 0
        else:
            return False

