        self.last_actions = {}
        self.generosity = 0.1
        self.adaptability = 0.2
        self._ctx_opponent_id = None
        self.round_count = 0
        self.self_reputation = 0.0
        # New: track a sliding window of overall cooperation rate
        self.recent_coop_rates = []
        self.window_size = 5

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        opp_rep = self.reputation[opp] if opp < len(self.reputation) else 0.5

        # Base threshold with generosity
        threshold = 0.5 - self.generosity

        # Adjust based on interaction history (same as parent)
        if opp in self.interactions:
            history = self.interactions[opp]
            if len(history) >= 2:
                if all(a == 'defect' for (my_a, opp_a) in history[-2:]):
                    threshold += 0.2
                elif all(a == 'cooperate' for (my_a, opp_a) in history[-2:]):
                    threshold -= 0.1

        # New mechanism: if recent cooperation rate is declining, be more cautious
        if self.recent_coop_rates:
            recent_avg = sum(self.recent_coop_rates) / len(self.recent_coop_rates)
            if recent_avg < 0.4:
                threshold += 0.1  # more selective when environment is harsh

        # Probabilistic exploration
        if random.random() < 0.02:
            return random.random() < 0.5

        return opp_rep > threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round_count += 1

        max_id = max(donor_id, recipient_id)
        if max_id >= len(self.reputation):
            self.reputation.extend([0.5] * (max_id + 1 - len(self.reputation)))
        if max_id >= len(self.recent_change):
            self.recent_change.extend([0.0] * (max_id + 1 - len(self.recent_change)))

