        if opp in self.interactions:
            history = self.interactions[opp]
            if len(history) >= 2:
                # Check for consistent defection
                if all(a == 'defect' for (my_a, opp_a) in history[-2:]):
                    threshold += 0.2
                # Check for consistent cooperation
                elif all(a == 'cooperate' for (my_a, opp_a) in history[-2:]):
                    threshold -= 0.1

        # Adjust threshold based on opponent's defection streak (more aggressive response)
        if opp in self.opponent_streaks:
            streak = self.opponent_streaks[opp]
            if streak >= 3:
                threshold += 0.15  # Punish long defection streaks
            elif streak <= -3:
                threshold -= 0.1  # Reward long cooperation streaks

        # Probabilistic exploration (reduced to 1%)
        if random.random() < 0.01:
            return random.random() < 0.5

        return opp_rep > threshold

    def observe(self, donor_id: int, donor_action: str,
