        for agent_id in range(len(self.reputation)):
            if agent_id in self.recent_change and abs(self.recent_change[agent_id]) < 0.01:
                # Slight boost for stability
                self.reputation[agent_id] = max(0, min(1, self.reputation[agent_id] + 0.005))

        # New mechanism: decay reputation slowly over time to avoid permanent stigma
        for i in range(len(self.reputation)):
            if i != self.agent_id:
                self.reputation[i] = max(0, min(1, self.reputation[i] * 0.999))

