                if my_coop_rate > 0.7:
                    self.generosity = max(0, self.generosity - 0.01)
                elif my_coop_rate < 0.3:
                    self.generosity = min(0.3, self.generosity + 0.01)

        # Forgive occasional defections (same as parent)
        for agent_id in range(len(self.reputation)):
            if agent_id in self.recent_change and abs(self.recent_change[agent_id]) < 0.01:
