from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = [0.5] * 15
        self.interactions = {}
        self.coop_count = {}
        self.total_count = {}
        self.recent_change = {}
        self.last_actions = {}
        self.generosity = 0.1
        self.adaptability = 0.2
        self._ctx_opponent_id = None
        self.round_count = 0
        self.self_reputation = 0.0
        # New: track a sliding window of overall cooperation rate
        self.recent_coop_rates = deque(maxlen=5)
        self.window_size = 5
        # New: track a decayed memory of opponent's recent actions
        self.opp_action_memory = {}
        self.memory_decay = 0.9
        # New: track a separate memory for when we cooperated with opponent
        self.coop_opp_memory = {}
        self.coop_memory_decay = 0.95
        # New: track a separate memory for when we defected against opponent
        self.defect_opp_memory = {}
        self.defect_memory_decay = 0.95

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        opp_rep = self.reputation[opp] if opp < len(self.reputation) else 0.5

        # Base threshold with generosity
        threshold = 0.5 - self.generosity

        # Adjust based on interaction history (same as parent)
        if opp in self.interactions:
            history = self.interactions[opp]
            if len(history) >= 2:
                if all(a == 'defect' for (my_a, opp_a) in history[-2:]):
                    threshold += 0.2
                elif all(a == 'cooperate' for (my_a, opp_a) in history[-2:]):
                    threshold -= 0.1

        # New mechanism: if recent cooperation rate is declining, be more cautious
        if self.recent_coop_rates:
            recent_avg = sum(self.recent_coop_rates) / len(self.recent_coop_rates)
            if recent_avg < 0.4:
                threshold += 0.1  # more selective when environment is harsh

        # New mechanism: adjust threshold based on decayed memory of opponent's actions
        if opp in self.opp_action_memory:
            memory = self.opp_action_memory[opp]
            if memory is not None:
                if memory < 0.5:
                    threshold += 0.15
                elif memory > 0.7:
                    threshold -= 0.1

        # New mechanism: asymmetric memory based on our previous action
        # If we cooperated with this opponent before, we are more trusting
        # If we defected against them before, we are less trusting
        if opp in self.coop_opp_memory:
            coop_memory = self.coop_opp_memory[opp]
            if coop_memory > 0.6:
                threshold -= 0.15  # more generous if they cooperated when we cooperated
            elif coop_memory < 0.3:
                threshold += 0.1
        if opp in self.defect_opp_memory:
            defect_memory = self.defect_opp_memory[opp]
            if defect_memory > 0.6:
                threshold += 0.15  # less trusting if they defected when we defected
            elif defect_memory < 0.3:
                threshold -= 0.1

        # Probabilistic exploration
        if random.random() < 0.02:
            return random.random() < 0.5

        return opp_rep > threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round_count += 1

        max_id = max(donor_id, recipient_id)
        if max_id >= len(self.reputation):
            self.reputation.extend([0.5] * (max_id + 1 - len(self.reputation)))
        if max_id >= len(self.recent_change):
            self.recent_change.extend([0.0] * (max_id + 1 - len(self.recent_change)))

        # Reputation updates (same as parent)
        if donor_action == 'cooperate':
            change = 0.05
        else:
            change = -0.1
        if recipient_action == 'defect' and donor_action == 'cooperate':
            change -= 0.02
        self.reputation[donor_id] = max(0, min(1, self.reputation[donor_id] + change))
        self.recent_change[donor_id] = change

        if recipient_action == 'cooperate':
            change = 0.05
        else:
            change = -0.1
        if donor_action == 'defect' and recipient_action == 'cooperate':
            change -= 0.02
        self.reputation[recipient_id] = max(0, min(1, self.reputation[recipient_id] + change))
        self.recent_change[recipient_id] = change

        # Self-reputation update
        if donor_id == self.agent_id:
            self.self_reputation = 0.5 * self.self_reputation + 0.5 * (1 if donor_action == 'cooperate' else 0)
        elif recipient_id == self.agent_id:
            self.self_reputation = 0.5 * self.self_reputation + 0.5 * (1 if recipient_action == 'cooperate' else 0)

        # Update interactions if we are one of the pair
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opp = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opp = donor_id
                my_action = recipient_action
                opp_action = donor_action

            if opp not in self.interactions:
                self.interactions[opp] = []
                self.coop_count[opp] = 0
                self.total_count[opp] = 0
                self.opp_action_memory[opp] = 0.5  # initialize memory at neutral
                self.coop_opp_memory[opp] = 0.5
                self.defect_opp_memory[opp] = 0.5
            self.interactions[opp].append((my_action, opp_action))
            if len(self.interactions[opp]) > 10:
                self.interactions[opp].pop(0)
            if my_action == 'cooperate':
                self.coop_count[opp] += 1
            self.total_count[opp] += 1

            # Update decayed memory of opponent's actions
            opp_cooperated = 1 if opp_action == 'cooperate' else 0
            old_memory = self.opp_action_memory.get(opp, 0.5)
            self.opp_action_memory[opp] = self.memory_decay * old_memory + (1 - self.memory_decay) * opp_cooperated

            # Update asymmetric memories
            if my_action == 'cooperate':
                # When we cooperate, update coop memory
                old_coop_memory = self.coop_opp_memory.get(opp, 0.5)
                self.coop_opp_memory[opp] = self.coop_memory_decay * old_coop_memory + (1 - self.coop_memory_decay) * opp_cooperated
            else:
                # When we defect, update defect memory
                old_defect_memory = self.defect_opp_memory.get(opp, 0.5)
                self.defect_opp_memory[opp] = self.defect_memory_decay * old_defect_memory + (1 - self.defect_memory_decay) * opp_cooperated

            # Update recent cooperation rate window (new mechanism)
            if self.total_count[opp] > 0:
                current_rate = self.coop_count[opp] / self.total_count[opp]
                self.recent_coop_rates.append(current_rate)

        # Adapt generosity (same as parent)
        if self.total_count:
            total_coop = sum(self.coop_count.values())
            total = sum(self.total_count.values())
            if total > 0:
                my_coop_rate = total_coop / total
                if my_coop_rate > 0.7:
                    self.generosity = max(0, self.generosity - 0.01)
                elif my_coop_rate < 0.3:
                    self.generosity = min(0.3, self.generosity + 0.01)

        # Forgive occasional defections (same as parent)
        for agent_id in range(len(self.reputation)):
            if agent_id in self.recent_change and abs(self.recent_change[agent_id]) < 0.01:
                self.reputation[agent_id] = max(0, min(1, self.reputation[agent_id] + 0.005))

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        self.forget_factor = 0.95
        self.suspicion = {}
        self.round_count = 0
        # New: track direct interaction outcomes for each opponent
        self.direct_outcomes = {}
        # New: track recent observations for decay
        self.recent_observations = deque(maxlen=20)

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _get_suspicion(self, agent_id: int) -> float:
        if agent_id not in self.suspicion:
            self.suspicion[agent_id] = 0.0
        return self.suspicion[agent_id]

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self._get_reputation(agent_id)
        if action == 'cooperate':
            new = current + (1 - current) * 0.15  # Increased learning rate
        else:
            new = current - current * 0.05  # Decreased penalty
        self.reputation[agent_id] = new

    def _update_suspicion(self, agent_id: int, action: str) -> None:
        current = self._get_suspicion(agent_id)
        if action == 'defect':
            new = min(1.0, current + 0.2)  # More sensitive to defection
        else:
            new = max(0.0, current - 0.02)  # Slower forgiveness
        self.suspicion[agent_id] = new

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self._update_suspicion(donor_id, donor_action)
            self._update_suspicion(recipient_id, recipient_action)
            # Store recent observations for decay
            self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1
        # Track direct outcomes
        if opponent_id not in self.direct_outcomes:
            self.direct_outcomes[opponent_id] = {'coop': 0, 'defect': 0}
        if opp_action == 'cooperate':
            self.direct_outcomes[opponent_id]['coop'] += 1
        else:
            self.direct_outcomes[opponent_id]['defect'] += 1

    def _decay_suspicion(self) -> None:
        # Decay suspicion over time to reduce permanent grudges
        decay = 0.95
        for agent_id in self.suspicion:
            self.suspicion[agent_id] *= decay

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action)
            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
            # Occasionally decay suspicion
            if self.round_count % 5 == 0:
                self._decay_suspicion()
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            self.round_count += 1
            rep = self._get_reputation(opponent)
            susp = self._get_suspicion(opponent)
            # Use direct outcomes primarily
            direct = self.direct_outcomes.get(opponent, {'coop': 0, 'defect': 0})
            total_direct = direct['coop'] + direct['defect']
            if total_direct > 0:
                coop_rate = direct['coop'] / total_direct
                # Strong tit-for-tat with forgiveness
                if coop_rate > 0.6:
                    return True
                elif coop_rate < 0.3:
                    return False
                else:
                    # Middle ground: use reputation and suspicion
                    if susp > 0.7:
                        return False
                    return rep > 0.5
            else:
                # No direct experience, use reputation and suspicion
                # More trusting early, but suspicion builds quickly
                if susp > 0.45:
                    return False
                return rep > 0.4
        except Exception:
            return True

