        self.recent_actions = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # Use reputation and trust, but add a recency bonus/penalty
        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # Get recent actions from opponent
        recent = self.recent_actions.get(opponent, deque())
        if len(recent) > 0:
            coop_fraction = sum(1 for a in recent if a == 'cooperate') / len(recent)
        else:
            coop_fraction = 0.5
        # Base score with recency weight
        score = 0.4 * opp_rep + 0.4 * trust + 0.2 * coop_fraction
        threshold = self.base_cooperation_threshold - self.forgiveness * 0.5
        return score >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both (same as parent but with slightly higher decay)
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85
        # Update cooperation counts
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        # Update recent_actions for both parties (only if not self)
        if donor_id != self.agent_id:
            if donor_id not in self.recent_actions:
                self.recent_actions[donor_id] = deque(maxlen=5)
            self.recent_actions[donor_id].append(donor_action)
        if recipient_id != self.agent_id:
            if recipient_id not in self.recent_actions:
                self.recent_actions[recipient_id] = deque(maxlen=5)
            self.recent_actions[recipient_id].append(recipient_action)
        # If we are involved, update opponent history and trust (same as parent)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            # Update trust with a more generous rule: forgive defection if we cooperated last time
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
            else:
                # If we cooperated last interaction, reduce penalty (forgiveness)
                if other in self.opponent_history and len(self.opponent_history[other]) >= 2:
                    prev_other, prev_my = self.opponent_history[other][-2]
                    if prev_my == 'cooperate' and prev_other == 'defect':
                        self.trust[other] = self.trust.get(other, 0.5) * 0.95
                    else:
