        # Reputation scores for all agents, initialized to 0.5 neutral
        self.reputation = [0.5] * 15  # assuming 15 agents, but will adjust dynamically
        # Track interactions: dict mapping opponent_id to list of (my_action, opponent_action)
        self.interactions = {}
        # Track cooperation counts and total interactions per opponent
        self.coop_count = {}
        self.total_count = {}
