        self.round_count = 0
        # Self reputation bias
        self.self_reputation = 0.0
        # Trust decay factor (new)
        self.trust_decay = 0.95
        # NEW: Variance tracking for reputation instability
        self.rep_variance = [0.0] * 15
        # NEW: Exaggerated response to reputation changes
        self.sensitivity = 0.15
        # NEW: Recency-weighted reputation memory (exploration: use a deque for reputation history)
        self.rep_history = {i: deque(maxlen=10) for i in range(15)}
        for i in range(15):
            self.rep_history[i].append(0.5)

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        # Get opponent's reputation - use a weighted average of history (more recent weight)
        if opp in self.rep_history and len(self.rep_history[opp]) > 0:
            hist = list(self.rep_history[opp])
            # Weight recent entries more (exponential decay)
            weights = [0.8 ** (len(hist) - 1 - i) for i in range(len(hist))]
            total_w = sum(weights)
            opp_rep = sum(w * r for w, r in zip(weights, hist)) / total_w
        else:
            opp_rep = 0.5

        # Base decision: cooperate if opponent reputation is high enough
        threshold = 0.5 - self.generosity

        # NEW: Adjust threshold based on reputation variance (instability)
        if opp < len(self.rep_variance):
            variance = self.rep_variance[opp]
            if variance > 0.02:
                threshold += 0.1  # Be more cautious with unstable agents
            elif variance < 0.005:
                threshold -= 0.05  # Trust stable agents more

        # Adjust threshold based on past interactions
        if opp in self.interactions:
