            if len(history) >= 2:
                # Check for consistent defection
                if all(a == 'defect' for (my_a, opp_a) in history[-2:]):
                    threshold += 0.25
                # Check for consistent cooperation
                elif all(a == 'cooperate' for (my_a, opp_a) in history[-2:]):
                    threshold -= 0.15

        # Probabilistic exploration (reduced)
        if random.random() < 0.02:
            return random.random() < 0.5

        # If we have a high self-reputation, be more trusting
        if self.self_reputation > 0.6:
            threshold -= 0.1

        return opp_rep > threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update round count
        self.round_count += 1

        # Ensure reputation list size
        max_id = max(donor_id, recipient_id)
        if max_id >= len(self.reputation):
            self.reputation.extend([0.5] * (max_id + 1 - len(self.reputation)))
            self.rep_variance.extend([0.0] * (max_id + 1 - len(self.rep_variance)))
        if max_id >= len(self.recent_change):
            self.recent_change.extend([0.0] * (max_id + 1 - len(self.recent_change)))
        if max_id >= len(self.rep_history):
            for i in range(len(self.rep_history), max_id + 1):
                self.rep_history[i] = deque(maxlen=10)
                self.rep_history[i].append(0.5)

        # Decay reputation slightly (new mechanism)
        for i in range(len(self.reputation)):
            self.reputation[i] = max(0, min(1, self.reputation[i] * self.trust_decay + (1 - self.trust_decay) * 0.5))

        # Update reputation for donor
        if donor_action == 'cooperate':
            change = 0.08
        else:
            change = -0.12
        # Recipient action affects donor reputation too (if recipient defects, donor might be exploited)
        if recipient_action == 'defect' and donor_action == 'cooperate':
            change -= 0.03
        self.reputation[donor_id] = max(0, min(1, self.reputation[donor_id] + change))
        self.recent_change[donor_id] = change

        # Update reputation for recipient
        if recipient_action == 'cooperate':
            change = 0.08
        else:
            change = -0.12
        if donor_action == 'defect' and recipient_action == 'cooperate':
            change -= 0.03
        self.reputation[recipient_id] = max(0, min(1, self.reputation[recipient_id] + change))
        self.recent_change[recipient_id] = change

        # NEW: Update variance tracking based on recent changes
        for agent in [donor_id, recipient_id]:
            if agent < len(self.rep_variance):
                # Exponentially weighted moving average of absolute change
                prev = self.rep_variance[agent]
                self.rep_variance[agent] = 0.7 * prev + 0.3 * abs(self.recent_change[agent])

        # NEW: Update reputation history with current reputation
        for agent in [donor_id, recipient_id]:
            if agent < len(self.rep_history):
                self.rep_history[agent].append(self.reputation[agent])

        # If this is about self, update self-reputation bias
        if donor_id == self.agent_id:
            self.self_reputation = 0.5 * self.self_reputation + 0.5 * (1 if donor_action == 'cooperate' else 0)
        elif recipient_id == self.agent_id:
            self.self_reputation = 0.5 * self.self_reputation + 0.5 * (1 if recipient_action == 'cooperate' else 0)

        # Update interactions if we are one of the pair
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opp = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opp = donor_id
                my_action = recipient_action
                opp_action = donor_action

            if opp not in self.interactions:
                self.interactions[opp] = deque(maxlen=8)  # shorter memory
                self.coop_count[opp] = 0
                self.total_count[opp] = 0
            self.interactions[opp].append((my_action, opp_action))
            if my_action == 'cooperate':
                self.coop_count[opp] += 1
            self.total_count[opp] += 1

        # Adapt generosity based on how often we cooperate vs others
        if self.total_count:
            total_coop = sum(self.coop_count.values())
            total = sum(self.total_count.values())
            if total > 0:
                my_coop_rate = total_coop / total
                # If I'm too cooperative, reduce generosity; if too selfish, increase a bit
                if my_coop_rate > 0.6:
                    self.generosity = max(0, self.generosity - 0.02)
                elif my_coop_rate < 0.4:
                    self.generosity = min(0.4, self.generosity + 0.02)

        # Forgive occasional defections: if an opponent's recent change is positive, boost their reputation
        for agent_id in range(len(self.reputation)):
            if agent_id in self.recent_change and abs(self.recent_change[agent_id]) < 0.01:
                # Slight boost for stability
                self.reputation[agent_id] = max(0, min(1, self.reputation[agent_id] + 0.01))

        # NEW: Apply sensitivity to recent changes (amplify effects)
        for agent_id in range(len(self.reputation)):
            if agent_id in self.recent_change:
                # If change is positive, boost reputation slightly; if negative, reduce more
                if self.recent_change[agent_id] > 0:
                    self.reputation[agent_id] = max(0, min(1, self.reputation[agent_id] + self.sensitivity * self.recent_change[agent_id]))
                else:
                    self.reputation[agent_id] = max(0, min(1, self.reputation[agent_id] + self.sensitivity * self.recent_change[agent_id] * 1.5))

        # NEW: Update reputation history again after all modifications to reflect final values
        for agent in [donor_id, recipient_id]:
            if agent < len(self.rep_history):
                self.rep_history[agent].append(self.reputation[agent])

import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.my_history = {}
        self.recent_actions = deque(maxlen=20)
        self.coop_threshold = 0.5
        self.default_coop = 0.5
        self.total_observations = 0
        self.opponent_recent = {}
        self.my_total_coops = 0
        self.my_total_actions = 0
        # New mechanism: track a short-term "trust momentum" per opponent,
        # which biases the decision toward the most recent trend.
        self.trust_momentum = {}
        self.momentum_decay = 0.9

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            return self.default_coop
        # Use a weighted recent-priority reputation with exponential decay
        coops, defects, total_weight = self.reputation[agent_id]
        if total_weight == 0:
            return self.default_coop
        return coops / total_weight

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        opp_rep = self._get_reputation(opponent)

        # Incorporate trust momentum: if opponent has been increasingly cooperative,
        # boost the reputation; if increasingly defecting, reduce it.
        momentum = self.trust_momentum.get(opponent, 0.0)
        # Scale momentum to a small adjustment, clipped to avoid extreme swings
        momentum_adjust = max(-0.3, min(0.3, momentum * 0.2))
        opp_rep = max(0.0, min(1.0, opp_rep + momentum_adjust))

        recent = self.opponent_recent.get(opponent, [])
        if recent:
            recent_rep = sum(1 for a in recent if a == "cooperate") / len(recent)
            # Weight recent more when momentum is strong (trend is informative)
            recent_weight = 0.4 + 0.3 * abs(momentum)
            combined_rep = recent_weight * recent_rep + (1 - recent_weight) * opp_rep
        else:
            combined_rep = opp_rep

        hist = self.my_history.get(opponent, [])
        if hist:
            my_coop_rate = sum(hist) / len(hist) if hist else 0.5
            weight_history = min(1.0, len(hist) / 5.0)
            combined = weight_history * my_coop_rate + (1 - weight_history) * combined_rep
        else:
            combined = combined_rep

        if 0.3 < combined < 0.7:
            if self.recent_actions:
                recent_coop_rate = sum(self.recent_actions) / len(self.recent_actions)
                combined = combined * 0.7 + recent_coop_rate * 0.3
            else:
                combined = combined * 0.5 + 0.5 * 0.5

        threshold = self.coop_threshold
        r = random.random()
        if r < 0.05:
            return random.random() < 0.5
        return combined >= threshold

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_id != self.agent_id:
            self._update_rep(donor_id, donor_action)
            self._record_opponent_recent(donor_id, donor_action)
            # Update trust momentum based on the observed action
            self._update_momentum(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_rep(recipient_id, recipient_action)
            self._record_opponent_recent(recipient_id, recipient_action)
            self._update_momentum(recipient_id, recipient_action)

        if donor_id == self.agent_id:
            self._record_my_action(recipient_id, donor_action == "cooperate")
            self.my_total_actions += 1
            if donor_action == "cooperate":
                self.my_total_coops += 1
        if recipient_id == self.agent_id:
            self._record_my_action(donor_id, recipient_action == "cooperate")
            self.my_total_actions += 1
            if recipient_action == "cooperate":
                self.my_total_coops += 1

        if donor_id == self.agent_id:
            self.recent_actions.append(1 if donor_action == "cooperate" else 0)
        if recipient_id == self.agent_id:
            self.recent_actions.append(1 if recipient_action == "cooperate" else 0)

        self.total_observations += 1
        if self.total_observations % 10 == 0:
            reps = [self._get_reputation(agent) for agent in self.reputation]
            if reps:
                avg_rep = sum(reps) / len(reps)
                if self.my_total_actions > 0:
                    self_coop_rate = self.my_total_coops / self.my_total_actions
                    blended = 0.7 * avg_rep + 0.3 * self_coop_rate
                else:
                    blended = avg_rep
                self.coop_threshold = self.coop_threshold * 0.95 + blended * 0.05
                self.coop_threshold = max(0.2, min(0.8, self.coop_threshold))

    def _update_rep(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = [0.0, 0.0, 0.0]  # [coops_weighted, defects_weighted, total_weight]
        # Exponential decay factor: more recent observations weighted higher
        decay = 0.95
        coops, defects, total_weight = self.reputation[agent_id]
        coops *= decay
        defects *= decay
        total_weight *= decay
        if action == "cooperate":
            coops += 1.0
        else:
            defects += 1.0
        total_weight += 1.0
        self.reputation[agent_id] = [coops, defects, total_weight]

    def _update_momentum(self, agent_id: int, action: str) -> None:
        # Momentum tracks the short-term trend: +1 for cooperate, -1 for defect,
        # decayed over time.
        current = self.trust_momentum.get(agent_id, 0.0)
        # Decay previous momentum, then add the new signal
        current = current * self.momentum_decay + (1.0 if action == "cooperate" else -1.0)
        # Clip to a reasonable range to avoid extreme values
        self.trust_momentum[agent_id] = max(-5.0, min(5.0, current))

    def _record_my_action(self, opponent_id: int, cooperated: bool) -> None:
        if opponent_id not in self.my_history:
            self.my_history[opponent_id] = []
        self.my_history[opponent_id].append(1 if cooperated else 0)
        if len(self.my_history[opponent_id]) > 30:
            self.my_history[opponent_id] = self.my_history[opponent_id][-30:]

    def _record_opponent_recent(self, agent_id: int, action: str) -> None:
        if agent_id not in self.opponent_recent:
            self.opponent_recent[agent_id] = deque(maxlen=10)
        self.opponent_recent[agent_id].append(action)

