from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        self.forget_factor = 0.95
        self.observation_window = {}
        self.global_coop_rate = 0.5
        self.total_observations = 0
        self.total_coops_observed = 0
        self.reciprocity_estimate = {}
        # NEW: Track a running average of recent opponent cooperation to detect trends
        self.opponent_trend = {}
        self.trend_window = deque(maxlen=15)
        # NEW: Track a "forgiveness" score for each opponent, based on their recent behavior
        self.forgiveness = {}
        self.forgiveness_window = deque(maxlen=20)

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self._get_reputation(agent_id)
        if action == 'cooperate':
            new = current + (1 - current) * 0.08  # Slightly faster recovery than parent
        else:
            penalty = 0.15 if current > 0.5 else 0.25  # Less harsh penalty, but still harsher for low rep
            new = current - current * penalty
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        self.total_observations += 1
        if donor_action == 'cooperate':
            self.total_coops_observed += 1
        if recipient_action == 'cooperate':
            self.total_coops_observed += 1
        self.global_coop_rate = self.total_coops_observed / (self.total_observations * 2)

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observation_window:
                self.observation_window[agent_id] = deque(maxlen=10)
            self.observation_window[agent_id].append(action)

        for agent_id in [donor_id, recipient_id]:
            window = self.observation_window.get(agent_id, [])
            if len(window) >= 5:
                coop_rate = window.count('cooperate') / len(window)
                self.reciprocity_estimate[agent_id] = coop_rate

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1
        # Track opponent trend: 1 for cooperate, 0 for defect
        self.trend_window.append(1 if opp_action == 'cooperate' else 0)
        # NEW: Update forgiveness score for this opponent
        if opp_action == 'cooperate':
            # Increase forgiveness (be more willing to cooperate after a defection)
            self.forgiveness[opponent_id] = self.forgiveness.get(opponent_id, 0.5) + 0.1
        else:
            # Decrease forgiveness (be less willing to cooperate after a defection)
            self.forgiveness[opponent_id] = self.forgiveness.get(opponent_id, 0.5) - 0.15
        # Clamp to [0, 1]
        self.forgiveness[opponent_id] = max(0.0, min(1.0, self.forgiveness[opponent_id]))
        # Add to forgiveness window for overall trend
        self.forgiveness_window.append(self.forgiveness[opponent_id])

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action)
            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            reciprocity = self.reciprocity_estimate.get(opponent, 0.5)

            total_interactions = 0
            opp_coop_count = 0
            my_coop_when_opp_coop = 0
            my_coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate':
                        opp_coop_count += count
                        if my == 'cooperate':
                            my_coop_when_opp_coop += count
                    else:
                        if my == 'cooperate':
                            my_coop_when_opp_defect += count

            p_opp_coop = opp_coop_count / total_interactions if total_interactions > 0 else 0.5
            p_my_coop_given_opp_coop = (my_coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
            p_my_coop_given_opp_defect = (my_coop_when_opp_defect / (total_interactions - opp_coop_count)) if (total_interactions - opp_coop_count) > 0 else 0.5

            # NEW: Use trend analysis - if opponent has been cooperating more recently, be more trusting
            trend_avg = sum(self.trend_window) / len(self.trend_window) if self.trend_window else 0.5
            trend_factor = 0.5 + (trend_avg - 0.5) * 0.3  # Amplify trend slightly

            # NEW: Use forgiveness score - if we've forgiven this opponent recently, be more lenient
            forg = self.forgiveness.get(opponent, 0.5)
            # If we've been forgiving overall, increase our threshold to avoid being exploited
            overall_forg = sum(self.forgiveness_window) / len(self.forgiveness_window) if self.forgiveness_window else 0.5
            forgiveness_factor = 0.5 + (forg - 0.5) * 0.4 - (overall_forg - 0.5) * 0.2  # Double-edged: personal forgiveness helps, but overall forgiveness makes us cautious

            # Modified threshold: less sensitive to global coop rate, more to own recent actions
            own_recent_coop = self.own_recent_actions.count('cooperate') / len(self.own_recent_actions) if self.own_recent_actions else 0.5
            adaptive_threshold = 0.5 + (1 - own_recent_coop) * 0.15  # If I've been cooperating, be slightly more lenient
            adaptive_threshold = max(0.35, min(0.75, adaptive_threshold))

            if total_interactions > 0:
                conditional_trust = p_my_coop_given_opp_coop - p_my_coop_given_opp_defect
                # Weights changed: more weight on trend and reciprocity, less on raw reputation
                # Added forgiveness factor
                combined_score = 0.2 * rep + 0.3 * reciprocity + 0.15 * p_opp_coop + 0.15 * max(0, conditional_trust) + 0.2 * trend_factor + 0.1 * forgiveness_factor
                return combined_score > adaptive_threshold
            else:
                combined_score = 0.4 * rep + 0.3 * reciprocity + 0.3 * trend_factor + 0.1 * forgiveness_factor
                return combined_score > adaptive_threshold
        except Exception:
            return True

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.generation = 0
        self.round = 0
        self.total_rounds = 30
        self.total_generations = 30
        self.cooperation_history = {}
        self.defection_history = {}
        self.third_party_observations = {}
        self.reputation = {}
        self.self_reputation = 0.5
        self.last_round_actions = {}
        self.my_last_action = None
        self.my_last_opponent = None
        self.last_opponent_action = None
        self.round_in_generation = 0
        self.personal_grudges = {}
        self.personal_favors = {}
        self.trust_scores = {}
        self.third_party_trust = {}
        self.my_defection_count = 0
        self.my_cooperation_count = 0
        self.opponent_defection_count = 0
        self.opponent_cooperation_count = 0
        self.early_generation = True
        self.generations_observed = 0
        self.recent_actions = {}
        self.retaliation_threshold = 2
        self.cooperation_bias = 0.6
        self.forgiveness = 0.1
        self.opponent_models = {}
        self.observed_interactions = {}
        self.last_observed = {}
        self.personal_reputation = 0.5
        self.third_party_reputation = {}
        self.rounds_played = 0
        self.partner_history = {}
        self.adaptation_rate = 0.1
        # New mechanism: switch from emotional memory to a "generosity" parameter
        # that decays over time and is updated by personal and observed interactions.
        self.generosity = 0.5  # baseline generosity, affects cooperation probability
        self.generosity_decay = 0.01  # decay per round
        self.generosity_update = 0.05  # update magnitude per interaction
        self.trust_threshold = 0.5  # fixed threshold, no emotional adjustment

    def decide(self) -> bool:
        if self._ctx_opponent_id is not None:
            self.opponent_id = self._ctx_opponent_id
        else:
            self.opponent_id = -1

        if self.opponent_id == -1:
            return True

        trust = self._get_trust(self.opponent_id)

        # Personal history factor
        personal_factor = 0.0
        if self.opponent_id in self.personal_grudges:
            grudges = self.personal_grudges[self.opponent_id]
            favors = self.personal_favors.get(self.opponent_id, 0)
            net = favors - grudges
            personal_factor = math.tanh(net * 0.5) * 0.5

        # Third-party reputation factor
        third_party_factor = 0.0
        if self.opponent_id in self.third_party_trust:
            third_party_factor = (self.third_party_trust[self.opponent_id] - 0.5) * 0.3

        # Combine factors with a generosity-based offset instead of adaptive threshold
        cooperation_probability = trust - self.trust_threshold + 0.5 + personal_factor + third_party_factor + self.generosity * 0.2
        cooperation_probability = max(0.1, min(0.9, cooperation_probability))

        seed = self.agent_id * 1000 + self.opponent_id * 10 + self.rounds_played
        rng = random.Random(seed)
        return rng.random() < cooperation_probability

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.rounds_played += 1
        self.round_in_generation += 1
        if self.round_in_generation >= self.total_rounds:
            self.round_in_generation = 0
            self.generation += 1

        self.observed_interactions[(donor_id, recipient_id)] = self.observed_interactions.get((donor_id, recipient_id), 0) + 1
        self.last_observed[(donor_id, recipient_id)] = (donor_action, recipient_action)

        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)

        # Decay generosity slightly each round
        self.generosity = max(0.0, min(1.0, self.generosity - self.generosity_decay))

        # Update generosity based on interactions
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            self.my_last_action = my_action
            self.my_last_opponent = recipient_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
