        self.trend_window.append(1 if opp_action == 'cooperate' else 0)
        if opp_action == 'cooperate':
            self.forgiveness[opponent_id] = self.forgiveness.get(opponent_id, 0.5) + 0.1
        else:
            self.forgiveness[opponent_id] = self.forgiveness.get(opponent_id, 0.5) - 0.15
        self.forgiveness[opponent_id] = max(0.0, min(1.0, self.forgiveness[opponent_id]))
        self.forgiveness_window.append(self.forgiveness[opponent_id])

        # NEW: Update trust based on opponent's action relative to my action
        if opponent_id not in self.trust:
            self.trust[opponent_id] = 0.5
        if opp_action == 'cooperate':
            # Trust increases more if I also cooperated (mutual cooperation)
            if my_action == 'cooperate':
                self.trust[opponent_id] += 0.15
            else:
                self.trust[opponent_id] += 0.05
        else:
            # Trust decreases more if I cooperated and they defected (betrayal)
            if my_action == 'cooperate':
                self.trust[opponent_id] -= 0.25
            else:
                self.trust[opponent_id] -= 0.1
        self.trust[opponent_id] = max(0.0, min(1.0, self.trust[opponent_id]))
        self.trust_window.append(self.trust[opponent_id])

        # NEW: Track recent opponent actions for immediate response
        if opponent_id not in self.recent_opponent_actions:
            self.recent_opponent_actions[opponent_id] = deque(maxlen=5)
        self.recent_opponent_actions[opponent_id].append(opp_action)

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action)
            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            reciprocity = self.reciprocity_estimate.get(opponent, 0.5)
            trust = self.trust.get(opponent, 0.5)  # NEW: Use trust as primary factor

            total_interactions = 0
            opp_coop_count = 0
            my_coop_when_opp_coop = 0
            my_coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate':
                        opp_coop_count += count
                        if my == 'cooperate':
                            my_coop_when_opp_coop += count
                    else:
                        if my == 'cooperate':
                            my_coop_when_opp_defect += count

            p_opp_coop = opp_coop_count / total_interactions if total_interactions > 0 else 0.5
            p_my_coop_given_opp_coop = (my_coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
            p_my_coop_given_opp_defect = (my_coop_when_opp_defect / (total_interactions - opp_coop_count)) if (total_interactions - opp_coop_count) > 0 else 0.5

            trend_avg = sum(self.trend_window) / len(self.trend_window) if self.trend_window else 0.5
            trend_factor = 0.5 + (trend_avg - 0.5) * 0.3

            forg = self.forgiveness.get(opponent, 0.5)
            overall_forg = sum(self.forgiveness_window) / len(self.forgiveness_window) if self.forgiveness_window else 0.5
            forgiveness_factor = 0.5 + (forg - 0.5) * 0.4 - (overall_forg - 0.5) * 0.2

            own_recent_coop = self.own_recent_actions.count('cooperate') / len(self.own_recent_actions) if self.own_recent_actions else 0.5
            adaptive_threshold = 0.5 + (1 - own_recent_coop) * 0.15
            adaptive_threshold = max(0.35, min(0.75, adaptive_threshold))

            # NEW: Immediate response - if opponent defected in last interaction, strongly consider defecting
            recent_actions = self.recent_opponent_actions.get(opponent, [])
            immediate_response = 0.0
            if recent_actions:
                if recent_actions[-1] == 'defect':
                    immediate_response = -0.2  # Punish recent defection
                else:
                    immediate_response = 0.1  # Reward recent cooperation

            if total_interactions > 0:
                conditional_trust = p_my_coop_given_opp_coop - p_my_coop_given_opp_defect
                # NEW: Trust gets highest weight, immediate response added
                combined_score = (0.35 * trust + 0.2 * rep + 0.15 * reciprocity + 
                                0.1 * p_opp_coop + 0.1 * max(0, conditional_trust) + 
                                0.1 * trend_factor + 0.05 * forgiveness_factor + 
                                immediate_response)
                return combined_score > adaptive_threshold
            else:
                combined_score = (0.5 * trust + 0.2 * rep + 0.2 * reciprocity + 
                                0.1 * trend_factor + immediate_response)
                return combined_score > adaptive_threshold
        except Exception:
            return True

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.generation = 0
        self.round = 0
        self.total_rounds = 30
        self.total_generations = 30
        self.cooperation_history = {}
        self.defection_history = {}
        self.third_party_observations = {}
        self.reputation = {}
        self.self_reputation = 0.5
        self.last_round_actions = {}
        self.my_last_action = None
        self.my_last_opponent = None
        self.last_opponent_action = None
        self.round_in_generation = 0
        self.personal_grudges = {}
        self.personal_favors = {}
        self.trust_scores = {}
        self.third_party_trust = {}
        self.my_defection_count = 0
        self.my_cooperation_count = 0
        self.opponent_defection_count = 0
        self.opponent_cooperation_count = 0
        self.early_generation = True
        self.generations_observed = 0
        self.recent_actions = {}
        self.retaliation_threshold = 2
        self.cooperation_bias = 0.6
        self.forgiveness = 0.1
        self.opponent_models = {}
        self.observed_interactions = {}
        self.last_observed = {}
        self.personal_reputation = 0.5
        self.third_party_reputation = {}
        self.rounds_played = 0
        self.partner_history = {}
        self.adaptation_rate = 0.1
        # New mechanism: switch from emotional memory to a "generosity" parameter
        # that decays over time and is updated by personal and observed interactions.
        self.generosity = 0.5  # baseline generosity, affects cooperation probability
        self.generosity_decay = 0.01  # decay per round
        self.generosity_update = 0.05  # update magnitude per interaction
        self.trust_threshold = 0.5  # fixed threshold, no emotional adjustment

    def decide(self) -> bool:
        if self._ctx_opponent_id is not None:
            self.opponent_id = self._ctx_opponent_id
        else:
            self.opponent_id = -1

        if self.opponent_id == -1:
            return True

        trust = self._get_trust(self.opponent_id)

        # Personal history factor
        personal_factor = 0.0
        if self.opponent_id in self.personal_grudges:
            grudges = self.personal_grudges[self.opponent_id]
            favors = self.personal_favors.get(self.opponent_id, 0)
            net = favors - grudges
            personal_factor = math.tanh(net * 0.5) * 0.5

        # Third-party reputation factor
        third_party_factor = 0.0
        if self.opponent_id in self.third_party_trust:
            third_party_factor = (self.third_party_trust[self.opponent_id] - 0.5) * 0.3

        # Combine factors with a generosity-based offset instead of adaptive threshold
        cooperation_probability = trust - self.trust_threshold + 0.5 + personal_factor + third_party_factor + self.generosity * 0.2
        cooperation_probability = max(0.1, min(0.9, cooperation_probability))

        seed = self.agent_id * 1000 + self.opponent_id * 10 + self.rounds_played
        rng = random.Random(seed)
        return rng.random() < cooperation_probability

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.rounds_played += 1
        self.round_in_generation += 1
        if self.round_in_generation >= self.total_rounds:
            self.round_in_generation = 0
            self.generation += 1

        self.observed_interactions[(donor_id, recipient_id)] = self.observed_interactions.get((donor_id, recipient_id), 0) + 1
        self.last_observed[(donor_id, recipient_id)] = (donor_action, recipient_action)

        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)

        # Decay generosity slightly each round
        self.generosity = max(0.0, min(1.0, self.generosity - self.generosity_decay))

        # Update generosity based on interactions
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            self.my_last_action = my_action
            self.my_last_opponent = recipient_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
                self.my_cooperation_count += 1
            else:
                self.my_defection_count += 1
            if recipient_id not in self.partner_history:
                self.partner_history[recipient_id] = []
            self.partner_history[recipient_id].append((my_action, opp_action))

            if opp_action == 'defect':
                self.personal_grudges[recipient_id] = self.personal_grudges.get(recipient_id, 0) + 1
                # Generosity decreases when I get exploited
                self.generosity = max(0.0, self.generosity - self.generosity_update)
            else:
                self.personal_favors[recipient_id] = self.personal_favors.get(recipient_id, 0) + 1
                # Generosity increases when cooperation is met
                self.generosity = min(1.0, self.generosity + self.generosity_update)

            if my_action == 'cooperate' and opp_action == 'defect':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.2)
            elif my_action == 'defect' and opp_action == 'cooperate':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.1)
            elif my_action == 'cooperate' and opp_action == 'cooperate':
                self.trust_scores[recipient_id] = min(1.0, self.trust_scores.get(recipient_id, 0.5) + 0.1)
            elif my_action == 'defect' and opp_action == 'defect':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.05)

        elif recipient_id == self.agent_id:
            my_action = recipient_action
            opp_action = donor_action
            self.my_last_action = my_action
            self.my_last_opponent = donor_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
                self.my_cooperation_count += 1
            else:
                self.my_defection_count += 1
            if donor_id not in self.partner_history:
                self.partner_history[donor_id] = []
            self.partner_history[donor_id].append((opp_action, my_action))

            if opp_action == 'defect':
                self.personal_grudges[donor_id] = self.personal_grudges.get(donor_id, 0) + 1
                self.generosity = max(0.0, self.generosity - self.generosity_update)
            else:
                self.personal_favors[donor_id] = self.personal_favors.get(donor_id, 0) + 1
                self.generosity = min(1.0, self.generosity + self.generosity_update)

            if opp_action == 'cooperate' and my_action == 'defect':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.2)
            elif opp_action == 'defect' and my_action == 'cooperate':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.1)
            elif opp_action == 'cooperate' and my_action == 'cooperate':
                self.trust_scores[donor_id] = min(1.0, self.trust_scores.get(donor_id, 0.5) + 0.1)
            elif opp_action == 'defect' and my_action == 'defect':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.05)

        else:
            # Third-party observation: update generosity based on observed cooperation
            if donor_action == 'cooperate':
                self.generosity = min(1.0, self.generosity + self.generosity_update * 0.5)
            else:
                self.generosity = max(0.0, self.generosity - self.generosity_update * 0.5)

            if donor_id not in self.third_party_trust:
                self.third_party_trust[donor_id] = 0.5
            if recipient_id not in self.third_party_trust:
                self.third_party_trust[recipient_id] = 0.5

            if donor_action == 'cooperate':
                self.third_party_trust[donor_id] = min(1.0, self.third_party_trust[donor_id] + 0.02)
            else:
                self.third_party_trust[donor_id] = max(0.0, self.third_party_trust[donor_id] - 0.02)

            if recipient_action == 'cooperate':
                self.third_party_trust[recipient_id] = min(1.0, self.third_party_trust[recipient_id] + 0.02)
            else:
                self.third_party_trust[recipient_id] = max(0.0, self.third_party_trust[recipient_id] - 0.02)

        if donor_id not in self.recent_actions:
            self.recent_actions[donor_id] = []
        self.recent_actions[donor_id].append(donor_action)
        if len(self.recent_actions[donor_id]) > 10:
            self.recent_actions[donor_id].pop(0)

        if recipient_id not in self.recent_actions:
            self.recent_actions[recipient_id] = []
        self.recent_actions[recipient_id].append(recipient_action)
        if len(self.recent_actions[recipient_id]) > 10:
            self.recent_actions[recipient_id].pop(0)

        if donor_id not in self.cooperation_history:
            self.cooperation_history[donor_id] = []
        self.cooperation_history[donor_id].append(donor_action == 'cooperate')

        if recipient_id not in self.cooperation_history:
            self.cooperation_history[recipient_id] = []
        self.cooperation_history[recipient_id].append(recipient_action == 'cooperate')

        if donor_id not in self.defection_history:
            self.defection_history[donor_id] = []
        self.defection_history[donor_id].append(donor_action == 'defect')

        if recipient_id not in self.defection_history:
            self.defection_history[recipient_id] = []
        self.defection_history[recipient_id].append(recipient_action == 'defect')

    def _get_trust(self, opponent_id: int) -> float:
        personal = self.trust_scores.get(opponent_id, 0.5)
        third_party = self.third_party_trust.get(opponent_id, 0.5)
        trust = 0.7 * personal + 0.3 * third_party
        if opponent_id in self.recent_actions:
            recent = self.recent_actions[opponent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                trust = 0.8 * trust + 0.2 * coop_rate
        return max(0.0, min(1.0, trust))

    def _update_reputation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.reputation:
            self.reputation[donor_id] = 0.5
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = 0.5

        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.01)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.01)

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.01)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.01)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.self_reputation = min(1.0, max(0.0, self.self_reputation + (0.01 if my_action == 'cooperate' else -0.01)))

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = []
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        # New: track recent interaction outcomes for each opponent
        self.recent_outcomes = {}  # opponent -> deque of (outcome, weight)
        self.recent_window = 5
        self.recency_weight = 0.7  # weight for recent outcomes vs overall

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # If we have history with this opponent, try to cooperate if they were cooperative last time
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        # New: incorporate recent outcomes into decision
        recent = self.recent_outcomes.get(opponent, deque())
        if recent:
            # Calculate recent cooperation rate
            recent_coop_count = sum(1 for outcome, _ in recent if outcome == 'cooperate')
            recent_rate = recent_coop_count / len(recent)
            # Blend recent rate with overall score
            base_score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
            score = (1 - self.recency_weight) * base_score + self.recency_weight * recent_rate
        else:
            score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        # Add forgiveness as a small bonus to cooperation
        score += self.forgiveness * 0.1
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation based on actions
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.9 + 0.1
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.9
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.9 + 0.1
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.9
        # Update cooperation counts for both
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        # If we are involved, update opponent history, trust, and recent outcomes
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            # Update trust based on other's action relative to mine
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
            # New: update recent outcomes deque
            if other not in self.recent_outcomes:
                self.recent_outcomes[other] = deque(maxlen=self.recent_window)
            # Weight more recent interactions higher
            weight = 1.0
            self.recent_outcomes[other].append((other_action, weight))
        # Increment round counter every time we observe (approximately every pair)
        self.round += 1
        # After many observations, increase forgiveness slightly
        if self.round % 100 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.01)

import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        # Reputation tracking: store for each agent a tuple (coops_seen, defects_seen)
        self.reputation = {}
        # Track how often I cooperated/defected with each opponent (for conditional strategies)
        self.my_history = {}
        # Track last few actions for trend detection (simple)
        self.recent_actions = deque(maxlen=20)
        # Cooperation threshold: initially moderately trusting
        self.coop_threshold = 0.5
        # Cooperation level to start with
        self.default_coop = 0.5
        # Track total observations for potential adaptation
        self.total_observations = 0
        # New: Memory of recent opponent actions for recency weighting
        self.opponent_recent = {}
        # New: Track my own cooperation count for self-assessment
        self.my_total_coops = 0
        self.my_total_actions = 0

    def _get_reputation(self, agent_id: int) -> float:
        # Returns estimated probability that agent cooperates (based on observed actions as donor)
        if agent_id not in self.reputation:
            return self.default_coop
        coops, defects = self.reputation[agent_id]
        total = coops + defects
        if total == 0:
            return self.default_coop
        return coops / total

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True  # no opponent? cooperate by default

        # Get reputation of opponent
        opp_rep = self._get_reputation(opponent)

        # New: Use recency-weighted reputation (last 10 observations more important)
        recent = self.opponent_recent.get(opponent, [])
        if recent:
            recent_rep = sum(1 for a in recent if a == "cooperate") / len(recent)
            # Blend: 40% recent, 60% overall reputation
            combined_rep = 0.4 * recent_rep + 0.6 * opp_rep
        else:
            combined_rep = opp_rep

        # Adjust threshold based on how I've interacted with this opponent before
        # If I have history with them, use that more heavily
        hist = self.my_history.get(opponent, [])
        if hist:
            my_coop_rate = sum(hist) / len(hist) if hist else 0.5
            weight_history = min(1.0, len(hist) / 5.0)  # up to 5 games matters
            combined = weight_history * my_coop_rate + (1 - weight_history) * combined_rep
        else:
            combined = combined_rep

        # Add a small bias toward cooperation if opponent reputation is ambiguous
        # Use a hysteresis-like effect to avoid being too volatile
        if 0.3 < combined < 0.7:
            if self.recent_actions:
                recent_coop_rate = sum(self.recent_actions) / len(self.recent_actions)
                combined = combined * 0.7 + recent_coop_rate * 0.3
            else:
                combined = combined * 0.5 + 0.5 * 0.5

        # Determine cooperation based on threshold with slight stochasticity for exploration
        threshold = self.coop_threshold
        r = random.random()
        if r < 0.05:
            return random.random() < 0.5
        return combined >= threshold

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor (as acting player)
        if donor_id != self.agent_id:
            self._update_rep(donor_id, donor_action)
            # New: Record recent action for recency weighting
            self._record_opponent_recent(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_rep(recipient_id, recipient_action)
            self._record_opponent_recent(recipient_id, recipient_action)

        # Track my own actions for history
        if donor_id == self.agent_id:
            self._record_my_action(recipient_id, donor_action == "cooperate")
            self.my_total_actions += 1
            if donor_action == "cooperate":
                self.my_total_coops += 1
        if recipient_id == self.agent_id:
