                        return rep + (self.generosity - 0.5) * 0.2 - self.suspicion * 0.3 > 0.45
            else:
                # No direct history, use reputation and generosity
                # Suspicion makes us more cautious
                return rep + (self.generosity - 0.5) * 0.2 - self.suspicion * 0.3 > 0.45
        except Exception:
            # Default to cooperate if any error
            return True

import math
