class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.my_history = {}
        self.recent_actions = deque(maxlen=20)
        self.coop_threshold = 0.5
        self.default_coop = 0.5
        self.total_observations = 0
        self.opponent_recent = {}
        self.my_total_coops = 0
        self.my_total_actions = 0
        # Modified: Add a forgiveness buffer that tracks how many times we've forgiven
        # an opponent after they defect. This is used to implement a forgiveness
        # mechanism that can help recover from a spiral of retaliation.
        self.forgiveness_count = {}

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            return self.default_coop
        # Use a weighted recent-priority reputation with exponential decay
        coops, defects, total_weight = self.reputation[agent_id]
        if total_weight == 0:
            return self.default_coop
        return coops / total_weight

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        opp_rep = self._get_reputation(opponent)

        # Forgiveness mechanism: if we have recently forgiven this opponent,
        # boost their effective reputation to encourage cooperation.
        forgiveness = self.forgiveness_count.get(opponent, 0)
        if forgiveness > 0:
            # Each forgiveness gives a +0.05 boost, capped at +0.2
            forgiveness_boost = min(0.2, forgiveness * 0.05)
            opp_rep = min(1.0, opp_rep + forgiveness_boost)

        recent = self.opponent_recent.get(opponent, [])
        if recent:
            recent_rep = sum(1 for a in recent if a == "cooperate") / len(recent)
            # Weight recent more when we have forgiven them recently
            recent_weight = 0.4 + 0.1 * forgiveness
            combined_rep = recent_weight * recent_rep + (1 - recent_weight) * opp_rep
        else:
            combined_rep = opp_rep

        hist = self.my_history.get(opponent, [])
        if hist:
            my_coop_rate = sum(hist) / len(hist) if hist else 0.5
            weight_history = min(1.0, len(hist) / 5.0)
            combined = weight_history * my_coop_rate + (1 - weight_history) * combined_rep
        else:
            combined = combined_rep

        if 0.3 < combined < 0.7:
            if self.recent_actions:
                recent_coop_rate = sum(self.recent_actions) / len(self.recent_actions)
                combined = combined * 0.7 + recent_coop_rate * 0.3
            else:
                combined = combined * 0.5 + 0.5 * 0.5

        threshold = self.coop_threshold
        r = random.random()
        if r < 0.05:
            return random.random() < 0.5
        return combined >= threshold

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Track forgiveness: if we observe a donor defecting but the recipient
        # cooperated, that means the recipient is showing forgiveness. We note
        # this to potentially boost that recipient's reputation.
        if donor_id != self.agent_id and donor_action == "defect" and recipient_action == "cooperate":
            # The recipient is forgiving the donor's defection. We record this
            # to boost the recipient's reputation slightly.
            self._update_forgiveness(recipient_id, donor_id)

