import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        self.forget_factor = 0.95
        # CHANGED: Replaced forgiveness with a "reputation_confidence" mechanism
        # that tracks how certain we are about each agent's reputation.
        # This explores a strategy that weighs recent observations more heavily
        # when reputation is uncertain.
        self.reputation_confidence = {}  # agent_id -> confidence (0 to 1)
        self.confidence_boost = 0.05  # Increase confidence on each observation
        self.confidence_decay = 0.98  # Decay confidence over time
        self.confidence_threshold = 0.5  # Below this, we rely more on recent actions
        self.recent_weight = 0.3  # How much recent actions influence decision when confidence is low
        # Keep volatility but slightly lower to balance the new mechanism
        self.rep_volatility = 0.12

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _get_confidence(self, agent_id: int) -> float:
        if agent_id not in self.reputation_confidence:
            self.reputation_confidence[agent_id] = 0.0
        return self.reputation_confidence[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_reputation(agent_id)
        weight = self.rep_volatility
        if is_own_interaction:
            weight += 0.02
        # Surprise factor as in parent
        if action == 'cooperate':
            surprise = (1.0 - current) ** 2
            new = current + (1 - current) * weight * (1 + surprise)
        else:
            surprise = current ** 2
            new = current - current * weight * (1 + surprise)
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _update_confidence(self, agent_id: int) -> None:
        # Increase confidence with each observation, but cap at 1
        current = self._get_confidence(agent_id)
        new = min(1.0, current + self.confidence_boost)
        self.reputation_confidence[agent_id] = new
        # Decay all confidences slightly over time (applied lazily when accessed)
        for aid in list(self.reputation_confidence.keys()):
            self.reputation_confidence[aid] *= self.confidence_decay
            if self.reputation_confidence[aid] < 0.01:
                del self.reputation_confidence[aid]

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        self._update_reputation(donor_id, donor_action, is_own_interaction=is_self)
        self._update_reputation(recipient_id, recipient_action, is_own_interaction=is_self)
        self._update_confidence(donor_id)
        self._update_confidence(recipient_id)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            confidence = self._get_confidence(opponent)

            total_interactions = 0
            coop_when_opp_coop = 0
            coop_when_opp_defect = 0
            # Also track recent interactions separately for low confidence
            recent_coop_opp = 0
            recent_total = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate' and my == 'cooperate':
                        coop_when_opp_coop += count
                    if their == 'defect' and my == 'cooperate':
                        coop_when_opp_defect += count
                    # For recent interactions, use last 5 encounters (approx)
                    if count > 0 and total_interactions <= 5:
                        recent_total += count
                        if their == 'cooperate':
                            recent_coop_opp += count

            if total_interactions > 0:
                opp_coop_count = sum(count for (opp, my, their), count in self.interaction_history.items()
                                     if opp == opponent and their == 'cooperate')
                p_opp_coop = opp_coop_count / total_interactions
                p_my_coop_given_opp_coop = (coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5

                # CHANGED: Use confidence to weight between historical and recent
                # When confidence is low, rely more on recent observations
                if confidence < self.confidence_threshold:
                    # Low confidence: use recent actions more heavily
                    if recent_total > 0:
                        recent_p = recent_coop_opp / recent_total
                        effective_p = self.recent_weight * recent_p + (1 - self.recent_weight) * p_opp_coop
                    else:
                        effective_p = p_opp_coop
                    # Be more cautious when uncertain
                    threshold = 0.55 - (confidence * 0.1)
                    return effective_p > threshold
                else:
                    # High confidence: use standard reputation-based logic
                    if rep > 0.6:
                        return True
                    elif rep < 0.4:
                        return False
                    else:
                        if total_interactions >= 3:
                            threshold = 0.5 - (confidence - 0.5) * 0.1
                            return p_opp_coop > threshold
                        else:
                            return rep > 0.45
            else:
                # No history: use reputation but be more cautious when uncertain
                if confidence < 0.2:
                    # Very uncertain, be cautious
                    return rep > 0.6
                return rep > 0.45
        except Exception:
            return True

import math
