        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        self.forget_factor = 0.95
        self.suspicion = {}
        self.round_count = 0
        # New: track direct interaction outcomes for each opponent
        self.direct_outcomes = {}
        # New: track recent observations for decay
        self.recent_observations = deque(maxlen=20)

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _get_suspicion(self, agent_id: int) -> float:
        if agent_id not in self.suspicion:
            self.suspicion[agent_id] = 0.0
        return self.suspicion[agent_id]

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self._get_reputation(agent_id)
        if action == 'cooperate':
            new = current + (1 - current) * 0.15  # Increased learning rate
        else:
            new = current - current * 0.05  # Decreased penalty
        self.reputation[agent_id] = new

    def _update_suspicion(self, agent_id: int, action: str) -> None:
        current = self._get_suspicion(agent_id)
        if action == 'defect':
            new = min(1.0, current + 0.2)  # More sensitive to defection
        else:
            new = max(0.0, current - 0.02)  # Slower forgiveness
        self.suspicion[agent_id] = new

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self._update_suspicion(donor_id, donor_action)
            self._update_suspicion(recipient_id, recipient_action)
            # Store recent observations for decay
            self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1
        # Track direct outcomes
        if opponent_id not in self.direct_outcomes:
            self.direct_outcomes[opponent_id] = {'coop': 0, 'defect': 0}
        if opp_action == 'cooperate':
            self.direct_outcomes[opponent_id]['coop'] += 1
        else:
            self.direct_outcomes[opponent_id]['defect'] += 1

    def _decay_suspicion(self) -> None:
        # Decay suspicion over time to reduce permanent grudges
        decay = 0.95
        for agent_id in self.suspicion:
            self.suspicion[agent_id] *= decay

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action)
            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
            # Occasionally decay suspicion
            if self.round_count % 5 == 0:
                self._decay_suspicion()
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            self.round_count += 1
            rep = self._get_reputation(opponent)
            susp = self._get_suspicion(opponent)
            # Use direct outcomes primarily
            direct = self.direct_outcomes.get(opponent, {'coop': 0, 'defect': 0})
            total_direct = direct['coop'] + direct['defect']
            if total_direct > 0:
                coop_rate = direct['coop'] / total_direct
                # Strong tit-for-tat with forgiveness
                if coop_rate > 0.6:
                    return True
                elif coop_rate < 0.3:
                    return False
                else:
                    # Middle ground: use reputation and suspicion
                    if susp > 0.7:
                        return False
                    return rep > 0.5
            else:
                # No direct experience, use reputation and suspicion
                # More trusting early, but suspicion builds quickly
                if susp > 0.45:
                    return False
                return rep > 0.4
        except Exception:
            return True

