        self.dynamic_forgiveness = 0.1  # starts equal to parent's static forgiveness
        self.exploitation_streak = 0  # counts consecutive defections against self
        self.forgiveness_boost = 0.05  # forgiveness increase per exploitation
        self.forgiveness_max = 0.5  # cap on forgiveness
        self.retaliation_inertia = 0.5  # how strongly past retaliation affects current choice

