import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, we store
        # a score between 0 and 1, initialised to 0.5 (neutral).
        self.reputation = {}
        # Track cooperation and defection counts for each agent
        self.coop_count = {}
        self.defect_count = {}
        # Track interactions with each agent: number of times we cooperated
        # when they cooperated, etc. For conditional strategies.
        self.interaction_history = {}
        # Own recent actions for context
        self.own_recent_actions = deque(maxlen=10)
        # Generational memory: simple forget factor
        self.forget_factor = 0.95
        # CHANGED: Instead of a single generosity score, we track
        # generosity separately for each opponent. This allows the agent
        # to have context-specific trust adjustments based on direct history,
        # exploring a more individualized social strategy.
        self.generosity = {}
        self.generosity_decay = 0.98
        # CHANGED: Lower rep_volatility makes reputation updates more
        # gradual, leading to more stable, less polarized views. This
        # contrasts with the parent's high volatility.
        self.rep_volatility = 0.05

    def _get_generosity(self, agent_id: int) -> float:
        if agent_id not in self.generosity:
            self.generosity[agent_id] = 0.5
        return self.generosity[agent_id]

    def _update_generosity(self, agent_id: int, action: str) -> None:
        current = self._get_generosity(agent_id)
        if action == 'cooperate':
            new = current + 0.05
        else:
            new = current - 0.05
        new *= self.generosity_decay
        self.generosity[agent_id] = max(0.0, min(1.0, new))

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_reputation(agent_id)
        weight = self.rep_volatility
        if is_own_interaction:
            weight += 0.02
        # CHANGED: Removed the surprise factor, making updates linear
        # and predictable. This explores a more conservative reputation
        # update that avoids overreactions to single events.
        if action == 'cooperate':
            new = current + (1 - current) * weight
        else:
            new = current - current * weight
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        self._update_reputation(donor_id, donor_action, is_own_interaction=is_self)
        self._update_reputation(recipient_id, recipient_action, is_own_interaction=is_self)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)
            # CHANGED: Update generosity only for the specific agents involved,
            # not globally. This makes the agent's generosity context-dependent.
            if donor_id != self.agent_id:
                self._update_generosity(donor_id, donor_action)
            if recipient_id != self.agent_id:
                self._update_generosity(recipient_id, recipient_action)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            # CHANGED: Use opponent-specific generosity instead of global
            generosity = self._get_generosity(opponent)
            total_interactions = 0
            coop_when_opp_coop = 0
            coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate' and my == 'cooperate':
                        coop_when_opp_coop += count
                    if their == 'defect' and my == 'cooperate':
                        coop_when_opp_defect += count
            if total_interactions > 0:
                opp_coop_count = sum(count for (opp, my, their), count in self.interaction_history.items()
                                     if opp == opponent and their == 'cooperate')
                p_opp_coop = opp_coop_count / total_interactions
                p_my_coop_given_opp_coop = (coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
                # CHANGED: Removed the reputation-consistency check. Instead,
                # we use a simple weighted average of reputation and direct
                # history, with the weight depending on interaction count.
                # This explores a more straightforward integration of
                # indirect and direct information.
                if total_interactions >= 3:
                    hist_coop_rate = opp_coop_count / total_interactions
                    # Weight history more heavily as interactions increase
                    weight_hist = min(0.5, total_interactions * 0.1)
                    rep = rep * (1 - weight_hist) + hist_coop_rate * weight_hist
                if rep > 0.6:
                    return generosity > 0.3
                elif rep < 0.4:
                    return generosity > 0.7
                else:
                    if total_interactions >= 3:
                        threshold = 0.5 - (generosity - 0.5) * 0.2
                        return p_opp_coop > threshold
                    else:
                        return rep + (generosity - 0.5) * 0.2 > 0.45
            else:
                return rep + (generosity - 0.5) * 0.2 > 0.45
        except Exception:
            return True

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        self.forget_factor = 0.95
        # Modified: Track a "suspicion" score that increases when observing defection
        # and decays over time, making the agent more cautious
        self.suspicion = 0.0
        self.suspicion_decay = 0.95
        self.suspicion_threshold = 0.6  # When suspicion exceeds this, be more conservative

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        # Simplified update: use a fixed step size and apply forget factor
        current = self._get_reputation(agent_id)
        # Apply forget factor to decay reputation towards neutral
        current = current * self.forget_factor + 0.5 * (1 - self.forget_factor)
        # Update based on action
        if action == 'cooperate':
            new = current + 0.15 * (1 - current)
        else:
            new = current - 0.15 * current
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        # Record counts for both actors
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1
        # Update reputation for both actors (no asymmetry in this variant)
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            # Record observation
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action)
            # Update suspicion based on observed actions (only defections increase it)
            if donor_action == 'defect':
                self.suspicion = min(1.0, self.suspicion + 0.1)
            if recipient_action == 'defect':
                self.suspicion = min(1.0, self.suspicion + 0.1)
            # Decay suspicion over time
            self.suspicion *= self.suspicion_decay

            # If we are one of the actors, record own interaction
            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)

            # Count interactions with this opponent
            total_interactions = 0
            opp_coop_count = 0
            my_coop_given_opp_coop = 0
            my_coop_given_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate':
                        opp_coop_count += count
                        if my == 'cooperate':
                            my_coop_given_opp_coop += count
                    else:
                        if my == 'cooperate':
                            my_coop_given_opp_defect += count

            # Compute conditional cooperation probabilities
            p_opp_coop = opp_coop_count / total_interactions if total_interactions > 0 else 0.5
            p_my_coop_given_opp_coop = (my_coop_given_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
            p_my_coop_given_opp_defect = (my_coop_given_opp_defect / (total_interactions - opp_coop_count)) if (total_interactions - opp_coop_count) > 0 else 0.5

            # Apply suspicion to adjust decision threshold
            suspicion_factor = self.suspicion * 0.3  # Suspicion reduces cooperation

            # Base decision on reputation
            if rep > 0.6:
                # High reputation: cooperate unless suspicious
                return (0.7 - suspicion_factor) > random.random()
            elif rep < 0.4:
                # Low reputation: defect unless not suspicious (but suspicion makes it worse)
                return (0.3 - suspicion_factor) > random.random()
            else:
                # Middle reputation: use history and suspicion
                if total_interactions >= 3:
                    # Use conditional probabilities, but suspicion shifts threshold
                    expected_coop = p_opp_coop * p_my_coop_given_opp_coop + (1 - p_opp_coop) * p_my_coop_given_opp_defect
                    threshold = 0.5 - suspicion_factor
                    return expected_coop > threshold
                else:
                    # Limited history: lean on reputation and suspicion
                    adjusted_rep = rep - suspicion_factor
                    return adjusted_rep > 0.45
        except Exception:
            return True

import random
import math
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation score (0 to 1)
        self.cooperation_count = 0
        self.defection_count = 0
        self.round_num = 0
        self.opponent_history = {}  # agent_id -> deque of True/False actions by this agent against them, maxlen=5
        self.other_history = {}  # (donor_id, recipient_id) -> (donor_action, recipient_action)
        self.trust = {}  # agent_id -> trust score (0 to 1), initial 0.5
        self.last_opponent = None
        self.generation_actions = []  # actions in current generation
        self.generation_opponents = []
        self.generation = 0
        self.my_action_history = []  # list of (opponent_id, action)
        self.opponent_action_history = []  # list of (opponent_id, action by opponent)
        self.defection_streak = {}  # agent_id -> consecutive defections observed
        self.cooperation_streak = {}  # agent_id -> consecutive cooperations observed
        # Initialize all agents with neutral reputation and trust
        for i in range(15):
            self.reputation[i] = 0.5
            self.trust[i] = 0.5
            self.opponent_history[i] = deque(maxlen=5)
            self.defection_streak[i] = 0
            self.cooperation_streak[i] = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        self.round_num += 1

        # Use a more nuanced decision based on recent history and streaks
        if len(self.opponent_history[opponent]) == 0:
            # No history, be cooperative but with slight chance of testing
            action = True if random.random() < 0.95 else False
        else:
            recent = list(self.opponent_history[opponent])[-3:]
            coop_count = sum(recent)
            if coop_count == len(recent):
                # All cooperative recently - high chance to cooperate
                action = True if random.random() < 0.95 else False
            elif coop_count >= 1:
                # Some cooperation - escalate cooperation if opponent has been cooperative recently
                # But be more cautious if they have long defection streaks
                if self.defection_streak[opponent] >= 2:
                    action = False
                else:
                    action = True if random.random() < 0.6 else False
            else:
                # All defections - be more likely to defect, but forgive if short streak
                if self.defection_streak[opponent] <= 1:
                    action = True if random.random() < 0.3 else False
                else:
                    action = False

        # Occasionally be generous if we have high trust in opponent, but not too often
        if self.trust[opponent] > 0.8 and random.random() < 0.05:
            action = True

        # Add a small randomness to avoid being too predictable
        if random.random() < 0.02:
            action = not action

        # Store action for later
        self.generation_actions.append(action)
        self.generation_opponents.append(opponent)
        return action

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update reputation with asymmetric updates: defections hurt more than cooperations help
        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.08)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.15)
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.08)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.15)

        # Update trust based on interactions with stronger reactions
        if donor_id == self.agent_id:
            # We are the donor - our action affects trust with recipient
            if donor_action == 'cooperate':
                self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + 0.05)
            else:
                self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - 0.08)
        if recipient_id == self.agent_id:
            # We are the recipient - donor's action affects trust
            if donor_action == 'cooperate':
                self.trust[donor_id] = min(1.0, self.trust[donor_id] + 0.12)
            else:
                self.trust[donor_id] = max(0.0, self.trust[donor_id] - 0.2)

        # Update streaks for both actors
        if donor_action == 'cooperate':
            self.cooperation_streak[donor_id] += 1
            self.defection_streak[donor_id] = 0
        else:
            self.defection_streak[donor_id] += 1
            self.cooperation_streak[donor_id] = 0
        if recipient_action == 'cooperate':
            self.cooperation_streak[recipient_id] += 1
            self.defection_streak[recipient_id] = 0
        else:
            self.defection_streak[recipient_id] += 1
            self.cooperation_streak[recipient_id] = 0

        # Store interaction history
        self.other_history[(donor_id, recipient_id)] = (donor_action, recipient_action)

        # If we are involved, update opponent history
        if donor_id == self.agent_id:
            self.opponent_history[recipient_id].append(recipient_action == 'cooperate')
            self.opponent_action_history.append((recipient_id, recipient_action == 'cooperate'))
        if recipient_id == self.agent_id:
            self.opponent_history[donor_id].append(donor_action == 'cooperate')
            self.opponent_action_history.append((donor_id, donor_action == 'cooperate'))

        # Update cooperation/defection counts
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1

        # At the end of a round, maybe adjust generation state - keep it simple
        pass

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.generation = 0
        self.round = 0
        self.total_rounds = 30
        self.total_generations = 30
        self.cooperation_history = {}
        self.defection_history = {}
        self.third_party_observations = {}
        self.reputation = {}
        self.self_reputation = 0.5
        self.last_round_actions = {}
        self.my_last_action = None
        self.my_last_opponent = None
        self.last_opponent_action = None
        self.round_in_generation = 0
        self.personal_grudges = {}
        self.personal_favors = {}
        self.trust_scores = {}
        self.third_party_trust = {}
        self.my_defection_count = 0
        self.my_cooperation_count = 0
        self.opponent_defection_count = 0
        self.opponent_cooperation_count = 0
        self.early_generation = True
        self.generations_observed = 0
        self.recent_actions = {}
        self.retaliation_threshold = 2
        self.cooperation_bias = 0.6
        self.forgiveness = 0.1
        self.opponent_models = {}
        self.observed_interactions = {}
        self.last_observed = {}
        self.personal_reputation = 0.5
        self.third_party_reputation = {}
        self.rounds_played = 0
        self.partner_history = {}
        self.adaptation_rate = 0.1
        # New mechanism: switch from static trust_threshold to a dynamic threshold
        # that adapts based on the agent's own generosity and recent experiences.
        self.generosity = 0.5
        self.generosity_decay = 0.01
        self.generosity_update = 0.05
        self.trust_threshold = 0.5  # dynamic threshold, updated each round
        self.threshold_adaptation = 0.05  # how fast threshold adapts
        self.threshold_min = 0.2
        self.threshold_max = 0.8

    def decide(self) -> bool:
        if self._ctx_opponent_id is not None:
            self.opponent_id = self._ctx_opponent_id
        else:
            self.opponent_id = -1

        if self.opponent_id == -1:
            return True

        trust = self._get_trust(self.opponent_id)

        # Personal history factor
        personal_factor = 0.0
        if self.opponent_id in self.personal_grudges:
            grudges = self.personal_grudges[self.opponent_id]
            favors = self.personal_favors.get(self.opponent_id, 0)
            net = favors - grudges
            personal_factor = math.tanh(net * 0.5) * 0.5

        # Third-party reputation factor
        third_party_factor = 0.0
        if self.opponent_id in self.third_party_trust:
            third_party_factor = (self.third_party_trust[self.opponent_id] - 0.5) * 0.3

        # Combine factors with a dynamic threshold
        cooperation_probability = trust - self.trust_threshold + 0.5 + personal_factor + third_party_factor + self.generosity * 0.2
        cooperation_probability = max(0.1, min(0.9, cooperation_probability))

        seed = self.agent_id * 1000 + self.opponent_id * 10 + self.rounds_played
        rng = random.Random(seed)
        return rng.random() < cooperation_probability

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.rounds_played += 1
        self.round_in_generation += 1
        if self.round_in_generation >= self.total_rounds:
            self.round_in_generation = 0
            self.generation += 1

        self.observed_interactions[(donor_id, recipient_id)] = self.observed_interactions.get((donor_id, recipient_id), 0) + 1
        self.last_observed[(donor_id, recipient_id)] = (donor_action, recipient_action)

        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)

        # Decay generosity slightly each round
        self.generosity = max(0.0, min(1.0, self.generosity - self.generosity_decay))

        # Update generosity and dynamic threshold based on interactions
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            self.my_last_action = my_action
            self.my_last_opponent = recipient_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
                self.my_cooperation_count += 1
            else:
                self.my_defection_count += 1
            if recipient_id not in self.partner_history:
                self.partner_history[recipient_id] = []
            self.partner_history[recipient_id].append((my_action, opp_action))

            if opp_action == 'defect':
                self.personal_grudges[recipient_id] = self.personal_grudges.get(recipient_id, 0) + 1
                # Generosity decreases when I get exploited
                self.generosity = max(0.0, self.generosity - self.generosity_update)
                # Raise threshold to be more cautious after being exploited
                self.trust_threshold = min(self.threshold_max, self.trust_threshold + self.threshold_adaptation)
            else:
                self.personal_favors[recipient_id] = self.personal_favors.get(recipient_id, 0) + 1
                # Generosity increases when cooperation is met
                self.generosity = min(1.0, self.generosity + self.generosity_update)
                # Lower threshold when cooperation is rewarded
                self.trust_threshold = max(self.threshold_min, self.trust_threshold - self.threshold_adaptation)

            if my_action == 'cooperate' and opp_action == 'defect':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.2)
            elif my_action == 'defect' and opp_action == 'cooperate':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.1)
            elif my_action == 'cooperate' and opp_action == 'cooperate':
                self.trust_scores[recipient_id] = min(1.0, self.trust_scores.get(recipient_id, 0.5) + 0.1)
            elif my_action == 'defect' and opp_action == 'defect':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.05)

        elif recipient_id == self.agent_id:
            my_action = recipient_action
            opp_action = donor_action
            self.my_last_action = my_action
            self.my_last_opponent = donor_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
                self.my_cooperation_count += 1
            else:
                self.my_defection_count += 1
            if donor_id not in self.partner_history:
                self.partner_history[donor_id] = []
            self.partner_history[donor_id].append((opp_action, my_action))

            if opp_action == 'defect':
                self.personal_grudges[donor_id] = self.personal_grudges.get(donor_id, 0) + 1
                self.generosity = max(0.0, self.generosity - self.generosity_update)
                self.trust_threshold = min(self.threshold_max, self.trust_threshold + self.threshold_adaptation)
            else:
                self.personal_favors[donor_id] = self.personal_favors.get(donor_id, 0) + 1
                self.generosity = min(1.0, self.generosity + self.generosity_update)
                self.trust_threshold = max(self.threshold_min, self.trust_threshold - self.threshold_adaptation)

            if opp_action == 'cooperate' and my_action == 'defect':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.2)
            elif opp_action == 'defect' and my_action == 'cooperate':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.1)
            elif opp_action == 'cooperate' and my_action == 'cooperate':
                self.trust_scores[donor_id] = min(1.0, self.trust_scores.get(donor_id, 0.5) + 0.1)
            elif opp_action == 'defect' and my_action == 'defect':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.05)

        else:
            # Third-party observation: update generosity and threshold based on observed behavior
            if donor_action == 'cooperate':
                self.generosity = min(1.0, self.generosity + self.generosity_update * 0.5)
                # Slightly lower threshold when observing cooperation
                self.trust_threshold = max(self.threshold_min, self.trust_threshold - self.threshold_adaptation * 0.3)
            else:
                self.generosity = max(0.0, self.generosity - self.generosity_update * 0.5)
                # Slightly raise threshold when observing defection
                self.trust_threshold = min(self.threshold_max, self.trust_threshold + self.threshold_adaptation * 0.3)

            if donor_id not in self.third_party_trust:
                self.third_party_trust[donor_id] = 0.5
            if recipient_id not in self.third_party_trust:
                self.third_party_trust[recipient_id] = 0.5

            if donor_action == 'cooperate':
                self.third_party_trust[donor_id] = min(1.0, self.third_party_trust[donor_id] + 0.02)
            else:
                self.third_party_trust[donor_id] = max(0.0, self.third_party_trust[donor_id] - 0.02)

            if recipient_action == 'cooperate':
                self.third_party_trust[recipient_id] = min(1.0, self.third_party_trust[recipient_id] + 0.02)
            else:
                self.third_party_trust[recipient_id] = max(0.0, self.third_party_trust[recipient_id] - 0.02)

        if donor_id not in self.recent_actions:
            self.recent_actions[donor_id] = []
        self.recent_actions[donor_id].append(donor_action)
        if len(self.recent_actions[donor_id]) > 10:
            self.recent_actions[donor_id].pop(0)

        if recipient_id not in self.recent_actions:
            self.recent_actions[recipient_id] = []
        self.recent_actions[recipient_id].append(recipient_action)
        if len(self.recent_actions[recipient_id]) > 10:
            self.recent_actions[recipient_id].pop(0)

        if donor_id not in self.cooperation_history:
            self.cooperation_history[donor_id] = []
        self.cooperation_history[donor_id].append(donor_action == 'cooperate')

        if recipient_id not in self.cooperation_history:
            self.cooperation_history[recipient_id] = []
        self.cooperation_history[recipient_id].append(recipient_action == 'cooperate')

        if donor_id not in self.defection_history:
            self.defection_history[donor_id] = []
        self.defection_history[donor_id].append(donor_action == 'defect')

        if recipient_id not in self.defection_history:
            self.defection_history[recipient_id] = []
        self.defection_history[recipient_id].append(recipient_action == 'defect')

    def _get_trust(self, opponent_id: int) -> float:
        personal = self.trust_scores.get(opponent_id, 0.5)
        third_party = self.third_party_trust.get(opponent_id, 0.5)
        trust = 0.7 * personal + 0.3 * third_party
        if opponent_id in self.recent_actions:
            recent = self.recent_actions[opponent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                trust = 0.8 * trust + 0.2 * coop_rate
        return max(0.0, min(1.0, trust))

    def _update_reputation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.reputation:
            self.reputation[donor_id] = 0.5
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = 0.5

        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.01)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.01)

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.01)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.01)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.self_reputation = min(1.0, max(0.0, self.self_reputation + (0.01 if my_action == 'cooperate' else -0.01)))

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        self.forget_factor = 0.95
        self.suspicion = {}
        self.round_count = 0
        self.direct_outcomes = {}
        self.recent_observations = deque(maxlen=20)
        # New: track a longer-term cooperation score that decays over time
        self.cooperation_score = {}
        self.last_observation_round = {}

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _get_suspicion(self, agent_id: int) -> float:
        if agent_id not in self.suspicion:
            self.suspicion[agent_id] = 0.0
        return self.suspicion[agent_id]

    def _get_cooperation_score(self, agent_id: int) -> float:
        if agent_id not in self.cooperation_score:
            self.cooperation_score[agent_id] = 0.5
        return self.cooperation_score[agent_id]

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self._get_reputation(agent_id)
        if action == 'cooperate':
            new = current + (1 - current) * 0.15
        else:
            new = current - current * 0.05
        self.reputation[agent_id] = new

    def _update_suspicion(self, agent_id: int, action: str) -> None:
        current = self._get_suspicion(agent_id)
        if action == 'defect':
            new = min(1.0, current + 0.2)
        else:
            new = max(0.0, current - 0.02)
        self.suspicion[agent_id] = new

    def _update_cooperation_score(self, agent_id: int, action: str) -> None:
        current = self._get_cooperation_score(agent_id)
        if action == 'cooperate':
            new = current + (1 - current) * 0.25
        else:
            new = current - current * 0.15
        self.cooperation_score[agent_id] = new

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        self._update_cooperation_score(donor_id, donor_action)
        self._update_cooperation_score(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self._update_suspicion(donor_id, donor_action)
            self._update_suspicion(recipient_id, recipient_action)
            self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))
        # Track the round of last observation for each agent
        self.last_observation_round[donor_id] = self.round_count
        self.last_observation_round[recipient_id] = self.round_count

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1
        if opponent_id not in self.direct_outcomes:
            self.direct_outcomes[opponent_id] = {'coop': 0, 'defect': 0}
        if opp_action == 'cooperate':
            self.direct_outcomes[opponent_id]['coop'] += 1
        else:
            self.direct_outcomes[opponent_id]['defect'] += 1

    def _decay_suspicion(self) -> None:
        decay = 0.95
        for agent_id in self.suspicion:
            self.suspicion[agent_id] *= decay

    def _decay_cooperation_score(self) -> None:
        # Decay cooperation score over time to emphasize recent behavior
        decay = 0.98
        for agent_id in self.cooperation_score:
            self.cooperation_score[agent_id] *= decay

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action)
            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
            if self.round_count % 5 == 0:
                self._decay_suspicion()
                self._decay_cooperation_score()
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            self.round_count += 1
            rep = self._get_reputation(opponent)
            susp = self._get_suspicion(opponent)
            coop_score = self._get_cooperation_score(opponent)
            # Use direct outcomes primarily
            direct = self.direct_outcomes.get(opponent, {'coop': 0, 'defect': 0})
            total_direct = direct['coop'] + direct['defect']
            if total_direct > 0:
                coop_rate = direct['coop'] / total_direct
                # Strong tit-for-tat with forgiveness, but factor in cooperation score
                if coop_rate > 0.6:
                    return True
                elif coop_rate < 0.3:
                    return False
                else:
                    # Middle ground: weigh recent cooperation score heavily
                    if coop_score > 0.7:
                        return True
                    elif susp > 0.7:
                        return False
                    return rep > 0.5
            else:
                # No direct experience, use cooperation score primarily
                # More trusting if recent observations show cooperation
                if coop_score > 0.6:
                    return True
                elif susp > 0.45:
                    return False
                return rep > 0.4
        except Exception:
            return True

import math
