                if total_interactions >= 3:
                    # Use conditional probabilities, but trust shifts threshold
                    expected_coop = p_opp_coop * p_my_coop_given_opp_coop + (1 - p_opp_coop) * p_my_coop_given_opp_defect
                    threshold = 0.5 - trust_factor
                    return expected_coop > threshold
                else:
                    # Limited history: lean on reputation and trust
                    adjusted_rep = rep + trust_factor
                    return adjusted_rep > 0.45
        except Exception:
            return True

