            # Compute conditional cooperation probabilities
            p_opp_coop = opp_coop_count / total_interactions if total_interactions > 0 else 0.5
            p_my_coop_given_opp_coop = (my_coop_given_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
            p_my_coop_given_opp_defect = (my_coop_given_opp_defect / (total_interactions - opp_coop_count)) if (total_interactions - opp_coop_count) > 0 else 0.5

            # Apply trust to adjust decision threshold (trust increases cooperation)
            trust_factor = self.trust * 0.3
            # New: Apply skepticism to reduce cooperation (skepticism makes agent more cautious)
            skepticism_factor = self.skepticism * 0.2

            # Base decision on reputation, adjusted by trust and skepticism
            if rep > 0.6:
                # High reputation: cooperate even more when trusting, but skepticism reduces
                return (0.7 + trust_factor - skepticism_factor) > random.random()
