        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)

            # Count interactions with this opponent
            total_interactions = 0
            opp_coop_count = 0
            my_coop_given_opp_coop = 0
            my_coop_given_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate':
                        opp_coop_count += count
                        if my == 'cooperate':
                            my_coop_given_opp_coop += count
                    else:
                        if my == 'cooperate':
                            my_coop_given_opp_defect += count

            # Compute conditional cooperation probabilities
            p_opp_coop = opp_coop_count / total_interactions if total_interactions > 0 else 0.5
            p_my_coop_given_opp_coop = (my_coop_given_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
            p_my_coop_given_opp_defect = (my_coop_given_opp_defect / (total_interactions - opp_coop_count)) if (total_interactions - opp_coop_count) > 0 else 0.5

            # Apply trust to adjust decision threshold (trust increases cooperation)
            trust_factor = self.trust * 0.3
            # New: Apply skepticism to reduce cooperation (skepticism makes agent more cautious)
            skepticism_factor = self.skepticism * 0.2

            # Base decision on reputation, adjusted by trust and skepticism
            if rep > 0.6:
                # High reputation: cooperate even more when trusting, but skepticism reduces
                return (0.7 + trust_factor - skepticism_factor) > random.random()
            elif rep < 0.4:
                # Low reputation: defect unless trusting strongly, skepticism increases defection
                return (0.3 + trust_factor - skepticism_factor) > random.random()
            else:
                # Middle reputation: use history, trust, and skepticism
                if total_interactions >= 3:
                    # Use conditional probabilities, but trust shifts threshold, skepticism shifts it back
                    expected_coop = p_opp_coop * p_my_coop_given_opp_coop + (1 - p_opp_coop) * p_my_coop_given_opp_defect
                    threshold = 0.5 - trust_factor + skepticism_factor
                    return expected_coop > threshold
                else:
                    # Limited history: lean on reputation, trust, and skepticism
                    adjusted_rep = rep + trust_factor - skepticism_factor
                    return adjusted_rep > 0.45
        except Exception:
            return True

