class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: maps other agent IDs to a score in [-1, 1]
        self.reputation = {}
        # Track cooperation counts and total interactions per other agent
        self.coop_count = {}
        self.total_interactions = {}
        # Track own recent cooperation rate for adaptive threshold
        self.own_coop_count = 0
        self.own_total = 0
        # Small epsilon for exploration/forgiveness
        self.epsilon = 0.05

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # default cooperate if no context
        # Get reputation of opponent, default 0.0 (neutral)
        rep = self.reputation.get(opponent, 0.0)
        # Adaptive threshold: if own cooperation rate is low, be more forgiving
        own_rate = 0.5 if self.own_total == 0 else self.own_coop_count / self.own_total
        threshold = 0.1 + 0.3 * (1 - own_rate)  # between 0.1 and 0.4
        if rep >= threshold:
            return True
        else:
            # Small chance to cooperate anyway (forgiveness/exploration)
            return random.random() < self.epsilon

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both donor and recipient based on actions
        # Actions: 'cooperate' -> +1, 'defect' -> -1
        donor_val = 1.0 if donor_action == 'cooperate' else -1.0
        recipient_val = 1.0 if recipient_action == 'cooperate' else -1.0

        # Update for donor
        self._update_reputation(donor_id, donor_val)
        # Update for recipient
        self._update_reputation(recipient_id, recipient_val)

        # Track interaction counts for both
        for pid in (donor_id, recipient_id):
            if pid != self.agent_id:
                if pid not in self.total_interactions:
                    self.total_interactions[pid] = 0
                    self.coop_count[pid] = 0
                self.total_interactions[pid] += 1
                # Count cooperation for each party
                if donor_id == pid and donor_action == 'cooperate':
                    self.coop_count[pid] += 1
                if recipient_id == pid and recipient_action == 'cooperate':
                    self.coop_count[pid] += 1

        # Update own stats if self is involved
        if donor_id == self.agent_id:
            self.own_total += 1
            if donor_action == 'cooperate':
                self.own_coop_count += 1
        if recipient_id == self.agent_id:
            self.own_total += 1
            if recipient_action == 'cooperate':
                self.own_coop_count += 1

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        if agent_id == self.agent_id:
            return  # ignore self-observation for reputation
        current = self.reputation.get(agent_id, 0.0)
        # Update with decay towards zero to model forgiveness over time
        # Use a simple moving average: new = old * 0.9 + delta * 0.1
        new = current * 0.9 + delta * 0.1
        # Clamp to [-1, 1]
        new = max(-1.0, min(1.0, new))
        self.reputation[agent_id] = new

