            # Move inertia towards the observed cooperation rate
            self.trust_inertia = min(1.0, max(0.0, self.trust_inertia + (coop_rate - self.trust_inertia) * 0.1))

        if donor_id not in self.recent_actions:
            self.recent_actions[donor_id] = []
        self.recent_actions[donor_id].append(donor_action)
        if len(self.recent_actions[donor_id]) > 10:
