            # We are the recipient; record donor's action
            opp_id = donor_id
            if opp_id not in self.reciprocity_memory:
                self.reciprocity_memory[opp_id] = deque(maxlen=self.reciprocity_window)
            self.reciprocity_memory[opp_id].append(donor_action == 'cooperate')

