                # Faster drop on betrayal
                self.reputation_momentum = max(0.0, self.reputation_momentum - self.momentum_drop)
            else:
                self.personal_favors[recipient_id] = self.personal_favors.get(recipient_id, 0) + 1
                # Slower rise on cooperation
