        self.adaptation_rate = 0.1
        # New mechanism: replace static trust_inertia with a dynamic "reputation momentum"
        # that combines personal and third-party reputation into a single momentum value,
        # updated asymmetrically: faster to drop than to rise, and reset only on betrayal.
        self.reputation_momentum = 0.5
        self.momentum_drop = 0.15  # faster drop on defection
        self.momentum_rise = 0.05  # slower rise on cooperation
        self.momentum_decay = 0.01  # slight decay per round
        self.momentum_threshold = 0.45  # lower threshold for cooperation (more forgiving)
        self.recent_interactions = deque(maxlen=10)

