        else:
            # Third-party observation: update trust inertia based on observed cooperation
            if donor_action == 'cooperate':
                self.trust_inertia = min(1.0, self.trust_inertia + self.inertia_update * 0.5)
            else:
                self.trust_inertia = max(0.0, self.trust_inertia - self.inertia_update * 0.5)

