            elif action == 'defect':
                self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - 0.1)

        # Track observed behaviors
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_coop:
                self.observed_coop[agent_id] = 0
                self.observed_defect[agent_id] = 0
            if action == 'cooperate':
                self.observed_coop[agent_id] += 1
            else:
                self.observed_defect[agent_id] += 1

        # Update trust based on consistency
        for agent_id in [donor_id, recipient_id]:
            total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
            if total >= 3:
                coop_ratio = self.observed_coop.get(agent_id, 0) / total
                # More consistent agents get trust adjustments
                if coop_ratio > 0.7:
                    self.trust[agent_id] = min(1.0, self.trust.get(agent_id, 0.5) + 0.1)
                elif coop_ratio < 0.3:
                    self.trust[agent_id] = max(0.0, self.trust.get(agent_id, 0.5) - 0.1)

        # Update own interaction history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            if other_id in self.interactions:
                self.interactions[other_id].append((my_action, other_action))
            else:
                self.interactions[other_id] = [(my_action, other_action)]

            # Update own reputation based on our actions
            if my_action == 'cooperate':
                self.my_coop_count += 1
                self.reputation[self.agent_id] = min(1.0, self.reputation.get(self.agent_id, 0.5) + 0.05)
            else:
                self.my_defect_count += 1
                self.reputation[self.agent_id] = max(0.0, self.reputation.get(self.agent_id, 0.5) - 0.1)

        # Track generation/round progress (approximate based on call frequency)
        self.total_rounds += 1
        if self.total_rounds % 30 == 0:
            self.generation += 1
            self.round_in_generation = 0
        else:
            self.round_in_generation += 1

        # Occasionally reassess reputation of all known agents
        if self.total_rounds % 10 == 0:
            for agent_id in list(self.reputation.keys()):
                coop = self.observed_coop.get(agent_id, 0)
                defect = self.observed_defect.get(agent_id, 0)
                total = coop + defect
                if total >= 5:
                    ratio = coop / total
                    # Weighted average of current reputation and observed ratio
                    self.reputation[agent_id] = self.reputation[agent_id] * 0.7 + ratio * 0.3

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.generation = 0
        self.round = 0
        self.total_rounds = 30
        self.total_generations = 30
        self.cooperation_history = {}
        self.defection_history = {}
        self.third_party_observations = {}
        self.reputation = {}
        self.self_reputation = 0.5
        self.last_round_actions = {}
        self.my_last_action = None
        self.my_last_opponent = None
        self.last_opponent_action = None
        self.round_in_generation = 0
        self.personal_grudges = {}
        self.personal_favors = {}
        self.trust_scores = {}
        self.third_party_trust = {}
        self.my_defection_count = 0
        self.my_cooperation_count = 0
        self.opponent_defection_count = 0
        self.opponent_cooperation_count = 0
        self.early_generation = True
        self.generations_observed = 0
        self.recent_actions = {}
        self.retaliation_threshold = 2
        self.cooperation_bias = 0.6
        self.forgiveness = 0.1
        self.opponent_models = {}
        self.observed_interactions = {}
        self.last_observed = {}
        self.personal_reputation = 0.5
        self.third_party_reputation = {}
        self.rounds_played = 0
        self.partner_history = {}
        self.adaptation_rate = 0.1
        # New mechanism: Instead of a dynamic threshold, use a recency-weighted
        # reputation that emphasizes recent behavior more strongly.
        self.reputation_threshold = 0.5  # fixed threshold
        self.recency_decay = 0.2  # decay factor for older observations
        self.reputation_scores = {}  # stores recency-weighted reputation per agent
        self.observation_weights = {}  # stores weight of recent observations
        self.self_cooperation_count = 0  # track own cooperations

    def decide(self) -> bool:
        if self._ctx_opponent_id is not None:
            self.opponent_id = self._ctx_opponent_id
        else:
            self.opponent_id = -1

        if self.opponent_id == -1:
            return True

        trust = self._get_trust(self.opponent_id)

        # Personal history factor
        personal_factor = 0.0
        if self.opponent_id in self.personal_grudges:
            grudges = self.personal_grudges[self.opponent_id]
            favors = self.personal_favors.get(self.opponent_id, 0)
            net = favors - grudges
            personal_factor = math.tanh(net * 0.5) * 0.5

        # Third-party reputation factor
        third_party_factor = 0.0
        if self.opponent_id in self.third_party_trust:
            third_party_factor = (self.third_party_trust[self.opponent_id] - 0.5) * 0.3

        # Combine factors with a fixed threshold, but trust is now recency-weighted
        cooperation_probability = trust - self.reputation_threshold + 0.5 + personal_factor + third_party_factor
        cooperation_probability = max(0.1, min(0.9, cooperation_probability))

        seed = self.agent_id * 1000 + self.opponent_id * 10 + self.rounds_played
        rng = random.Random(seed)
        return rng.random() < cooperation_probability

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.rounds_played += 1
        self.round_in_generation += 1
        if self.round_in_generation >= self.total_rounds:
            self.round_in_generation = 0
            self.generation += 1
            # Reset own cooperation count for the new generation
            self.self_cooperation_count = 0

        self.observed_interactions[(donor_id, recipient_id)] = self.observed_interactions.get((donor_id, recipient_id), 0) + 1
        self.last_observed[(donor_id, recipient_id)] = (donor_action, recipient_action)

        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)

        # Update personal history and trust scores
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            self.my_last_action = my_action
            self.my_last_opponent = recipient_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
                self.my_cooperation_count += 1
                self.self_cooperation_count += 1
            else:
                self.my_defection_count += 1
            if recipient_id not in self.partner_history:
                self.partner_history[recipient_id] = []
            self.partner_history[recipient_id].append((my_action, opp_action))

            if opp_action == 'defect':
                self.personal_grudges[recipient_id] = self.personal_grudges.get(recipient_id, 0) + 1
            else:
                self.personal_favors[recipient_id] = self.personal_favors.get(recipient_id, 0) + 1

            if my_action == 'cooperate' and opp_action == 'defect':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.2)
            elif my_action == 'defect' and opp_action == 'cooperate':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.1)
            elif my_action == 'cooperate' and opp_action == 'cooperate':
                self.trust_scores[recipient_id] = min(1.0, self.trust_scores.get(recipient_id, 0.5) + 0.1)
            elif my_action == 'defect' and opp_action == 'defect':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.05)

        elif recipient_id == self.agent_id:
            my_action = recipient_action
            opp_action = donor_action
            self.my_last_action = my_action
            self.my_last_opponent = donor_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
                self.my_cooperation_count += 1
                self.self_cooperation_count += 1
            else:
                self.my_defection_count += 1
            if donor_id not in self.partner_history:
                self.partner_history[donor_id] = []
            self.partner_history[donor_id].append((opp_action, my_action))

            if opp_action == 'defect':
                self.personal_grudges[donor_id] = self.personal_grudges.get(donor_id, 0) + 1
            else:
                self.personal_favors[donor_id] = self.personal_favors.get(donor_id, 0) + 1

            if opp_action == 'cooperate' and my_action == 'defect':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.2)
            elif opp_action == 'defect' and my_action == 'cooperate':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.1)
            elif opp_action == 'cooperate' and my_action == 'cooperate':
                self.trust_scores[donor_id] = min(1.0, self.trust_scores.get(donor_id, 0.5) + 0.1)
            elif opp_action == 'defect' and my_action == 'defect':
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.05)

        else:
            # Third-party observation: update recency-weighted reputation
            # Decay existing weights for this donor
            if donor_id in self.observation_weights:
                self.observation_weights[donor_id] *= (1 - self.recency_decay)
            else:
                self.observation_weights[donor_id] = 0.0
            # Add new observation with weight 1 (after decay, it will be less)
            if donor_id not in self.reputation_scores:
                self.reputation_scores[donor_id] = 0.5
            # Update weighted score: new observation weight is 1, but we need to normalize
            # Use a simple exponential moving average
            self.reputation_scores[donor_id] = (1 - self.recency_decay) * self.reputation_scores[donor_id] + self.recency_decay * (1.0 if donor_action == 'cooperate' else 0.0)
            self.observation_weights[donor_id] = min(1.0, self.observation_weights[donor_id] + 1.0)

            # Similarly for recipient
            if recipient_id in self.observation_weights:
                self.observation_weights[recipient_id] *= (1 - self.recency_decay)
            else:
                self.observation_weights[recipient_id] = 0.0
            if recipient_id not in self.reputation_scores:
                self.reputation_scores[recipient_id] = 0.5
            self.reputation_scores[recipient_id] = (1 - self.recency_decay) * self.reputation_scores[recipient_id] + self.recency_decay * (1.0 if recipient_action == 'cooperate' else 0.0)
            self.observation_weights[recipient_id] = min(1.0, self.observation_weights[recipient_id] + 1.0)

            # Update third-party trust based on the recency-weighted reputation
            self.third_party_trust[donor_id] = self.reputation_scores[donor_id]
            self.third_party_trust[recipient_id] = self.reputation_scores[recipient_id]

        # Update recent actions for both parties
        if donor_id not in self.recent_actions:
            self.recent_actions[donor_id] = []
        self.recent_actions[donor_id].append(donor_action)
        if len(self.recent_actions[donor_id]) > 10:
            self.recent_actions[donor_id].pop(0)

        if recipient_id not in self.recent_actions:
            self.recent_actions[recipient_id] = []
        self.recent_actions[recipient_id].append(recipient_action)
        if len(self.recent_actions[recipient_id]) > 10:
            self.recent_actions[recipient_id].pop(0)

        if donor_id not in self.cooperation_history:
            self.cooperation_history[donor_id] = []
        self.cooperation_history[donor_id].append(donor_action == 'cooperate')

        if recipient_id not in self.cooperation_history:
            self.cooperation_history[recipient_id] = []
        self.cooperation_history[recipient_id].append(recipient_action == 'cooperate')

        if donor_id not in self.defection_history:
            self.defection_history[donor_id] = []
        self.defection_history[donor_id].append(donor_action == 'defect')

        if recipient_id not in self.defection_history:
            self.defection_history[recipient_id] = []
        self.defection_history[recipient_id].append(recipient_action == 'defect')

    def _get_trust(self, opponent_id: int) -> float:
        personal = self.trust_scores.get(opponent_id, 0.5)
        third_party = self.third_party_trust.get(opponent_id, 0.5)
        trust = 0.7 * personal + 0.3 * third_party
        if opponent_id in self.recent_actions:
            recent = self.recent_actions[opponent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                trust = 0.8 * trust + 0.2 * coop_rate
        return max(0.0, min(1.0, trust))

    def _update_reputation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.reputation:
            self.reputation[donor_id] = 0.5
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = 0.5

        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.01)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.01)

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.01)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.01)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.self_reputation = min(1.0, max(0.0, self.self_reputation + (0.01 if my_action == 'cooperate' else -0.01)))

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        # New: memory of past defections against me to increase sensitivity
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        # New: track opponent's cooperation streaks
        self.opponent_streaks = {}
        self.streak_bonus = 0.1
        self.streak_threshold = 3

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        # New mechanism: if I've been defected against repeatedly, increase suspicion
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        # New mechanism: reward long cooperation streaks
        if opponent in self.opponent_streaks and self.opponent_streaks[opponent] >= self.streak_threshold:
            score += self.streak_bonus * self.opponent_streaks[opponent]
        # Reciprocity bias based on my recent cooperation rate
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        # Adaptive threshold based on recent outcomes
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            # Update streak tracking
            if other not in self.opponent_streaks:
                self.opponent_streaks[other] = 0
            if other_action == 'cooperate':
                self.opponent_streaks[other] += 1
            else:
                self.opponent_streaks[other] = 0
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                # Reset defection memory on cooperation
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                # Increment defection memory when they defect against me
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        self.forget_factor = 0.95
        # CHANGED: Use a single global generosity score instead of per-agent.
        # This explores a simpler, more uniform social style.
        self.generosity = 0.5
        self.generosity_decay = 0.98
        # CHANGED: Higher rep_volatility makes reputation updates more
        # dramatic, leading to more polarized views and stronger reactions.
        self.rep_volatility = 0.15
        # CHANGED: Added a pessimism bias - starts at 0 and increases when
        # observing defections. This makes the agent gradually more cautious.
        self.pessimism = 0.0
        self.pessimism_floor = 0.0
        self.pessimism_cap = 0.3
        # CHANGED: Added a trust factor that decays over time, making the
        # agent more trusting of known agents but less so of strangers.
        self.trust_decay = 0.9
        self.trust_threshold = 0.5

    def _get_generosity(self, agent_id: int) -> float:
        return self.generosity

    def _update_generosity(self, agent_id: int, action: str) -> None:
        if action == 'cooperate':
            self.generosity += 0.03
        else:
            self.generosity -= 0.03
        self.generosity *= self.generosity_decay
        self.generosity = max(0.0, min(1.0, self.generosity))

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_reputation(agent_id)
        weight = self.rep_volatility
        if is_own_interaction:
            weight += 0.03
        # CHANGED: Added a surprise factor: updates are larger when the
        # current reputation is far from the action (i.e., unexpected).
        # This explores a strategy that reacts strongly to surprising events.
        if action == 'cooperate':
            surprise = 1 - current
            new = current + surprise * weight
        else:
            surprise = current
            new = current - surprise * weight
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        self._update_reputation(donor_id, donor_action, is_own_interaction=is_self)
        self._update_reputation(recipient_id, recipient_action, is_own_interaction=is_self)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
            # CHANGED: Increase pessimism when observing others defect
            self.pessimism = min(self.pessimism_cap, self.pessimism + 0.01)
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1
            # CHANGED: Also increase pessimism when opponent defects
            self.pessimism = min(self.pessimism_cap, self.pessimism + 0.01)

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)
            # CHANGED: Update global generosity for all observations, not just
            # specific agents, making it more uniform.
            self._update_generosity(donor_id, donor_action)
            self._update_generosity(recipient_id, recipient_action)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            # CHANGED: Use global generosity and subtract pessimism bias
            generosity = self._get_generosity(opponent) - self.pessimism
            total_interactions = 0
            coop_when_opp_coop = 0
            coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate' and my == 'cooperate':
                        coop_when_opp_coop += count
                    if their == 'defect' and my == 'cooperate':
                        coop_when_opp_defect += count
            if total_interactions > 0:
                opp_coop_count = sum(count for (opp, my, their), count in self.interaction_history.items()
                                     if opp == opponent and their == 'cooperate')
                p_opp_coop = opp_coop_count / total_interactions
                p_my_coop_given_opp_coop = (coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
                # CHANGED: More aggressive weight on history - weight grows
                # faster and can reach up to 0.8
                if total_interactions >= 2:
                    hist_coop_rate = opp_coop_count / total_interactions
                    weight_hist = min(0.8, total_interactions * 0.2)
                    rep = rep * (1 - weight_hist) + hist_coop_rate * weight_hist
                # CHANGED: Lower thresholds due to pessimism, making the agent
                # more likely to defect overall.
                if rep > 0.7:
                    return generosity > 0.2
                elif rep < 0.3:
                    return generosity > 0.6
                else:
                    if total_interactions >= 2:
                        threshold = 0.5 - (generosity - 0.5) * 0.3
                        return p_opp_coop > threshold
                    else:
                        return rep + (generosity - 0.5) * 0.3 > 0.4
            else:
                # CHANGED: Added trust decay mechanism - for strangers, the
                # agent is more cautious and requires higher generosity to
                # cooperate. This explores a strategy that is more wary of
                # unknown agents.
                if opponent not in self.reputation:
                    trust_multiplier = self.trust_decay
                else:
                    trust_multiplier = 1.0
                return rep + (generosity - 0.5) * 0.3 * trust_multiplier > 0.4
        except Exception:
            return True

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation score
        self.interactions = {}  # agent_id -> deque of (my_action, other_action) with maxlen 10
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.observed_coop = {}
        self.observed_defect = {}
        self.trust = {}  # agent_id -> trust level
        self.reciprocity = {}  # agent_id -> recent reciprocity score (0-1)
        self.last_my_action = None  # for tracking own last action in observe
        self.last_other_action = None  # for tracking other's last action in observe
        self.last_opponent = None  # for decide context

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        # Get opponent's reputation if known, default to neutral
        opp_rep = self.reputation.get(opponent, 0.5)

        # Check if we have interaction history with this opponent
        if opponent in self.interactions and self.interactions[opponent]:
            history = self.interactions[opponent]
            # If opponent defected last time we played, be more cautious
            if history[-1][1] == 'defect':
                opp_rep *= 0.7
            # If opponent cooperated last time, be more trusting
            elif history[-1][1] == 'cooperate':
                opp_rep = min(1.0, opp_rep * 1.3)

        # Reciprocity adjustment: if opponent has been reciprocal recently, boost trust
        if opponent in self.reciprocity:
            rec = self.reciprocity[opponent]
            if rec > 0.6:
                opp_rep = min(1.0, opp_rep * (1 + rec * 0.2))
            elif rec < 0.3:
                opp_rep *= (1 - (0.3 - rec) * 0.5)

        # Adaptive strategy based on reputation
        if opp_rep >= 0.6:
            return True  # Cooperate with trustworthy agents
        elif opp_rep <= 0.3:
            return False  # Defect against untrustworthy agents
        else:
            # Mixed strategy with slight bias based on our own reputation
            my_rep = self.reputation.get(self.agent_id, 0.5)
            if my_rep > 0.5:
                return True
            else:
                return random.random() < 0.4  # Slight temptation to defect

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation scores for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.5
            if action == 'cooperate':
                self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + 0.05)
            elif action == 'defect':
                self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - 0.1)

        # Track observed behaviors
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_coop:
                self.observed_coop[agent_id] = 0
                self.observed_defect[agent_id] = 0
            if action == 'cooperate':
                self.observed_coop[agent_id] += 1
            else:
                self.observed_defect[agent_id] += 1

        # Update trust based on consistency
        for agent_id in [donor_id, recipient_id]:
            total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
            if total >= 3:
                coop_ratio = self.observed_coop.get(agent_id, 0) / total
                # More consistent agents get trust adjustments
                if coop_ratio > 0.7:
                    self.trust[agent_id] = min(1.0, self.trust.get(agent_id, 0.5) + 0.1)
                elif coop_ratio < 0.3:
                    self.trust[agent_id] = max(0.0, self.trust.get(agent_id, 0.5) - 0.1)

        # Update own interaction history and reciprocity tracking
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action

            # Store actions for reciprocity calculation
            self.last_my_action = my_action
            self.last_other_action = other_action

            if other_id in self.interactions:
                self.interactions[other_id].append((my_action, other_action))
            else:
                self.interactions[other_id] = deque([(my_action, other_action)], maxlen=10)

            # Update reciprocity score based on last interaction with this opponent
            if len(self.interactions[other_id]) >= 2:
                # Check if our last action was reciprocal to their last action
                # Reciprocal means we cooperated if they cooperated, or defected if they defected
                # But we want to encourage cooperation, so only count cooperation reciprocity
                if self.last_my_action == 'cooperate' and self.last_other_action == 'cooperate':
                    # We cooperated when they cooperated -> good reciprocity
                    if other_id not in self.reciprocity:
                        self.reciprocity[other_id] = 0.5
                    self.reciprocity[other_id] = min(1.0, self.reciprocity[other_id] + 0.15)
                elif self.last_my_action == 'defect' and self.last_other_action == 'defect':
                    # Both defected -> bad reciprocity
                    if other_id not in self.reciprocity:
                        self.reciprocity[other_id] = 0.5
                    self.reciprocity[other_id] = max(0.0, self.reciprocity[other_id] - 0.15)
                elif self.last_my_action == 'cooperate' and self.last_other_action == 'defect':
                    # We cooperated but they defected -> very bad reciprocity
                    if other_id not in self.reciprocity:
                        self.reciprocity[other_id] = 0.5
                    self.reciprocity[other_id] = max(0.0, self.reciprocity[other_id] - 0.25)
                elif self.last_my_action == 'defect' and self.last_other_action == 'cooperate':
                    # We defected but they cooperated -> we exploited them, slight positive? Actually neutral
                    if other_id not in self.reciprocity:
                        self.reciprocity[other_id] = 0.5
                    # Keep as is or slight decrease to discourage exploitation
                    self.reciprocity[other_id] = max(0.0, self.reciprocity[other_id] - 0.05)

            # Update own reputation based on our actions
            if my_action == 'cooperate':
                self.my_coop_count += 1
                self.reputation[self.agent_id] = min(1.0, self.reputation.get(self.agent_id, 0.5) + 0.05)
            else:
                self.my_defect_count += 1
                self.reputation[self.agent_id] = max(0.0, self.reputation.get(self.agent_id, 0.5) - 0.1)

        # Track generation/round progress (approximate based on call frequency)
        self.total_rounds += 1
        if self.total_rounds % 30 == 0:
            self.generation += 1
            self.round_in_generation = 0
        else:
            self.round_in_generation += 1

        # Occasionally reassess reputation of all known agents
        if self.total_rounds % 10 == 0:
            for agent_id in list(self.reputation.keys()):
                coop = self.observed_coop.get(agent_id, 0)
                defect = self.observed_defect.get(agent_id, 0)
                total = coop + defect
                if total >= 5:
                    ratio = coop / total
                    # Weighted average of current reputation and observed ratio
                    self.reputation[agent_id] = self.reputation[agent_id] * 0.7 + ratio * 0.3

        # Decay reciprocity scores slowly over time to avoid staleness
        if self.total_rounds % 5 == 0:
            for agent_id in list(self.reciprocity.keys()):
                self.reciprocity[agent_id] = self.reciprocity[agent_id] * 0.95

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.generation = 0
        self.round = 0
        self.total_rounds = 30
        self.total_generations = 30
        self.cooperation_history = {}
        self.defection_history = {}
        self.third_party_observations = {}
        self.reputation = {}
        self.self_reputation = 0.5
        self.last_round_actions = {}
        self.my_last_action = None
        self.my_last_opponent = None
        self.last_opponent_action = None
        self.round_in_generation = 0
        self.personal_grudges = {}
        self.personal_favors = {}
        self.trust_scores = {}
        self.third_party_trust = {}
        self.my_defection_count = 0
        self.my_cooperation_count = 0
        self.opponent_defection_count = 0
        self.opponent_cooperation_count = 0
        self.early_generation = True
        self.generations_observed = 0
        self.recent_actions = {}
        self.retaliation_threshold = 2
        self.cooperation_bias = 0.6
        self.forgiveness = 0.1
        self.opponent_models = {}
        self.observed_interactions = {}
        self.last_observed = {}
        self.personal_reputation = 0.5
        self.third_party_reputation = {}
        self.rounds_played = 0
        self.partner_history = {}
        self.adaptation_rate = 0.1
        # New mechanism: replace static generosity with a dynamic "trust inertia" that
        # resets each generation and is influenced by the recency of interactions.
        self.trust_inertia = 0.5  # baseline trust inertia, affects cooperation probability
        self.inertia_decay = 0.02  # decay per round
        self.inertia_update = 0.08  # update magnitude per interaction
        self.trust_threshold = 0.5  # fixed threshold, no emotional adjustment
        self.recent_interactions = deque(maxlen=10)  # track recent interaction outcomes

    def decide(self) -> bool:
        if self._ctx_opponent_id is not None:
            self.opponent_id = self._ctx_opponent_id
        else:
            self.opponent_id = -1

        if self.opponent_id == -1:
            return True

        trust = self._get_trust(self.opponent_id)

        # Personal history factor
        personal_factor = 0.0
        if self.opponent_id in self.personal_grudges:
            grudges = self.personal_grudges[self.opponent_id]
            favors = self.personal_favors.get(self.opponent_id, 0)
            net = favors - grudges
            personal_factor = math.tanh(net * 0.5) * 0.5

        # Third-party reputation factor
        third_party_factor = 0.0
        if self.opponent_id in self.third_party_trust:
            third_party_factor = (self.third_party_trust[self.opponent_id] - 0.5) * 0.3

        # Combine factors with a trust-inertia-based offset
        cooperation_probability = trust - self.trust_threshold + 0.5 + personal_factor + third_party_factor + self.trust_inertia * 0.2
        cooperation_probability = max(0.1, min(0.9, cooperation_probability))

        seed = self.agent_id * 1000 + self.opponent_id * 10 + self.rounds_played
        rng = random.Random(seed)
        return rng.random() < cooperation_probability

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.rounds_played += 1
        self.round_in_generation += 1
        if self.round_in_generation >= self.total_rounds:
            self.round_in_generation = 0
            self.generation += 1
            # Reset trust inertia at the start of each generation
            self.trust_inertia = 0.5
            self.recent_interactions.clear()

        self.observed_interactions[(donor_id, recipient_id)] = self.observed_interactions.get((donor_id, recipient_id), 0) + 1
        self.last_observed[(donor_id, recipient_id)] = (donor_action, recipient_action)

        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)

        # Decay trust inertia slightly each round
        self.trust_inertia = max(0.0, min(1.0, self.trust_inertia - self.inertia_decay))

        # Update trust inertia based on interactions
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            self.my_last_action = my_action
            self.my_last_opponent = recipient_id
            self.last_opponent_action = opp_action
            if my_action == 'cooperate':
                self.my_cooperation_count += 1
            else:
                self.my_defection_count += 1
            if recipient_id not in self.partner_history:
                self.partner_history[recipient_id] = []
            self.partner_history[recipient_id].append((my_action, opp_action))

            if opp_action == 'defect':
                self.personal_grudges[recipient_id] = self.personal_grudges.get(recipient_id, 0) + 1
                self.trust_inertia = max(0.0, self.trust_inertia - self.inertia_update)
            else:
                self.personal_favors[recipient_id] = self.personal_favors.get(recipient_id, 0) + 1
                self.trust_inertia = min(1.0, self.trust_inertia + self.inertia_update)

            if my_action == 'cooperate' and opp_action == 'defect':
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.2)
