import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation score
        self.interactions = {}  # agent_id -> list of (my_action, other_action)
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.observed_coop = {}
        self.observed_defect = {}
        self.trust = {}  # agent_id -> trust level

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Get opponent's reputation if known, default to neutral
        opp_rep = self.reputation.get(opponent, 0.5)

        # Check if we have interaction history with this opponent
        if opponent in self.interactions:
            history = self.interactions[opponent]
            # If opponent defected last time we played, be more cautious
            if history and history[-1][1] == 'defect':
                opp_rep *= 0.7
            # If opponent cooperated last time, be more trusting
            elif history and history[-1][1] == 'cooperate':
                opp_rep = min(1.0, opp_rep * 1.3)

        # Adaptive strategy based on reputation
        if opp_rep >= 0.6:
            return True  # Cooperate with trustworthy agents
        elif opp_rep <= 0.3:
            return False  # Defect against untrustworthy agents
        else:
            # Mixed strategy with slight bias based on our own reputation
            my_rep = self.reputation.get(self.agent_id, 0.5)
            if my_rep > 0.5:
                return True
            else:
                return random.random() < 0.4  # Slight temptation to defect

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation scores for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.5
            if action == 'cooperate':
                self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + 0.05)
            elif action == 'defect':
                self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - 0.1)

        # Track observed behaviors
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_coop:
                self.observed_coop[agent_id] = 0
                self.observed_defect[agent_id] = 0
            if action == 'cooperate':
                self.observed_coop[agent_id] += 1
            else:
                self.observed_defect[agent_id] += 1

        # Update trust based on consistency
        for agent_id in [donor_id, recipient_id]:
            total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
            if total >= 3:
                coop_ratio = self.observed_coop.get(agent_id, 0) / total
                # More consistent agents get trust adjustments
                if coop_ratio > 0.7:
                    self.trust[agent_id] = min(1.0, self.trust.get(agent_id, 0.5) + 0.1)
                elif coop_ratio < 0.3:
                    self.trust[agent_id] = max(0.0, self.trust.get(agent_id, 0.5) - 0.1)

        # Update own interaction history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            if other_id in self.interactions:
                self.interactions[other_id].append((my_action, other_action))
            else:
                self.interactions[other_id] = [(my_action, other_action)]

            # Update own reputation based on our actions
            if my_action == 'cooperate':
                self.my_coop_count += 1
                self.reputation[self.agent_id] = min(1.0, self.reputation.get(self.agent_id, 0.5) + 0.05)
            else:
                self.my_defect_count += 1
                self.reputation[self.agent_id] = max(0.0, self.reputation.get(self.agent_id, 0.5) - 0.1)

        # Track generation/round progress (approximate based on call frequency)
        self.total_rounds += 1
        if self.total_rounds % 30 == 0:
            self.generation += 1
            self.round_in_generation = 0
        else:
            self.round_in_generation += 1

        # Occasionally reassess reputation of all known agents
        if self.total_rounds % 10 == 0:
            for agent_id in list(self.reputation.keys()):
                coop = self.observed_coop.get(agent_id, 0)
                defect = self.observed_defect.get(agent_id, 0)
                total = coop + defect
                if total >= 5:
                    ratio = coop / total
                    # Weighted average of current reputation and observed ratio
                    self.reputation[agent_id] = self.reputation[agent_id] * 0.7 + ratio * 0.3

