import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        # CHANGED: Replaced trust scores with a reputation adjustment based on
        # interaction similarity. This explores a mechanism that compares
        # observed interactions to one's own to update reputation, making the
        # agent more sensitive to consistent behavior patterns.
        self.rep_adjustment = {}
        self.rep_adjustment_learning_rate = 0.15
        self.rep_adjustment_decay = 0.95
        # CHANGED: Added a forgiveness factor that slowly decays negative
        # reputation updates, allowing agents to recover from past mistakes.
        self.forgiveness = 0.02
        self.forgiveness_rate = 0.01
        self.forgiveness_cap = 0.1
        # CHANGED: Added a stubbornness parameter that makes the agent rely
        # more heavily on initial reputation impressions.
        self.stubbornness = 0.2
        self.stubbornness_decay = 0.99

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_reputation(agent_id)
        # CHANGED: Use a non-linear update that is more sensitive to extreme
        # actions but with a forgiveness factor that reduces negative updates
        # over time.
        weight = 0.1
        if is_own_interaction:
            weight += 0.02
        if action == 'cooperate':
            target = 1.0
        else:
            target = 0.0
        # CHANGED: Apply forgiveness only to negative updates (defections)
        if action == 'defect':
            weight *= (1 - self.forgiveness)
        surprise = target - current
        new = current + surprise * weight
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        # CHANGED: Update reputation with a similarity-based adjustment.
        # Compare donor and recipient actions to see if they match a pattern
        # that the agent values: cooperation is good, defection is bad.
        self._update_reputation(donor_id, donor_action, is_own_interaction=is_self)
        self._update_reputation(recipient_id, recipient_action, is_own_interaction=is_self)
        # CHANGED: Track reputation adjustments based on consistency.
        # If an agent cooperates, they get a positive adjustment; if they
        # defect, a negative one. This adjustment is then used to modify the
        # reputation update rule.
        if donor_action == 'cooperate':
            self.rep_adjustment[donor_id] = self.rep_adjustment.get(donor_id, 0.0) + self.rep_adjustment_learning_rate * (1 - self._get_reputation(donor_id))
        else:
            self.rep_adjustment[donor_id] = self.rep_adjustment.get(donor_id, 0.0) - self.rep_adjustment_learning_rate * self._get_reputation(donor_id)
        if recipient_action == 'cooperate':
            self.rep_adjustment[recipient_id] = self.rep_adjustment.get(recipient_id, 0.0) + self.rep_adjustment_learning_rate * (1 - self._get_reputation(recipient_id))
        else:
            self.rep_adjustment[recipient_id] = self.rep_adjustment.get(recipient_id, 0.0) - self.rep_adjustment_learning_rate * self._get_reputation(recipient_id)
        # Decay adjustments
        for agent in list(self.rep_adjustment.keys()):
            self.rep_adjustment[agent] *= self.rep_adjustment_decay
        # Update counts and forgiveness
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
            self.forgiveness = min(self.forgiveness_cap, self.forgiveness + self.forgiveness_rate)
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1
            self.forgiveness = min(self.forgiveness_cap, self.forgiveness + self.forgiveness_rate)
        # Decay forgiveness slowly
        self.forgiveness *= (1 - self.forgiveness_rate)

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            # CHANGED: Incorporate the reputation adjustment and stubbornness
            # into the decision. The adjustment acts as a bias that amplifies
            # or dampens reputation based on observed patterns.
            adjustment = self.rep_adjustment.get(opponent, 0.0)
            # Stubbornness makes the initial reputation count more
            adjusted_rep = rep * (1 - self.stubbornness) + 0.5 * self.stubbornness + adjustment * 0.5
            combined_score = adjusted_rep
            total_interactions = 0
            coop_when_opp_coop = 0
            coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate' and my == 'cooperate':
                        coop_when_opp_coop += count
                    if their == 'defect' and my == 'cooperate':
                        coop_when_opp_defect += count
            if total_interactions > 0:
                opp_coop_count = sum(count for (opp, my, their), count in self.interaction_history.items()
                                     if opp == opponent and their == 'cooperate')
                p_opp_coop = opp_coop_count / total_interactions
                p_my_coop_given_opp_coop = (coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
                # CHANGED: Use adjusted reputation and a more forgiving threshold
                # due to the forgiveness factor, making the agent more likely
                # to cooperate after seeing defections.
                if total_interactions >= 2:
                    hist_coop_rate = opp_coop_count / total_interactions
                    weight_hist = min(0.5, total_interactions * 0.1)
                    combined_score = combined_score * (1 - weight_hist) + hist_coop_rate * weight_hist
                # CHANGED: Thresholds are slightly lower due to forgiveness
                if combined_score > 0.65:
                    return True
                elif combined_score < 0.35:
                    return False
                else:
                    if total_interactions >= 2:
                        threshold = 0.5 - (combined_score - 0.5) * 0.15
                        return p_opp_coop > threshold
                    else:
                        return combined_score > 0.5
            else:
                return combined_score > 0.5
        except Exception:
            return True

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        # CHANGED: Replaced per-agent trust with a global "forgiveness" factor
        # that decays over time. This explores a more forgiving strategy that
        # gradually forgets past defections and treats all agents equally.
        self.global_forgiveness = 0.5
        self.forgiveness_decay = 0.9
        # CHANGED: Added a recency-weighted reputation tracker that gives
        # more weight to recent observations, making the agent more adaptive
        # to changes in opponent behavior.
        self.reputation_recent = {}
        self.recent_window = 5
        self.reputation_history = {}  # agent_id -> deque of recent reputation values
        # CHANGED: Added a "cooperation momentum" parameter that increases
        # when the agent itself cooperates, making it more likely to cooperate
        # in the future (habit formation).
        self.cooperation_momentum = 0.0
        self.cooperation_momentum_increment = 0.05
        self.cooperation_momentum_decay = 0.95
        # CHANGED: Added a "grudge" counter that tracks how many times the
        # current opponent has defected against us, making us more retaliatory.
        self.grudge = {}
        self.grudge_decay = 0.9

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
            self.reputation_history[agent_id] = deque(maxlen=self.recent_window)
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_reputation(agent_id)
        weight = 0.15
        if is_own_interaction:
            weight += 0.05
        # CHANGED: Use a simpler update rule without momentum, but with
        # forgiveness: the update is scaled by the global forgiveness factor.
        if action == 'cooperate':
            target = 1.0
        else:
            target = 0.0
        surprise = target - current
        # Forgiveness softens the update: if forgiveness is high, updates are
        # smaller, making reputation more stable.
        new = current + surprise * weight * self.global_forgiveness
        self.reputation[agent_id] = max(0.0, min(1.0, new))
        # Track recent reputation values for recency-weighted average
        self.reputation_history[agent_id].append(self.reputation[agent_id])

    def _get_recent_reputation(self, agent_id: int) -> float:
        history = self.reputation_history.get(agent_id, deque())
        if not history:
            return self._get_reputation(agent_id)
        # Weight more recent values higher
        weights = [1.0 / (i + 1) for i in range(len(history))]
        total_weight = sum(weights)
        weighted_sum = sum(val * w for val, w in zip(history, weights))
        return weighted_sum / total_weight if total_weight > 0 else 0.5

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        self._update_reputation(donor_id, donor_action, is_own_interaction=is_self)
        self._update_reputation(recipient_id, recipient_action, is_own_interaction=is_self)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1
        # CHANGED: Update grudge: if I cooperated and they defected, increase
        # grudge; if they cooperated, decrease grudge.
        if opp_action == 'defect' and my_action == 'cooperate':
            self.grudge[opponent_id] = self.grudge.get(opponent_id, 0) + 1
        elif opp_action == 'cooperate':
            self.grudge[opponent_id] = self.grudge.get(opponent_id, 0) * self.grudge_decay
        # Update cooperation momentum based on my own action
        if my_action == 'cooperate':
            self.cooperation_momentum = min(1.0, self.cooperation_momentum + self.cooperation_momentum_increment)
        else:
            self.cooperation_momentum = max(0.0, self.cooperation_momentum - self.cooperation_momentum_increment)
        # Decay forgiveness over time
        self.global_forgiveness = max(0.1, self.global_forgiveness * self.forgiveness_decay)

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_recent_reputation(opponent)
            # CHANGED: Use recency-weighted reputation and adjust by
            # cooperation momentum and grudge.
