    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent

        # Get opponent's reputation if known, default to neutral
        opp_rep = self.reputation.get(opponent, 0.5)

        # Check if we have interaction history with this opponent
        if opponent in self.interactions:
            history = self.interactions[opponent]
            if history:
                # Look at the last 3 interactions for a more robust pattern
                recent = list(history)[-3:]
                defects = sum(1 for _, other in recent if other == 'defect')
                coop = len(recent) - defects
                # Adjust reputation based on recent behavior with stronger weighting
                if defects > coop:
                    opp_rep *= 0.5  # More punitive for recent defections
                elif coop > defects:
                    opp_rep = min(1.0, opp_rep * 1.5)  # More trusting of recent cooperation

        # Use trust as an additional signal (trust is more dynamic)
        trust_level = self.trust.get(opponent, 0.5)
        combined_score = opp_rep * 0.6 + trust_level * 0.4  # Weighted combination

        # Adaptive strategy based on combined score
        if combined_score >= 0.65:
            return True  # Cooperate with trustworthy agents
        elif combined_score <= 0.35:
            return False  # Defect against untrustworthy agents
        else:
            # Mixed strategy with a probabilistic element that adapts to own reputation
            my_rep = self.reputation.get(self.agent_id, 0.5)
            # More cooperative if we have a good reputation, but with slight randomness
            if my_rep > 0.6:
                return random.random() < 0.8  # High chance to cooperate
            elif my_rep < 0.4:
                return random.random() < 0.2  # Low chance to cooperate
            else:
                return random.random() < 0.5  # Neutral

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation scores with a recency-weighted approach
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.5
            # Recent actions have more weight (use a decay factor)
            decay = 0.9  # Recency factor
            if action == 'cooperate':
                self.reputation[agent_id] = min(1.0, decay * self.reputation[agent_id] + 0.1)
            elif action == 'defect':
                self.reputation[agent_id] = max(0.0, decay * self.reputation[agent_id] - 0.15)

