            if action == 'cooperate':
                self.observed_coop[agent_id] += 1
            else:
                self.observed_defect[agent_id] += 1

        # Update trust based on consistency but with a faster adjustment
        for agent_id in [donor_id, recipient_id]:
            total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
            if total >= 3:
                coop_ratio = self.observed_coop.get(agent_id, 0) / total
                current_trust = self.trust.get(agent_id, 0.5)
                # Faster trust adjustment with a momentum term
                if coop_ratio > 0.6:
                    # Increase trust more aggressively when already high
                    adjustment = 0.15 if current_trust > 0.5 else 0.1
                    self.trust[agent_id] = min(1.0, current_trust + adjustment)
                elif coop_ratio < 0.4:
                    # Decrease trust more aggressively when already low
                    adjustment = 0.15 if current_trust < 0.5 else 0.1
                    self.trust[agent_id] = max(0.0, current_trust - adjustment)

        # Update own interaction history with bounded deque (keep last 10 interactions)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            if other_id in self.interactions:
                self.interactions[other_id].append((my_action, other_action))
