            # Update defection streak tracking
            if other not in self.opponent_defection_streaks:
                self.opponent_defection_streaks[other] = 0
            if other_action == 'defect':
                self.opponent_defection_streaks[other] += 1
            else:
                self.opponent_defection_streaks[other] = 0
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
