        self.reciprocity_factor = 0.8  # How much to weight recent interactions
        self.memory_decay = 0.95  # Decay factor for observed behavior counts

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self.reputation.get(opponent, 0.5)

        # Check recent interaction history using deque (last 5 interactions)
        if opponent in self.interactions:
            history = self.interactions[opponent]
            recent = list(history)[-5:]
            coop_count = sum(1 for _, other in recent if other == 'cooperate')
            defect_count = sum(1 for _, other in recent if other == 'defect')

            if defect_count > coop_count:
                # More defections than cooperations recently
                opp_rep *= 0.6
            elif coop_count > defect_count:
                # More cooperations than defections recently
                opp_rep = min(1.0, opp_rep * 1.4)

        # Reciprocity-based adjustment: if we cooperated last time and they defected, be cautious
        if opponent in self.interactions and len(self.interactions[opponent]) > 0:
            last_my_action, last_other_action = self.interactions[opponent][-1]
            if last_my_action == 'cooperate' and last_other_action == 'defect':
                opp_rep *= 0.5  # Strong penalty for betrayal
            elif last_my_action == 'defect' and last_other_action == 'cooperate':
                opp_rep = min(1.0, opp_rep * 1.5)  # Reward for forgiveness

        # Adaptive strategy based on reputation and trust
        if opp_rep >= 0.6:
            return True  # Cooperate with trustworthy agents
        elif opp_rep <= 0.3:
            return False  # Defect against untrustworthy agents
        else:
            # Mixed strategy with reciprocity, own reputation, and trust
            my_rep = self.reputation.get(self.agent_id, 0.5)
            trust_level = self.trust.get(opponent, 0.5)
            if my_rep > 0.5:
                # If we have good reputation, be more cooperative, but consider trust
                cooperation_prob = 0.5 + 0.4 * trust_level
                return random.random() < cooperation_prob
            else:
                # Lower reputation, more temptation to defect, but trust can help
                cooperation_prob = 0.1 + 0.4 * trust_level
                return random.random() < cooperation_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay existing observed counts to emphasize recent behavior
        for agent_id in list(self.observed_coop.keys()):
            self.observed_coop[agent_id] *= self.memory_decay
            self.observed_defect[agent_id] *= self.memory_decay

        # Update reputation scores for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.5
