            coop_count = sum(1 for _, other in recent if other == 'cooperate')
            defect_count = sum(1 for _, other in recent if other == 'defect')

            if defect_count > coop_count:
                # More defections than cooperations recently
                opp_rep *= 0.6
            elif coop_count > defect_count:
                # More cooperations than defections recently
