                elif coop_count <= 1:
                    self.risk_taking = max(-1.0, self.risk_taking - 0.05)
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)
            # Also slightly adjust risk_taking decay
            self.risk_taking *= 0.95
            # Decay volatility to avoid permanent high penalties
            for key in list(self.reputation_volatility.keys()):
                self.reputation_volatility[key] *= 0.9

