            elif last_my_action == 'defect' and last_other_action == 'cooperate':
                opp_rep = min(1.0, opp_rep * 1.5)  # Reward for forgiveness

        # Adaptive strategy based on reputation and trust
        if opp_rep >= 0.6:
            return True  # Cooperate with trustworthy agents
        elif opp_rep <= 0.3:
            return False  # Defect against untrustworthy agents
        else:
            # Mixed strategy with reciprocity, own reputation, and trust
            my_rep = self.reputation.get(self.agent_id, 0.5)
            trust_level = self.trust.get(opponent, 0.5)
            if my_rep > 0.5:
                # If we have good reputation, be more cooperative, but consider trust
