from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        # CHANGED: Replaced global forgiveness with per-agent trust that
        # updates asymmetrically: cooperation increases trust more than
        # defection decreases it, making the agent more optimistic and
        # less vindictive.
        self.trust = {}
        self.trust_increment = 0.2
        self.trust_decrement = 0.1
        self.trust_decay = 0.95  # slow decay of trust over time
        # CHANGED: Added a "benefit of the doubt" parameter that gives
        # unknown agents a slight positive bias, encouraging exploration.
        self.initial_trust = 0.55
        # CHANGED: Added a "cooperation streak" counter that tracks how
        # many consecutive times we cooperated with the opponent, making
        # us more likely to continue cooperating if the streak is long.
        self.coop_streak = {}
        self.streak_threshold = 3  # after this many, we are more trusting
        self.streak_bonus = 0.1
        # CHANGED: Removed grudge mechanism entirely; instead, we use
        # a "reciprocity" score that combines trust with our own recent
        # actions to decide.

    def _get_trust(self, agent_id: int) -> float:
        if agent_id not in self.trust:
            self.trust[agent_id] = self.initial_trust
            self.coop_streak[agent_id] = 0
        return self.trust[agent_id]

    def _update_trust(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_trust(agent_id)
        if action == 'cooperate':
            # Asymmetric update: cooperate boosts trust more than defect lowers it
            new = current + self.trust_increment
        else:
            new = current - self.trust_decrement
        self.trust[agent_id] = max(0.0, min(1.0, new))
        # Apply decay to trust over time (gentle forgetting)
        self.trust[agent_id] *= self.trust_decay
        # Ensure trust stays in [0,1] after decay
        self.trust[agent_id] = max(0.0, min(1.0, self.trust[agent_id]))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        self._update_trust(donor_id, donor_action, is_own_interaction=is_self)
        self._update_trust(recipient_id, recipient_action, is_own_interaction=is_self)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1
        # Update cooperation streak: if we cooperated, increment; else reset
        if my_action == 'cooperate':
            self.coop_streak[opponent_id] = self.coop_streak.get(opponent_id, 0) + 1
        else:
            self.coop_streak[opponent_id] = 0
        # Update trust based on our own interaction (already done in observe via _update_trust)
        # No grudge or momentum to keep this variant simple and optimistic

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            trust = self._get_trust(opponent)
            # Add streak bonus if we have cooperated consecutively enough
            streak = self.coop_streak.get(opponent, 0)
            if streak >= self.streak_threshold:
                trust += self.streak_bonus
            trust = max(0.0, min(1.0, trust))

            total_interactions = 0
            opp_coop_count = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate':
                        opp_coop_count += count
            if total_interactions > 0:
                p_opp_coop = opp_coop_count / total_interactions
                # Combine trust with observed cooperation rate
                combined = 0.6 * trust + 0.4 * p_opp_coop
                if combined > 0.65:
                    return True
                elif combined < 0.35:
                    return False
                else:
                    # Use a simple threshold based on combined score
                    return combined > 0.5
            else:
                # No history: trust alone decides, with initial optimism
                return trust > 0.5
        except Exception:
            return True

