                # More defections than cooperations recently
                opp_rep *= 0.6
            elif coop_count > defect_count:
                # More cooperations than defections recently
                opp_rep = min(1.0, opp_rep * 1.4)

        # Reciprocity-based adjustment: if we cooperated last time and they defected, be cautious
        if opponent in self.interactions and len(self.interactions[opponent]) > 0:
