                opp_rep = min(1.0, opp_rep * 1.5)  # Reward for forgiveness

        # Adaptive strategy based on reputation and trust
        if opp_rep >= 0.6:
            return True  # Cooperate with trustworthy agents
        elif opp_rep <= 0.3:
