        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        # New: memory of past defections against me to increase sensitivity
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        # New: track opponent's cooperation streaks
        self.opponent_streaks = {}
        self.streak_bonus = 0.1
        self.streak_threshold = 3
        # New: track opponent's defection streaks to exploit them
        self.opponent_defection_streaks = {}
        self.defection_streak_bonus = 0.15
        self.defection_streak_threshold = 2
        # New: track my own recent outcomes to adjust risk-taking
        self.risk_taking = 0.0  # -1 to 1, positive means more likely to cooperate
        # New: track opponent's reputation volatility to adapt trust
        self.reputation_volatility = {}
        self.volatility_threshold = 0.2
        self.volatility_decay = 0.95
        self.volatility_penalty = 0.2
        # New: track opponent's cooperation rate in the last N interactions
        self.recent_cooperation_rate = {}
        self.rate_window = 10
        self.rate_bonus = 0.15

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        # New mechanism: if I've been defected against repeatedly, increase suspicion
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        # New mechanism: reward long cooperation streaks
        if opponent in self.opponent_streaks and self.opponent_streaks[opponent] >= self.streak_threshold:
            score += self.streak_bonus * self.opponent_streaks[opponent]
        # New mechanism: punish long defection streaks (exploit them)
        if opponent in self.opponent_defection_streaks and self.opponent_defection_streaks[opponent] >= self.defection_streak_threshold:
            score -= self.defection_streak_bonus * self.opponent_defection_streaks[opponent]
