class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each agent, count cooperative and defective actions observed
        self.coop_counts = {}
        self.defect_counts = {}
        # Track personal interactions: opponent_id -> (my_actions, their_actions)
        self.personal_history = {}
        # Track defection rates for threshold-based decisions
        self.defection_rate = {}
        # Number of observations for each agent to compute reliable reputation
        self.observation_count = {}
        # Number of rounds played
        self.rounds_played = 0
        # Track if we have interacted with an agent before
        self.interacted_with = set()

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True
        # If no info about opponent, cooperate initially
        if opponent not in self.defection_rate:
            return True

        # Get opponent's defection rate based on all observed actions
        total_obs = self.coop_counts.get(opponent, 0) + self.defect_counts.get(opponent, 0)
        if total_obs == 0:
            return True

        def_rate = self.defect_counts.get(opponent, 0) / total_obs

        # If opponent has defected more than 30% of time, defect
        if def_rate > 0.3:
            return False

        # If we have personal history, use reciprocity with forgiveness
        if opponent in self.personal_history:
            my_actions, their_actions = self.personal_history[opponent]
            if their_actions and their_actions[-1] == 'defect':
                # If they defected last time we met, defect with probability 0.8
                return random.random() > 0.2
            else:
                # If they cooperated last time, cooperate
                return True

        # If opponent has low defection rate, cooperate
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update counts for donor
        self._update_counts(donor_id, donor_action)
        # Update counts for recipient
        self._update_counts(recipient_id, recipient_action)

        # If we are part of this interaction, record personal history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent = recipient_id
                my_action = donor_action
                their_action = recipient_action
            else:
                opponent = donor_id
                my_action = recipient_action
                their_action = donor_action

            if opponent not in self.personal_history:
                self.personal_history[opponent] = ([], [])
            self.personal_history[opponent][0].append(my_action)
            self.personal_history[opponent][1].append(their_action)
            self.interacted_with.add(opponent)
            self.rounds_played += 1

    def _update_counts(self, agent_id: int, action: str) -> None:
        if action == 'cooperate':
            self.coop_counts[agent_id] = self.coop_counts.get(agent_id, 0) + 1
        else:
            self.defect_counts[agent_id] = self.defect_counts.get(agent_id, 0) + 1
        # Update observation count and defection rate
        total = self.coop_counts.get(agent_id, 0) + self.defect_counts.get(agent_id, 0)
        self.observation_count[agent_id] = total
        if total > 0:
            self.defection_rate[agent_id] = self.defect_counts.get(agent_id, 0) / total

