            elif all(a == 'cooperate' for a in pattern):
                self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.1)
        threshold = self.base_cooperation_threshold - self.risk_taking * 0.1
        if score >= threshold:
            return True
        else:
            return False

