                self.opponent_streaks[other] = 0
            if other_action == 'cooperate':
                self.opponent_streaks[other] += 1
            else:
                self.opponent_streaks[other] = 0
            if other not in self.opponent_defection_streaks:
                self.opponent_defection_streaks[other] = 0
            if other_action == 'defect':
                self.opponent_defection_streaks[other] += 1
            else:
                self.opponent_defection_streaks[other] = 0
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
            if other not in self.recent_cooperation_rate:
                self.recent_cooperation_rate[other] = 0.0
            actions = [act for act, _ in self.opponent_history[other][-self.rate_window:]]
            if len(actions) > 0:
                self.recent_cooperation_rate[other] = sum(1 for a in actions if a == 'cooperate') / len(actions)
            if len(self.my_history) >= 5:
                recent = list(self.my_history)[-5:]
                coop_count = sum(1 for a in recent if a == 'cooperate')
