        mean = sum(actions) / len(actions)
        variance = sum((x - mean) ** 2 for x in actions) / len(actions)
        # Consistency is inverse of variance, normalized
        consistency = 1.0 - min(1.0, variance * 4)
        if opponent in self.coop_consistency:
            self.coop_consistency[opponent] = 0.9 * self.coop_consistency[opponent] + 0.1 * consistency
        else:
