from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        # CHANGED: Replaced per-agent trust with a single, global trust value
        # that is updated based on all observed actions. This explores a
        # simpler, more generalized trust mechanism that treats all agents
        # similarly but adapts to the overall environment.
        self.global_trust = 0.5
        self.trust_learning_rate = 0.05
        self.trust_decay = 0.99
        # CHANGED: Added a forgiveness parameter that slowly increases trust
        # after cooperation, making the agent more forgiving over time.
        self.forgiveness = 0.0
        self.forgiveness_increment = 0.01
        self.forgiveness_cap = 0.3
        # CHANGED: Replaced reputation momentum with a reputation smoothing
        # factor that averages new observations with past reputation, making
        # updates less extreme and more stable.
        self.rep_smoothing = 0.7
        # CHANGED: Added a threshold adaptation parameter that shifts the
        # cooperation threshold based on the agent's own recent actions.
        self.threshold_shift = 0.0
        self.threshold_shift_rate = 0.05

    def _get_global_trust(self) -> float:
        return self.global_trust

    def _update_global_trust(self, action: str) -> None:
        current = self._get_global_trust()
        if action == 'cooperate':
            delta = self.trust_learning_rate * (1 - current)
        else:
            delta = -self.trust_learning_rate * current
        new = current + delta
        self.global_trust = max(0.0, min(1.0, new * self.trust_decay))

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_reputation(agent_id)
        # CHANGED: Use smoothing to blend new observation with existing reputation
        target = 1.0 if action == 'cooperate' else 0.0
        new = current * self.rep_smoothing + target * (1 - self.rep_smoothing)
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        self._update_reputation(donor_id, donor_action, is_own_interaction=is_self)
        self._update_reputation(recipient_id, recipient_action, is_own_interaction=is_self)
        # CHANGED: Update global trust based on all observed actions
        self._update_global_trust(donor_action)
        self._update_global_trust(recipient_action)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
            # CHANGED: Increase forgiveness when seeing cooperation
            self.forgiveness = min(self.forgiveness_cap, self.forgiveness + self.forgiveness_increment)
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
            self.forgiveness = min(self.forgiveness_cap, self.forgiveness + self.forgiveness_increment)
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1
        # CHANGED: Adjust threshold shift based on own recent actions
        if my_action == 'cooperate':
            self.threshold_shift = max(-0.2, self.threshold_shift - self.threshold_shift_rate)
        else:
            self.threshold_shift = min(0.2, self.threshold_shift + self.threshold_shift_rate)

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            global_trust = self._get_global_trust()
            # CHANGED: Use global trust instead of per-agent trust, and add forgiveness
            combined_score = 0.7 * rep + 0.3 * global_trust + self.forgiveness
            # CHANGED: Apply threshold shift to make behavior more adaptive
            threshold = 0.5 - self.threshold_shift
            total_interactions = 0
            coop_when_opp_coop = 0
            coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate' and my == 'cooperate':
                        coop_when_opp_coop += count
                    if their == 'defect' and my == 'cooperate':
                        coop_when_opp_defect += count
            if total_interactions > 0:
                opp_coop_count = sum(count for (opp, my, their), count in self.interaction_history.items()
                                     if opp == opponent and their == 'cooperate')
                p_opp_coop = opp_coop_count / total_interactions
                p_my_coop_given_opp_coop = (coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
                # CHANGED: Use global trust in history weighting
                if total_interactions >= 2:
                    hist_coop_rate = opp_coop_count / total_interactions
                    weight_hist = min(0.5, total_interactions * 0.1)
                    combined_score = combined_score * (1 - weight_hist) + hist_coop_rate * weight_hist
                # CHANGED: Use adaptive threshold
                if combined_score > threshold + 0.2:
                    return True
                elif combined_score < threshold - 0.2:
                    return False
                else:
                    if total_interactions >= 2:
                        return p_opp_coop > threshold
                    else:
                        return combined_score > threshold
            else:
                return combined_score > threshold
        except Exception:
            return True

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        # New: memory of past defections against me to increase sensitivity
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        # New: track opponent's variance in behavior to detect unpredictability
        self.action_variance = {}
        self.variance_weight = 0.2
        # New: exponential moving average of opponent cooperation to detect trends
        self.coop_trend = {}
        self.trend_weight = 0.25
        # Exploration: add a "generosity" parameter that decays over time
        self.generosity = 0.3
        self.generosity_decay = 0.005

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-10:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        """Update exponential moving average of opponent's cooperation (1) or defection (0)."""
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        # New mechanism: if opponent's trend is strongly cooperative, boost score; if strongly defective, penalize
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]  # 0 to 1
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3  # up to +0.25
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3  # up to -0.25
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        # New exploration: add a generosity bonus that decays over time
        score += self.generosity
        # Decay generosity each decision
        self.generosity = max(0.0, self.generosity - self.generosity_decay)
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            self._update_variance(other, other_action)
            self._update_trend(other, other_action)
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        # New: track probability of reciprocity based on opponent's past behavior
        self.reciprocity_history = {}
        self.reciprocity_weight = 0.4  # How much to weight reciprocity vs direct trust
        self.reciprocity_decay = 0.9
        # New: track opponent's tendency to retaliate against my defections
        self.retaliation_scores = {}
        self.retaliation_bonus = 0.2
        # New: track my own defection frequency to moderate aggression
        self.self_defection_rate = 0.0
        self.self_adjustment = 0.1
        # New: track opponent's action volatility (how often they switch)
        self.action_volatility = {}
        self.volatility_bonus = 0.1
        self.volatility_threshold = 0.4

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # Direct trust based on reputation and cooperation count
        direct_score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        # Reciprocity component based on opponent's past responses to my actions
        reciprocity_score = 0.0
        if opponent in self.reciprocity_history and len(self.reciprocity_history[opponent]) > 0:
            # Calculate how often they cooperate after I cooperate vs after I defect
            coop_after_coop = 0
            coop_after_defect = 0
            total_coop = 0
            total_defect = 0
            for my_act, opp_act in self.reciprocity_history[opponent][-20:]:
                if my_act == 'cooperate':
                    total_coop += 1
                    if opp_act == 'cooperate':
                        coop_after_coop += 1
                else:
                    total_defect += 1
                    if opp_act == 'cooperate':
                        coop_after_defect += 1
            if total_coop > 0:
                prob_coop_given_coop = coop_after_coop / total_coop
            else:
                prob_coop_given_coop = 0.5
            if total_defect > 0:
                prob_coop_given_defect = coop_after_defect / total_defect
            else:
                prob_coop_given_defect = 0.5
            # Reciprocity score: positive if they cooperate more after I cooperate
            reciprocity_score = prob_coop_given_coop - prob_coop_given_defect
        # Combine direct and reciprocity scores
        score = (1 - self.reciprocity_weight) * direct_score + self.reciprocity_weight * reciprocity_score
        # Recent defections penalty
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        # Retaliation bonus: if opponent tends to defect after I defect, avoid defecting
        if opponent in self.retaliation_scores and self.retaliation_scores[opponent] > 0.5:
            score -= self.retaliation_bonus * (self.retaliation_scores[opponent] - 0.5) * 2
        # Action volatility penalty: unpredictable opponents are risky
        if opponent in self.action_volatility and self.action_volatility[opponent] > self.volatility_threshold:
            score -= 0.1 * (self.action_volatility[opponent] - self.volatility_threshold)
        # Self-defection adjustment: if I've been defecting a lot, be more cautious
        if self.self_defection_rate > 0.6:
            score -= self.self_adjustment * (self.self_defection_rate - 0.6)
        # Adaptive threshold based on recent outcomes
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation (standard)
        if donor_id != self.agent_id:
            old_rep = self.reputation.get(donor_id, 0.5)
            if donor_action == 'cooperate':
                new_rep = old_rep * 0.85 + 0.15
            else:
                new_rep = old_rep * 0.85
            self.reputation[donor_id] = new_rep
        if recipient_id != self.agent_id:
            old_rep = self.reputation.get(recipient_id, 0.5)
            if recipient_action == 'cooperate':
                new_rep = old_rep * 0.85 + 0.15
            else:
                new_rep = old_rep * 0.85
            self.reputation[recipient_id] = new_rep
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            # Track reciprocity history: (my_action, opponent_action)
            if other not in self.reciprocity_history:
                self.reciprocity_history[other] = []
            self.reciprocity_history[other].append((my_action, other_action))
            if len(self.reciprocity_history[other]) > 30:
                self.reciprocity_history[other].pop(0)
            # Update trust
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
            # Update action volatility
            if other not in self.action_volatility:
                self.action_volatility[other] = 0.0
            if len(self.recent_actions[other]) >= 2:
                last_two = self.recent_actions[other][-2:]
                if last_two[0] != last_two[1]:
                    self.action_volatility[other] = self.action_volatility[other] * 0.8 + 0.2
                else:
                    self.action_volatility[other] = self.action_volatility[other] * 0.8
            # Update retaliation score: probability opponent defects after I defect
            if other in self.reciprocity_history and len(self.reciprocity_history[other]) > 0:
                my_defects = [pair for pair in self.reciprocity_history[other] if pair[0] == 'defect']
                if len(my_defects) > 0:
                    retaliation = sum(1 for my_act, opp_act in my_defects if opp_act == 'defect') / len(my_defects)
                    # Smooth update
                    if other not in self.retaliation_scores:
                        self.retaliation_scores[other] = retaliation
                    else:
                        self.retaliation_scores[other] = self.retaliation_scores[other] * 0.9 + retaliation * 0.1
            # Update self_defection_rate based on my history
            if len(self.my_history) > 0:
                self.self_defection_rate = sum(1 for a in self.my_history if a == 'defect') / len(self.my_history)
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)
            # Decay reciprocity weight slightly over time to rely more on direct signals
            self.reciprocity_weight = max(0.2, self.reciprocity_weight * self.reciprocity_decay)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_history = {}
        self.own_recent_actions = deque(maxlen=10)
        # CHANGED: Replaced global generosity with per-agent trust scores.
        # This explores a more individualized strategy that tracks the
        # trustworthiness of each agent separately.
        self.trust = {}
        self.trust_learning_rate = 0.1
        self.trust_decay = 0.99
        # CHANGED: Added a reputation momentum factor that makes reputation
        # updates trend in the same direction, creating stronger polarization.
        self.rep_momentum = {}
        self.rep_momentum_decay = 0.8
        self.rep_volatility = 0.1
        # CHANGED: Added a risk-aversion parameter that scales with observed
        # defections, making the agent more cautious in uncertain situations.
        self.risk_aversion = 0.0
        self.risk_aversion_increment = 0.02
        self.risk_aversion_cap = 0.5

    def _get_trust(self, agent_id: int) -> float:
        if agent_id not in self.trust:
            self.trust[agent_id] = 0.5
        return self.trust[agent_id]

    def _update_trust(self, agent_id: int, action: str) -> None:
        current = self._get_trust(agent_id)
        if action == 'cooperate':
            delta = self.trust_learning_rate * (1 - current)
        else:
            delta = -self.trust_learning_rate * current
        new = current + delta
        self.trust[agent_id] = max(0.0, min(1.0, new * self.trust_decay))

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id: int, action: str, is_own_interaction: bool = False) -> None:
        current = self._get_reputation(agent_id)
        weight = self.rep_volatility
        if is_own_interaction:
            weight += 0.02
        # CHANGED: Added momentum: reputation changes carry over, making
        # streaks more impactful and creating more extreme opinions.
        momentum = self.rep_momentum.get(agent_id, 0.0)
        if action == 'cooperate':
            target = 1.0
        else:
            target = 0.0
        surprise = target - current
        new = current + surprise * weight + momentum
        # Update momentum in the direction of the change
        self.rep_momentum[agent_id] = (surprise * weight + momentum) * self.rep_momentum_decay
        self.reputation[agent_id] = max(0.0, min(1.0, new))

    def _record_observation(self, donor_id: int, donor_action: str,
                            recipient_id: int, recipient_action: str,
                            is_self: bool = False) -> None:
        self._update_reputation(donor_id, donor_action, is_own_interaction=is_self)
        self._update_reputation(recipient_id, recipient_action, is_own_interaction=is_self)
        # CHANGED: Update per-agent trust based on observed actions
        self._update_trust(donor_id, donor_action)
        self._update_trust(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
            # CHANGED: Increase risk aversion when seeing others defect
            self.risk_aversion = min(self.risk_aversion_cap, self.risk_aversion + self.risk_aversion_increment)
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1
            self.risk_aversion = min(self.risk_aversion_cap, self.risk_aversion + self.risk_aversion_increment)

    def _record_own_interaction(self, opponent_id: int, my_action: str,
                                opp_action: str) -> None:
        key = (opponent_id, my_action, opp_action)
        self.interaction_history[key] = self.interaction_history.get(key, 0) + 1

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        try:
            is_self = (donor_id == self.agent_id or recipient_id == self.agent_id)
            self._record_observation(donor_id, donor_action, recipient_id, recipient_action, is_self)

            if donor_id == self.agent_id:
                self._record_own_interaction(recipient_id, donor_action, recipient_action)
                self.own_recent_actions.append(donor_action)
            elif recipient_id == self.agent_id:
                self._record_own_interaction(donor_id, recipient_action, donor_action)
                self.own_recent_actions.append(recipient_action)
        except Exception:
            pass

    def decide(self) -> bool:
        try:
            opponent = self._ctx_opponent_id
            rep = self._get_reputation(opponent)
            trust = self._get_trust(opponent)
            # CHANGED: Combine reputation with trust, and subtract risk aversion
            combined_score = 0.7 * rep + 0.3 * trust - self.risk_aversion
            total_interactions = 0
            coop_when_opp_coop = 0
            coop_when_opp_defect = 0
            for (opp, my, their), count in self.interaction_history.items():
                if opp == opponent:
                    total_interactions += count
                    if their == 'cooperate' and my == 'cooperate':
                        coop_when_opp_coop += count
                    if their == 'defect' and my == 'cooperate':
                        coop_when_opp_defect += count
            if total_interactions > 0:
                opp_coop_count = sum(count for (opp, my, their), count in self.interaction_history.items()
                                     if opp == opponent and their == 'cooperate')
                p_opp_coop = opp_coop_count / total_interactions
                p_my_coop_given_opp_coop = (coop_when_opp_coop / opp_coop_count) if opp_coop_count > 0 else 0.5
                # CHANGED: Use combined score instead of just rep, and add a
                # history weight that's more moderate
                if total_interactions >= 2:
                    hist_coop_rate = opp_coop_count / total_interactions
                    weight_hist = min(0.6, total_interactions * 0.1)
                    combined_score = combined_score * (1 - weight_hist) + hist_coop_rate * weight_hist
                # CHANGED: Thresholds shifted due to risk aversion making the
                # agent more likely to defect when uncertain
                if combined_score > 0.7:
                    return True
                elif combined_score < 0.3:
                    return False
                else:
                    if total_interactions >= 2:
                        threshold = 0.5 - (combined_score - 0.5) * 0.2
                        return p_opp_coop > threshold
                    else:
                        return combined_score > 0.5
            else:
                return combined_score > 0.5
        except Exception:
            return True

