        self.reciprocation_rate = {}
        self.reciprocation_weight = 0.15
        # New: track opponent's defection streak to escalate penalties
        self.defection_streak = {}
        self.streak_penalty = 0.2
        # New: track opponent's cooperation consistency (standard deviation)
        self.coop_consistency = {}
        self.consistency_weight = 0.15
        # New: track long-term cooperation ratio for each opponent
        self.long_term_coop = {}
        self.long_term_weight = 0.2
        # New: track opponent's tendency to defect after cooperating (betrayal)
        self.betrayal_rate = {}
        self.betrayal_weight = 0.1
        # New: track opponent's action history for consistency calculation
        self.action_history = {}
        # Mutation: add a mechanism that predicts opponent's next action using a simple Markov model
        # and adjusts score based on the probability of cooperation.
        self.markov_model = {}  # opponent -> { 'coop_coop': prob, 'coop_defect': prob, 'defect_coop': prob, 'defect_defect': prob }
        self.markov_weight = 0.2
        self.markov_bias = 0.0  # bias towards predicted cooperation
        # New mutation: track exponential moving average of opponent's cooperation probability
        # and use it to adjust the base cooperation threshold dynamically per opponent
        self.opponent_coop_ema = {}
        self.ema_weight = 0.15
        self.ema_threshold_adjustment = 0.1

    def _update_consistency(self, opponent: int, action: str) -> None:
        """Update a measure of how consistent opponent's actions are (low variance = high consistency)."""
        if opponent not in self.action_history:
            self.action_history[opponent] = deque(maxlen=20)
        self.action_history[opponent].append(1 if action == 'cooperate' else 0)
        if len(self.action_history[opponent]) < 5:
            return
        actions = list(self.action_history[opponent])
        mean = sum(actions) / len(actions)
        variance = sum((x - mean) ** 2 for x in actions) / len(actions)
        # Consistency is inverse of variance, normalized
        consistency = 1.0 - min(1.0, variance * 4)
        if opponent in self.coop_consistency:
            self.coop_consistency[opponent] = 0.9 * self.coop_consistency[opponent] + 0.1 * consistency
        else:
            self.coop_consistency[opponent] = consistency

    def _update_long_term_coop(self, opponent: int, action: str) -> None:
        """Update long-term cooperation ratio with exponential decay."""
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.long_term_coop:
            self.long_term_coop[opponent] = value
        else:
            self.long_term_coop[opponent] = 0.95 * self.long_term_coop[opponent] + 0.05 * value

    def _update_betrayal(self, opponent: int, my_action: str, other_action: str) -> None:
        """Track how often opponent defects right after I cooperated (betrayal)."""
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 1:
            return
        # Check if my previous action was cooperate and opponent now defects
        if len(self.my_history) >= 1 and self.my_history[-1] == 'cooperate' and other_action == 'defect':
            if opponent in self.betrayal_rate:
                self.betrayal_rate[opponent] = self.betrayal_rate[opponent] * 0.9 + 0.1
            else:
                self.betrayal_rate[opponent] = 0.1
        else:
            if opponent in self.betrayal_rate:
                self.betrayal_rate[opponent] = self.betrayal_rate[opponent] * 0.9
            else:
                self.betrayal_rate[opponent] = 0.0

    def _update_markov_model(self, opponent: int, action: str) -> None:
        """Update a simple Markov model for opponent's action transition probabilities."""
        if opponent not in self.markov_model:
            self.markov_model[opponent] = {'coop_coop': 0.5, 'coop_defect': 0.5, 'defect_coop': 0.5, 'defect_defect': 0.5}
        # Get the opponent's last action if available
        last_action = None
        if opponent in self.recent_actions and self.recent_actions[opponent]:
            last_action = self.recent_actions[opponent][-1]
        if last_action is not None:
            # Update the transition probability based on last action and current action
            if last_action == 'cooperate':
                if action == 'cooperate':
                    self.markov_model[opponent]['coop_coop'] = self.markov_model[opponent]['coop_coop'] * 0.9 + 0.1
                    self.markov_model[opponent]['coop_defect'] = 1 - self.markov_model[opponent]['coop_coop']
                else:
                    self.markov_model[opponent]['coop_defect'] = self.markov_model[opponent]['coop_defect'] * 0.9 + 0.1
                    self.markov_model[opponent]['coop_coop'] = 1 - self.markov_model[opponent]['coop_defect']
            else:  # last_action == 'defect'
                if action == 'cooperate':
                    self.markov_model[opponent]['defect_coop'] = self.markov_model[opponent]['defect_coop'] * 0.9 + 0.1
                    self.markov_model[opponent]['defect_defect'] = 1 - self.markov_model[opponent]['defect_coop']
                else:
                    self.markov_model[opponent]['defect_defect'] = self.markov_model[opponent]['defect_defect'] * 0.9 + 0.1
                    self.markov_model[opponent]['defect_coop'] = 1 - self.markov_model[opponent]['defect_defect']

    def _predict_cooperation_probability(self, opponent: int) -> float:
        """Predict probability that opponent will cooperate next based on Markov model."""
        if opponent not in self.markov_model:
            return 0.5
        # Get opponent's last action
        last_action = None
        if opponent in self.recent_actions and self.recent_actions[opponent]:
            last_action = self.recent_actions[opponent][-1]
        if last_action is None:
            return 0.5
        if last_action == 'cooperate':
            return self.markov_model[opponent]['coop_coop']
        else:
            return self.markov_model[opponent]['defect_coop']

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        # New mechanism: if opponent's trend is strongly cooperative, boost score; if strongly defective, penalize
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]  # 0 to 1
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3  # up to +0.25
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3  # up to -0.25
        # New: dynamically adjust forgiveness based on opponent's recent cooperation rate
        if opponent in self.opponent_recent_coop:
            recent_coop_rate = self.opponent_recent_coop[opponent]
            if recent_coop_rate > 0.7:
                self.forgiveness = min(0.4, self.forgiveness + self.forgiveness_adjustment)
            elif recent_coop_rate < 0.3:
                self.forgiveness = max(0.1, self.forgiveness - self.forgiveness_adjustment)
            score += self.dynamic_forgiveness * (recent_coop_rate - 0.5)  # small boost/penalty
        # New mechanism: use opponent's reciprocation rate to adjust score
        if opponent in self.reciprocation_rate:
            recip = self.reciprocation_rate[opponent]
            if recip > 0.6:
                score += self.reciprocation_weight * (recip - 0.6) / 0.4  # up to +0.15
            elif recip < 0.4:
                score -= self.reciprocation_weight * (0.4 - recip) / 0.4  # up to -0.15
        # New mechanism: escalate penalty for consecutive defections
        if opponent in self.defection_streak and self.defection_streak[opponent] > 0:
            score -= self.streak_penalty * self.defection_streak[opponent]
        # New: consistency bonus (reward for predictable behavior)
        if opponent in self.coop_consistency:
            consistency = self.coop_consistency[opponent]
            if consistency > 0.6:
                score += self.consistency_weight * (consistency - 0.6) / 0.4  # up to +0.15
            elif consistency < 0.3:
                score -= self.consistency_weight * (0.3 - consistency) / 0.3  # up to -0.15
        # New: long-term cooperation ratio adjustment
        if opponent in self.long_term_coop:
            ltc = self.long_term_coop[opponent]
            if ltc > 0.7:
                score += self.long_term_weight * (ltc - 0.7) / 0.3  # up to +0.2
            elif ltc < 0.3:
                score -= self.long_term_weight * (0.3 - ltc) / 0.3  # up to -0.2
        # New: betrayal penalty - if opponent often defects after I cooperate
        if opponent in self.betrayal_rate:
            betrayal = self.betrayal_rate[opponent]
            if betrayal > 0.2:
                score -= self.betrayal_weight * (betrayal - 0.2) / 0.8  # up to -0.1
        # Mutation: Add Markov model prediction adjustment
        predicted_coop_prob = self._predict_cooperation_probability(opponent)
        # Adjust score based on predicted cooperation probability with bias
        score += self.markov_weight * (predicted_coop_prob - 0.5) + self.markov_bias * (predicted_coop_prob - 0.5)
        # New mutation: use EMA of opponent cooperation probability to adjust base threshold
        if opponent in self.opponent_coop_ema:
            ema = self.opponent_coop_ema[opponent]
            # If opponent is very cooperative, lower threshold to cooperate more; if very defective, raise
            if ema > 0.7:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.ema_threshold_adjustment)
            elif ema < 0.3:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.ema_threshold_adjustment)
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)

