        if opponent in self.recent_actions and self.recent_actions[opponent]:
            last_action = self.recent_actions[opponent][-1]
        if last_action is None:
            return 0.5
        if last_action == 'cooperate':
            return self.markov_model[opponent]['coop_coop']
        else:
            return self.markov_model[opponent]['defect_coop']

