        if opponent in self.coop_consistency:
            consistency = self.coop_consistency[opponent]
            if consistency > 0.6:
                score += self.consistency_weight * (consistency - 0.6) / 0.4  # up to +0.15
            elif consistency < 0.3:
                score -= self.consistency_weight * (0.3 - consistency) / 0.3  # up to -0.15
        # New: long-term cooperation ratio adjustment
        if opponent in self.long_term_coop:
            ltc = self.long_term_coop[opponent]
            if ltc > 0.7:
