                self.retaliation[other] = 0.9 * self.retaliation[other] + 0.1 * 0.0
            elif other_action == 'defect':
                # Retaliatory: defected in response to my defection
                self.generosity[other] = 0.9 * self.generosity[other] + 0.1 * 0.0
                self.retaliation[other] = 0.9 * self.retaliation[other] + 0.1 * 1.0

