                self.pattern_memory[other].pop(0)
            # Update streak tracking (unchanged)
            if other not in self.opponent_streaks:
                self.opponent_streaks[other] = 0
            if other_action == 'cooperate':
                self.opponent_streaks[other] += 1
            else:
                self.opponent_streaks[other] = 0
            if other not in self.opponent_defection_streaks:
                self.opponent_defection_streaks[other] = 0
            if other_action == 'defect':
                self.opponent_defection_streaks[other] += 1
            else:
                self.opponent_defection_streaks[other] = 0
            # Modified: update opponent-specific forgiveness based on outcomes
            if other not in self.opponent_forgiveness:
                self.opponent_forgiveness[other] = self.forgiveness_base
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
                # Increase forgiveness for cooperative partners, up to cap
                self.opponent_forgiveness[other] = min(self.forgiveness_cap, self.opponent_forgiveness[other] + self.forgiveness_boost)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
                # Decrease forgiveness after defection, but not below base
                self.opponent_forgiveness[other] = max(self.forgiveness_base, self.opponent_forgiveness[other] - self.forgiveness_boost)
            if other not in self.recent_cooperation_rate:
                self.recent_cooperation_rate[other] = 0.0
            actions = [act for act, _ in self.opponent_history[other][-self.rate_window:]]
            if len(actions) > 0:
                self.recent_cooperation_rate[other] = sum(1 for a in actions if a == 'cooperate') / len(actions)
            if len(self.my_history) >= 5:
                recent = list(self.my_history)[-5:]
                coop_count = sum(1 for a in recent if a == 'cooperate')
                if coop_count >= 4:
                    self.risk_taking = min(1.0, self.risk_taking + 0.05)
                elif coop_count <= 1:
                    self.risk_taking = max(-1.0, self.risk_taking - 0.05)
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)
            self.risk_taking *= 0.95
            for key in list(self.reputation_volatility.keys()):
                self.reputation_volatility[key] *= 0.9
            # Also decay opponent-specific forgiveness over time
            for key in list(self.opponent_forgiveness.keys()):
                self.opponent_forgiveness[key] = max(self.forgiveness_base, self.opponent_forgiveness[key] * 0.95)

