        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_generosity_retaliation(self, other: int, my_action: str, other_action: str) -> None:
        """Track opponent's generosity (cooperate when I defected) and retaliation (defect when I defected)."""
        if other not in self.generosity:
            self.generosity[other] = 0.5
        if other not in self.retaliation:
            self.retaliation[other] = 0.5
        if my_action == 'defect':
            if other_action == 'cooperate':
                # Generous: cooperated despite my defection
                self.generosity[other] = 0.9 * self.generosity[other] + 0.1 * 1.0
                self.retaliation[other] = 0.9 * self.retaliation[other] + 0.1 * 0.0
            elif other_action == 'defect':
                # Retaliatory: defected in response to my defection
                self.generosity[other] = 0.9 * self.generosity[other] + 0.1 * 0.0
                self.retaliation[other] = 0.9 * self.retaliation[other] + 0.1 * 1.0

