            # If opponent has low reputation, increase penalty
            elif rep < 0.3:
                score -= self.rep_forgiveness_weight * (0.3 - rep) / 0.3
        # New: incorporate balance of cooperation vs defection for opponent
        if opponent in self.opponent_coop_balance:
            balance = self.opponent_coop_balance[opponent]  # positive = more coop, negative = more defect
            score += self.balance_weight * balance
        # New: reward generous opponents (cooperate when I defected) and penalize retaliatory ones
        if opponent in self.generosity:
