        coop_count = 0
        if donor_action == 'cooperate':
            coop_count += 1
        if recipient_action == 'cooperate':
            coop_count += 1
        self.pop_coop_rate = self.pop_coop_rate * 0.99 + (coop_count/2) * 0.01

