            elif recent_coop_rate < 0.3:
                self.forgiveness = max(self.min_forgiveness, self.forgiveness - self.forgiveness_adjustment)
            score += self.dynamic_forgiveness * (recent_coop_rate - 0.5)  # small boost/penalty
        # New: forgiveness modulated by opponent's reputation
        if opponent in self.reputation:
            rep = self.reputation[opponent]
            # If opponent has high reputation, increase forgiveness (reduce penalty)
            if rep > 0.7:
                score += self.rep_forgiveness_weight * (rep - 0.7) / 0.3
            # If opponent has low reputation, increase penalty
            elif rep < 0.3:
                score -= self.rep_forgiveness_weight * (0.3 - rep) / 0.3
        # New: incorporate balance of cooperation vs defection for opponent
        if opponent in self.opponent_coop_balance:
            balance = self.opponent_coop_balance[opponent]  # positive = more coop, negative = more defect
            score += self.balance_weight * balance
        # New: reward generous opponents (cooperate when I defected) and penalize retaliatory ones
        if opponent in self.generosity:
            generosity = self.generosity[opponent]
            score += self.generosity_weight * (generosity - 0.5)  # up to +0.1 for generous, -0.1 for stingy
        if opponent in self.retaliation:
