                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
            # Update balance: +1 for cooperation, -1 for defection, bounded to avoid extremes
            if other not in self.opponent_coop_balance:
                self.opponent_coop_balance[other] = 0
            if other_action == 'cooperate':
                self.opponent_coop_balance[other] = min(5, self.opponent_coop_balance[other] + 1)
            else:
                self.opponent_coop_balance[other] = max(-5, self.opponent_coop_balance[other] - 1)
            # New: update generosity and retaliation based on my action and opponent's response
            self._update_generosity_retaliation(other, my_action, other_action)
        self.round += 1
        if self.round % 50 == 0:
