class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        # Track reputation scores for each agent (including self)
        self.reputation = {}
        # Track cooperation counts for each agent
        self.coop_counts = {}
        self.total_counts = {}
        # Track interaction history with each opponent
        self.interaction_history = {}
        # Track recent outcomes for adaptive strategy
        self.recent_outcomes = []
        # Generation counter for periodic strategy shifts
        self.round_count = 0
        # Track if we've been exploited recently
        self.exploited_recently = False

    def decide(self) -> bool:
        self.round_count += 1
        opponent = self._ctx_opponent_id
        self.opponent_id = opponent

        # Get opponent's reputation and history
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop_rate = self._get_coop_rate(opponent)
        history = self.interaction_history.get(opponent, [])

        # Initial trust: cooperate unless opponent has bad reputation
        if len(history) == 0:
            # Start with cooperation but be cautious with very bad reputations
            if opp_rep < 0.3:
                return False
            return True

        # Adaptive strategy based on opponent's behavior
        # Count recent own outcomes with this opponent
        recent_own = [outcome for outcome in history[-5:] if outcome[0] == self.agent_id]
        if not recent_own:
            # No direct history, use reputation
            return opp_rep >= 0.4

        # Calculate opponent's cooperation rate in recent interactions
        recent_opp_coop = sum(1 for outcome in recent_own if outcome[1] == 'cooperate')
        recent_rate = recent_opp_coop / len(recent_own)

        # Detect if we've been exploited (opponent defected when we cooperated)
        exploited = any(
            outcome[0] == self.agent_id and outcome[1] == 'cooperate' and 
            outcome[2] == 'defect' for outcome in recent_own
        )

        if exploited:
            self.exploited_recently = True
            # Punish but offer forgiveness after a few rounds
            if len(recent_own) >= 3 and recent_rate < 0.3:
                return False
            # If opponent starts cooperating, return to cooperation
            if recent_rate >= 0.5:
                return True
            return False

        self.exploited_recently = False

        # Tit-for-tat with forgiveness: cooperate if opponent cooperated recently
        if recent_rate >= 0.5:
            return True
        elif recent_rate >= 0.3:
            # Forgive occasionally with random chance
            return random.random() < 0.3
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for the donor
        if donor_id not in self.reputation:
            self.reputation[donor_id] = 0.5
        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.1)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.15)

        # Update reputation for the recipient (their action also matters)
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = 0.5
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.1)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.15)

        # Update cooperation counts
        self._update_counts(donor_id, donor_action)
        self._update_counts(recipient_id, recipient_action)

        # If we are involved in this interaction, record it for our history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action

            if other_id not in self.interaction_history:
                self.interaction_history[other_id] = []
            self.interaction_history[other_id].append(
                (self.agent_id, my_action, other_action)
            )
            # Keep history manageable
            if len(self.interaction_history[other_id]) > 20:
                self.interaction_history[other_id] = self.interaction_history[other_id][-20:]

            # Track recent outcomes for global adaptation
            self.recent_outcomes.append((my_action, other_action))
            if len(self.recent_outcomes) > 30:
                self.recent_outcomes = self.recent_outcomes[-30:]

    def _get_coop_rate(self, agent_id: int) -> float:
        total = self.total_counts.get(agent_id, 0)
        if total == 0:
            return 0.5
        return self.coop_counts.get(agent_id, 0) / total

    def _update_counts(self, agent_id: int, action: str) -> None:
        if agent_id not in self.total_counts:
            self.total_counts[agent_id] = 0
            self.coop_counts[agent_id] = 0
        self.total_counts[agent_id] += 1
        if action == 'cooperate':
            self.coop_counts[agent_id] += 1

