                self.optimism = 0.9 * self.optimism + 0.1 * 0.1
            else:
                self.optimism = 0.9 * self.optimism + 0.1 * 0.0

            if len(self.recent_outcomes) >= 5:
                coop_rate_recent = sum(self.recent_outcomes[-5:]) / 5
