            # Track my recent actions
            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 10:
                self.my_recent_actions.pop(0)

            self.last_my_action = my_action
            self.last_opp_action = opp_action

            # New: update exploitation tracker
            if my_action == 'cooperate' and opp_action == 'defect':
                self.exploited_by[opp_id] = self.exploited_by.get(opp_id, 0) + 1
            elif my_action == 'defect' and opp_action == 'cooperate':
                self.exploited_by[opp_id] = self.exploited_by.get(opp_id, 0) - 1
                if self.exploited_by[opp_id] < 0:
                    self.exploited_by[opp_id] = 0

            if my_action == 'cooperate' and opp_action == 'cooperate':
                self.optimism = 0.9 * self.optimism + 0.1 * 0.3
            elif my_action == 'cooperate' and opp_action == 'defect':
