import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_counts = {}
        self.my_actions = []
        self.my_partners = []
        self.base_generosity = 0.6
        self.recent_outcomes = []
        self.forget_factor = 0.9
        self.rounds_played = 0
        self.my_payoff = 0
        self.pop_coop_rate = 0.5
        self.last_my_action = None
        self.last_opp_action = None
        self.adaptation = 1.0
        self.rep_update_count = {}
        self.confidence_threshold = 5
        self.optimism = 0.0
        self.opp_recent_actions = {}
        # New: track personal history of cooperation to condition on
        self.my_recent_actions = []
        # New: track whether we've been exploited by each opponent
        self.exploited_by = {}
        # New: threshold for distrust after being exploited
        self.distrust_threshold = 0.3

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, 0.5)
        inter = self.interaction_counts.get(opponent, {'cc':0, 'cd':0, 'dc':0, 'dd':0})
        total_inter = sum(inter.values())
        if total_inter > 0:
            coop_when_we_coop = inter.get('cc',0) / max(1, inter.get('cc',0)+inter.get('cd',0))
            opp_coop = (inter.get('cc',0)+inter.get('dc',0)) / max(1, total_inter)
            effective_rep = 0.7 * opp_coop + 0.3 * rep
        else:
            effective_rep = rep

        obs_count = self.rep_update_count.get(opponent, 0)
        if obs_count < self.confidence_threshold:
            effective_rep *= (obs_count / self.confidence_threshold) * 0.5 + 0.5

        effective_rep += self.optimism * 0.2

        recent_opp_actions = self.opp_recent_actions.get(opponent, [])
        if len(recent_opp_actions) > 0:
            recent_opp_coop_rate = sum(1 for a in recent_opp_actions if a == 'cooperate') / len(recent_opp_actions)
            effective_rep += (recent_opp_coop_rate - 0.5) * 0.15

        # New: if we've been exploited recently by this opponent, reduce rep much more
        if self.exploited_by.get(opponent, 0) > 0:
            effective_rep -= self.exploited_by[opponent] * 0.2
            # If we've been exploited multiple times, be very cautious
            if self.exploited_by[opponent] >= 2:
                effective_rep *= 0.5

        threshold = 0.4 + (1 - self.pop_coop_rate) * 0.2
        if self.rounds_played > 10:
            avg_payoff = self.my_payoff / self.rounds_played
            if avg_payoff > 2.5:
                threshold -= 0.1
            elif avg_payoff < 1.5:
                threshold += 0.1

        if self.rounds_played > 0 and self.last_my_action == 'cooperate' and self.last_opp_action == 'defect':
            threshold += 0.15 * self.adaptation
        elif self.rounds_played > 0 and self.last_my_action == 'defect' and self.last_opp_action == 'cooperate':
            threshold -= 0.05 * self.adaptation

        # New: if I've been cooperating a lot recently, be slightly more willing to cooperate
        if len(self.my_recent_actions) >= 5:
            my_recent_coop_rate = sum(1 for a in self.my_recent_actions[-5:] if a == 'cooperate') / 5
            threshold -= (my_recent_coop_rate - 0.5) * 0.1

        noise = random.uniform(-0.05, 0.05)
        decision_threshold = threshold + noise

        return effective_rep > decision_threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, agent_action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
