                    self.adaptation = max(0.5, self.adaptation * 0.95)

        coop_count = 0
        if donor_action == 'cooperate':
            coop_count += 1
        if recipient_action == 'cooperate':
            coop_count += 1
        self.pop_coop_rate = self.pop_coop_rate * 0.99 + (coop_count/2) * 0.01

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        # New: memory of past defections against me to increase sensitivity
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        # New: track opponent's variance in behavior to detect unpredictability
        self.action_variance = {}
        self.variance_weight = 0.2
        # New: exponential moving average of opponent cooperation to detect trends
        self.coop_trend = {}
        self.trend_weight = 0.25
        # New: track opponent's recent cooperation count to adjust forgiveness dynamically
        self.opponent_recent_coop = {}
        self.dynamic_forgiveness = 0.1
        self.forgiveness_adjustment = 0.05
        # New: reputation-based forgiveness modulation
        self.rep_forgiveness_weight = 0.15
        self.max_forgiveness = 0.5
        self.min_forgiveness = 0.05
        # New: track accumulated cooperation vs defection for opponent to adjust threshold
        self.opponent_coop_balance = {}
        self.balance_weight = 0.15
        # New: track opponent's streak of consecutive defections to punish more severely
        self.defection_streak = {}
        self.streak_penalty = 0.2
        self.streak_threshold = 3
        # New: track opponent's total interactions to weight recent vs all history
        self.interaction_count = {}
        # New: adaptive reciprocity bias that decreases if overly cooperative/defective
        self.reciprocity_bias = 0.3
        self.reciprocity_adaptation_rate = 0.01
        # New: threshold for detecting "too cooperative" to avoid exploitation
        self.max_cooperation_threshold = 0.7
        self.min_cooperation_threshold = 0.3
        # New mechanism: track opponent's recent defection count for exponential decay
        self.recent_defection_count = {}
        self.decay_factor = 0.9
        self.defection_decay_weight = 0.3
        # New: exploration mechanism: pattern-based response using last 3 interactions
        self.pattern_history = {}
        self.pattern_length = 3
        self.pattern_boost = 0.15
        self.pattern_penalty = 0.15

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-10:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        """Update exponential moving average of opponent's cooperation (1) or defection (0)."""
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_pattern(self, opponent: int, action: str) -> None:
        """Update pattern history for opponent and compute pattern-based adjustment."""
        if opponent not in self.pattern_history:
            self.pattern_history[opponent] = deque(maxlen=self.pattern_length)
        self.pattern_history[opponent].append(1 if action == 'cooperate' else 0)
        # Calculate pattern score: if last pattern is all defections, penalize; if all cooperations, boost
        if len(self.pattern_history[opponent]) == self.pattern_length:
            pattern = list(self.pattern_history[opponent])
            if all(p == 0 for p in pattern):
                self._current_pattern_penalty[opponent] = self.pattern_penalty
            elif all(p == 1 for p in pattern):
                self._current_pattern_penalty[opponent] = -self.pattern_boost
            else:
                self._current_pattern_penalty[opponent] = 0
        else:
            self._current_pattern_penalty[opponent] = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                # New: forgive recent defections if opponent has high reputation
                if opp_rep > 0.6:
                    return True
                else:
                    return True
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        # New: punish long defection streaks more severely
        if opponent in self.defection_streak and self.defection_streak[opponent] >= self.streak_threshold:
            streak = self.defection_streak[opponent]
            score -= self.streak_penalty * (streak - self.streak_threshold + 1)
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        # New mechanism: if opponent's trend is strongly cooperative, boost score; if strongly defective, penalize
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]  # 0 to 1
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3  # up to +0.25
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3  # up to -0.25
        # New: dynamically adjust forgiveness based on opponent's recent cooperation rate
        if opponent in self.opponent_recent_coop:
            recent_coop_rate = self.opponent_recent_coop[opponent]
            if recent_coop_rate > 0.7:
                self.forgiveness = min(self.max_forgiveness, self.forgiveness + self.forgiveness_adjustment)
            elif recent_coop_rate < 0.3:
                self.forgiveness = max(self.min_forgiveness, self.forgiveness - self.forgiveness_adjustment)
            score += self.dynamic_forgiveness * (recent_coop_rate - 0.5)  # small boost/penalty
        # New: forgiveness modulated by opponent's reputation
        if opponent in self.reputation:
            rep = self.reputation[opponent]
            # If opponent has high reputation, increase forgiveness (reduce penalty)
            if rep > 0.7:
                score += self.rep_forgiveness_weight * (rep - 0.7) / 0.3
            # If opponent has low reputation, increase penalty
            elif rep < 0.3:
                score -= self.rep_forgiveness_weight * (0.3 - rep) / 0.3
        # New: incorporate balance of cooperation vs defection for opponent
        if opponent in self.opponent_coop_balance:
            balance = self.opponent_coop_balance[opponent]  # positive = more coop, negative = more defect
            score += self.balance_weight * balance
        # New mechanism: exponential decay of recent defection count
        if opponent in self.recent_defection_count:
            decayed_count = self.recent_defection_count[opponent] * self.decay_factor
            self.recent_defection_count[opponent] = decayed_count
            score -= self.defection_decay_weight * decayed_count
        # New: pattern-based adjustment
        if opponent in self._current_pattern_penalty:
            score -= self._current_pattern_penalty[opponent]
        # New: adapt reciprocity bias based on my own recent cooperation rate to avoid being too generous or too harsh
        if len(self.my_history) >= 10:
            my_coop_rate = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
            if my_coop_rate > 0.8:
                # If I'm cooperating too much, reduce reciprocity bias to avoid being exploited
                self.reciprocity_bias = max(0.1, self.reciprocity_bias - self.reciprocity_adaptation_rate)
            elif my_coop_rate < 0.2:
                # If I'm defecting too much, increase reciprocity bias to be more cooperative
                self.reciprocity_bias = min(0.5, self.reciprocity_bias + self.reciprocity_adaptation_rate)
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(self.min_cooperation_threshold, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(self.max_cooperation_threshold, self.base_cooperation_threshold + self.adaptation_rate)
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
