            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        # Give more weight to recent reputation than the parent's average reputation
        score = 0.4 * opp_rep_recent + 0.2 * opp_rep + 0.2 * opp_coop + 0.4 * trust
