        # New exploration: keep coop_ratio_history but use a longer window
        self.coop_ratio_history = {}
        self.coop_ratio_window = 20  # Changed from 10 to 20
        # New exploration: reduce skepticism to give reputation more weight
        self.skepticism = 0.2  # Changed from 0.5 to 0.2
        # New exploration: increase grudge to make defections sting more
        self.grudge = 0.4  # Changed from 0.2 to 0.4

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-10:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if action == 'cooperate':
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.5) * self.reputation_inertia + (1 - self.reputation_inertia) * 1.0
        else:
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.5) * self.reputation_inertia + (1 - self.reputation_inertia) * 0.0

    def _update_coop_ratio_history(self, opponent: int) -> None:
        if opponent not in self.opponent_history or not self.opponent_history[opponent]:
            return
        recent = self.opponent_history[opponent][-self.coop_ratio_window:]
        coop_count = sum(1 for act, _ in recent if act == 'cooperate')
        ratio = coop_count / len(recent)
        if opponent not in self.coop_ratio_history:
            self.coop_ratio_history[opponent] = deque(maxlen=self.coop_ratio_window)
        self.coop_ratio_history[opponent].append(ratio)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
