        # New exploration: add a "tit_for_tat" flag that, when active, forces copying last opponent action
        self.tit_for_tat = False
        self.tit_for_tat_length = 3  # how many times to be tit-for-tat after a defection

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-10:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_reputation(self, agent_id: int, action: str) -> None:
        # New exploration: use a separate recent_reputation that updates with recency weight
        old_rep = self.reputation.get(agent_id, 0.5)
        old_recent = self.recent_reputation.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = 1.0
        else:
            new_val = 0.0
        # Update the main reputation with inertia (as parent)
        self.reputation[agent_id] = old_rep * self.reputation_inertia + (1 - self.reputation_inertia) * new_val
        # Update the recency-weighted reputation with higher weight on new observations
        self.recent_reputation[agent_id] = old_recent * (1 - self.recency_weight) + self.recency_weight * new_val

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
