        if self.tit_for_tat and opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, _ = self.opponent_history[opponent][-1]
            if last_opp_action == 'defect':
                # Decrease tit_for_tat counter
                self.tit_for_tat = False
                return False
            else:
                self.tit_for_tat = False
                return True
        # Use recency-weighted reputation as primary signal
        opp_rep_recent = self.recent_reputation.get(opponent, 0.5)
