            if opponent in self.recent_actions and self.recent_actions[opponent][-1] == 'defect':
                # Start tit-for-tat mode for a few rounds
                self.tit_for_tat = True
            return True
        else:
            # If we defect, increase grudge against opponent
            if opponent not in self.grudge:
                self.grudge[opponent] = 0.0
            self.grudge[opponent] = min(0.5, self.grudge[opponent] + self.grudge_increment)
            return False

