            return False

        # If opponent has high reputation, cooperate more
        if opp_rep > 0.3 and trust > 0.6:
            return True

        # Use a probabilistic approach based on trust and reputation score
        coop_prob = 0.5 + trust * 0.3 + opp_rep * 0.2
        # Clamp between 0 and 1
        coop_prob = max(0, min(1, coop_prob))
        return random.random() < coop_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_coop = 1.0 if donor_action == 'cooperate' else 0.0
        recipient_coop = 1.0 if recipient_action == 'cooperate' else 0.0

        # Update cooperation history for both agents
        self.cooperation_history[donor_id].append(donor_coop)
        self.cooperation_history[recipient_id].append(recipient_coop)

        # Update reputation based on actions (cooperate increases, defect decreases)
