            self.reputation[recipient_id] += 0.2
        else:  # donor defects, recipient cooperates
            self.reputation[donor_id] += 0.2
            self.reputation[recipient_id] -= 0.2

        # Clamp reputation to [-1, 1]
        self.reputation[donor_id] = max(-1, min(1, self.reputation[donor_id]))
        self.reputation[recipient_id] = max(-1, min(1, self.reputation[recipient_id]))

