            elif donor_action == 'defect' and recipient_action == 'cooperate':
                payoff = 2
            else:
                payoff = 0
            self.my_rewards.append(payoff)
            self.total_interactions += 1
            # Update trust for opponent based on their action toward me
            if recipient_action == 'cooperate':
                self.trust_scores[recipient_id] = min(1.0, self.trust_scores.get(recipient_id, 0.5) + 0.1)
            else:
                self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.1)
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_coop == 1.0)
            self.opponent_actions[donor_id] = donor_action
            # Calculate my payoff from recipient perspective
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                payoff = 1
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                payoff = 2  # I defected, opponent cooperated
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                payoff = -1  # I cooperated, opponent defected
            else:
                payoff = 0
            self.my_rewards.append(payoff)
            self.total_interactions += 1
            # Update trust for donor based on their action
            if donor_action == 'cooperate':
                self.trust_scores[donor_id] = min(1.0, self.trust_scores.get(donor_id, 0.5) + 0.1)
            else:
                self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.1)

        # Update own reputation based on my actions (if I was donor or recipient)
        if donor_id == self.agent_id:
            # My action as donor
            if donor_action == 'cooperate':
                self.personal_rep += 0.1
            else:
