        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.personal_rep += 0.1
            else:
                self.personal_rep -= 0.1
        self.personal_rep = max(-1, min(1, self.personal_rep))

        # Periodically adjust trust based on reputation alignment
        if self.total_interactions % 10 == 0:
