        # New: incorporate conditional cooperation - if opponent cooperates when I cooperate, boost
        if opponent in self.conditional_coop:
            cond = self.conditional_coop[opponent]
            # cond > 0.5 means opponent reciprocates, so cooperate more
            score += self.conditional_weight * (cond - 0.5) * 2  # -0.15 to +0.15
        # New: incorporate recent cooperation ratio (last 5)
        if opponent in self.recent_coop_ratio:
            ratio = self.recent_coop_ratio[opponent]
            score += self.ratio_weight * (ratio - 0.5) * 2  # -0.1 to +0.1
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

