            self.interaction_count[other] += 1
            # New: update pattern history and set current pattern penalty
            if not hasattr(self, '_current_pattern_penalty'):
                self._current_pattern_penalty = {}
            self._update_pattern(other, other_action)
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(self.max_forgiveness, self.forgiveness + 0.02)

