import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores for all possible opponents (0..14)
        # We use a dict to be safe, but assume max 15 agents
        self.reputations = {}
        # Track cooperation/defection rates for each opponent we've seen
        self.coop_count = {}
        self.defect_count = {}
        # Track our own interactions: opponent id -> list of (our_action, their_action)
        self.own_history = {}
        # Track third-party observations: opponent id -> list of observed donor/recipient actions
        # For simplicity, we'll just count total cooperations by each agent
        self.total_coops = {}
        self.total_defects = {}
        # Parameters
        self.alpha = 0.8  # weight for direct experience vs reputation
        self.beta = 2.0   # sensitivity to reputation
        self.gamma = 0.5  # forgiveness factor for past defections

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return True  # default cooperate if no opponent info
        # Compute probability of cooperating based on reputation and history
        p = 0.5  # default
        try:
            # Direct experience weight
            direct_score = 0.0
            if opp in self.own_history:
                history = self.own_history[opp]
                if history:
                    # Simple: fraction of times opponent cooperated with us
                    coop_count = sum(1 for _, their in history if their == 'cooperate')
                    direct_score = coop_count / len(history)
                else:
                    direct_score = 0.5
            else:
                direct_score = 0.5

            # Reputation score from observations
            rep_score = 0.5
            total_actions = self.total_coops.get(opp, 0) + self.total_defects.get(opp, 0)
            if total_actions > 0:
                rep_score = self.total_coops.get(opp, 0) / total_actions

            # Combine: direct experience weighted more heavily
            combined = self.alpha * direct_score + (1 - self.alpha) * rep_score

            # Apply a sigmoid-like transformation to make it more decisive
            # Use logistic function with beta as steepness
            p = 1 / (1 + math.exp(-self.beta * (combined - 0.5)))
            # Add slight randomness to avoid predictability (but deterministic seed not needed)
            # We'll use a deterministic pseudo-random based on agent_id and round
            # But we don't know round number, so use a fixed threshold
            # Instead, just use p directly without random to be deterministic
            # But we need to return boolean, so compare p to 0.5
            return p >= 0.5
        except Exception:
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation counts for donor and recipient
        try:
            # Donor's action
            if donor_action == 'cooperate':
                self.total_coops[donor_id] = self.total_coops.get(donor_id, 0) + 1
            else:
                self.total_defects[donor_id] = self.total_defects.get(donor_id, 0) + 1
            # Recipient's action
            if recipient_action == 'cooperate':
                self.total_coops[recipient_id] = self.total_coops.get(recipient_id, 0) + 1
            else:
                self.total_defects[recipient_id] = self.total_defects.get(recipient_id, 0) + 1

            # If we are one of the players, record direct interaction
            if donor_id == self.agent_id:
                # We are donor, opponent is recipient
                opp = recipient_id
                if opp not in self.own_history:
                    self.own_history[opp] = []
                self.own_history[opp].append((donor_action, recipient_action))
            elif recipient_id == self.agent_id:
                # We are recipient, opponent is donor
                opp = donor_id
                if opp not in self.own_history:
                    self.own_history[opp] = []
                self.own_history[opp].append((recipient_action, donor_action))
        except Exception:
            pass

