        self.defection_decay_weight = 0.3
        self.pattern_history = {}
        self.pattern_length = 3
        self.pattern_boost = 0.15
        self.pattern_penalty = 0.15
        self._current_pattern_penalty = {}
        # New: track opponent's kindness (net cooperation minus defection) with decay
        self.kindness = {}
        self.kindness_decay = 0.95
        self.kindness_weight = 0.2
        # New: track opponent's action consistency (1 - variance of last N actions)
        self.consistency = {}
        self.consistency_window = 8
        self.consistency_weight = 0.1
        # New: track opponent's generosity (cooperation rate when they could have defected)
        self.generosity = {}
        self.generosity_weight = 0.15

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-10:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        """Update exponential moving average of opponent's cooperation (1) or defection (0)."""
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_pattern(self, opponent: int, action: str) -> None:
        """Update pattern history for opponent and compute pattern-based adjustment."""
        if opponent not in self.pattern_history:
            self.pattern_history[opponent] = deque(maxlen=self.pattern_length)
        self.pattern_history[opponent].append(1 if action == 'cooperate' else 0)
        if len(self.pattern_history[opponent]) == self.pattern_length:
            pattern = list(self.pattern_history[opponent])
            if all(p == 0 for p in pattern):
                self._current_pattern_penalty[opponent] = self.pattern_penalty
            elif all(p == 1 for p in pattern):
                self._current_pattern_penalty[opponent] = -self.pattern_boost
            else:
                self._current_pattern_penalty[opponent] = 0
        else:
            self._current_pattern_penalty[opponent] = 0

    def _update_kindness(self, opponent: int, action: str) -> None:
        """Update kindness score: +1 for cooperate, -1 for defect, with decay."""
        if opponent not in self.kindness:
            self.kindness[opponent] = 0
        self.kindness[opponent] = self.kindness[opponent] * self.kindness_decay
        if action == 'cooperate':
            self.kindness[opponent] += 1
        else:
            self.kindness[opponent] -= 1
        # Bound to avoid extremes
        self.kindness[opponent] = max(-10, min(10, self.kindness[opponent]))

    def _update_consistency(self, opponent: int, action: str) -> None:
        """Update consistency based on recent actions: 1 - variance."""
        if opponent not in self.opponent_history:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-self.consistency_window:]]
        if len(recent) < 2:
            self.consistency[opponent] = 0.5
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        # Consistency: 1 - variance (variance max ~0.25, so scale)
        self.consistency[opponent] = max(0, min(1, 1 - variance * 4))

    def _update_generosity(self, opponent: int, action: str) -> None:
        """Update generosity: cooperation rate weighted by interaction count."""
        if opponent not in self.generosity:
            self.generosity[opponent] = 0.5
        # Simple moving average of cooperation rate
        if opponent in self.opponent_history:
            coop = sum(1 for a, _ in self.opponent_history[opponent] if a == 'cooperate')
            total = len(self.opponent_history[opponent])
            if total > 0:
                self.generosity[opponent] = coop / total

