        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if action == 'cooperate':
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.5) * self.reputation_inertia + (1 - self.reputation_inertia) * 1.0
        else:
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.5) * self.reputation_inertia + (1 - self.reputation_inertia) * 0.0

    def _update_coop_ratio_history(self, opponent: int) -> None:
        if opponent not in self.opponent_history or not self.opponent_history[opponent]:
            return
        recent = self.opponent_history[opponent][-self.coop_ratio_window:]
        coop_count = sum(1 for act, _ in recent if act == 'cooperate')
        ratio = coop_count / len(recent)
        if opponent not in self.coop_ratio_history:
            self.coop_ratio_history[opponent] = deque(maxlen=self.coop_ratio_window)
        self.coop_ratio_history[opponent].append(ratio)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                # New exploration: with higher noise, this immediate cooperation is less certain
                if random.random() > 0.1:
                    return True
        # New exploration: skepticism is lower, so reputation has more influence
        score = 0.3 * (1 - self.skepticism) * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            # New exploration: grudge is higher, so defections have a stronger negative effect
            score -= (self.defection_sensitivity + self.grudge) * self.defection_memory[opponent]
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3
        if opponent in self.coop_ratio_history and len(self.coop_ratio_history[opponent]) >= 3:
            ratios = list(self.coop_ratio_history[opponent])
            mean_ratio = sum(ratios) / len(ratios)
            variance_ratio = sum((r - mean_ratio) ** 2 for r in ratios) / len(ratios)
            # New exploration: with longer window, we are more confident in stable patterns
            if mean_ratio > 0.7 and variance_ratio < 0.05:
                score += 0.15  # Increased from 0.1 to 0.15
            elif variance_ratio > 0.2:
                score -= 0.15  # Increased from 0.1 to 0.15
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        score += self.generosity
        self.generosity = max(0.0, self.generosity - self.generosity_decay)

        suspicion = self.suspicion.get(opponent, 0.0)
        if suspicion > 0:
            score -= suspicion
            self.suspicion[opponent] = max(0.0, suspicion - self.suspicion_decay)

        # New exploration: higher noise makes decisions more unpredictable
        noisy_threshold = self.base_cooperation_threshold + random.gauss(0, self.noise)
        if score >= noisy_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            self._update_reputation(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_reputation(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            self._update_variance(other, other_action)
            self._update_trend(other, other_action)
            self._update_coop_ratio_history(other)
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
                if other in self.suspicion:
                    self.suspicion[other] = max(0.0, self.suspicion[other] - 0.05)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
                if other not in self.suspicion:
                    self.suspicion[other] = 0.0
                self.suspicion[other] = min(0.5, self.suspicion[other] + self.suspicion_increment)
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)

import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores for all possible opponents (0..14)
        self.reputations = {}
        # Track cooperation/defection counts for each opponent we've seen
        self.coop_count = {}
        self.defect_count = {}
        # Track our own interactions: opponent id -> list of (our_action, their_action)
        self.own_history = {}
        # Track third-party observations: opponent id -> list of observed donor/recipient actions
        self.total_coops = {}
        self.total_defects = {}
        # Parameters - new: higher alpha for direct experience, lower beta for less sensitivity
        self.alpha = 0.9  # weight for direct experience vs reputation (increased)
        self.beta = 1.0   # sensitivity to reputation (decreased)
        self.gamma = 0.5  # forgiveness factor for past defections

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return True  # default cooperate if no opponent info
        # Compute probability of cooperating based on reputation and history
        p = 0.5  # default
        try:
            # Direct experience weight
            direct_score = 0.0
            if opp in self.own_history:
                history = self.own_history[opp]
                if history:
                    # Simple: fraction of times opponent cooperated with us
                    coop_count = sum(1 for _, their in history if their == 'cooperate')
                    direct_score = coop_count / len(history)
                else:
                    direct_score = 0.5
            else:
                direct_score = 0.5

            # Reputation score from observations
            rep_score = 0.5
            total_actions = self.total_coops.get(opp, 0) + self.total_defects.get(opp, 0)
            if total_actions > 0:
                rep_score = self.total_coops.get(opp, 0) / total_actions

            # Combine: direct experience weighted more heavily
            combined = self.alpha * direct_score + (1 - self.alpha) * rep_score

            # Apply a sigmoid-like transformation to make it more decisive
            # Use logistic function with beta as steepness
            p = 1 / (1 + math.exp(-self.beta * (combined - 0.5)))
            # Add slight randomness to avoid predictability (but deterministic seed not needed)
            # We'll use a deterministic pseudo-random based on agent_id and round
            # But we don't know round number, so use a fixed threshold
            # Instead, just use p directly without random to be deterministic
            # But we need to return boolean, so compare p to 0.5
            return p >= 0.5
        except Exception:
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation counts for donor and recipient
        try:
            # Donor's action
            if donor_action == 'cooperate':
                self.total_coops[donor_id] = self.total_coops.get(donor_id, 0) + 1
            else:
                self.total_defects[donor_id] = self.total_defects.get(donor_id, 0) + 1
            # Recipient's action
            if recipient_action == 'cooperate':
                self.total_coops[recipient_id] = self.total_coops.get(recipient_id, 0) + 1
            else:
                self.total_defects[recipient_id] = self.total_defects.get(recipient_id, 0) + 1

            # If we are one of the players, record direct interaction
            if donor_id == self.agent_id:
                # We are donor, opponent is recipient
                opp = recipient_id
                if opp not in self.own_history:
                    self.own_history[opp] = []
                self.own_history[opp].append((donor_action, recipient_action))
            elif recipient_id == self.agent_id:
                # We are recipient, opponent is donor
                opp = donor_id
                if opp not in self.own_history:
                    self.own_history[opp] = []
                self.own_history[opp].append((recipient_action, donor_action))
        except Exception:
            pass

