from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Use a sliding window of recent observations per opponent
        self.recent_obs = {}
        self.window_size = 10
        # Track direct interaction history with opponent: opponent -> deque of (our_action, their_action)
        self.direct_history = {}
        # Recent cooperation/defection counts for each opponent (from window)
        self.coop_count = {}
        self.defect_count = {}
        # Memory decay factor for older observations
        self.decay = 0.9
        # Base trust level for unknown opponents
        self.base_trust = 0.5
        # Sensitivity to negative interactions
        self.punishment = 2.0

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return True

        # Get direct experience score from window
        direct_score = 0.5
        if opp in self.direct_history and len(self.direct_history[opp]) > 0:
            history = list(self.direct_history[opp])
            coop = sum(1 for _, their in history if their == 'cooperate')
            direct_score = coop / len(history)

        # Get reputation score from recent observations (with decay)
        if opp in self.recent_obs and len(self.recent_obs[opp]) > 0:
            total_weight = 0.0
            coop_weight = 0.0
            for i, (action, weight) in enumerate(self.recent_obs[opp]):
                # Apply decay: more recent observations get higher weight
                effective_weight = weight * (self.decay ** (len(self.recent_obs[opp]) - i - 1))
                total_weight += effective_weight
                if action == 'cooperate':
                    coop_weight += effective_weight
            rep_score = coop_weight / total_weight if total_weight > 0 else self.base_trust
        else:
            rep_score = self.base_trust

        # Combine direct and reputation, but be more cautious if direct experience is negative
        combined = 0.6 * direct_score + 0.4 * rep_score
        # If we have direct evidence of defection, punish more strongly
        if opp in self.direct_history and len(self.direct_history[opp]) > 0:
            last_action = list(self.direct_history[opp])[-1][1]
            if last_action == 'defect':
                combined -= self.punishment * (1 - direct_score)

        # Sigmoid transformation
        p = 1 / (1 + math.exp(-2.5 * (combined - 0.5)))
        return p >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update recent observation windows for donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.recent_obs:
                self.recent_obs[agent_id] = deque(maxlen=self.window_size)
            # Store action with weight 1 (base weight)
            self.recent_obs[agent_id].append((action, 1.0))
            # Update counts
            if action == 'cooperate':
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            else:
                self.defect_count[agent_id] = self.defect_count.get(agent_id, 0) + 1

        # If we are involved, record direct interaction
        if donor_id == self.agent_id:
            opp = recipient_id
            if opp not in self.direct_history:
                self.direct_history[opp] = deque(maxlen=self.window_size)
            self.direct_history[opp].append((donor_action, recipient_action))
        elif recipient_id == self.agent_id:
            opp = donor_id
            if opp not in self.direct_history:
                self.direct_history[opp] = deque(maxlen=self.window_size)
            self.direct_history[opp].append((recipient_action, donor_action))

