        self.recent_history = {}
        self.alpha = 0.7  # lower weight for direct experience
        self.beta = 2.0   # higher sensitivity to reputation
        self.gamma = 0.5
        self.recency_window = 5  # look at last 5 interactions

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
