        p = 0.5
        try:
            # Direct score from recent history (recency weighted)
            direct_score = 0.5
            if opp in self.recent_history:
                hist = self.recent_history[opp]
                if hist:
                    coop = sum(1 for _, their in hist if their == 'cooperate')
                    direct_score = coop / len(hist)
                else:
                    direct_score = 0.5

