            total_actions = self.total_coops.get(opp, 0) + self.total_defects.get(opp, 0)
            if total_actions > 0:
                rep_score = self.total_coops.get(opp, 0) / total_actions

            # Combine: direct experience weighted more heavily
            combined = self.alpha * direct_score + (1 - self.alpha) * rep_score

            # Apply a sigmoid-like transformation to make it more decisive
            # Use logistic function with beta as steepness
            p = 1 / (1 + math.exp(-self.beta * (combined - 0.5)))
            # Add slight randomness to avoid predictability (but deterministic seed not needed)
            # We'll use a deterministic pseudo-random based on agent_id and round
            # But we don't know round number, so use a fixed threshold
            # Instead, just use p directly without random to be deterministic
            # But we need to return boolean, so compare p to 0.5
            return p >= 0.5
        except Exception:
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation counts for donor and recipient
        try:
            # Donor's action
            if donor_action == 'cooperate':
