        score += self.generosity
        self.generosity = max(0.0, self.generosity - self.generosity_decay)

        suspicion = self.suspicion.get(opponent, 0.0)
        if suspicion > 0:
            score -= suspicion
            self.suspicion[opponent] = max(0.0, suspicion - self.suspicion_decay)

