    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-10:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_pattern(self, opponent: int, action: str) -> None:
        if opponent not in self.pattern_history:
            self.pattern_history[opponent] = deque(maxlen=self.pattern_length)
        self.pattern_history[opponent].append(1 if action == 'cooperate' else 0)
        if len(self.pattern_history[opponent]) == self.pattern_length:
            pattern = list(self.pattern_history[opponent])
            if all(p == 0 for p in pattern):
                self._current_pattern_penalty[opponent] = self.pattern_penalty
            elif all(p == 1 for p in pattern):
                self._current_pattern_penalty[opponent] = -self.pattern_boost
            else:
                self._current_pattern_penalty[opponent] = 0
        else:
            self._current_pattern_penalty[opponent] = 0

    def _update_perceived_hostility(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if agent_id not in self.perceived_hostility:
                self.perceived_hostility[agent_id] = 0.0
            if action == 'defect':
                self.perceived_hostility[agent_id] = self.perceived_hostility[agent_id] * self.hostility_decay + 1.0
            else:
                self.perceived_hostility[agent_id] = self.perceived_hostility[agent_id] * self.hostility_decay

