import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_history = deque(maxlen=10)  # limited memory of personal interactions
        self.opponent_history = {}
        self.generation = 0
        self.round = 0
        self.total_cooperate = 0
        self.total_defect = 0
        self.last_action = None
        self.last_opponent = None

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)

        # Use personal history if available
        my_hist = [h for h in self.my_history if h[0] == opponent]
        if my_hist:
            coop_count = sum(1 for h in my_hist if h[2])
            coop_rate = coop_count / len(my_hist)
            # More forgiving: cooperate unless opponent defected in last interaction
            if coop_rate >= 0.5:
                return True
            else:
                # Check if last interaction with this opponent was defection
                last_interaction = my_hist[-1]
                if not last_interaction[2]:
                    # Punish only if defection was recent, otherwise forgive
                    return random.random() < 0.3
                return False
        else:
            # No personal history, use reputation with a momentum factor
            # If we just cooperated with someone else, slightly more cooperative overall
            momentum = 0.0
            if self.last_action is not None and self.last_action:
                momentum = 0.05
            threshold = 0.5 - momentum
            if opp_rep > threshold:
                prob = min(0.95, 0.5 + (opp_rep - 0.5) * 0.9)
                return random.random() < prob
            else:
                prob = max(0.05, 0.5 - (0.5 - opp_rep) * 0.9)
                return random.random() < prob

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        if self.round % 30 == 0:
            self.generation += 1
            self.round = 0
            # Stronger decay to be more adaptive
            for agent in list(self.reputation.keys()):
                self.reputation[agent] *= 0.8

        is_self_donor = (donor_id == self.agent_id)
        is_self_recipient = (recipient_id == self.agent_id)

        if is_self_donor or is_self_recipient:
            opponent = recipient_id if is_self_donor else donor_id
            my_action = donor_action if is_self_donor else recipient_action
            opp_action = recipient_action if is_self_donor else donor_action
            my_action_bool = (my_action == 'cooperate')
            opp_action_bool = (opp_action == 'cooperate')

            self.my_history.append((opponent, my_action_bool, opp_action_bool))
            self.last_action = my_action_bool
            self.last_opponent = opponent

            if my_action_bool:
                self.total_cooperate += 1
            else:
                self.total_defect += 1

            # More extreme reputation update: strong reward/punish but with forgiveness
            if opp_action_bool:
                self.reputation[opponent] = self.reputation.get(opponent, 0.5) + 0.15
            else:
                self.reputation[opponent] = self.reputation.get(opponent, 0.5) - 0.25

            self.reputation[opponent] = max(0.0, min(1.0, self.reputation[opponent]))

            # Symmetric update: both actions affect reputation equally
            if is_self_donor:
                if recipient_action == 'cooperate':
                    self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.08
                else:
                    self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.12
                self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))
            else:
                if donor_action == 'cooperate':
                    self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.08
                else:
                    self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.12
