class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores for all possible opponents (0..14)
        # We use a dict to be safe, but assume max 15 agents
        self.reputations = {}
        # Track cooperation/defection rates for each opponent we've seen
        self.coop_count = {}
        self.defect_count = {}
        # Track our own interactions: opponent id -> deque of (our_action, their_action) with max length
        self.own_history = {}
        # Track third-party observations: opponent id -> deque of recent actions for sliding window
        self.observation_window = {}
        self.window_size = 10  # sliding window for recent reputation
        # Parameters
        self.alpha = 0.8  # weight for direct experience vs reputation
        self.beta = 2.0   # sensitivity to reputation
        self.gamma = 0.5  # forgiveness factor for past defections
        # Decay factor for old observations
        self.decay = 0.9

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return True  # default cooperate if no opponent info
        # Compute probability of cooperating based on reputation and history
        p = 0.5  # default
        try:
            # Direct experience weight (only from recent window)
            direct_score = 0.5
            if opp in self.own_history:
                history = self.own_history[opp]
                if history:
                    # Fraction of times opponent cooperated with us in recent window
                    coop_count = sum(1 for _, their in history if their == 'cooperate')
                    direct_score = coop_count / len(history)
                else:
                    direct_score = 0.5
            else:
                direct_score = 0.5

            # Reputation score from sliding window of third-party observations
            rep_score = 0.5
            if opp in self.observation_window:
                window = self.observation_window[opp]
                if window:
                    # Apply decay to older observations
                    total_weight = 0.0
                    coop_weight = 0.0
                    for i, action in enumerate(window):
                        weight = self.decay ** (len(window) - 1 - i)
                        total_weight += weight
                        if action == 'cooperate':
                            coop_weight += weight
                    if total_weight > 0:
                        rep_score = coop_weight / total_weight
                else:
                    rep_score = 0.5
            else:
                rep_score = 0.5

            # Combine: direct experience weighted more heavily
            combined = self.alpha * direct_score + (1 - self.alpha) * rep_score

            # Apply a sigmoid-like transformation to make it more decisive
            # Use logistic function with beta as steepness
            p = 1 / (1 + math.exp(-self.beta * (combined - 0.5)))
            # Add slight randomness to avoid predictability (but deterministic seed not needed)
            # We'll use a deterministic pseudo-random based on agent_id and round
            # But we don't know round number, so use a fixed threshold
            # Instead, just use p directly without random to be deterministic
            # But we need to return boolean, so compare p to 0.5
            return p >= 0.5
        except Exception:
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update sliding window for donor's action
        try:
            # Initialize window if needed
            if donor_id not in self.observation_window:
                self.observation_window[donor_id] = deque(maxlen=self.window_size)
            self.observation_window[donor_id].append(donor_action)
            # Update window for recipient's action
            if recipient_id not in self.observation_window:
                self.observation_window[recipient_id] = deque(maxlen=self.window_size)
            self.observation_window[recipient_id].append(recipient_action)

            # If we are one of the players, record direct interaction (also with window)
            if donor_id == self.agent_id:
                # We are donor, opponent is recipient
                opp = recipient_id
                if opp not in self.own_history:
                    self.own_history[opp] = deque(maxlen=self.window_size)
                self.own_history[opp].append((donor_action, recipient_action))
            elif recipient_id == self.agent_id:
                # We are recipient, opponent is donor
                opp = donor_id
                if opp not in self.own_history:
                    self.own_history[opp] = deque(maxlen=self.window_size)
                self.own_history[opp].append((recipient_action, donor_action))
        except Exception:
            pass

