            self.coop_counts[opponent] = 0
            self.defect_counts[opponent] = 0
            self.interactions[opponent] = 0
            self.opponent_coop_history[opponent] = []
            self.opponent_defect_history[opponent] = []

        # Calculate opponent cooperation rate
        total_opp = self.coop_counts[opponent] + self.defect_counts[opponent]
        if total_opp > 0:
            opp_coop_rate = self.coop_counts[opponent] / total_opp
        else:
            opp_coop_rate = 0.5

        # Calculate my cooperation rate
        my_total = len(self.my_coop_history) + len(self.my_defect_history)
        if my_total > 0:
            my_coop_rate = len(self.my_coop_history) / my_total
        else:
            my_coop_rate = 0.5

        # Trust based on opponent behavior
        if opponent in self.trust:
            trust = self.trust[opponent]
        else:
            trust = 0.5

        # Reputation of opponent
        if opponent in self.reputation:
            reputation = self.reputation[opponent]
        else:
            reputation = 0.5

