        recent_window = 10
        recent_opp = self.opponent_coop_history[opponent][-recent_window:] + self.opponent_defect_history[opponent][-recent_window:]
        if len(recent_opp) > 0:
            recent_coop = sum(1 for a in recent_opp if a == 'cooperate')
            recent_rate = recent_coop / len(recent_opp)
        else:
            recent_rate = 0.5

        # Combine factors
        combined_score = (opp_coop_rate * 0.4 + trust * 0.2 + reputation * 0.2 + recent_rate * 0.2)

