                self.betrayal_count[other] += 1
                # Child exploration: remove from forgiven set if they defect again
                self.forgiven_opponents.discard(other)
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)

