                self.suspicion[other] = min(0.5, self.suspicion[other] + self.suspicion_increment)
                self.cooperation_since_defection[other] = 0
                self.mutual_coop_streak[other] = 0

            # Child exploration: update reciprocity_strength and cooperation_momentum based on last action
            if my_action == 'cooperate':
