class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None

        # Reputation tracking: agent_id -> {'coop': count, 'def': count}
        self.reputation = {}

        # For self-play memory: track outcomes with each partner
        # partner_id -> {'my_coop': int, 'my_def': int, 'their_coop': int, 'their_def': int}
        self.history = {}

        # Track my own recent actions and outcomes for strategy adjustment
        self.my_recent = deque(maxlen=200)  # deque for bounded memory
        self.sit_out_count = 0

        # Parameters for strategy
        self.coop_threshold = 0.5  # willingness to cooperate with strangers
        self.alpha = 0.3  # weight for reputation vs personal history
        self.beta = 0.1   # exploration noise

        # Generation tracking
        self.generation_round = 0
        self.total_rounds = 0

        # New: memory decay factor for reputation (forget old observations)
        self.decay = 0.95

    def decide(self) -> bool:
        self.total_rounds += 1
        self.generation_round += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # shouldn't happen, but safe

        # Initialize reputation if unknown
        if opp not in self.reputation:
            self.reputation[opp] = {'coop': 0, 'def': 0, 'total': 0}
        if opp not in self.history:
            self.history[opp] = {'my_coop': 0, 'my_def': 0, 'their_coop': 0, 'their_def': 0, 'total': 0}

        # Compute opponent's cooperation rate from reputation with decay
        rep = self.reputation[opp]
        total_obs = rep['total']
        coop_rate = rep['coop'] / total_obs if total_obs > 0 else 0.5

        # Compute opponent's cooperation rate from personal history
        hist = self.history[opp]
        total_hist = hist['total']
        their_rate = (hist['their_coop'] / total_hist) if total_hist > 0 else 0.5

        # Combine reputation and personal history with adaptive alpha
        # If I have little personal history, trust reputation more
        if total_hist < 5:
            alpha_eff = min(0.8, self.alpha + 0.2)
        else:
            alpha_eff = self.alpha
        combined_coop = alpha_eff * coop_rate + (1 - alpha_eff) * their_rate

        # My history with this opponent: what did I do last time?
        # Use a more flexible tit-for-tat based on recent interactions
        if total_hist > 0:
            # Their last action (most recent) - track in history as a counter
            # We approximate by checking if their total coop is increasing
            # Instead, use a simple conditional: if they cooperated more than 60% recently, be cooperative
            if their_rate > 0.6:
                prob_coop = 0.8 + 0.2 * (their_rate - 0.6) * 2
            elif their_rate > 0.3:
                prob_coop = 0.4 + 0.3 * (their_rate - 0.3) / 0.3
            else:
                prob_coop = max(0.1, 0.2 - (0.3 - their_rate) * 2)
        else:
            # No history - use reputation and general trust, more cautious
            prob_coop = max(0.1, min(0.8, combined_coop * 0.7 + 0.1))

        # Add exploration noise
        prob_coop = max(0.0, min(1.0, prob_coop + random.uniform(-self.beta, self.beta)))

        # Occasionally adjust based on my recent performance
        if len(self.my_recent) >= 10:
            recent_actions = [a for a, _, _ in self.my_recent]
            coop_count = sum(1 for a in recent_actions if a)
            # If I've been mostly cooperating, be more cautious; if mostly defecting, be more cooperative
            if coop_count > 8:
                prob_coop = min(0.9, prob_coop - 0.05)
            elif coop_count < 2:
                prob_coop = max(0.1, prob_coop + 0.05)

        # Decide
        return random.random() < prob_coop

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for all observed actions with decay
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid not in self.reputation:
                self.reputation[pid] = {'coop': 0, 'def': 0, 'total': 0}
            rep = self.reputation[pid]
            # Decay existing counts
            rep['coop'] *= self.decay
            rep['def'] *= self.decay
            rep['total'] *= self.decay
            # Add new observation
            if action == 'cooperate':
                rep['coop'] += 1
            else:
                rep['def'] += 1
            rep['total'] += 1

        # If I am involved, update my personal history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who is me and who is opponent
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            if opp_id not in self.history:
                self.history[opp_id] = {'my_coop': 0, 'my_def': 0, 'their_coop': 0, 'their_def': 0, 'total': 0}
            hist = self.history[opp_id]

            # Update my count
            if my_action == 'cooperate':
                hist['my_coop'] += 1
            else:
                hist['my_def'] += 1

            # Update opponent count
            if opp_action == 'cooperate':
                hist['their_coop'] += 1
            else:
                hist['their_def'] += 1
            hist['total'] += 1

            # Record outcome for this interaction
            # Outcome: 1 if I cooperated and they cooperated, 0.5 if mixed, 0 if both defected
            if my_action == 'cooperate' and opp_action == 'cooperate':
                outcome = 1.0
            elif my_action == 'defect' and opp_action == 'defect':
                outcome = 0.0
            else:
                outcome = 0.5
            self.my_recent.append((my_action == 'cooperate', opp_id, outcome))

        # If I sat out, just track that
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            pass  # We observe third-party interactions for reputation

        # Reset generation round if needed? Not needed; we keep track in decide.

