        # Use a faster update for reputation to be more responsive
        self.reputation[agent_id] = old_rep * 0.8 + 0.2 * new_val
        # Update norm based on observed actions
        self.reputation_norm = (1 - self.norm_adaptation) * self.reputation_norm + self.norm_adaptation * new_val

