        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_pattern(self, opponent: int, action: str) -> None:
        if opponent not in self.pattern_history:
            self.pattern_history[opponent] = deque(maxlen=self.pattern_length)
        self.pattern_history[opponent].append(1 if action == 'cooperate' else 0)
        if len(self.pattern_history[opponent]) == self.pattern_length:
            pattern = list(self.pattern_history[opponent])
            if all(p == 0 for p in pattern):
                self._current_pattern_penalty[opponent] = self.pattern_penalty
            elif all(p == 1 for p in pattern):
                self._current_pattern_penalty[opponent] = -self.pattern_boost
            else:
                self._current_pattern_penalty[opponent] = 0
        else:
            self._current_pattern_penalty[opponent] = 0

    def _update_perceived_hostility(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if agent_id not in self.perceived_hostility:
                self.perceived_hostility[agent_id] = 0.0
            if action == 'defect':
                self.perceived_hostility[agent_id] = self.perceived_hostility[agent_id] * self.hostility_decay + 1.0
            else:
                self.perceived_hostility[agent_id] = self.perceived_hostility[agent_id] * self.hostility_decay

    def _update_uncertainty(self, opponent: int, action: str) -> None:
        if opponent not in self.rep_uncertainty:
            self.rep_uncertainty[opponent] = 0.5
        current_rep = self.reputation.get(opponent, 0.5)
        expected = 1 if current_rep > 0.5 else 0
        actual = 1 if action == 'cooperate' else 0
        if expected != actual:
            self.rep_uncertainty[opponent] = min(1.0, self.rep_uncertainty[opponent] * self.uncertainty_decay + 0.1)
        else:
            self.rep_uncertainty[opponent] *= self.uncertainty_decay

    def _update_trust_momentum(self, opponent: int, new_trust: float) -> None:
        if opponent not in self.trust_momentum:
            self.trust_momentum[opponent] = self.momentum_init
        self.trust_momentum[opponent] = self.momentum_factor * self.trust_momentum[opponent] + (1 - self.momentum_factor) * new_trust
        self.trust_momentum[opponent] = max(0.0, min(1.0, self.trust_momentum[opponent]))

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust_momentum.get(opponent, self.momentum_init)
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust

        # Novel: generosity - if opponent is new or has low interaction count, boost score
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 3:
            score += self.generosity

        if opponent in self.rep_uncertainty:
            uncertainty = self.rep_uncertainty[opponent]
            score -= self.uncertainty_weight * uncertainty

        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        if opponent in self.defection_streak and self.defection_streak[opponent] >= self.streak_threshold:
            streak = self.defection_streak[opponent]
            score -= self.streak_penalty * (streak - self.streak_threshold + 1)
        my_recent_coop = self.my_coop_rate
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity

        if my_recent_coop < 0.3 and opp_coop > 0.6:
            score += self.coop_reward_sensitivity * (0.3 - my_recent_coop) * (opp_coop - 0.6) * 2

        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3
        if opponent in self.opponent_recent_coop:
            recent_coop_rate = self.opponent_recent_coop[opponent]
            if recent_coop_rate > 0.7:
                self.forgiveness = min(self.max_forgiveness, self.forgiveness + self.forgiveness_adjustment)
            elif recent_coop_rate < 0.3:
                self.forgiveness = max(self.min_forgiveness, self.forgiveness - self.forgiveness_adjustment)
            score += self.dynamic_forgiveness * (recent_coop_rate - 0.5)
        if opponent in self.reputation:
            rep = self.reputation[opponent]
            if rep > 0.7:
                score += self.rep_forgiveness_weight * (rep - 0.7) / 0.3
            elif rep < 0.3:
                score -= self.rep_forgiveness_weight * (0.3 - rep) / 0.3
        if opponent in self.opponent_coop_balance:
            balance = self.opponent_coop_balance[opponent]
            score += self.balance_weight * balance
        if opponent in self.recent_defection_count:
            decayed_count = self.recent_defection_count[opponent] * self.decay_factor
            self.recent_defection_count[opponent] = decayed_count
            score -= self.defection_decay_weight * decayed_count
        if opponent in self.perceived_hostility:
            hostility = self.perceived_hostility[opponent]
            if hostility > self.hostility_threshold:
                score -= self.hostility_weight * (hostility - self.hostility_threshold)
        if len(self.my_history) >= 10:
            my_coop_rate = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
            if my_coop_rate > 0.8:
                self.reciprocity_bias = max(0.1, self.reciprocity_bias - self.reciprocity_adaptation_rate)
            elif my_coop_rate < 0.2:
                self.reciprocity_bias = min(0.5, self.reciprocity_bias + self.reciprocity_adaptation_rate)
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(self.min_cooperation_threshold, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(self.max_cooperation_threshold, self.base_cooperation_threshold + self.adaptation_rate)
        # Novel: generosity decays over time
        self.generosity *= self.generosity_decay
        if score >= self.base_cooperation_threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_perceived_hostility(donor_id, donor_action, recipient_id, recipient_action)

        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) * 0.85
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85 + 0.15
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) * 0.85
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if len(self.my_history) > 0:
                self.my_coop_rate = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            if other not in self.opponent_recent_coop:
                self.opponent_recent_coop[other] = 0.5
            recent_actions = self.recent_actions[other]
            coop_count = sum(1 for a in recent_actions if a == 'cooperate')
            self.opponent_recent_coop[other] = coop_count / len(recent_actions) if recent_actions else 0.5
            self._update_variance(other, other_action)
            self._update_trend(other, other_action)
            self._update_uncertainty(other, other_action)

            # Novel: update trust momentum - trust changes slowly
            if my_action == 'cooperate' and other_action == 'cooperate':
                self._update_trust_momentum(other, self.trust_momentum.get(other, self.momentum_init) + 0.1)
            elif my_action == 'defect' and other_action == 'defect':
                self._update_trust_momentum(other, self.trust_momentum.get(other, self.momentum_init) - 0.05)
            # Novel: generosity boost when cooperating with a defector
            if my_action == 'cooperate' and other_action == 'defect':
                self.generosity = min(0.5, self.generosity + self.generosity_boost)

            if other not in self.defection_streak:
                self.defection_streak[other] = 0
            if other_action == 'defect':
                self.defection_streak[other] += 1
            else:
                self.defection_streak[other] = 0
            if other not in self.recent_defection_count:
                self.recent_defection_count[other] = 0
            if other_action == 'defect':
                self.recent_defection_count[other] = self.recent_defection_count[other] * self.decay_factor + 1

