                coop_total, total = self.opponent_coop_rate[opponent]
                hist_coop_rate = coop_total / max(1, total)
                # Blend current effective rate with historical rate, favoring recent
                effective_coop_rate = 0.6 * effective_coop_rate + 0.4 * hist_coop_rate

            # Adjust threshold based on my own reputation and experience level
            threshold = self.trust_threshold
            if self.self_reputation_estimate < 0.2:
                threshold = 0.65  # Very cautious when reputation is low
            elif self.self_reputation_estimate > 0.8:
