import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        self.action_variance = {}
        self.variance_weight = 0.2
        self.coop_trend = {}
        self.trend_weight = 0.25
        self.generosity = 0.3
        self.generosity_decay = 0.005
        self.suspicion = {}
        self.suspicion_increment = 0.15
        self.suspicion_decay = 0.02
        # Child exploration: use a reputation_reference that stabilizes over time
        self.reputation_reference = {}
        self.reference_decay = 0.05
        self.reference_influence = 0.1
        # Child exploration: add a "cooperation_streak" to reward consistent cooperation
        self.cooperation_streak = {}
        self.streak_reward = 0.1
        self.streak_penalty = 0.05
        # Child exploration: add a "defection_escalation" to penalize repeated defections more
        self.defection_escalation = {}
        self.escalation_increment = 0.05
        # Child exploration: add a "memory_span" parameter that shortens over time
        self.memory_span = 30
        self.memory_span_decay = 0.1
        self.memory_span_min = 5
        # Child exploration: add a "forgiveness_boost" that increases when opponent cooperates after defection
        self.forgiveness_boost = 0.05
        # New exploration: add a "reputation_volatility" to penalize erratic reputation changes
        self.reputation_volatility = {}
        self.volatility_weight = 0.15
        self.volatility_decay = 0.1
        # New exploration: add a "cooperation_consistency" to reward steady cooperation
        self.cooperation_consistency = {}
        self.consistency_weight = 0.2
        self.consistency_window = 5
        # New exploration: add a "defection_alternation" to penalize alternating cooperate/defect
        self.defection_alternation = {}
        self.alternation_weight = 0.1
        self.alternation_decay = 0.05

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-self.memory_span:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_reputation(self, agent_id: int, action: str) -> None:
        old_rep = self.reputation.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = 1.0
        else:
            new_val = 0.0
        # Use a slower update for reputation to make changes more gradual
        self.reputation[agent_id] = old_rep * 0.95 + 0.05 * new_val
        # Update reputation reference with a slower moving average
        old_ref = self.reputation_reference.get(agent_id, 0.5)
        self.reputation_reference[agent_id] = old_ref * (1 - self.reference_decay) + self.reputation[agent_id] * self.reference_decay
        # Update volatility: track how much reputation changes over time
        if agent_id not in self.reputation_volatility:
            self.reputation_volatility[agent_id] = 0.0
        change = abs(self.reputation[agent_id] - old_rep)
        self.reputation_volatility[agent_id] = self.reputation_volatility[agent_id] * (1 - self.volatility_decay) + change

    def _update_consistency(self, opponent: int, action: str) -> None:
        """Track how consistent the opponent's actions are (cooperate vs defect)."""
        if opponent not in self.cooperation_consistency:
            self.cooperation_consistency[opponent] = deque(maxlen=self.consistency_window)
        self.cooperation_consistency[opponent].append(1 if action == 'cooperate' else 0)

    def _update_alternation(self, opponent: int, action: str) -> None:
        """Track how often the opponent alternates between cooperate and defect."""
        if opponent in self.opponent_history and len(self.opponent_history[opponent]) > 1:
            last_action = self.opponent_history[opponent][-1][0]
            current = 1 if action == 'cooperate' else 0
            last = 1 if last_action == 'cooperate' else 0
            if current != last:
                self.defection_alternation[opponent] = self.defection_alternation.get(opponent, 0.0) + self.alternation_weight
            else:
                self.defection_alternation[opponent] = self.defection_alternation.get(opponent, 0.0) * (1 - self.alternation_decay)
        else:
            self.defection_alternation[opponent] = self.defection_alternation.get(opponent, 0.0)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # New exploration: check if we have a strong cooperation streak to reward
        if opponent in self.cooperation_streak and self.cooperation_streak[opponent] >= 3:
            # Reward consistent cooperation
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # Use a stronger reciprocity bias
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.2 * opp_coop + 0.3 * trust
        # Add a small influence from the reputation reference to stabilize decisions
        ref = self.reputation_reference.get(opponent, 0.5)
        score += self.reference_influence * (ref - 0.5)
        # Penalize high reputation volatility (unpredictable changes)
        if opponent in self.reputation_volatility:
            score -= self.volatility_weight * min(1.0, self.reputation_volatility[opponent] * 5)
        if opponent in self.opponent_history:
            # Use shorter memory for defection detection
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-self.memory_span:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
            # Escalation penalty grows with repeated defections
            if opponent in self.defection_escalation:
                score -= self.defection_escalation[opponent]
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        # Use a stronger reciprocity bias
        score += self.reciprocity_bias * reciprocity
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3
        # New exploration: reward consistent cooperation (low variance in recent actions)
        if opponent in self.cooperation_consistency and len(self.cooperation_consistency[opponent]) == self.consistency_window:
            actions = list(self.cooperation_consistency[opponent])
            mean = sum(actions) / len(actions)
            consistency = 1 - abs(mean - 0.5) * 2  # 1 if all same, 0 if mixed
            if consistency > 0.8:
                score += self.consistency_weight * (consistency - 0.8) / 0.2
        # New exploration: penalize alternating behavior
        if opponent in self.defection_alternation:
            score -= self.defection_alternation[opponent]
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        score += self.generosity
        self.generosity = max(0.0, self.generosity - self.generosity_decay)

        suspicion = self.suspicion.get(opponent, 0.0)
        if suspicion > 0:
            score -= suspicion
            self.suspicion[opponent] = max(0.0, suspicion - self.suspicion_decay)

        # Child exploration: adapt memory span based on recent defections
        if opponent in self.opponent_history and len(self.opponent_history[opponent]) >= 5:
            recent_defect_count = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defect_count >= 3:
                self.memory_span = max(self.memory_span_min, self.memory_span - self.memory_span_decay)
            elif recent_defect_count <= 1:
                self.memory_span = min(30, self.memory_span + self.memory_span_decay * 0.5)

        # No noise, deterministic decision
        if score >= self.base_cooperation_threshold:
            return True
        else:
            # Track how many times we've defected against this opponent
            if opponent not in self.cooperation_streak:
                self.cooperation_streak[opponent] = 0
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            self._update_reputation(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_reputation(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            self._update_variance(other, other_action)
            self._update_trend(other, other_action)
            self._update_consistency(other, other_action)
            self._update_alternation(other, other_action)
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
                if other in self.suspicion:
                    self.suspicion[other] = max(0.0, self.suspicion[other] - 0.05)
                # Update cooperation streak
                if other not in self.cooperation_streak:
                    self.cooperation_streak[other] = 0
                self.cooperation_streak[other] += 1
                self.cooperation_streak[other] = min(10, self.cooperation_streak[other])
                # Reset escalation on cooperation
                self.defection_escalation[other] = 0
                # Child exploration: if opponent cooperated after a defection, boost forgiveness
                if other in self.defection_memory and self.defection_memory[other] == 0 and other in self.opponent_history and len(self.opponent_history[other]) >= 2:
                    # Check if last action was defection and now cooperation
                    last_opp_action = self.opponent_history[other][-2][0]
                    if last_opp_action == 'defect':
                        self.forgiveness = min(0.5, self.forgiveness + self.forgiveness_boost)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
                if other not in self.suspicion:
                    self.suspicion[other] = 0.0
                self.suspicion[other] = min(0.5, self.suspicion[other] + self.suspicion_increment)
                # Reset cooperation streak
                self.cooperation_streak[other] = 0
                # Escalate defection penalty
                if other not in self.defection_escalation:
                    self.defection_escalation[other] = 0.0
                self.defection_escalation[other] += self.escalation_increment
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_history = []
        self.opponent_history = {}
        self.generation = 0
        self.round = 0
        self.total_cooperate = 0
        self.total_defect = 0
        self.trust_decay = 0.95
        self.forgiveness = 0.10
        self.third_party_weight = 0.08
        self.recent_interactions = deque(maxlen=10)
        # New: track reputation momentum (rate of change) for adaptive learning
        self.reputation_momentum = {}  # agent_id -> momentum value
        self.momentum_decay = 0.9
        # New: track opponent's action variability (variance) for prediction
        self.opponent_variability = {}  # agent_id -> (sum_sq, count)
        # New: adaptive exploration based on uncertainty
        self.exploration_rate = 0.6
        self.exploration_decay = 0.99
        # New: memory of opponent's last action for streak detection
        self.opponent_last_action = {}
        self.opponent_streak = {}
        # New: track opponent's historical cooperation rate with recency weighting
        self.opponent_coop_rate = {}  # agent_id -> (weighted_coop, weight)
        # New: track my own reputation as seen by others (simulated)
        self.self_reputation_estimate = 0.5
        # New: adaptive trust threshold based on my own reputation
        self.trust_threshold = 0.5
        # New: learning rate for updating reputation based on third-party observations
        self.third_party_learning_rate = 0.08
        # New: decay factor for opponent cooperation rate memory
        self.coop_rate_decay = 0.98
        # New: momentum threshold to trigger more aggressive updates
        self.momentum_threshold = 0.05
        # New: track opponent's cooperation consistency (variance of cooperation over time)
        self.opponent_consistency = {}  # agent_id -> (coop_count, total_count, weighted_variance)
        # New: adaptive forgiveness based on opponent's consistency
        self.adaptive_forgiveness = 0.10

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        my_hist = [h for h in self.my_history if h[0] == opponent]

        if my_hist:
            coop_count = sum(1 for h in my_hist if h[2])
            coop_rate = coop_count / len(my_hist)
            # New: incorporate momentum to predict future behavior
            if opponent in self.reputation_momentum:
                momentum = self.reputation_momentum[opponent]
                # If momentum is positive, opponent is improving; if negative, declining
                effective_coop_rate = coop_rate + momentum * 0.5
            else:
                effective_coop_rate = coop_rate

            # New: incorporate variability to adjust confidence
            if opponent in self.opponent_variability:
                sum_sq, count = self.opponent_variability[opponent]
                if count > 1:
                    variance = sum_sq / count - (coop_rate ** 2)
                    variance = max(0, variance)
                    # High variance -> less predictable, so be more cautious
                    effective_coop_rate = effective_coop_rate * (1 - 0.2 * variance)
                else:
                    effective_coop_rate = effective_coop_rate

            # New: use streak information
            if opponent in self.opponent_streak:
                streak_len, streak_type = self.opponent_streak[opponent]
                if streak_len >= 3:
                    if streak_type == True:
                        effective_coop_rate = min(1.0, effective_coop_rate * 1.1)
                    else:
                        effective_coop_rate = max(0.0, effective_coop_rate * 0.9)

            # New: incorporate weighted historical cooperation rate
            if opponent in self.opponent_coop_rate:
                weighted_coop, weight = self.opponent_coop_rate[opponent]
                if weight > 0:
                    hist_coop_rate = weighted_coop / weight
                    # Blend with a slightly higher weight on recent history
                    effective_coop_rate = 0.6 * effective_coop_rate + 0.4 * hist_coop_rate

            # New: adjust threshold based on my own reputation and momentum
            threshold = self.trust_threshold
            if self.self_reputation_estimate < 0.3:
                threshold = 0.6
            elif self.self_reputation_estimate > 0.7:
                threshold = 0.4
            # New: if my own reputation is improving, be more trusting
            if self.self_reputation_estimate > 0.5 and self.self_reputation_estimate > 0.5:
                # Check if we have momentum on self? Not tracked, so skip
                pass

            if effective_coop_rate > threshold:
                return True
            elif effective_coop_rate < threshold:
                return False
            else:
                return opp_rep >= threshold
        else:
            threshold = self.trust_threshold
            if opponent not in self.reputation:
                # New: exploration rate increases with uncertainty (no data)
                return random.random() < self.exploration_rate
            if opp_rep > threshold:
                prob = min(0.9, 0.5 + (opp_rep - 0.5) * 0.8)
                return random.random() < prob
            else:
                prob = max(0.1, 0.5 - (0.5 - opp_rep) * 0.8)
                return random.random() < prob

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        if self.round % 30 == 0:
            self.generation += 1
            self.round = 0
            # Decay old reputation and momentum
            for agent in list(self.reputation.keys()):
                self.reputation[agent] *= self.trust_decay
            for agent in list(self.reputation_momentum.keys()):
                self.reputation_momentum[agent] *= self.momentum_decay
            # Decay exploration rate
            self.exploration_rate *= self.exploration_decay
            # Decay variability records
            for agent in list(self.opponent_variability.keys()):
                sum_sq, count = self.opponent_variability[agent]
                self.opponent_variability[agent] = (sum_sq * 0.9, max(1, int(count * 0.9)))
            # Decay streaks
            for agent in list(self.opponent_streak.keys()):
                streak_len, streak_type = self.opponent_streak[agent]
                if streak_len > 0:
                    self.opponent_streak[agent] = (streak_len - 1, streak_type)
                else:
                    del self.opponent_streak[agent]
            # Decay opponent cooperation rate memory
            for agent in list(self.opponent_coop_rate.keys()):
                weighted_coop, weight = self.opponent_coop_rate[agent]
                self.opponent_coop_rate[agent] = (weighted_coop * self.coop_rate_decay, max(0.1, weight * self.coop_rate_decay))
            # Decay consistency records
            for agent in list(self.opponent_consistency.keys()):
                coop_count, total_count, var = self.opponent_consistency[agent]
                if total_count > 0:
                    decayed_total = max(1, int(total_count * 0.9))
                    decayed_coop = coop_count * 0.9
                    self.opponent_consistency[agent] = (decayed_coop, decayed_total, var * 0.9)

        is_self_donor = (donor_id == self.agent_id)
        is_self_recipient = (recipient_id == self.agent_id)

        if is_self_donor or is_self_recipient:
            opponent = recipient_id if is_self_donor else donor_id
            my_action = donor_action if is_self_donor else recipient_action
            opp_action = recipient_action if is_self_donor else donor_action
            my_action_bool = (my_action == 'cooperate')
            opp_action_bool = (opp_action == 'cooperate')

            self.my_history.append((opponent, my_action_bool, opp_action_bool))
            self.recent_interactions.append((opponent, opp_action_bool))

            if my_action_bool:
                self.total_cooperate += 1
            else:
                self.total_defect += 1

            # New: update variability record
            if opponent in self.opponent_variability:
                sum_sq, count = self.opponent_variability[opponent]
                self.opponent_variability[opponent] = (sum_sq + (1 if opp_action_bool else 0) ** 2, count + 1)
            else:
                self.opponent_variability[opponent] = ((1 if opp_action_bool else 0) ** 2, 1)

            # New: update streak tracking
            if opponent in self.opponent_last_action:
                last_action = self.opponent_last_action[opponent]
                if last_action == opp_action_bool:
                    if opponent in self.opponent_streak:
                        streak_len, streak_type = self.opponent_streak[opponent]
                        self.opponent_streak[opponent] = (streak_len + 1, streak_type)
                    else:
                        self.opponent_streak[opponent] = (1, opp_action_bool)
                else:
                    self.opponent_streak[opponent] = (1, opp_action_bool)
            else:
                self.opponent_streak[opponent] = (1, opp_action_bool)
            self.opponent_last_action[opponent] = opp_action_bool

            # New: update weighted cooperation rate with recency weighting
            if opponent in self.opponent_coop_rate:
                weighted_coop, weight = self.opponent_coop_rate[opponent]
                # Use a recency weight: recent actions more important
                recency_weight = 1.0  # could be time-based, but keep simple
                self.opponent_coop_rate[opponent] = (weighted_coop + recency_weight * (1 if opp_action_bool else 0), weight + recency_weight)
            else:
                self.opponent_coop_rate[opponent] = ((1 if opp_action_bool else 0), 1)

            # New: update consistency tracking
            if opponent in self.opponent_consistency:
                coop_count, total_count, var = self.opponent_consistency[opponent]
                old_rate = coop_count / total_count if total_count > 0 else 0.5
                new_rate = (coop_count + (1 if opp_action_bool else 0)) / (total_count + 1)
                # Update variance with exponential moving average
                var = 0.9 * var + 0.1 * (new_rate - old_rate) ** 2
                self.opponent_consistency[opponent] = (coop_count + (1 if opp_action_bool else 0), total_count + 1, var)
            else:
                self.opponent_consistency[opponent] = ((1 if opp_action_bool else 0), 1, 0.0)

            # New: update reputation with momentum-based adjustment and adaptive forgiveness
            old_rep = self.reputation.get(opponent, 0.5)
            # Adjust forgiveness based on opponent's consistency
            if opponent in self.opponent_consistency:
                coop_count, total_count, var = self.opponent_consistency[opponent]
                if total_count > 3 and var < 0.05:
                    self.adaptive_forgiveness = min(0.3, self.adaptive_forgiveness + 0.02)
                elif total_count > 3 and var > 0.15:
                    self.adaptive_forgiveness = max(0.05, self.adaptive_forgiveness - 0.02)
            else:
                self.adaptive_forgiveness = 0.10

            if opp_action_bool:
                if old_rep > 0.7:
                    delta = 0.15
                elif old_rep < 0.3:
                    delta = 0.1
                else:
                    delta = 0.12
            else:
                if old_rep < 0.3:
                    delta = -0.2
                elif old_rep > 0.7:
                    if random.random() < self.adaptive_forgiveness:
                        delta = 0.03
                    else:
                        delta = -0.1
                else:
                    delta = -0.15

            # Apply delta, but adjust based on momentum
            if opponent in self.reputation_momentum:
                momentum = self.reputation_momentum[opponent]
                # If momentum is positive and we are cooperating, reinforce; if negative, dampen
                if momentum > 0 and delta > 0:
                    delta *= 1.2
                elif momentum < 0 and delta < 0:
                    delta *= 1.2
                else:
                    delta *= 0.8  # Opposite direction

            new_rep = old_rep + delta
            new_rep = max(0.0, min(1.0, new_rep))
            self.reputation[opponent] = new_rep

            # Update momentum: exponential moving average of recent changes
            change = new_rep - old_rep
            if opponent in self.reputation_momentum:
                self.reputation_momentum[opponent] = 0.7 * self.reputation_momentum[opponent] + 0.3 * change
            else:
                self.reputation_momentum[opponent] = change

            # Also update the other agent's reputation (same as parent)
            if is_self_donor:
                target = recipient_id
                target_action = recipient_action
            else:
                target = donor_id
                target_action = donor_action

            old_target_rep = self.reputation.get(target, 0.5)
            # Use adaptive forgiveness for target as well
            if target_action == 'cooperate':
                target_delta = 0.05
            else:
                if random.random() < self.adaptive_forgiveness:
                    target_delta = 0.02
                else:
                    target_delta = -0.1
            new_target_rep = max(0.0, min(1.0, old_target_rep + target_delta))
            self.reputation[target] = new_target_rep
            # Update momentum for target
            target_change = new_target_rep - old_target_rep
            if target in self.reputation_momentum:
                self.reputation_momentum[target] = 0.7 * self.reputation_momentum[target] + 0.3 * target_change
            else:
                self.reputation_momentum[target] = target_change

            # New: update self reputation estimate based on my action
            if my_action_bool:
                self.self_reputation_estimate = min(1.0, self.self_reputation_estimate + 0.02)
            else:
                self.self_reputation_estimate = max(0.0, self.self_reputation_estimate - 0.03)

        else:
            # Third-party observation: use adaptive weight based on momentum
            donor_known = donor_id in self.reputation
            recipient_known = recipient_id in self.reputation

            donor_weight = self.third_party_learning_rate * (0.5 if donor_known else 1.5)
            recipient_weight = self.third_party_learning_rate * (0.5 if recipient_known else 1.5)

            # New: adjust weight based on momentum - if momentum is high, trust less (unstable)
            if donor_id in self.reputation_momentum:
                momentum = self.reputation_momentum[donor_id]
                if abs(momentum) > self.momentum_threshold:
                    donor_weight *= 0.7  # Unstable, trust less
                else:
                    donor_weight *= 1.3  # Stable, trust more
            if recipient_id in self.reputation_momentum:
                momentum = self.reputation_momentum[recipient_id]
                if abs(momentum) > self.momentum_threshold:
                    recipient_weight *= 0.7
                else:
                    recipient_weight *= 1.3

            # New: adjust weight based on my own reputation estimate
            if self.self_reputation_estimate < 0.3:
                donor_weight *= 1.2
                recipient_weight *= 1.2
            elif self.self_reputation_estimate > 0.7:
                donor_weight *= 0.8
                recipient_weight *= 0.8

            old_donor_rep = self.reputation.get(donor_id, 0.5)
            old_recipient_rep = self.reputation.get(recipient_id, 0.5)

            if donor_action == 'cooperate':
                donor_delta = donor_weight
            else:
                donor_delta = -donor_weight * 2

            if recipient_action == 'cooperate':
                recipient_delta = recipient_weight
            else:
                recipient_delta = -recipient_weight

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        self.action_variance = {}
        self.variance_weight = 0.2
        self.coop_trend = {}
        self.trend_weight = 0.25
        self.generosity = 0.3
        self.generosity_decay = 0.005
        self.suspicion = {}
        self.suspicion_increment = 0.15
        self.suspicion_decay = 0.02
        # New exploration: use a "reputation_reference" that stabilizes over time
        self.reputation_reference = {}
        self.reference_decay = 0.05
        self.reference_influence = 0.1
        # New exploration: add a "cooperation_streak" to reward consistent cooperation
        self.cooperation_streak = {}
        self.streak_reward = 0.1
        self.streak_penalty = 0.05
        # New exploration: add a "defection_escalation" to penalize repeated defections more
        self.defection_escalation = {}
        self.escalation_increment = 0.05
        # Child exploration: add a "memory_span" parameter that shortens over time
        self.memory_span = 30
        self.memory_span_decay = 0.1
        self.memory_span_min = 5
        # Child exploration: add a "forgiveness_boost" that increases when opponent cooperates after defection
        self.forgiveness_boost = 0.05
        # New child exploration: add a "risk_tolerance" that makes the agent more willing to cooperate when uncertain
        self.risk_tolerance = 0.1
        # New child exploration: add a "trust_momentum" that makes trust changes more gradual
        self.trust_momentum = 0.1

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-self.memory_span:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_reputation(self, agent_id: int, action: str) -> None:
        old_rep = self.reputation.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = 1.0
        else:
            new_val = 0.0
        # Use a slower update for reputation to make changes more gradual
        self.reputation[agent_id] = old_rep * 0.95 + 0.05 * new_val
        # Update reputation reference with a slower moving average
        old_ref = self.reputation_reference.get(agent_id, 0.5)
        self.reputation_reference[agent_id] = old_ref * (1 - self.reference_decay) + self.reputation[agent_id] * self.reference_decay

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # New exploration: check if we have a strong cooperation streak to reward
        if opponent in self.cooperation_streak and self.cooperation_streak[opponent] >= 3:
            # Reward consistent cooperation
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # Use a stronger reciprocity bias
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.2 * opp_coop + 0.3 * trust
        # Add a small influence from the reputation reference to stabilize decisions
        ref = self.reputation_reference.get(opponent, 0.5)
        score += self.reference_influence * (ref - 0.5)
        if opponent in self.opponent_history:
            # Use shorter memory for defection detection
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-self.memory_span:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
            # Escalation penalty grows with repeated defections
            if opponent in self.defection_escalation:
                score -= self.defection_escalation[opponent]
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        # Use a stronger reciprocity bias
        score += self.reciprocity_bias * reciprocity
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        score += self.generosity
        self.generosity = max(0.0, self.generosity - self.generosity_decay)

        suspicion = self.suspicion.get(opponent, 0.0)
        if suspicion > 0:
            score -= suspicion
            self.suspicion[opponent] = max(0.0, suspicion - self.suspicion_decay)

        # Child exploration: adapt memory span based on recent defections
        if opponent in self.opponent_history and len(self.opponent_history[opponent]) >= 5:
            recent_defect_count = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defect_count >= 3:
                self.memory_span = max(self.memory_span_min, self.memory_span - self.memory_span_decay)
            elif recent_defect_count <= 1:
                self.memory_span = min(30, self.memory_span + self.memory_span_decay * 0.5)

        # Child exploration: add risk tolerance - if uncertainty is high, be more willing to cooperate
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score += self.risk_tolerance * (1 - normalized_var)  # Less variance means more willing to cooperate
        else:
            # No history, be slightly more cooperative due to risk tolerance
            score += self.risk_tolerance * 0.5

        # Child exploration: trust momentum - trust changes more slowly
        if opponent in self.trust:
            self.trust[opponent] = self.trust[opponent] * (1 - self.trust_momentum) + trust * self.trust_momentum

        # No noise, deterministic decision
        if score >= self.base_cooperation_threshold:
            return True
        else:
            # Track how many times we've defected against this opponent
            if opponent not in self.cooperation_streak:
                self.cooperation_streak[opponent] = 0
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            self._update_reputation(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_reputation(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            self._update_variance(other, other_action)
            self._update_trend(other, other_action)
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
                if other in self.suspicion:
                    self.suspicion[other] = max(0.0, self.suspicion[other] - 0.05)
                # Update cooperation streak
                if other not in self.cooperation_streak:
                    self.cooperation_streak[other] = 0
                self.cooperation_streak[other] += 1
                self.cooperation_streak[other] = min(10, self.cooperation_streak[other])
                # Reset escalation on cooperation
                self.defection_escalation[other] = 0
                # Child exploration: if opponent cooperated after a defection, boost forgiveness
                if other in self.defection_memory and self.defection_memory[other] == 0 and other in self.opponent_history and len(self.opponent_history[other]) >= 2:
                    # Check if last action was defection and now cooperation
                    last_opp_action = self.opponent_history[other][-2][0]
                    if last_opp_action == 'defect':
                        self.forgiveness = min(0.5, self.forgiveness + self.forgiveness_boost)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
                if other not in self.suspicion:
                    self.suspicion[other] = 0.0
                self.suspicion[other] = min(0.5, self.suspicion[other] + self.suspicion_increment)
                # Reset cooperation streak
                self.cooperation_streak[other] = 0
                # Escalate defection penalty
                if other not in self.defection_escalation:
                    self.defection_escalation[other] = 0.0
                self.defection_escalation[other] += self.escalation_increment
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_history = []
        self.opponent_history = {}
        self.generation = 0
        self.round = 0
        self.total_cooperate = 0
        self.total_defect = 0
        self.trust_decay = 0.95
        self.forgiveness = 0.10
        self.third_party_weight = 0.08
        self.recent_interactions = deque(maxlen=10)
        self.reputation_delta = {}
        self.reputation_count = {}
        self.opponent_consistency = {}
        self.exploration_rate = 0.6
        self.exploration_decay = 0.99
        self.opponent_last_action = {}
        self.opponent_streak = {}
        self.opponent_coop_rate = {}
        self.self_reputation_estimate = 0.5
        self.trust_threshold = 0.5
        self.third_party_learning_rate = 0.08
        self.coop_rate_decay = 0.98
        # New: track recent opponent actions for adaptive forgiveness
        self.recent_opponent_actions = {}  # agent_id -> deque of recent bool actions
        self.recent_memory_size = 5

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        my_hist = [h for h in self.my_history if h[0] == opponent]

        if my_hist:
            coop_count = sum(1 for h in my_hist if h[2])
            coop_rate = coop_count / len(my_hist)
            if opponent in self.reputation_delta:
                volatility = abs(self.reputation_delta[opponent] / max(1, self.reputation_count[opponent]))
                effective_coop_rate = coop_rate * (1 - 0.5 * volatility)
            else:
                effective_coop_rate = coop_rate

            if opponent in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[opponent]
                consistency = coop_total / max(1, total)
                if consistency > 0.8:
                    effective_coop_rate = min(1.0, effective_coop_rate * 1.2)
                elif consistency < 0.2:
                    effective_coop_rate = max(0.0, effective_coop_rate * 0.8)

            if opponent in self.opponent_streak:
                streak_len, streak_type = self.opponent_streak[opponent]
                if streak_len >= 3:
                    if streak_type == True:
                        effective_coop_rate = min(1.0, effective_coop_rate * 1.1)
                    else:
                        effective_coop_rate = max(0.0, effective_coop_rate * 0.9)

            if opponent in self.opponent_coop_rate:
                coop_total, total = self.opponent_coop_rate[opponent]
                hist_coop_rate = coop_total / max(1, total)
                effective_coop_rate = 0.7 * effective_coop_rate + 0.3 * hist_coop_rate

            threshold = self.trust_threshold
            if self.self_reputation_estimate < 0.3:
                threshold = 0.6
            elif self.self_reputation_estimate > 0.7:
                threshold = 0.4

            # New: adaptive forgiveness - if opponent recently cooperated after a defection, be more forgiving
            if opponent in self.recent_opponent_actions and len(self.recent_opponent_actions[opponent]) > 0:
                recent_actions = list(self.recent_opponent_actions[opponent])
                if recent_actions[-1] == True and (len(recent_actions) < 2 or recent_actions[-2] == False):
                    # Opponent switched from defect to cooperate - give a bonus
                    effective_coop_rate = min(1.0, effective_coop_rate + 0.1)

            if effective_coop_rate > threshold:
                return True
            elif effective_coop_rate < threshold:
                return False
            else:
                return opp_rep >= threshold
        else:
            threshold = self.trust_threshold
            if opponent not in self.reputation:
                return random.random() < self.exploration_rate
            if opp_rep > threshold:
                prob = min(0.9, 0.5 + (opp_rep - 0.5) * 0.8)
                return random.random() < prob
            else:
                prob = max(0.1, 0.5 - (0.5 - opp_rep) * 0.8)
                return random.random() < prob

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        if self.round % 30 == 0:
            self.generation += 1
            self.round = 0
            for agent in list(self.reputation.keys()):
                self.reputation[agent] *= self.trust_decay
            for agent in list(self.reputation_delta.keys()):
                self.reputation_delta[agent] *= self.trust_decay
            self.exploration_rate *= self.exploration_decay
            for agent in list(self.opponent_consistency.keys()):
                coop_total, total = self.opponent_consistency[agent]
                self.opponent_consistency[agent] = (coop_total * 0.9, max(1, int(total * 0.9)))
            for agent in list(self.opponent_streak.keys()):
                streak_len, streak_type = self.opponent_streak[agent]
                if streak_len > 0:
                    self.opponent_streak[agent] = (streak_len - 1, streak_type)
                else:
                    del self.opponent_streak[agent]
            for agent in list(self.opponent_coop_rate.keys()):
                coop_total, total = self.opponent_coop_rate[agent]
                self.opponent_coop_rate[agent] = (coop_total * self.coop_rate_decay, max(1, int(total * self.coop_rate_decay)))
            # New: decay recent opponent actions (only keep recent)
            for agent in list(self.recent_opponent_actions.keys()):
                dq = self.recent_opponent_actions[agent]
                if len(dq) > self.recent_memory_size:
                    # Keep only the most recent ones
                    while len(dq) > self.recent_memory_size:
                        dq.popleft()

        is_self_donor = (donor_id == self.agent_id)
        is_self_recipient = (recipient_id == self.agent_id)

        if is_self_donor or is_self_recipient:
            opponent = recipient_id if is_self_donor else donor_id
            my_action = donor_action if is_self_donor else recipient_action
            opp_action = recipient_action if is_self_donor else donor_action
            my_action_bool = (my_action == 'cooperate')
            opp_action_bool = (opp_action == 'cooperate')

            self.my_history.append((opponent, my_action_bool, opp_action_bool))
            self.recent_interactions.append((opponent, opp_action_bool))

            # New: add to recent opponent actions deque
            if opponent not in self.recent_opponent_actions:
                self.recent_opponent_actions[opponent] = deque(maxlen=self.recent_memory_size)
            self.recent_opponent_actions[opponent].append(opp_action_bool)

            if my_action_bool:
                self.total_cooperate += 1
            else:
                self.total_defect += 1

            if opponent in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[opponent]
                self.opponent_consistency[opponent] = (coop_total + (1 if opp_action_bool else 0), total + 1)
            else:
                self.opponent_consistency[opponent] = (1 if opp_action_bool else 0, 1)

            if opponent in self.opponent_coop_rate:
                coop_total, total = self.opponent_coop_rate[opponent]
                self.opponent_coop_rate[opponent] = (coop_total + (1 if opp_action_bool else 0), total + 1)
            else:
                self.opponent_coop_rate[opponent] = (1 if opp_action_bool else 0, 1)

            if opponent in self.opponent_last_action:
                last_action = self.opponent_last_action[opponent]
                if last_action == opp_action_bool:
                    if opponent in self.opponent_streak:
                        streak_len, streak_type = self.opponent_streak[opponent]
                        self.opponent_streak[opponent] = (streak_len + 1, streak_type)
                    else:
                        self.opponent_streak[opponent] = (1, opp_action_bool)
                else:
                    self.opponent_streak[opponent] = (1, opp_action_bool)
            else:
                self.opponent_streak[opponent] = (1, opp_action_bool)
            self.opponent_last_action[opponent] = opp_action_bool

            old_rep = self.reputation.get(opponent, 0.5)
            if opp_action_bool:
                # New: adaptive forgiveness - if recent behavior showed a switch from defect, reward more
                if opponent in self.recent_opponent_actions:
                    recent_list = list(self.recent_opponent_actions[opponent])
                    if len(recent_list) >= 2 and recent_list[-1] == True and recent_list[-2] == False:
                        delta = 0.18  # Extra reward for switching to cooperation
                    else:
                        if old_rep > 0.7:
                            delta = 0.15
                        elif old_rep < 0.3:
                            delta = 0.1
                        else:
                            delta = 0.12
                else:
                    if old_rep > 0.7:
                        delta = 0.15
                    elif old_rep < 0.3:
                        delta = 0.1
                    else:
                        delta = 0.12
            else:
                if old_rep < 0.3:
                    delta = -0.2
                elif old_rep > 0.7:
                    if random.random() < self.forgiveness:
                        delta = 0.03
                    else:
                        delta = -0.1
                else:
                    delta = -0.15

            new_rep = old_rep + delta
            new_rep = max(0.0, min(1.0, new_rep))
            self.reputation[opponent] = new_rep

            self.reputation_delta[opponent] = self.reputation_delta.get(opponent, 0) + abs(new_rep - old_rep)
            self.reputation_count[opponent] = self.reputation_count.get(opponent, 0) + 1

            if is_self_donor:
                target = recipient_id
                target_action = recipient_action
            else:
                target = donor_id
                target_action = donor_action

            old_target_rep = self.reputation.get(target, 0.5)
            if target_action == 'cooperate':
                target_delta = 0.05
            else:
                target_delta = -0.1
            new_target_rep = max(0.0, min(1.0, old_target_rep + target_delta))
            self.reputation[target] = new_target_rep
            self.reputation_delta[target] = self.reputation_delta.get(target, 0) + abs(new_target_rep - old_target_rep)
            self.reputation_count[target] = self.reputation_count.get(target, 0) + 1

            if my_action_bool:
                self.self_reputation_estimate = min(1.0, self.self_reputation_estimate + 0.02)
            else:
                self.self_reputation_estimate = max(0.0, self.self_reputation_estimate - 0.03)

        else:
            donor_known = donor_id in self.reputation
            recipient_known = recipient_id in self.reputation

            donor_weight = self.third_party_learning_rate * (0.5 if donor_known else 1.5)
            recipient_weight = self.third_party_learning_rate * (0.5 if recipient_known else 1.5)

            if donor_id in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[donor_id]
                consistency = coop_total / max(1, total)
                donor_weight *= (0.7 if consistency > 0.8 or consistency < 0.2 else 1.3)
            if recipient_id in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[recipient_id]
                consistency = coop_total / max(1, total)
                recipient_weight *= (0.7 if consistency > 0.8 or consistency < 0.2 else 1.3)

            if self.self_reputation_estimate < 0.3:
                donor_weight *= 1.2
                recipient_weight *= 1.2
            elif self.self_reputation_estimate > 0.7:
                donor_weight *= 0.8
                recipient_weight *= 0.8

            old_donor_rep = self.reputation.get(donor_id, 0.5)
