from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        self.action_variance = {}
        self.variance_weight = 0.2
        self.coop_trend = {}
        self.trend_weight = 0.25
        self.generosity = 0.3
        self.generosity_decay = 0.005
        self.suspicion = {}
        self.suspicion_increment = 0.15
        self.suspicion_decay = 0.02
        # New exploration: use a "reputation_reference" that stabilizes over time
        self.reputation_reference = {}
        self.reference_decay = 0.05
        self.reference_influence = 0.1
        # New exploration: add a "cooperation_streak" to reward consistent cooperation
        self.cooperation_streak = {}
        self.streak_reward = 0.1
        self.streak_penalty = 0.05
        # New exploration: add a "defection_escalation" to penalize repeated defections more
        self.defection_escalation = {}
        self.escalation_increment = 0.05
        # Child exploration: add a "memory_span" parameter that shortens over time
        self.memory_span = 30
        self.memory_span_decay = 0.1
        self.memory_span_min = 5
        # Child exploration: add a "forgiveness_boost" that increases when opponent cooperates after defection
        self.forgiveness_boost = 0.05
        # New child exploration: add a "risk_tolerance" that makes the agent more willing to cooperate when uncertain
        self.risk_tolerance = 0.1
        # New child exploration: add a "trust_momentum" that makes trust changes more gradual
        self.trust_momentum = 0.1

    def _update_variance(self, opponent: int, action: str) -> None:
        if opponent not in self.opponent_history or len(self.opponent_history[opponent]) < 2:
            return
        recent = [1 if a == 'cooperate' else 0 for a, _ in self.opponent_history[opponent][-self.memory_span:]]
        if len(recent) < 2:
            return
        mean = sum(recent) / len(recent)
        variance = sum((x - mean) ** 2 for x in recent) / len(recent)
        if opponent in self.action_variance:
            self.action_variance[opponent] = 0.9 * self.action_variance[opponent] + 0.1 * variance
        else:
            self.action_variance[opponent] = variance

    def _update_trend(self, opponent: int, action: str) -> None:
        value = 1 if action == 'cooperate' else 0
        if opponent not in self.coop_trend:
            self.coop_trend[opponent] = value
        else:
            self.coop_trend[opponent] = 0.8 * self.coop_trend[opponent] + 0.2 * value

    def _update_reputation(self, agent_id: int, action: str) -> None:
        old_rep = self.reputation.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = 1.0
        else:
            new_val = 0.0
        # Use a slower update for reputation to make changes more gradual
        self.reputation[agent_id] = old_rep * 0.95 + 0.05 * new_val
        # Update reputation reference with a slower moving average
        old_ref = self.reputation_reference.get(agent_id, 0.5)
        self.reputation_reference[agent_id] = old_ref * (1 - self.reference_decay) + self.reputation[agent_id] * self.reference_decay

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # New exploration: check if we have a strong cooperation streak to reward
        if opponent in self.cooperation_streak and self.cooperation_streak[opponent] >= 3:
            # Reward consistent cooperation
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # Use a stronger reciprocity bias
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.2 * opp_coop + 0.3 * trust
        # Add a small influence from the reputation reference to stabilize decisions
        ref = self.reputation_reference.get(opponent, 0.5)
        score += self.reference_influence * (ref - 0.5)
        if opponent in self.opponent_history:
            # Use shorter memory for defection detection
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-self.memory_span:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
            # Escalation penalty grows with repeated defections
            if opponent in self.defection_escalation:
                score -= self.defection_escalation[opponent]
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        # Use a stronger reciprocity bias
        score += self.reciprocity_bias * reciprocity
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score -= self.variance_weight * normalized_var
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]
            if trend > 0.7:
                score += self.trend_weight * (trend - 0.7) / 0.3
            elif trend < 0.3:
                score -= self.trend_weight * (0.3 - trend) / 0.3
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        score += self.generosity
        self.generosity = max(0.0, self.generosity - self.generosity_decay)

        suspicion = self.suspicion.get(opponent, 0.0)
        if suspicion > 0:
            score -= suspicion
            self.suspicion[opponent] = max(0.0, suspicion - self.suspicion_decay)

        # Child exploration: adapt memory span based on recent defections
        if opponent in self.opponent_history and len(self.opponent_history[opponent]) >= 5:
            recent_defect_count = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defect_count >= 3:
                self.memory_span = max(self.memory_span_min, self.memory_span - self.memory_span_decay)
            elif recent_defect_count <= 1:
                self.memory_span = min(30, self.memory_span + self.memory_span_decay * 0.5)

        # Child exploration: add risk tolerance - if uncertainty is high, be more willing to cooperate
        if opponent in self.action_variance:
            normalized_var = min(1.0, self.action_variance[opponent] * 4)
            score += self.risk_tolerance * (1 - normalized_var)  # Less variance means more willing to cooperate
        else:
            # No history, be slightly more cooperative due to risk tolerance
            score += self.risk_tolerance * 0.5

        # Child exploration: trust momentum - trust changes more slowly
        if opponent in self.trust:
            self.trust[opponent] = self.trust[opponent] * (1 - self.trust_momentum) + trust * self.trust_momentum

        # No noise, deterministic decision
        if score >= self.base_cooperation_threshold:
            return True
        else:
            # Track how many times we've defected against this opponent
            if opponent not in self.cooperation_streak:
                self.cooperation_streak[opponent] = 0
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            self._update_reputation(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_reputation(recipient_id, recipient_action)
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                my_action = donor_action
                other_action = recipient_action
            else:
                other = donor_id
                my_action = recipient_action
                other_action = donor_action
            self.my_history.append(my_action)
            if other not in self.opponent_history:
                self.opponent_history[other] = []
            self.opponent_history[other].append((other_action, my_action))
            if other not in self.recent_actions:
                self.recent_actions[other] = []
            self.recent_actions[other].append(other_action)
            if len(self.recent_actions[other]) > 10:
                self.recent_actions[other].pop(0)
            self._update_variance(other, other_action)
            self._update_trend(other, other_action)
            if other_action == 'cooperate':
                self.trust[other] = self.trust.get(other, 0.5) * 0.9 + 0.1
                if other in self.defection_memory:
                    self.defection_memory[other] = max(0, self.defection_memory[other] - 1)
                if other in self.suspicion:
                    self.suspicion[other] = max(0.0, self.suspicion[other] - 0.05)
                # Update cooperation streak
                if other not in self.cooperation_streak:
                    self.cooperation_streak[other] = 0
                self.cooperation_streak[other] += 1
                self.cooperation_streak[other] = min(10, self.cooperation_streak[other])
                # Reset escalation on cooperation
                self.defection_escalation[other] = 0
                # Child exploration: if opponent cooperated after a defection, boost forgiveness
                if other in self.defection_memory and self.defection_memory[other] == 0 and other in self.opponent_history and len(self.opponent_history[other]) >= 2:
                    # Check if last action was defection and now cooperation
                    last_opp_action = self.opponent_history[other][-2][0]
                    if last_opp_action == 'defect':
                        self.forgiveness = min(0.5, self.forgiveness + self.forgiveness_boost)
            else:
                self.trust[other] = self.trust.get(other, 0.5) * 0.9
                if other not in self.defection_memory:
                    self.defection_memory[other] = 0
                self.defection_memory[other] += 1
                if other not in self.suspicion:
                    self.suspicion[other] = 0.0
                self.suspicion[other] = min(0.5, self.suspicion[other] + self.suspicion_increment)
                # Reset cooperation streak
                self.cooperation_streak[other] = 0
                # Escalate defection penalty
                if other not in self.defection_escalation:
                    self.defection_escalation[other] = 0.0
                self.defection_escalation[other] += self.escalation_increment
        self.round += 1
        if self.round % 50 == 0:
            self.forgiveness = min(0.5, self.forgiveness + 0.02)

