            # If I've been too cooperative, be slightly more cautious
            if my_coop_rate > 0.8:
                base_coop_prob *= 0.9
            # If I've been too defecting, be more generous to rebuild trust
            elif my_coop_rate < 0.2:
                base_coop_prob = min(0.7, base_coop_prob + 0.1)

        # Add some randomness to avoid being completely predictable
        noise = random.uniform(-0.1, 0.1)
        coop_prob = max(0.0, min(1.0, base_coop_prob + noise))

        return random.random() < coop_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
