            if actor_id not in self.defect_counts:
                self.defect_counts[actor_id] = 0

            # Update counts and reputation
            if action == 'cooperate':
                self.coop_counts[actor_id] += 1
                # Positive adjustment
                self.reputation[actor_id] = self.reputation[actor_id] * 0.95 + 0.05
            else:
                self.defect_counts[actor_id] += 1
                # Negative adjustment
                self.reputation[actor_id] = self.reputation[actor_id] * 0.95

            # Clamp reputation to [0,1]
            self.reputation[actor_id] = max(0.0, min(1.0, self.reputation[actor_id]))

        # Update my own stats if I'm involved
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_defect += 1
            self.total_interactions += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_defect += 1
            self.total_interactions += 1

        # Track per-opponent history for the current round if I'm involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            if other_id not in self.opponent_history:
                self.opponent_history[other_id] = []
            self.opponent_history[other_id].append(1 if other_action == 'cooperate' else 0)
            # Keep only recent history
            if len(self.opponent_history[other_id]) > 10:
                self.opponent_history[other_id] = self.opponent_history[other_id][-10:]

        # Update round counter based on self-observations? Since observe is called for all actions,
        # we can't easily count rounds. We'll just leave round_num as is for now.
        # Could increment on self-involvement, but not necessary.

import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None

        # Reputation tracking: agent_id -> {'coop': count, 'def': count}
        self.reputation = {}

        # For self-play memory: track outcomes with each partner
        # partner_id -> {'my_coop': int, 'my_def': int, 'their_coop': int, 'their_def': int}
        self.history = {}

        # Track my own recent actions and outcomes for strategy adjustment
        self.my_recent = deque(maxlen=200)  # deque for bounded memory
        self.sit_out_count = 0

        # Parameters for strategy
        self.coop_threshold = 0.5  # willingness to cooperate with strangers
        self.alpha = 0.3  # weight for reputation vs personal history
        self.beta = 0.1   # exploration noise

        # Generation tracking
        self.generation_round = 0
        self.total_rounds = 0

        # New: memory decay factor for reputation (forget old observations)
        self.decay = 0.95

    def decide(self) -> bool:
        self.total_rounds += 1
        self.generation_round += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # shouldn't happen, but safe

        # Initialize reputation if unknown
        if opp not in self.reputation:
            self.reputation[opp] = {'coop': 0, 'def': 0, 'total': 0}
        if opp not in self.history:
            self.history[opp] = {'my_coop': 0, 'my_def': 0, 'their_coop': 0, 'their_def': 0, 'total': 0}

        # Compute opponent's cooperation rate from reputation with decay
        rep = self.reputation[opp]
        total_obs = rep['total']
        coop_rate = rep['coop'] / total_obs if total_obs > 0 else 0.5

        # Compute opponent's cooperation rate from personal history
        hist = self.history[opp]
        total_hist = hist['total']
        their_rate = (hist['their_coop'] / total_hist) if total_hist > 0 else 0.5

        # Combine reputation and personal history with adaptive alpha
        # If I have little personal history, trust reputation more
        if total_hist < 5:
            alpha_eff = min(0.8, self.alpha + 0.2)
        else:
            alpha_eff = self.alpha
        combined_coop = alpha_eff * coop_rate + (1 - alpha_eff) * their_rate

        # My history with this opponent: what did I do last time?
        # Use a more flexible tit-for-tat based on recent interactions
        if total_hist > 0:
            # Their last action (most recent) - track in history as a counter
            # We approximate by checking if their total coop is increasing
            # Instead, use a simple conditional: if they cooperated more than 60% recently, be cooperative
            if their_rate > 0.6:
                prob_coop = 0.8 + 0.2 * (their_rate - 0.6) * 2
            elif their_rate > 0.3:
                prob_coop = 0.4 + 0.3 * (their_rate - 0.3) / 0.3
            else:
                prob_coop = max(0.1, 0.2 - (0.3 - their_rate) * 2)
        else:
            # No history - use reputation and general trust, more cautious
            prob_coop = max(0.1, min(0.8, combined_coop * 0.7 + 0.1))

        # Add exploration noise
        prob_coop = max(0.0, min(1.0, prob_coop + random.uniform(-self.beta, self.beta)))

        # Occasionally adjust based on my recent performance
        if len(self.my_recent) >= 10:
            recent_actions = [a for a, _, _ in self.my_recent]
            coop_count = sum(1 for a in recent_actions if a)
            # If I've been mostly cooperating, be more cautious; if mostly defecting, be more cooperative
            if coop_count > 8:
                prob_coop = min(0.9, prob_coop - 0.05)
            elif coop_count < 2:
                prob_coop = max(0.1, prob_coop + 0.05)

        # Decide
        return random.random() < prob_coop

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for all observed actions with decay
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid not in self.reputation:
                self.reputation[pid] = {'coop': 0, 'def': 0, 'total': 0}
            rep = self.reputation[pid]
            # Decay existing counts
            rep['coop'] *= self.decay
            rep['def'] *= self.decay
            rep['total'] *= self.decay
            # Add new observation
            if action == 'cooperate':
                rep['coop'] += 1
            else:
                rep['def'] += 1
            rep['total'] += 1

        # If I am involved, update my personal history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who is me and who is opponent
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            if opp_id not in self.history:
                self.history[opp_id] = {'my_coop': 0, 'my_def': 0, 'their_coop': 0, 'their_def': 0, 'total': 0}
            hist = self.history[opp_id]

            # Update my count
            if my_action == 'cooperate':
                hist['my_coop'] += 1
            else:
                hist['my_def'] += 1

            # Update opponent count
            if opp_action == 'cooperate':
                hist['their_coop'] += 1
            else:
                hist['their_def'] += 1
            hist['total'] += 1

            # Record outcome for this interaction
            # Outcome: 1 if I cooperated and they cooperated, 0.5 if mixed, 0 if both defected
            if my_action == 'cooperate' and opp_action == 'cooperate':
                outcome = 1.0
            elif my_action == 'defect' and opp_action == 'defect':
                outcome = 0.0
            else:
                outcome = 0.5
            self.my_recent.append((my_action == 'cooperate', opp_id, outcome))

        # If I sat out, just track that
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            pass  # We observe third-party interactions for reputation

        # Reset generation round if needed? Not needed; we keep track in decide.

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_history = []
        self.opponent_history = {}
        self.generation = 0
        self.round = 0
        self.total_cooperate = 0
        self.total_defect = 0
        self.trust_decay = 0.95
        self.forgiveness = 0.10
        self.third_party_weight = 0.08
        self.recent_interactions = deque(maxlen=10)
        # New: track reputation momentum (rate of change) for adaptive learning
        self.reputation_momentum = {}  # agent_id -> momentum value
        self.momentum_decay = 0.9
        # New: track opponent's action variability (variance) for prediction
        self.opponent_variability = {}  # agent_id -> (sum_sq, count)
        # New: adaptive exploration based on uncertainty
        self.exploration_rate = 0.6
        self.exploration_decay = 0.99
        # New: memory of opponent's last action for streak detection
        self.opponent_last_action = {}
        self.opponent_streak = {}
        # New: track opponent's historical cooperation rate with recency weighting
        self.opponent_coop_rate = {}  # agent_id -> (weighted_coop, weight)
        # New: track my own reputation as seen by others (simulated)
        self.self_reputation_estimate = 0.5
        # New: adaptive trust threshold based on my own reputation
        self.trust_threshold = 0.5
        # New: learning rate for updating reputation based on third-party observations
        self.third_party_learning_rate = 0.08
        # New: decay factor for opponent cooperation rate memory
        self.coop_rate_decay = 0.98
        # New: momentum threshold to trigger more aggressive updates
        self.momentum_threshold = 0.05
        # New: track opponent's cooperation consistency (variance of cooperation over time)
        self.opponent_consistency = {}  # agent_id -> (coop_count, total_count, weighted_variance)
        # New: adaptive forgiveness based on opponent's consistency
        self.adaptive_forgiveness = 0.10
        # New: my own action streak for self-monitoring
        self.my_action_streak = 0
        self.my_last_action = None
        # New: regret signal - how often I've been exploited (cooperated while opponent defected)
        self.regret = 0.0
        self.regret_memory = deque(maxlen=20)
        # New: opponent-specific trust thresholds (learning per-opponent)
        self.opponent_thresholds = {}
        # New: threshold adaptation rate
        self.threshold_adapt_rate = 0.05
        self.exploit_count = 0
        self.coop_with_defect_count = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        my_hist = [h for h in self.my_history if h[0] == opponent]

        if my_hist:
            coop_count = sum(1 for h in my_hist if h[2])
            coop_rate = coop_count / len(my_hist)
            # New: incorporate momentum to predict future behavior
            if opponent in self.reputation_momentum:
                momentum = self.reputation_momentum[opponent]
                # If momentum is positive, opponent is improving; if negative, declining
                effective_coop_rate = coop_rate + momentum * 0.5
            else:
                effective_coop_rate = coop_rate

            # New: incorporate variability to adjust confidence
            if opponent in self.opponent_variability:
                sum_sq, count = self.opponent_variability[opponent]
                if count > 1:
                    variance = sum_sq / count - (coop_rate ** 2)
                    variance = max(0, variance)
                    # High variance -> less predictable, so be more cautious
                    effective_coop_rate = effective_coop_rate * (1 - 0.2 * variance)
                else:
                    effective_coop_rate = effective_coop_rate

            # New: use streak information
            if opponent in self.opponent_streak:
                streak_len, streak_type = self.opponent_streak[opponent]
                if streak_len >= 3:
                    if streak_type == True:
                        effective_coop_rate = min(1.0, effective_coop_rate * 1.1)
                    else:
                        effective_coop_rate = max(0.0, effective_coop_rate * 0.9)

            # New: incorporate weighted historical cooperation rate
            if opponent in self.opponent_coop_rate:
                weighted_coop, weight = self.opponent_coop_rate[opponent]
                if weight > 0:
                    hist_coop_rate = weighted_coop / weight
                    # Blend with a slightly higher weight on recent history
                    effective_coop_rate = 0.6 * effective_coop_rate + 0.4 * hist_coop_rate

            # New: adjust threshold based on my own reputation and momentum
            threshold = self.trust_threshold
            # New: use per-opponent threshold if available
            if opponent in self.opponent_thresholds:
                threshold = self.opponent_thresholds[opponent]
            if self.self_reputation_estimate < 0.3:
                threshold = max(threshold, 0.6)
            elif self.self_reputation_estimate > 0.7:
                threshold = min(threshold, 0.4)
            # New: incorporate regret - if I've been exploited a lot, raise threshold
            if self.regret > 0.3:
                threshold = min(0.9, threshold + self.regret * 0.2)

            if effective_coop_rate > threshold:
                return True
            elif effective_coop_rate < threshold:
                return False
            else:
                return opp_rep >= threshold
        else:
            threshold = self.trust_threshold
            if opponent in self.opponent_thresholds:
                threshold = self.opponent_thresholds[opponent]
            if opponent not in self.reputation:
                # New: exploration rate increases with uncertainty (no data)
                return random.random() < self.exploration_rate
            if opp_rep > threshold:
                prob = min(0.9, 0.5 + (opp_rep - 0.5) * 0.8)
                return random.random() < prob
            else:
                prob = max(0.1, 0.5 - (0.5 - opp_rep) * 0.8)
                return random.random() < prob

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        if self.round % 30 == 0:
            self.generation += 1
            self.round = 0
            # Decay old reputation and momentum
            for agent in list(self.reputation.keys()):
                self.reputation[agent] *= self.trust_decay
            for agent in list(self.reputation_momentum.keys()):
                self.reputation_momentum[agent] *= self.momentum_decay
            # Decay exploration rate
            self.exploration_rate *= self.exploration_decay
            # Decay variability records
            for agent in list(self.opponent_variability.keys()):
                sum_sq, count = self.opponent_variability[agent]
                self.opponent_variability[agent] = (sum_sq * 0.9, max(1, int(count * 0.9)))
            # Decay streaks
            for agent in list(self.opponent_streak.keys()):
                streak_len, streak_type = self.opponent_streak[agent]
                if streak_len > 0:
                    self.opponent_streak[agent] = (streak_len - 1, streak_type)
                else:
                    del self.opponent_streak[agent]
            # Decay opponent cooperation rate memory
            for agent in list(self.opponent_coop_rate.keys()):
                weighted_coop, weight = self.opponent_coop_rate[agent]
                self.opponent_coop_rate[agent] = (weighted_coop * self.coop_rate_decay, max(0.1, weight * self.coop_rate_decay))
            # Decay consistency records
            for agent in list(self.opponent_consistency.keys()):
                coop_count, total_count, var = self.opponent_consistency[agent]
                if total_count > 0:
                    decayed_total = max(1, int(total_count * 0.9))
                    decayed_coop = coop_count * 0.9
                    self.opponent_consistency[agent] = (decayed_coop, decayed_total, var * 0.9)
            # Decay regret
            self.regret *= 0.9
            # Decay opponent-specific thresholds back to base
            for agent in list(self.opponent_thresholds.keys()):
                self.opponent_thresholds[agent] = 0.5 + (self.opponent_thresholds[agent] - 0.5) * 0.9

        is_self_donor = (donor_id == self.agent_id)
        is_self_recipient = (recipient_id == self.agent_id)

        if is_self_donor or is_self_recipient:
            opponent = recipient_id if is_self_donor else donor_id
            my_action = donor_action if is_self_donor else recipient_action
            opp_action = recipient_action if is_self_donor else donor_action
            my_action_bool = (my_action == 'cooperate')
            opp_action_bool = (opp_action == 'cooperate')

            self.my_history.append((opponent, my_action_bool, opp_action_bool))
            self.recent_interactions.append((opponent, opp_action_bool))

            if my_action_bool:
                self.total_cooperate += 1
            else:
                self.total_defect += 1

            # New: update my own action streak
            if self.my_last_action is not None:
                if self.my_last_action == my_action_bool:
                    self.my_action_streak += 1
                else:
                    self.my_action_streak = 1
            else:
                self.my_action_streak = 1
            self.my_last_action = my_action_bool

            # New: update variability record
            if opponent in self.opponent_variability:
                sum_sq, count = self.opponent_variability[opponent]
                self.opponent_variability[opponent] = (sum_sq + (1 if opp_action_bool else 0) ** 2, count + 1)
            else:
                self.opponent_variability[opponent] = ((1 if opp_action_bool else 0) ** 2, 1)

            # New: update streak tracking
            if opponent in self.opponent_last_action:
                last_action = self.opponent_last_action[opponent]
                if last_action == opp_action_bool:
                    if opponent in self.opponent_streak:
                        streak_len, streak_type = self.opponent_streak[opponent]
                        self.opponent_streak[opponent] = (streak_len + 1, streak_type)
                    else:
                        self.opponent_streak[opponent] = (1, opp_action_bool)
                else:
                    self.opponent_streak[opponent] = (1, opp_action_bool)
            else:
                self.opponent_streak[opponent] = (1, opp_action_bool)
            self.opponent_last_action[opponent] = opp_action_bool

            # New: update weighted cooperation rate with recency weighting
            if opponent in self.opponent_coop_rate:
                weighted_coop, weight = self.opponent_coop_rate[opponent]
                # Use a recency weight: recent actions more important
                recency_weight = 1.0  # could be time-based, but keep simple
                self.opponent_coop_rate[opponent] = (weighted_coop + recency_weight * (1 if opp_action_bool else 0), weight + recency_weight)
            else:
                self.opponent_coop_rate[opponent] = ((1 if opp_action_bool else 0), 1)

            # New: update consistency tracking
            if opponent in self.opponent_consistency:
                coop_count, total_count, var = self.opponent_consistency[opponent]
                old_rate = coop_count / total_count if total_count > 0 else 0.5
                new_rate = (coop_count + (1 if opp_action_bool else 0)) / (total_count + 1)
                # Update variance with exponential moving average
                var = 0.9 * var + 0.1 * (new_rate - old_rate) ** 2
                self.opponent_consistency[opponent] = (coop_count + (1 if opp_action_bool else 0), total_count + 1, var)
            else:
                self.opponent_consistency[opponent] = ((1 if opp_action_bool else 0), 1, 0.0)

            # New: update reputation with momentum-based adjustment and adaptive forgiveness
            old_rep = self.reputation.get(opponent, 0.5)
            # Adjust forgiveness based on opponent's consistency
            if opponent in self.opponent_consistency:
                coop_count, total_count, var = self.opponent_consistency[opponent]
                if total_count > 3 and var < 0.05:
                    self.adaptive_forgiveness = min(0.3, self.adaptive_forgiveness + 0.02)
                elif total_count > 3 and var > 0.15:
                    self.adaptive_forgiveness = max(0.05, self.adaptive_forgiveness - 0.02)
            else:
                self.adaptive_forgiveness = 0.10

            if opp_action_bool:
                if old_rep > 0.7:
                    delta = 0.15
                elif old_rep < 0.3:
                    delta = 0.1
                else:
                    delta = 0.12
            else:
                if old_rep < 0.3:
                    delta = -0.2
                elif old_rep > 0.7:
                    if random.random() < self.adaptive_forgiveness:
                        delta = 0.03
                    else:
                        delta = -0.1
                else:
                    delta = -0.15

            # Apply delta, but adjust based on momentum
            if opponent in self.reputation_momentum:
                momentum = self.reputation_momentum[opponent]
                # If momentum is positive and we are cooperating, reinforce; if negative, dampen
                if momentum > 0 and delta > 0:
                    delta *= 1.2
                elif momentum < 0 and delta < 0:
                    delta *= 1.2
                else:
                    delta *= 0.8  # Opposite direction

            new_rep = old_rep + delta
            new_rep = max(0.0, min(1.0, new_rep))
            self.reputation[opponent] = new_rep

            # Update momentum: exponential moving average of recent changes
            change = new_rep - old_rep
            if opponent in self.reputation_momentum:
                self.reputation_momentum[opponent] = 0.7 * self.reputation_momentum[opponent] + 0.3 * change
            else:
                self.reputation_momentum[opponent] = change

            # Also update the other agent's reputation (same as parent)
            if is_self_donor:
                target = recipient_id
                target_action = recipient_action
            else:
                target = donor_id
                target_action = donor_action

            old_target_rep = self.reputation.get(target, 0.5)
            # Use adaptive forgiveness for target as well
            if target_action == 'cooperate':
                target_delta = 0.05
            else:
                if random.random() < self.adaptive_forgiveness:
                    target_delta = 0.02
                else:
                    target_delta = -0.1
            new_target_rep = max(0.0, min(1.0, old_target_rep + target_delta))
            self.reputation[target] = new_target_rep
            # Update momentum for target
            target_change = new_target_rep - old_target_rep
            if target in self.reputation_momentum:
                self.reputation_momentum[target] = 0.7 * self.reputation_momentum[target] + 0.3 * target_change
            else:
                self.reputation_momentum[target] = target_change

            # New: update self reputation estimate based on my action
            if my_action_bool:
                self.self_reputation_estimate = min(1.0, self.self_reputation_estimate + 0.02)
            else:
                self.self_reputation_estimate = max(0.0, self.self_reputation_estimate - 0.03)

            # NEW: Regret and threshold adaptation
            # If I cooperated and opponent defected, that's exploitation
            if my_action_bool and not opp_action_bool:
                self.exploit_count += 1
                self.coop_with_defect_count += 1
                self.regret

