import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_counts = {}
        self.defect_counts = {}
        self.round_num = 0
        self.my_coop_rate = 0.5
        self.generosity = 0.5
        self.total_interactions = 0
        self.my_total_coop = 0
        self.my_total_defect = 0
        self.last_opponent = None
        self.opponent_history = {}
        # Emotional memory with a higher decay (more forgetful) and a larger threshold
        self.emotional_memory = {}
        self.trust_decay = 0.7  # Faster decay -> recent interactions dominate
        self.emotion_threshold = 0.5  # Higher threshold -> need stronger emotion to trigger bias

        # New: track a "grudge" counter for defections against me
        self.grudges = {}

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        self.last_opponent = opponent
        if opponent not in self.reputation:
            self.reputation[opponent] = 0.5
        if opponent not in self.coop_counts:
            self.coop_counts[opponent] = 0
        if opponent not in self.defect_counts:
            self.defect_counts[opponent] = 0
        if opponent not in self.emotional_memory:
            self.emotional_memory[opponent] = 0.0
        if opponent not in self.grudges:
            self.grudges[opponent] = 0

        opp_rep = self.reputation[opponent]
        opp_coop = self.coop_counts[opponent]
        opp_defect = self.defect_counts[opponent]
        opp_total = opp_coop + opp_defect

        # Determine opponent's tendency: if enough data, use their coop rate
        if opp_total >= 3:
            opp_tendency = opp_coop / opp_total
        else:
            opp_tendency = opp_rep

        # Cooperation probability based on opponent's cooperative tendency
        base_coop_prob = 0.2 + 0.8 * opp_tendency

        # Emotional adjustment: use a stronger bias when triggered
        emotional_bias = self.emotional_memory[opponent]
        if emotional_bias > self.emotion_threshold:
            base_coop_prob += 0.25  # More boost for strong positive emotion
        elif emotional_bias < -self.emotion_threshold:
            base_coop_prob -= 0.35  # Stronger punishment for strong negative emotion

        # Grudge penalty: if they've defected against me recently, reduce cooperation
        if self.grudges[opponent] > 0:
            base_coop_prob -= 0.1 * self.grudges[opponent]

        # Adjust for my own recent behavior
        if self.total_interactions > 0:
            my_coop_rate = self.my_total_coop / self.total_interactions
            if my_coop_rate > 0.8:
                base_coop_prob *= 0.9
            elif my_coop_rate < 0.2:
                base_coop_prob = min(0.7, base_coop_prob + 0.1)

        # Add noise
        noise = random.uniform(-0.1, 0.1)
        coop_prob = max(0.0, min(1.0, base_coop_prob + noise))

        return random.random() < coop_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation for both actors (same as parent)
        for actor_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if actor_id not in self.reputation:
                self.reputation[actor_id] = 0.5
            if actor_id not in self.coop_counts:
                self.coop_counts[actor_id] = 0
            if actor_id not in self.defect_counts:
                self.defect_counts[actor_id] = 0

            if action == 'cooperate':
                self.coop_counts[actor_id] += 1
                self.reputation[actor_id] = self.reputation[actor_id] * 0.95 + 0.05
            else:
                self.defect_counts[actor_id] += 1
                self.reputation[actor_id] = self.reputation[actor_id] * 0.95

            self.reputation[actor_id] = max(0.0, min(1.0, self.reputation[actor_id]))

        # Update own stats if involved
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_defect += 1
            self.total_interactions += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.my_total_coop += 1
            else:
                self.my_total_defect += 1
            self.total_interactions += 1

        # Track per-opponent history and emotional memory if I'm involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            if other_id not in self.opponent_history:
                self.opponent_history[other_id] = deque(maxlen=10)
            if other_id not in self.emotional_memory:
                self.emotional_memory[other_id] = 0.0
            if other_id not in self.grudges:
                self.grudges[other_id] = 0

            # Record action
            self.opponent_history[other_id].append(1 if other_action == 'cooperate' else 0)

            # Update emotional memory with faster decay
            delta = 0.1 if other_action == 'cooperate' else -0.15
            self.emotional_memory[other_id] = self.emotional_memory[other_id] * self.trust_decay + delta
            self.emotional_memory[other_id] = max(-1.0, min(1.0, self.emotional_memory[other_id]))

            # Update grudge: if they defected against me, increase grudge; if they cooperated, decrease
            if other_action == 'defect':
                self.grudges[other_id] += 1
            else:
                self.grudges[other_id] = max(0, self.grudges[other_id] - 1)

