        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # Modified: use opponent-specific forgiveness in immediate cooperation condition
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        if opponent in self.opponent_streaks and self.opponent_streaks[opponent] >= self.streak_threshold:
            score += self.streak_bonus * self.opponent_streaks[opponent]
        if opponent in self.opponent_defection_streaks and self.opponent_defection_streaks[opponent] >= self.defection_streak_threshold:
            score -= self.defection_streak_bonus * self.opponent_defection_streaks[opponent]
        if opponent in self.reputation_volatility and self.reputation_volatility[opponent] > self.volatility_threshold:
            score -= self.volatility_penalty * (self.reputation_volatility[opponent] - self.volatility_threshold)
        if opponent in self.recent_cooperation_rate:
            rate = self.recent_cooperation_rate[opponent]
            if rate > 0.7:
                score += self.rate_bonus * (rate - 0.7) * 10
        # New mechanism: pattern-based adjustment
        if opponent in self.pattern_memory:
            pattern = self.pattern_memory[opponent]
            if len(pattern) == self.pattern_length:
                if all(a == 'defect' for a in pattern):
                    score -= self.pattern_penalty
                elif all(a == 'cooperate' for a in pattern):
                    score += self.pattern_bonus
        # New mechanism: reputation trend adjustment
        if opponent in self.reputation_history and len(self.reputation_history[opponent]) >= 2:
            hist = self.reputation_history[opponent]
            recent = hist[-self.trend_window:]
            if len(recent) >= 2:
                slope = (recent[-1] - recent[0]) / (len(recent) - 1)
                if slope > 0.02:
                    score += self.trend_bonus
                elif slope < -0.02:
                    score -= self.trend_penalty
        # New mechanism: cooperation consistency (variance) adjustment
        if opponent in self.coop_variance:
            var = self.coop_variance[opponent]
            if var < 0.1:
                score += self.variance_bonus
            elif var > 0.3:
                score -= self.variance_penalty
        # New mechanism: decaying cooperation ratio adjustment
        if opponent in self.decay_coop_ratio:
            ratio = self.decay_coop_ratio[opponent]
            if ratio > 0.7:
                score += self.decay_bonus * (ratio - 0.7) * 2
        # New mechanism: betrayal count adjustment
        if opponent in self.betrayal_count and self.betrayal_count[opponent] >= self.betrayal_threshold:
            score -= self.betrayal_penalty * (self.betrayal_count[opponent] - self.betrayal_threshold + 1)
        # New mechanism: cooperation rate adjustment
        if opponent in self.coop_rate:
            rate = self.coop_rate[opponent]
            if rate > 0.7:
                score += self.coop_rate_bonus * (rate - 0.7) * 10
            elif rate < 0.3:
                score -= self.coop_rate_penalty * (0.3 - rate) * 10
        # New mechanism: reputation shift adjustment
        if opponent in self.reputation_shift:
            shift = self.reputation_shift[opponent]
            if shift > self.shift_threshold:
                score -= self.shift_penalty * (shift - self.shift_threshold)
            elif shift < -self.shift_threshold:
                score += self.shift_bonus * (-shift - self.shift_threshold)
        # New mechanism: conditional cooperation adjustment
        if opponent in self.conditional_coop:
            cond_rate = self.conditional_coop[opponent]
            if cond_rate > self.conditional_threshold:
                score += self.conditional_bonus
            elif cond_rate < (1 - self.conditional_threshold):
                score -= self.conditional_penalty
        # New mechanism: response to my cooperation adjustment
        if opponent in self.response_to_coop:
            response = self.response_to_coop[opponent]
            if response > 0.7:
                score += self.response_bonus
            elif response < 0.3:
                score -= self.response_penalty
        # New mechanism: temporal discounting adjustment
        if opponent in self.temporal_history:
            hist = self.temporal_history[opponent]
            if len(hist) >= 2:
                weighted_sum = 0.0
                weight = 1.0
                total_weight = 0.0
                for action in hist:
                    if action == 'cooperate':
                        weighted_sum += weight
                    weight *= self.temporal_discount
                    total_weight += weight
                if total_weight > 0:
                    recent_ratio = weighted_sum / total_weight
                    if recent_ratio > 0.7:
                        score += self.temporal_bonus
                    elif recent_ratio < 0.3:
                        score -= self.temporal_penalty
        # New mechanism: entropy-based stability adjustment
        if opponent in self.coop_entropy:
            entropy = self.coop_entropy[opponent]
            if entropy < 0.5:
                score += self.entropy_bonus
            elif entropy > 1.5:
                score -= self.entropy_penalty
        # Reciprocity bias based on my recent cooperation rate
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        # Adaptive threshold based on recent outcomes (unchanged)
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
