            self.reputation_history[recipient_id].append(new_rep)
            if len(self.reputation_history[recipient_id]) > self.trend_window:
                self.reputation_history[recipient_id].pop(0)
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
