            coop_rate = coop_count / len(my_hist)

            if opponent in self.reputation_delta:
                volatility = abs(self.reputation_delta[opponent] / max(1, self.reputation_count[opponent]))
                effective_coop_rate = coop_rate * (1 - 0.5 * volatility)
            else:
                effective_coop_rate = coop_rate

            if opponent in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[opponent]
                consistency = coop_total / max(1, total)
                if consistency > 0.8:
                    effective_coop_rate = min(1.0, effective_coop_rate * 1.2)
                elif consistency < 0.2:
                    effective_coop_rate = max(0.0, effective_coop_rate * 0.8)

            if opponent in self.opponent_streak:
                streak_len, streak_type = self.opponent_streak[opponent]
                if streak_len >= 3:
                    if streak_type == True:
                        effective_coop_rate = min(1.0, effective_coop_rate * 1.1)
                    else:
                        effective_coop_rate = max(0.0, effective_coop_rate * 0.9)

            if opponent in self.opponent_coop_rate:
                coop_total, total = self.opponent_coop_rate[opponent]
                hist_coop_rate = coop_total / max(1, total)
                effective_coop_rate = 0.7 * effective_coop_rate + 0.3 * hist_coop_rate

            # New: incorporate recency-weighted average from opponent_recent
            if opponent in self.opponent_recent:
                recent_coop = sum(self.opponent_recent[opponent])
                recent_total = len(self.opponent_recent[opponent])
                if recent_total > 0:
                    recent_rate = recent_coop / recent_total
                    # Blend with recent rate, giving more weight to recent if we have enough data
                    blend_weight = min(0.5, recent_total / 10)
                    effective_coop_rate = (1 - blend_weight) * effective_coop_rate + blend_weight * recent_rate

            # New: adapt threshold based on my own recent cooperation rate
            # If I've been cooperating a lot recently, I expect others to cooperate; if defecting, be more cautious
            if self.my_recent_coop:
                my_coop_rate = sum(self.my_recent_coop) / len(self.my_recent_coop)
                threshold = 0.5 + 0.2 * (0.5 - my_coop_rate)  # higher threshold if I defect often
            else:
                threshold = self.trust_threshold
            if self.self_reputation_estimate < 0.3:
                threshold = 0.6
            elif self.self_reputation_estimate > 0.7:
                threshold = 0.4

            if effective_coop_rate > threshold:
                return True
            elif effective_coop_rate < threshold:
                return False
            else:
                return opp_rep >= threshold
        else:
            threshold = self.trust_threshold
            if opponent not in self.reputation:
                return random.random() < self.exploration_rate
            if opp_rep > threshold:
                prob = min(0.9, 0.5 + (opp_rep - 0.5) * 0.8)
                return random.random() < prob
            else:
                prob = max(0.1, 0.5 - (0.5 - opp_rep) * 0.8)
                return random.random() < prob

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        if self.round % 30 == 0:
            self.generation += 1
            self.round = 0
            for agent in list(self.reputation.keys()):
                self.reputation[agent] *= self.trust_decay
            for agent in list(self.reputation_delta.keys()):
                self.reputation_delta[agent] *= self.trust_decay
            self.exploration_rate *= self.exploration_decay
            for agent in list(self.opponent_consistency.keys()):
                coop_total, total = self.opponent_consistency[agent]
                self.opponent_consistency[agent] = (coop_total * 0.9, max(1, int(total * 0.9)))
            for agent in list(self.opponent_streak.keys()):
                streak_len, streak_type = self.opponent_streak[agent]
                if streak_len > 0:
                    self.opponent_streak[agent] = (streak_len - 1, streak_type)
                else:
                    del self.opponent_streak[agent]
            for agent in list(self.opponent_coop_rate.keys()):
                coop_total, total = self.opponent_coop_rate[agent]
                self.opponent_coop_rate[agent] = (coop_total * self.coop_rate_decay, max(1, int(total * self.coop_rate_decay)))
            # New: decay recent observations to emphasize recent behavior
            for agent in list(self.opponent_recent.keys()):
                # Keep last 10, but multiply by decay to give older ones less weight
                self.opponent_recent[agent] = [x * 0.95 for x in self.opponent_recent[agent]]
                if len(self.opponent_recent[agent]) > 10:
                    self.opponent_recent[agent] = self.opponent_recent[agent][-10:]

        is_self_donor = (donor_id == self.agent_id)
        is_self_recipient = (recipient_id == self.agent_id)

        if is_self_donor or is_self_recipient:
            opponent = recipient_id if is_self_donor else donor_id
            my_action = donor_action if is_self_donor else recipient_action
            opp_action = recipient_action if is_self_donor else donor_action
            my_action_bool = (my_action == 'cooperate')
            opp_action_bool = (opp_action == 'cooperate')

            self.my_history.append((opponent, my_action_bool, opp_action_bool))
            self.recent_interactions.append((opponent, opp_action_bool))
            self.my_recent_coop.append(1 if my_action_bool else 0)

            if my_action_bool:
                self.total_cooperate += 1
            else:
                self.total_defect += 1

            # New: update recency-weighted record
            if opponent in self.opponent_recent:
                self.opponent_recent[opponent].append(1 if opp_action_bool else 0)
                if len(self.opponent_recent[opponent]) > 10:
                    self.opponent_recent[opponent] = self.opponent_recent[opponent][-10:]
            else:
                self.opponent_recent[opponent] = [1 if opp_action_bool else 0]

            if opponent in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[opponent]
                self.opponent_consistency[opponent] = (coop_total + (1 if opp_action_bool else 0), total + 1)
            else:
                self.opponent_consistency[opponent] = (1 if opp_action_bool else 0, 1)

            if opponent in self.opponent_coop_rate:
                coop_total, total = self.opponent_coop_rate[opponent]
                self.opponent_coop_rate[opponent] = (coop_total + (1 if opp_action_bool else 0), total + 1)
            else:
                self.opponent_coop_rate[opponent] = (1 if opp_action_bool else 0, 1)

            if opponent in self.opponent_last_action:
                last_action = self.opponent_last_action[opponent]
                if last_action == opp_action_bool:
                    if opponent in self.opponent_streak:
                        streak_len, streak_type = self.opponent_streak[opponent]
                        self.opponent_streak[opponent] = (streak_len + 1, streak_type)
                    else:
                        self.opponent_streak[opponent] = (1, opp_action_bool)
                else:
                    self.opponent_streak[opponent] = (1, opp_action_bool)
            else:
                self.opponent_streak[opponent] = (1, opp_action_bool)
            self.opponent_last_action[opponent] = opp_action_bool

            old_rep = self.reputation.get(opponent, 0.5)
            if opp_action_bool:
                if old_rep > 0.7:
                    delta = 0.15
                elif old_rep < 0.3:
                    delta = 0.1
                else:
                    delta = 0.12
            else:
                if old_rep < 0.3:
                    delta = -0.2
                elif old_rep > 0.7:
                    if random.random() < self.forgiveness:
                        delta = 0.03
                    else:
                        delta = -0.1
                else:
                    delta = -0.15

            new_rep = old_rep + delta
            new_rep = max(0.0, min(1.0, new_rep))
            self.reputation[opponent] = new_rep

            self.reputation_delta[opponent] = self.reputation_delta.get(opponent, 0) + abs(new_rep - old_rep)
            self.reputation_count[opponent] = self.reputation_count.get(opponent, 0) + 1

            if is_self_donor:
                target = recipient_id
                target_action = recipient_action
            else:
                target = donor_id
                target_action = donor_action

            old_target_rep = self.reputation.get(target, 0.5)
            if target_action == 'cooperate':
                target_delta = 0.05
            else:
                target_delta = -0.1
            new_target_rep = max(0.0, min(1.0, old_target_rep + target_delta))
            self.reputation[target] = new_target_rep
            self.reputation_delta[target] = self.reputation_delta.get(target, 0) + abs(new_target_rep - old_target_rep)
            self.reputation_count[target] = self.reputation_count.get(target, 0) + 1

            if my_action_bool:
                self.self_reputation_estimate = min(1.0, self.self_reputation_estimate + 0.02)
            else:
                self.self_reputation_estimate = max(0.0, self.self_reputation_estimate - 0.03)

        else:
            donor_known = donor_id in self.reputation
            recipient_known = recipient_id in self.reputation

            donor_weight = self.third_party_learning_rate * (0.5 if donor_known else 1.5)
            recipient_weight = self.third_party_learning_rate * (0.5 if recipient_known else 1.5)

            if donor_id in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[donor_id]
                consistency = coop_total / max(1, total)
                donor_weight *= (0.7 if consistency > 0.8 or consistency < 0.2 else 1.3)
            if recipient_id in self.opponent_consistency:
                coop_total, total = self.opponent_consistency[recipient_id]
                consistency = coop_total / max(1, total)
                recipient_weight *= (0.7 if consistency > 0.8 or consistency < 0.2 else 1.3)

            if self.self_reputation_estimate < 0.3:
                donor_weight *= 1.2
                recipient_weight *= 1.2
            elif self.self_reputation_estimate > 0.7:
                donor_weight *= 0.8
                recipient_weight *= 0.8

            old_donor_rep = self.reputation.get(donor_id, 0.5)
            old_recipient_rep = self.reputation.get(recipient_id, 0.5)

            if donor_action == 'cooperate':
                donor_delta = donor_weight
            else:
                donor_delta = -donor_weight * 2

            if recipient_action == 'cooperate':
                recipient_delta = recipient_weight
            else:
                recipient_delta = -recipient_weight * 2

            new_donor_rep = max(0.0, min(1.0, old_donor_rep + donor_delta))
            new_recipient_rep = max(0.0, min(1.0, old_recipient_rep + recipient_delta))

            self.reputation[donor_id] = new_donor_rep
            self.reputation[recipient_id] = new_recipient_rep

            self.reputation_delta[donor_id] = self.reputation_delta.get(donor_id, 0) + abs(new_donor_rep - old_donor_rep)
            self.reputation_count[donor_id] = self.reputation_count.get(donor_id, 0) + 1
            self.reputation_delta[recipient_id] = self.reputation_delta.get(recipient_id, 0) + abs(new_recipient_rep - old_recipient_rep)
            self.reputation_count[recipient_id] = self.reputation_count.get(recipient_id, 0) + 1

            # New: update opponent recent observations from third-party
            if donor_id not in [self.agent_id, recipient_id]:
                if donor_id in self.opponent_recent:
                    self.opponent_recent[donor_id].append(1 if donor_action == 'cooperate' else 0)
                    if len(self.opponent_recent[donor_id]) > 10:
                        self.opponent_recent[donor_id] = self.opponent_recent[donor_id][-10:]
                else:
                    self.opponent_recent[donor_id] = [1 if donor_action == 'cooperate' else 0]
            if recipient_id not in [self.agent_id, donor_id]:
                if recipient_id in self.opponent_recent:
                    self.opponent_recent[recipient_id].append(1 if recipient_action == 'cooperate' else 0)
                    if len(self.opponent_recent[recipient_id]) > 10:
                        self.opponent_recent[recipient_id] = self.opponent_recent[recipient_id][-10:]
                else:
                    self.opponent_recent[recipient_id] = [1 if recipient_action == 'cooperate' else 0]

            if donor_id not in [self.agent_id, recipient_id]:
                if donor_id in self.opponent_coop_rate:
                    coop_total, total = self.opponent_coop_rate[donor_id]
                    self.opponent_coop_rate[donor_id] = (coop_total + (1 if donor_action == 'cooperate' else 0), total + 1)
                else:
                    self.opponent_coop_rate[donor_id] = (1 if donor_action == 'cooperate' else 0, 1)
            if recipient_id not in [self.agent_id, donor_id]:
                if recipient_id in self.opponent_coop_rate:
                    coop_total, total = self.opponent_coop_rate[recipient_id]
                    self.opponent_coop_rate[recipient_id] = (coop_total + (1 if recipient_action == 'cooperate' else 0), total + 1)
                else:
                    self.opponent_coop_rate

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.round = 0
        self.opponent_history = {}
        self.my_history = deque(maxlen=30)
        self.generation = 0
        self.trust = {}
        self.forgiveness = 0.2
        self.base_cooperation_threshold = 0.5
        self.defection_penalty = 0.1
        self.recent_actions = {}
        self.reciprocity_bias = 0.3
        self.adaptation_rate = 0.05
        self.defection_memory = {}
        self.defection_sensitivity = 0.1
        self.opponent_streaks = {}
        self.streak_bonus = 0.1
        self.streak_threshold = 3
        self.opponent_defection_streaks = {}
        self.defection_streak_bonus = 0.15
        self.defection_streak_threshold = 2
        self.risk_taking = 0.0
        self.reputation_volatility = {}
        self.volatility_threshold = 0.2
        self.volatility_decay = 0.95
        self.volatility_penalty = 0.2
        self.recent_cooperation_rate = {}
        self.rate_window = 10
        self.rate_bonus = 0.15
        # New mechanism: track opponent's action patterns (last 3)
        self.pattern_memory = {}
        self.pattern_length = 3
        self.pattern_bonus = 0.2
        self.pattern_penalty = 0.2
        # New mechanism: track reputation trend (slope) over time
        self.reputation_history = {}
        self.trend_window = 5
        self.trend_bonus = 0.1
        self.trend_penalty = 0.1
        # Modified mechanism: explicit forgiveness factor per opponent
        self.opponent_forgiveness = {}
        self.forgiveness_base = 0.2
        self.forgiveness_boost = 0.05
        self.forgiveness_cap = 0.5
        # New mechanism: track opponent cooperation consistency (variance)
        self.coop_variance = {}
        self.variance_window = 5
        self.variance_bonus = 0.2
        self.variance_penalty = 0.2
        # New mechanism: track opponent's recent cooperation ratio with a decaying average
        self.decay_coop_ratio = {}
        self.decay_factor = 0.9
        self.decay_bonus = 0.15
        # New mechanism: track opponent's betrayal count and use it to adjust forgiveness
        self.betrayal_count = {}
        self.betrayal_threshold = 2
        self.betrayal_penalty = 0.2
        self.betrayal_forgiveness_reduction = 0.1
        # New mechanism: track opponent's cooperation rate in the last N rounds
        self.coop_rate_window = 5
        self.coop_rate_bonus = 0.1
        self.coop_rate_penalty = 0.1
        self.coop_rate = {}
        # New mechanism: track opponent's reputation changes to detect strategic shifts
        self.reputation_shift = {}
        self.shift_threshold = 0.15
        self.shift_bonus = 0.1
        self.shift_penalty = 0.1
        self.last_reputation = {}
        # New mechanism: track opponent's cooperation history to detect conditional cooperation
        self.conditional_coop = {}
        self.conditional_threshold = 0.6
        self.conditional_bonus = 0.15
        self.conditional_penalty = 0.1
        # New mechanism: track opponent's response to my cooperation
        self.response_to_coop = {}
        self.response_bonus = 0.1
        self.response_penalty = 0.1
        # New mechanism: track opponent's action history for temporal discounting
        self.temporal_history = {}
        self.temporal_discount = 0.9
        self.temporal_bonus = 0.2
        self.temporal_penalty = 0.2
        # New mechanism: track opponent's cooperation stability (entropy)
        self.coop_entropy = {}
        self.entropy_window = 5
        self.entropy_bonus = 0.15
        self.entropy_penalty = 0.15

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_coop = self.cooperation_count.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        # Modified: use opponent-specific forgiveness in immediate cooperation condition
        if opponent in self.opponent_history and self.opponent_history[opponent]:
            last_opp_action, last_my_action = self.opponent_history[opponent][-1]
            if last_opp_action == 'cooperate' and last_my_action == 'cooperate':
                return True
        score = 0.3 * opp_rep + 0.3 * opp_coop + 0.4 * trust
        if opponent in self.opponent_history:
            recent_defections = sum(1 for act, _ in self.opponent_history[opponent][-5:] if act == 'defect')
            if recent_defections > 2:
                score -= self.defection_penalty * recent_defections
        if opponent in self.recent_actions:
            last_action = self.recent_actions[opponent][-1]
            if last_action == 'defect':
                score -= 0.15
        if opponent in self.defection_memory and self.defection_memory[opponent] > 0:
            score -= self.defection_sensitivity * self.defection_memory[opponent]
        if opponent in self.opponent_streaks and self.opponent_streaks[opponent] >= self.streak_threshold:
            score += self.streak_bonus * self.opponent_streaks[opponent]
        if opponent in self.opponent_defection_streaks and self.opponent_defection_streaks[opponent] >= self.defection_streak_threshold:
            score -= self.defection_streak_bonus * self.opponent_defection_streaks[opponent]
        if opponent in self.reputation_volatility and self.reputation_volatility[opponent] > self.volatility_threshold:
            score -= self.volatility_penalty * (self.reputation_volatility[opponent] - self.volatility_threshold)
        if opponent in self.recent_cooperation_rate:
            rate = self.recent_cooperation_rate[opponent]
            if rate > 0.7:
                score += self.rate_bonus * (rate - 0.7) * 10
        # New mechanism: pattern-based adjustment
        if opponent in self.pattern_memory:
            pattern = self.pattern_memory[opponent]
            if len(pattern) == self.pattern_length:
                if all(a == 'defect' for a in pattern):
                    score -= self.pattern_penalty
                elif all(a == 'cooperate' for a in pattern):
                    score += self.pattern_bonus
        # New mechanism: reputation trend adjustment
        if opponent in self.reputation_history and len(self.reputation_history[opponent]) >= 2:
            hist = self.reputation_history[opponent]
            recent = hist[-self.trend_window:]
            if len(recent) >= 2:
                slope = (recent[-1] - recent[0]) / (len(recent) - 1)
                if slope > 0.02:
                    score += self.trend_bonus
                elif slope < -0.02:
                    score -= self.trend_penalty
        # New mechanism: cooperation consistency (variance) adjustment
        if opponent in self.coop_variance:
            var = self.coop_variance[opponent]
            if var < 0.1:
                score += self.variance_bonus
            elif var > 0.3:
                score -= self.variance_penalty
        # New mechanism: decaying cooperation ratio adjustment
        if opponent in self.decay_coop_ratio:
            ratio = self.decay_coop_ratio[opponent]
            if ratio > 0.7:
                score += self.decay_bonus * (ratio - 0.7) * 2
        # New mechanism: betrayal count adjustment
        if opponent in self.betrayal_count and self.betrayal_count[opponent] >= self.betrayal_threshold:
            score -= self.betrayal_penalty * (self.betrayal_count[opponent] - self.betrayal_threshold + 1)
        # New mechanism: cooperation rate adjustment
        if opponent in self.coop_rate:
            rate = self.coop_rate[opponent]
            if rate > 0.7:
                score += self.coop_rate_bonus * (rate - 0.7) * 10
            elif rate < 0.3:
                score -= self.coop_rate_penalty * (0.3 - rate) * 10
        # New mechanism: reputation shift adjustment
        if opponent in self.reputation_shift:
            shift = self.reputation_shift[opponent]
            if shift > self.shift_threshold:
                score -= self.shift_penalty * (shift - self.shift_threshold)
            elif shift < -self.shift_threshold:
                score += self.shift_bonus * (-shift - self.shift_threshold)
        # New mechanism: conditional cooperation adjustment
        if opponent in self.conditional_coop:
            cond_rate = self.conditional_coop[opponent]
            if cond_rate > self.conditional_threshold:
                score += self.conditional_bonus
            elif cond_rate < (1 - self.conditional_threshold):
                score -= self.conditional_penalty
        # New mechanism: response to my cooperation adjustment
        if opponent in self.response_to_coop:
            response = self.response_to_coop[opponent]
            if response > 0.7:
                score += self.response_bonus
            elif response < 0.3:
                score -= self.response_penalty
        # New mechanism: temporal discounting adjustment
        if opponent in self.temporal_history:
            hist = self.temporal_history[opponent]
            if len(hist) >= 2:
                weighted_sum = 0.0
                weight = 1.0
                total_weight = 0.0
                for action in hist:
                    if action == 'cooperate':
                        weighted_sum += weight
                    weight *= self.temporal_discount
                    total_weight += weight
                if total_weight > 0:
                    recent_ratio = weighted_sum / total_weight
                    if recent_ratio > 0.7:
                        score += self.temporal_bonus
                    elif recent_ratio < 0.3:
                        score -= self.temporal_penalty
        # New mechanism: entropy-based stability adjustment
        if opponent in self.coop_entropy:
            entropy = self.coop_entropy[opponent]
            if entropy < 0.5:
                score += self.entropy_bonus
            elif entropy > 1.5:
                score -= self.entropy_penalty
        # Reciprocity bias based on my recent cooperation rate
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        # Adaptive threshold based on recent outcomes (unchanged)
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        # Modified: pattern-based threshold adjustment uses opponent-specific forgiveness
        if opponent in self.pattern_memory and len(self.pattern_memory[opponent]) == self.pattern_length:
            pattern = self.pattern_memory[opponent]
            opp_forgiveness = self.opponent_forgiveness.get(opponent, self.forgiveness_base)
            if all(a == 'defect' for a in pattern):
                self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.1 * (1 - opp_forgiveness))
            elif all(a == 'cooperate' for a in pattern):
                self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.1 * (1 + opp_forgiveness))
        # Modified: betrayal count also adjusts threshold
        if opponent in self.betrayal_count and self.betrayal_count[opponent] >= self.betrayal_threshold:
            self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + self.betrayal_penalty * 0.5)
        # New mechanism: temporal discounting also adjusts threshold
        if opponent in self.temporal_history:
            hist = self.temporal_history[opponent]
            if len(hist) >= 2:
                weighted_sum = 0.0
                weight = 1.0
                total_weight = 0.0
                for action in hist:
                    if action == 'cooperate':
                        weighted_sum += weight
                    weight *= self.temporal_discount
                    total_weight += weight
                if total_weight > 0:
                    recent_ratio = weighted_sum / total_weight
                    if recent_ratio > 0.7:
                        self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.05)
                    elif recent_ratio < 0.3:
                        self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.05)
