import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.gen = 0
        self.coop_count = 0
        self.defect_count = 0
        self.total_payoff = 0.0
        self.opponent_history = {}
        self.reputation = {}
        self.trust = {}
        self.last_decisions = []
        self.defection_penalty = 0.5
        self.cooperation_bonus = 0.2
        self.memory_limit = 10

    def decide(self) -> bool:
        self.round += 1
        opp = self._ctx_opponent_id
        if opp not in self.trust:
            self.trust[opp] = 0.5
        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.opponent_history:
            self.opponent_history[opp] = []

        # Simple heuristic: cooperate if trust is high or opponent has good reputation
        trust_factor = self.trust[opp]
        rep_factor = self.reputation[opp]

        # Recent behavior
        recent = self.opponent_history[opp][-3:] if len(self.opponent_history[opp]) >= 3 else self.opponent_history[opp]
        coop_recent = sum(1 for act in recent if act == 'cooperate') / max(1, len(recent))

        # Combined score
        score = 0.3 * trust_factor + 0.4 * rep_factor + 0.3 * coop_recent

        # Slight randomness to avoid being too predictable
        threshold = 0.5
        if random.random() < 0.05:
            return random.random() < 0.5
        return score >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both parties
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + self.cooperation_bonus
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - self.defection_penalty

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + self.cooperation_bonus
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - self.defection_penalty

        # Clamp reputation to [0,1]
        for pid in [donor_id, recipient_id]:
            self.reputation[pid] = max(0.0, min(1.0, self.reputation[pid]))

        # Update trust when we observe interactions
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) * 0.9 + 0.1
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) * 0.9 + 0.1
            elif donor_action == 'defect' or recipient_action == 'defect':
                if donor_action == 'defect':
                    self.trust[donor_id] = self.trust.get(donor_id, 0.5) * 0.9 - 0.05
                if recipient_action == 'defect':
                    self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) * 0.9 - 0.05

