        if opponent in self.pattern_memory:
            pattern = self.pattern_memory[opponent]
            if len(pattern) == self.pattern_length:
                if all(a == 'defect' for a in pattern):
                    score -= self.pattern_penalty
                elif all(a == 'cooperate' for a in pattern):
                    score += self.pattern_bonus
        # New mechanism: reputation trend adjustment
        if opponent in self.reputation_history and len(self.reputation_history[opponent]) >= 2:
            hist = self.reputation_history[opponent]
            recent = hist[-self.trend_window:]
            if len(recent) >= 2:
                slope = (recent[-1] - recent[0]) / (len(recent) - 1)
                if slope > 0.02:
                    score += self.trend_bonus
                elif slope < -0.02:
                    score -= self.trend_penalty
        # New mechanism: cooperation consistency (variance) adjustment
        if opponent in self.coop_variance:
            var = self.coop_variance[opponent]
            if var < 0.1:
                score += self.variance_bonus
            elif var > 0.3:
                score -= self.variance_penalty
        # New mechanism: decaying cooperation ratio adjustment
        if opponent in self.decay_coop_ratio:
            ratio = self.decay_coop_ratio[opponent]
            if ratio > 0.7:
                score += self.decay_bonus * (ratio - 0.7) * 2
        # New mechanism: betrayal count adjustment
        if opponent in self.betrayal_count and self.betrayal_count[opponent] >= self.betrayal_threshold:
