            self.observation_count[agent_id] = 0
            self.history[agent_id] = []
            self.recent_coop_streak[agent_id] = 0
        action_val = 1.0 if action == "cooperate" else 0.0
        self.reputations[agent_id] = (1 - self.alpha) * self.reputations[agent_id] + self.alpha * action_val
        self.history[agent_id].append(action_val)
        if len(self.history[agent_id]) > 50:
            self.history[agent_id].pop(0)
        self.observation_count[agent_id] += 1

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True
        if opponent not in self.reputations:
            rng = random.Random(self.agent_id * 1000 + opponent)
            return rng.random() < self.base_coop_prob
        rep = self.reputations[opponent]
        own_hist = self.own_interactions.get(opponent, [])
        if own_hist:
            my_actions = [a for a, _ in own_hist]
            their_actions = [b for _, b in own_hist]
            coop_rate_them = sum(1 for b in their_actions if b) / len(their_actions)
            weight_direct = min(0.8, len(own_hist) * 0.1)
            effective_coop = (1 - weight_direct) * rep + weight_direct * coop_rate_them
        else:
