        # Adaptive threshold: if we've been exploited recently, become more cautious
        # Track our own payoff: if we cooperated and they defected, lower threshold
        recent_exploits = 0
        for opponent_id, interactions in self.own_interactions.items():
            for my_action, their_action in interactions[-5:]:
                if my_action and not their_action:
