                elif my_action and their_action:
                    recent_exploits -= 0.5
        # Adjust threshold: more exploits -> higher threshold (less trusting)
        self.adaptive_threshold = 0.5 + 0.1 * recent_exploits
        self.adaptive_threshold = max(0.1, min(0.9, self.adaptive_threshold))
