                # Heavily weight negative reputation
                if rep_score < 0.3:
                    base_prob -= 0.3
                elif rep_score < 0.5:
                    base_prob -= 0.15
                elif rep_score > 0.7:
                    base_prob += 0.2
                else:
                    base_prob += 0.05

