import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round_num = 0
        self.generation = 0
        self._ctx_opponent_id = None

        # Reputation tracking: opponent_id -> (cooperate_count, defect_count, observations)
        self.reputation = {}

        # Personal interaction history: opponent_id -> deque of (my_action, their_action)
        self.interaction_history = {}

        # Cooperation probability per opponent based on reputation and history
        self.coop_prob = {}

        # Track own recent actions for adaptive behavior
        self.my_recent_actions = deque(maxlen=10)

        # Track overall trust level and cooperation propensity
        self.trust_level = 0.5
        self.cooperation_propensity = 0.5

        # Track recent opponent actions per opponent for pattern detection
        self.opponent_recent = {}

        # New: Stubbornness factor - how much we stick to our past decisions
        self.stubbornness = 0.7

        # New: Forgiveness factor - how quickly we forgive past defections
        self.forgiveness = 0.6

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Base probability from trust and propensity
        base_prob = 0.5 * self.trust_level + 0.3 * self.cooperation_propensity

        # Adjust based on opponent reputation if known
        if opponent in self.reputation:
            coop, defect, obs = self.reputation[opponent]
            total = coop + defect
            if total > 0:
                rep_score = coop / total
                # Heavily weight negative reputation
                if rep_score < 0.3:
                    base_prob -= 0.3
                elif rep_score < 0.5:
                    base_prob -= 0.15
                elif rep_score > 0.7:
                    base_prob += 0.2
                else:
                    base_prob += 0.05

        # Adjust based on personal interaction history
        if opponent in self.interaction_history:
            history = self.interaction_history[opponent]
            if len(history) >= 3:
                recent = list(history)[-3:]
                their_coop = sum(1 for _, their in recent if their == 'cooperate')
                my_coop = sum(1 for my, _ in recent if my == 'cooperate')
                if their_coop == 0 and len(recent) >= 2:
                    base_prob -= 0.4  # They've defected twice recently
                elif their_coop >= 2:
                    base_prob += 0.15
                if my_coop == 0 and len(recent) >= 2:
                    base_prob -= 0.1  # We've been defecting, maybe switch strategy

        # New: Stubbornness - if we've been cooperating a lot with this opponent, stick with it
        if opponent in self.interaction_history and len(self.interaction_history[opponent]) >= 2:
            history = list(self.interaction_history[opponent])[-2:]
            my_actions = [my for my, _ in history]
            if all(my_actions):  # both were cooperate
                base_prob += self.stubbornness * 0.1
            elif not any(my_actions):  # both were defect
                base_prob -= self.stubbornness * 0.1

        # New: Pattern recognition - if opponent alternates, be more cautious
        if opponent in self.opponent_recent and len(self.opponent_recent[opponent]) >= 4:
            recent_actions = list(self.opponent_recent[opponent])[-4:]
            # Check for alternating pattern (C,D,C,D or D,C,D,C)
            alternating = all(recent_actions[i] != recent_actions[i+1] for i in range(3))
            if alternating:
                base_prob -= 0.2

        # New: Forgiveness - if opponent defected long ago but has since cooperated, forgive
        if opponent in self.interaction_history:
            history = list(self.interaction_history[opponent])
            if len(history) >= 5:
                # Look at last 5 interactions, check for recent cooperation after earlier defection
                recent_5 = history[-5:]
                if any(their == 'defect' for _, their in history[:-5]) and sum(1 for _, their in recent_5 if their == 'cooperate') >= 3:
                    base_prob += self.forgiveness * 0.15

        # Add random noise for exploration
        prob = max(0.05, min(0.95, base_prob + random.uniform(-0.05, 0.05)))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track round and generation info (approximate)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
