class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation rates per opponent
        self.coop_counts = {}
        self.total_counts = {}
        # Track recent defections (opponent_id -> round number)
        self.defection_history = {}
        # Track own actions per opponent
        self.my_actions = {}
        # Generation counter to implement forgiveness cycles
        self.generation = 0
        self.round_in_generation = 0
        # Current opponent
        self._ctx_opponent_id = None
        # Probability to forgive after a defection (starts moderate)
        self.forgiveness_prob = 0.15
        # Track overall cooperation tendency
        self.my_coop_total = 0
        self.my_actions_total = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # Default: cooperate
        decision = True
        try:
            # Update round counter
            self.round_in_generation += 1
            if self.round_in_generation > 30:
                self.round_in_generation = 1
                self.generation += 1
                # Occasionally increase forgiveness over generations
                if self.generation % 5 == 0:
                    self.forgiveness_prob = min(0.4, self.forgiveness_prob + 0.05)

            # Retrieve history
            opp_coop = self.coop_counts.get(opponent, 0)
            opp_total = self.total_counts.get(opponent, 0)
            opp_defect = opp_total - opp_coop

            my_coop = self.my_actions.get(opponent, [True, True])  # default: cooperate
            # my_actions stores [coops, total] for this opponent
            my_coop_count = my_coop[0]
            my_total_count = my_coop[1]

            # If no history, cooperate
            if opp_total == 0:
                decision = True
            else:
                # Calculate opponent cooperation rate
                coop_rate = opp_coop / opp_total
                # Check recent defection (within last 2 rounds)
                recent_defect = False
                if opponent in self.defection_history:
                    if self.round_in_generation - self.defection_history[opponent] <= 2:
                        recent_defect = True

                # Strategy: Tit-for-tat with forgiveness and occasional probing
                if recent_defect:
                    # If they recently defected, sometimes forgive, else defect
                    if random.random() < self.forgiveness_prob:
                        decision = True
                    else:
                        decision = False
                else:
                    # If they've been cooperative, cooperate
                    if coop_rate >= 0.5:
                        decision = True
                    else:
                        # If they are generally uncooperative, defect unless we've never defected against them
                        if my_total_count == 0:
                            decision = True  # initial trust
                        else:
                            # If we've been cooperating and they haven't, defect
                            decision = False

                # Occasionally probe with defection to test if opponent is forgiving
                # Only when we have a long cooperative relationship and we haven't defected recently
                if opp_total >= 10 and coop_rate > 0.8 and my_total_count >= 5:
                    if random.random() < 0.05:  # 5% chance to probe
                        decision = False

        except Exception:
            decision = True
        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update self observations
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                # Determine opponent and their action
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action
                    opp_action = recipient_action
                else:
                    opponent = donor_id
                    my_action = recipient_action
                    opp_action = donor_action

                # Update my actions
                if opponent not in self.my_actions:
                    self.my_actions[opponent] = [0, 0]
                if my_action == 'cooperate':
                    self.my_actions[opponent][0] += 1
                self.my_actions[opponent][1] += 1
                self.my_coop_total += 1 if my_action == 'cooperate' else 0
                self.my_actions_total += 1

                # Update opponent's action counts
                if opponent not in self.coop_counts:
                    self.coop_counts[opponent] = 0
                    self.total_counts[opponent] = 0
                if opp_action == 'cooperate':
                    self.coop_counts[opponent] += 1
                self.total_counts[opponent] += 1

                # Track defection history
                if opp_action == 'defect':
                    self.defection_history[opponent] = self.round_in_generation
            else:
                # Third-party observation: update opponent reputation
                # Only observe if we have interacted with either party before
                if donor_id in self.total_counts or recipient_id in self.total_counts:
                    # Update reputation for both parties based on their actions
                    for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                        if pid in self.total_counts:  # only track if we know them
                            if pid not in self.coop_counts:
