import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round_num = 0
        self.generation = 0
        self._ctx_opponent_id = None

        # Reputation tracking: opponent_id -> (cooperate_count, defect_count, observations)
        self.reputation = {}

        # Personal interaction history: opponent_id -> deque of (my_action, their_action)
        self.interaction_history = {}

        # Cooperation probability per opponent based on reputation and history
        self.coop_prob = {}

        # Track own recent actions for adaptive behavior
        self.my_recent_actions = deque(maxlen=10)

        # Track overall trust level and cooperation propensity
        self.trust_level = 0.5
        self.cooperation_propensity = 0.5

        # Track recent opponent actions per opponent for pattern detection
        self.opponent_recent = {}

        # New: Stubbornness factor - how much we stick to our past decisions
        self.stubbornness = 0.7

        # New: Forgiveness factor - how quickly we forgive past defections
        self.forgiveness = 0.6

        # New: Risk aversion - how much we avoid potential losses from defection
        self.risk_aversion = 0.5

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Base probability from trust and propensity
        base_prob = 0.5 * self.trust_level + 0.3 * self.cooperation_propensity

        # Adjust based on opponent reputation if known
        if opponent in self.reputation:
            coop, defect, obs = self.reputation[opponent]
            total = coop + defect
            if total > 0:
                rep_score = coop / total
                # Heavily weight negative reputation
                if rep_score < 0.3:
                    base_prob -= 0.3
                elif rep_score < 0.5:
                    base_prob -= 0.15
                elif rep_score > 0.7:
                    base_prob += 0.2
                else:
                    base_prob += 0.05

        # Adjust based on personal interaction history
        if opponent in self.interaction_history:
            history = self.interaction_history[opponent]
            if len(history) >= 3:
                recent = list(history)[-3:]
                their_coop = sum(1 for _, their in recent if their == 'cooperate')
                my_coop = sum(1 for my, _ in recent if my == 'cooperate')
                if their_coop == 0 and len(recent) >= 2:
                    base_prob -= 0.4  # They've defected twice recently
                elif their_coop >= 2:
                    base_prob += 0.15
                if my_coop == 0 and len(recent) >= 2:
                    base_prob -= 0.1  # We've been defecting, maybe switch strategy

        # New: Stubbornness - if we've been cooperating a lot with this opponent, stick with it
        if opponent in self.interaction_history and len(self.interaction_history[opponent]) >= 2:
            history = list(self.interaction_history[opponent])[-2:]
            my_actions = [my for my, _ in history]
            if all(my_actions):  # both were cooperate
                base_prob += self.stubbornness * 0.1
            elif not any(my_actions):  # both were defect
                base_prob -= self.stubbornness * 0.1

        # New: Pattern recognition - if opponent alternates, be more cautious
        if opponent in self.opponent_recent and len(self.opponent_recent[opponent]) >= 4:
            recent_actions = list(self.opponent_recent[opponent])[-4:]
            # Check for alternating pattern (C,D,C,D or D,C,D,C)
            alternating = all(recent_actions[i] != recent_actions[i+1] for i in range(3))
            if alternating:
                base_prob -= 0.2

        # New: Forgiveness - if opponent defected long ago but has since cooperated, forgive
        if opponent in self.interaction_history:
            history = list(self.interaction_history[opponent])
            if len(history) >= 5:
                # Look at last 5 interactions, check for recent cooperation after earlier defection
                recent_5 = history[-5:]
                if any(their == 'defect' for _, their in history[:-5]) and sum(1 for _, their in recent_5 if their == 'cooperate') >= 3:
                    base_prob += self.forgiveness * 0.15

        # New: Risk aversion - if we have low trust and opponent has defected before, be more cautious
        if opponent in self.reputation:
            coop, defect, obs = self.reputation[opponent]
            total = coop + defect
            if total > 0:
                rep_score = coop / total
                if rep_score < 0.5 and self.trust_level < 0.5:
                    base_prob -= self.risk_aversion * 0.2

        # Add random noise for exploration
        prob = max(0.05, min(0.95, base_prob + random.uniform(-0.05, 0.05)))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track round and generation info (approximate)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1
            if self.round_num % 30 == 0:
                self.generation += 1
                self.round_num = 0
                # Decay old reputation slightly each generation
                for opp in list(self.reputation.keys()):
                    coop, defect, obs = self.reputation[opp]
                    self.reputation[opp] = (coop * 0.9, defect * 0.9, obs * 0.9)
                # Update propensity based on recent actions
                if len(self.my_recent_actions) > 0:
                    coop_rate = sum(1 for a in self.my_recent_actions if a) / len(self.my_recent_actions)
                    self.cooperation_propensity = 0.8 * self.cooperation_propensity + 0.2 * coop_rate
                # Decay stubbornness slightly each generation
                self.stubbornness = max(0.4, self.stubbornness * 0.95)
                # New: Increase forgiveness slightly each generation (becoming more forgiving over time)
                self.forgiveness = min(0.9, self.forgiveness * 1.05)
                # New: Decrease risk aversion gradually
                self.risk_aversion = max(0.2, self.risk_aversion * 0.97)
                self.my_recent_actions.clear()

        # Update reputation for all observed interactions
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation
            if donor_id not in self.reputation:
                self.reputation[donor_id] = [0, 0, 0]
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = [0, 0, 0]

            if donor_action == 'cooperate':
                self.reputation[donor_id][0] += 1
            else:
                self.reputation[donor_id][1] += 1
            self.reputation[donor_id][2] += 1

            if recipient_action == 'cooperate':
                self.reputation[recipient_id][0] += 1
            else:
                self.reputation[recipient_id][1] += 1
            self.reputation[recipient_id][2] += 1

            # Update trust based on observed cooperation
            total_coop = self.reputation[donor_id][0] + self.reputation[recipient_id][0]
            total_obs = self.reputation[donor_id][2] + self.reputation[recipient_id][2]
            if total_obs > 0:
                self.trust_level = 0.9 * self.trust_level + 0.1 * (total_coop / total_obs)

        # Update personal interaction history if we're involved
        if donor_id == self.agent_id:
            # We are donor
            if recipient_id not in self.interaction_history:
                self.interaction_history[recipient_id] = deque(maxlen=10)
            self.interaction_history[recipient_id].append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.my_recent_actions.append(donor_action == 'cooperate')
        elif recipient_id == self.agent_id:
            # We are recipient
            if donor_id not in self.interaction_history:
                self.interaction_history[donor_id] = deque(maxlen=10)
            self.interaction_history[donor_id].append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.my_recent_actions.append(recipient_action == 'cooperate')

        # Track opponent actions for pattern detection
        if donor_id != self.agent_id:
            if donor_id not in self.opponent_recent:
                self.opponent_recent[donor_id] = deque(maxlen=6)
            self.opponent_recent[donor_id].append(donor_action == 'cooperate')
        if recipient_id != self.agent_id:
            if recipient_id not in self.opponent_recent:
                self.opponent_recent[recipient_id] = deque(maxlen=6)
            self.opponent_recent[recipient_id].append(recipient_action == 'cooperate')

        # Update trust level with direct interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            their_action = recipient_action if donor_id == self.agent_id else donor_action
            if my_action == 'cooperate' and their_action == 'cooperate':
                self.trust_level = min(1.0, self.trust_level + 0.1)
            elif my_action == 'defect' and their_action == 'defect':
                self.trust_level = max(0.0, self.trust_level - 0.05)
            elif their_action == 'defect':
                self.trust_level = max(0.0, self.trust_level - 0.15)

            # Update stubbornness based on outcomes
            if my_action == their_action:
                # We matched their action, reinforcement
                self.stubbornness = min(0.9, self.stubbornness + 0.05)
            else:
                # Mismatch, become less stubborn
                self.stubbornness = max(0.4, self.stubbornness - 0.05)

            # New: Update risk aversion based on outcomes
            if my_action == 'cooperate' and their_action == 'defect':
                # We got exploited, increase risk aversion
                self.risk_aversion = min(0.9, self.risk_aversion + 0.05)
            elif my_action == 'defect' and their_action == 'cooperate':
                # We exploited them, decrease risk aversion slightly
                self.risk_aversion = max(0.2, self.risk_aversion - 0.02)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation rates per opponent
        self.coop_counts = {}
        self.total_counts = {}
        # Track recent defections (opponent_id -> round number)
        self.defection_history = {}
        # Track own actions per opponent
        self.my_actions = {}
        # Generation counter to implement forgiveness cycles
        self.generation = 0
        self.round_in_generation = 0
        # Current opponent
        self._ctx_opponent_id = None
        # Probability to forgive after a defection (starts moderate)
        self.forgiveness_prob = 0.15
        # Track overall cooperation tendency
        self.my_coop_total = 0
        self.my_actions_total = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # Default: cooperate
        decision = True
        try:
            # Update round counter
            self.round_in_generation += 1
            if self.round_in_generation > 30:
                self.round_in_generation = 1
                self.generation += 1
                # Occasionally increase forgiveness over generations
                if self.generation % 5 == 0:
                    self.forgiveness_prob = min(0.4, self.forgiveness_prob + 0.05)

            # Retrieve history
            opp_coop = self.coop_counts.get(opponent, 0)
            opp_total = self.total_counts.get(opponent, 0)
            opp_defect = opp_total - opp_coop

            my_coop = self.my_actions.get(opponent, [True, True])  # default: cooperate
            # my_actions stores [coops, total] for this opponent
            my_coop_count = my_coop[0]
            my_total_count = my_coop[1]

            # If no history, cooperate
            if opp_total == 0:
                decision = True
            else:
                # Calculate opponent cooperation rate
                coop_rate = opp_coop / opp_total
                # Check recent defection (within last 2 rounds)
                recent_defect = False
                if opponent in self.defection_history:
                    if self.round_in_generation - self.defection_history[opponent] <= 2:
                        recent_defect = True

                # Strategy: Tit-for-tat with forgiveness and occasional probing
                if recent_defect:
                    # If they recently defected, sometimes forgive, else defect
                    if random.random() < self.forgiveness_prob:
                        decision = True
                    else:
                        decision = False
                else:
                    # If they've been cooperative, cooperate
                    if coop_rate >= 0.5:
                        decision = True
                    else:
                        # If they are generally uncooperative, defect unless we've never defected against them
                        if my_total_count == 0:
                            decision = True  # initial trust
                        else:
                            # If we've been cooperating and they haven't, defect
                            decision = False

                # Occasionally probe with defection to test if opponent is forgiving
                # Only when we have a long cooperative relationship and we haven't defected recently
                if opp_total >= 10 and coop_rate > 0.8 and my_total_count >= 5:
                    if random.random() < 0.05:  # 5% chance to probe
                        decision = False

        except Exception:
            decision = True
        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update self observations
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                # Determine opponent and their action
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action
                    opp_action = recipient_action
                else:
                    opponent = donor_id
                    my_action = recipient_action
                    opp_action = donor_action

                # Update my actions
                if opponent not in self.my_actions:
                    self.my_actions[opponent] = [0, 0]
                if my_action == 'cooperate':
                    self.my_actions[opponent][0] += 1
                self.my_actions[opponent][1] += 1
                self.my_coop_total += 1 if my_action == 'cooperate' else 0
                self.my_actions_total += 1

                # Update opponent's action counts
                if opponent not in self.coop_counts:
                    self.coop_counts[opponent] = 0
                    self.total_counts[opponent] = 0
                if opp_action == 'cooperate':
                    self.coop_counts[opponent] += 1
                self.total_counts[opponent] += 1

                # Track defection history
                if opp_action == 'defect':
                    self.defection_history[opponent] = self.round_in_generation
            else:
                # Third-party observation: update opponent reputation
                # Only observe if we have interacted with either party before
                if donor_id in self.total_counts or recipient_id in self.total_counts:
                    # Update reputation for both parties based on their actions
                    for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                        if pid in self.total_counts:  # only track if we know them
                            if pid not in self.coop_counts:
                                self.coop_counts[pid] = 0
                            if action == 'cooperate':
                                self.coop_counts[pid] += 1
                            self.total_counts[pid] += 1
        except Exception:
            pass

