            if all(a == 'defect' for a in pattern):
                self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.1 * (1 - opp_forgiveness))
            elif all(a == 'cooperate' for a in pattern):
                self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.1 * (1 + opp_forgiveness))
        # Modified: betrayal count also adjusts threshold
        if opponent in self.betrayal_count and self.betrayal_count[opponent] >= self.betrayal_threshold:
            self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + self.betrayal_penalty * 0.5)
        # New mechanism: temporal discounting also adjusts threshold
        if opponent in self.temporal_history:
            hist = self.temporal_history[opponent]
            if len(hist) >= 2:
                weighted_sum = 0.0
                weight = 1.0
                total_weight = 0.0
                for action in hist:
                    if action == 'cooperate':
                        weighted_sum += weight
                    weight *= self.temporal_discount
                    total_weight += weight
                if total_weight > 0:
                    recent_ratio = weighted_sum / total_weight
                    if recent_ratio > 0.7:
                        self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.05)
                    elif recent_ratio < 0.3:
                        self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.05)
        # New mechanism: generosity also adjusts threshold
        if opponent in self.generosity:
            gen = self.generosity[opponent]
            if gen > 0.7:
                self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.05)
            elif gen < 0.3:
                self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.05)
        threshold = self.base_cooperation_threshold - self.risk_taking * 0.1
        if score >= threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation with volatility tracking (unchanged)
        if donor_id != self.agent_id:
            old_rep = self.reputation.get(donor_id, 0.5)
            if donor_action == 'cooperate':
                new_rep = old_rep * 0.85 + 0.15
            else:
                new_rep = old_rep * 0.85
            self.reputation[donor_id] = new_rep
            if donor_id not in self.reputation_volatility:
                self.reputation_volatility[donor_id] = 0.0
            self.reputation_volatility[donor_id] = self.volatility_decay * self.reputation_volatility[donor_id] + abs(new_rep - old_rep)
            if donor_id not in self.reputation_history:
                self.reputation_history[donor_id] = []
            self.reputation_history[donor_id].append(new_rep)
            if len(self.reputation_history[donor_id]) > self.trend_window:
                self.reputation_history[donor_id].pop(0)
        if recipient_id != self.agent_id:
            old_rep = self.reputation.get(recipient_id, 0.5)
            if recipient_action == 'cooperate':
                new_rep = old_rep * 0.85 + 0.15
            else:
                new_rep = old_rep * 0.85
            self.reputation[recipient_id] = new_rep
            if recipient_id not in self.reputation_volatility:
                self.reputation_volatility[recipient_id] = 0.0
            self.reputation_volatility[recipient_id] = self

