import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation rates per opponent
        self.coop_counts = {}
        self.total_counts = {}
        # Track recent defections (opponent_id -> round number)
        self.defection_history = {}
        # Track own actions per opponent
        self.my_actions = {}
        # Generation counter to implement forgiveness cycles
        self.generation = 0
        self.round_in_generation = 0
        # Current opponent
        self._ctx_opponent_id = None
        # Probability to forgive after a defection (starts moderate)
        self.forgiveness_prob = 0.15
        # Track overall cooperation tendency
        self.my_coop_total = 0
        self.my_actions_total = 0
        # NEW: Track reputation scores for third-party observations
        self.reputation = {}
        # NEW: Use a deque to store recent opponent actions for sliding window
        self.recent_opp_actions = {}  # opponent_id -> deque of actions
        # NEW: Track the last time we observed a defection from this opponent (for decay)
        self.last_defection_round = {}
        # NEW: Track our own recent actions for self-reflection
        self.recent_own_actions = deque(maxlen=10)
        # NEW: Track a short-term memory of others' reputations to adapt forgiveness
        self.reputation_adaptation = {}
        # NEW: Track cumulative opponent cooperation deficit for a more nuanced response
        self.coop_deficit = {}
        # NEW: Track a personal baseline of cooperation to compare against
        self.my_baseline_coop = 0.5

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # Default: cooperate
        decision = True
        try:
            # Update round counter
            self.round_in_generation += 1
            if self.round_in_generation > 30:
                self.round_in_generation = 1
                self.generation += 1
                # Occasionally increase forgiveness over generations
                if self.generation % 5 == 0:
                    self.forgiveness_prob = min(0.4, self.forgiveness_prob + 0.05)

            # Retrieve history
            opp_coop = self.coop_counts.get(opponent, 0)
            opp_total = self.total_counts.get(opponent, 0)
            opp_defect = opp_total - opp_coop

            my_coop = self.my_actions.get(opponent, [True, True])  # default: cooperate
            # my_actions stores [coops, total] for this opponent
            my_coop_count = my_coop[0]
            my_total_count = my_coop[1]

            # If no history, cooperate
            if opp_total == 0:
                decision = True
            else:
                # Calculate opponent cooperation rate using sliding window if available
                if opponent in self.recent_opp_actions and len(self.recent_opp_actions[opponent]) > 0:
                    window_actions = self.recent_opp_actions[opponent]
                    coop_rate = sum(1 for a in window_actions if a == 'cooperate') / len(window_actions)
                else:
                    coop_rate = opp_coop / opp_total
                # Check recent defection (within last 2 rounds)
                recent_defect = False
                if opponent in self.defection_history:
                    if self.round_in_generation - self.defection_history[opponent] <= 2:
                        recent_defect = True

                # NEW: Calculate cumulative cooperation deficit (total times they defected minus total times they cooperated)
                deficit = self.coop_deficit.get(opponent, 0)

                # Strategy: Tit-for-tat with forgiveness and occasional probing
                if recent_defect:
                    # If they recently defected, sometimes forgive, else defect
                    # NEW: Adjust forgiveness based on our recent own behavior (reciprocity)
                    self_forgiveness = self.forgiveness_prob
                    if len(self.recent_own_actions) > 0:
                        own_coop_rate = sum(1 for a in self.recent_own_actions if a == 'cooperate') / len(self.recent_own_actions)
                        if own_coop_rate > 0.7:
                            self_forgiveness += 0.05  # be more forgiving if we've been cooperative
                        elif own_coop_rate < 0.3:
                            self_forgiveness -= 0.05  # be more strict if we've been defecting
                    # NEW: If deficit is large, be less forgiving
                    if deficit > 3:
                        self_forgiveness *= 0.5
                    if random.random() < self_forgiveness:
                        decision = True
                    else:
                        decision = False
                else:
                    # If they've been cooperative, cooperate
                    if coop_rate >= 0.5:
                        decision = True
                    else:
                        # If they are generally uncooperative, defect unless we've never defected against them
                        if my_total_count == 0:
                            decision = True  # initial trust
                        else:
                            # If we've been cooperating and they haven't, defect
                            decision = False

                # Occasionally probe with defection to test if opponent is forgiving
                # Only when we have a long cooperative relationship and we haven't defected recently
                if opp_total >= 10 and coop_rate > 0.8 and my_total_count >= 5:
                    if random.random() < 0.05:  # 5% chance to probe
                        decision = False

            # NEW: Incorporate reputation into decision
            # If we have a reputation for this opponent and it's low, be more likely to defect
            if opponent in self.reputation:
                rep = self.reputation[opponent]
                if rep < -0.2 and decision:
                    # Slight chance to defect if reputation is bad
                    if random.random() < 0.15:
                        decision = False
                elif rep > 0.2 and not decision:
                    # Slight chance to cooperate if reputation is good
                    if random.random() < 0.1:
                        decision = True
            # NEW: Adjust decision based on cumulative deficit with a threshold
            if deficit >= 5 and decision:
                # If the deficit is high, we are more likely to defect even if they recently cooperated
                if random.random() < 0.3:
                    decision = False
            # NEW: Compare to personal baseline; if we are cooperating more than usual, be more cautious
            if self.my_actions_total > 0:
                my_rate = self.my_coop_total / self.my_actions_total
                if my_rate > self.my_baseline_coop + 0.2 and decision:
                    # We are being too cooperative; be more cautious
                    if random.random() < 0.1:
                        decision = False
        except Exception:
            decision = True
        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update self observations
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                # Determine opponent and their action
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action
                    opp_action = recipient_action
                else:
                    opponent = donor_id
                    my_action = recipient_action
                    opp_action = donor_action

                # Update my actions
                if opponent not in self.my_actions:
                    self.my_actions[opponent] = [0, 0]
                if my_action == 'cooperate':
                    self.my_actions[opponent][0] += 1
                self.my_actions[opponent][1] += 1
                self.my_coop_total += 1 if my_action == 'cooperate' else 0
                self.my_actions_total += 1
                # NEW: Track recent own actions for self-reflection
                self.recent_own_actions.append(my_action)

                # Update opponent's action counts
                if opponent not in self.coop_counts:
                    self.coop_counts[opponent] = 0
                    self.total_counts[opponent] = 0
                    self.coop_deficit[opponent] = 0
                if opp_action == 'cooperate':
                    self.coop_counts[opponent] += 1
                    # NEW: Decrease deficit when they cooperate
                    self.coop_deficit[opponent] = max(0, self.coop_deficit[opponent] - 1)
                else:
                    # NEW: Increase deficit when they defect
                    self.coop_deficit[opponent] += 1
                self.total_counts[opponent] += 1

                # Track defection history
                if opp_action == 'defect':
                    self.defection_history[opponent] = self.round_in_generation
                    # NEW: Update last_defection_round for decay
                    if opponent not in self.last_defection_round:
                        self.last_defection_round[opponent] = 0
                    self.last_defection_round[opponent] = self.round_in_generation
                else:
                    # NEW: Decay reputation if they cooperate after a defection
                    if opponent in self.last_defection_round:
                        rounds_since_defect = self.round_in_generation - self.last_defection_round[opponent]
                        if rounds_since_defect > 5:
                            # If they've been cooperative for a while, boost their reputation slightly
                            if opponent not in self.reputation:
                                self.reputation[opponent] = 0
                            self.reputation[opponent] += 0.05
                            self.reputation[opponent] = max(-1.0, min(1.0, self.reputation[opponent]))

                # NEW: Update sliding window for opponent actions
                if opponent not in self.recent_opp_actions:
