import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputations = {}
        self.interactions = {}
        self.my_actions = deque(maxlen=10)
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.alpha = 0.5
        self.beta = 0.3
        self.gamma = 0.2
        self.forgiveness = 0.05
        self.my_ko = 0.0
        self.partner_ko = {}
        self.trust_memory = {}
        self.observation_count = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.reputations.get(opponent, 0.5)
        exp = 0.5
        if opponent in self.interactions:
            exp = self.interactions[opponent]

        # Add a trust factor from recent observations of this opponent
        trust = self.trust_memory.get(opponent, 0.5)
        combined = self.alpha * rep + self.beta * exp + self.gamma * trust

        # Explore with small probability
        if random.random() < 0.02:
            return random.random() < 0.5

        threshold = 0.55 - self.forgiveness * self.cooperation_count / max(1, self.cooperation_count + self.defection_count)
        return combined >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        self.observation_count += 1

        # Update trust memory based on observed actions (weighted by recency)
        self._update_trust(donor_id, donor_action)
        self._update_trust(recipient_id, recipient_action)

        # Update reputations
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            if donor_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            self.my_ko = self._calculate_ko(donor_id, donor_action, recipient_id, recipient_action)
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_action)
            if recipient_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            self.my_ko = self._calculate_ko(recipient_id, recipient_action, donor_id, donor_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            partner_id = recipient_id if donor_id == self.agent_id else donor_id
            partner_action = recipient_action if donor_id == self.agent_id else donor_action
            self.partner_ko[partner_id] = self._calculate_ko(partner_id, partner_action, self.agent_id, donor_action if donor_id == self.agent_id else recipient_action)

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observations: decay trust slightly to avoid over-reliance
            for aid in [donor_id, recipient_id]:
                if aid in self.trust_memory:
                    self.trust_memory[aid] *= 0.99

    def _update_trust(self, agent_id: int, action: str) -> None:
        current = self.trust_memory.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = current + 0.05
        else:
            new_val = current - 0.08
        self.trust_memory[agent_id] = max(0.0, min(1.0, new_val))

    def _calculate_ko(self, agent_id, action, other_id, other_action):
        if action == 'cooperate':
            ko = 1.0
        else:
            ko = -1.0
        if other_action == 'cooperate' and action == 'defect':
            ko -= 0.5
        elif other_action == 'defect' and action == 'cooperate':
            ko += 0.5
        return ko

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.reputations.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = current + 0.1
        else:
            new_val = current - 0.15
        self.reputations[agent_id] = max(0.0, min(1.0, new_val))

        if agent_id in [self._ctx_opponent_id, self.agent_id]:
            pass

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputations = {}
        self.interactions = {}
        self.my_actions = deque(maxlen=50)
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.alpha = 0.5
        self.beta = 0.5
        self.gamma = 0.3
        self.forgiveness = 0.05
        self.my_ko = 0.0
        self.partner_ko = {}
        self.last_actions = {}
        self.mood = 0.5
        self.mood_decay = 0.1

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.reputations.get(opponent, 0.5)
        exp = 0.5
        if opponent in self.interactions:
            exp = self.interactions[opponent]

        combined = self.alpha * rep + (1 - self.alpha) * exp

        # Incorporate mood: if mood is positive, more likely to cooperate
        combined = combined * (1 - self.mood_decay) + self.mood * self.mood_decay

        # Exploration
        if random.random() < 0.02:
            return random.random() < 0.5

        threshold = 0.55 - self.forgiveness * self.cooperation_count / max(1, self.cooperation_count + self.defection_count)

        # Add a "sucker" penalty: if opponent defected last time and I cooperated, lower threshold
        if opponent in self.last_actions:
            if self.last_actions[opponent] == 'defect' and self.my_actions and self.my_actions[-1] == 'cooperate':
                threshold += 0.1

        return combined >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round += 1

        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Track last actions of others
        if donor_id != self.agent_id:
            self.last_actions[donor_id] = donor_action
        if recipient_id != self.agent_id:
            self.last_actions[recipient_id] = recipient_action

        # If I'm involved, update personal memory and mood
        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            if donor_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            self.my_ko = self._calculate_ko(donor_id, donor_action, recipient_id, recipient_action)
            # Mood update: cooperating makes me happier, defecting makes me sadder
            if donor_action == 'cooperate':
                self.mood = min(1.0, self.mood + 0.1)
            else:
                self.mood = max(0.0, self.mood - 0.1)
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_action)
            if recipient_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            self.my_ko = self._calculate_ko(recipient_id, recipient_action, donor_id, donor_action)
            if recipient_action == 'cooperate':
                self.mood = min(1.0, self.mood + 0.1)
            else:
                self.mood = max(0.0, self.mood - 0.1)

        # Update partner Ko if I'm involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            partner_id = recipient_id if donor_id == self.agent_id else donor_id
            partner_action = recipient_action if donor_id == self.agent_id else donor_action
            self.partner_ko[partner_id] = self._calculate_ko(partner_id, partner_action, self.agent_id, donor_action if donor_id == self.agent_id else recipient_action)

        # Mood decays over time
        self.mood *= (1 - self.mood_decay)

        # Update interaction memory for third-party observations with a learning rate
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Learn from observing others: update reputation with a smaller step
            pass

    def _calculate_ko(self, agent_id, action, other_id, other_action):
        if action == 'cooperate':
            ko = 1.0
        else:
            ko = -1.0
        if other_action == 'cooperate' and action == 'defect':
            ko -= 0.5
        elif other_action == 'defect' and action == 'cooperate':
            ko += 0.5
        return ko

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.reputations.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = current + 0.1
        else:
            new_val = current - 0.15
        self.reputations[agent_id] = max(0.0, min(1.0, new_val))

        if agent_id in [self._ctx_opponent_id, self.agent_id]:
            pass

    def _update_interaction(self, other_id: int, action: str) -> None:
        if other_id not in self.interactions:
            self.interactions[other_id] = 0.5
        current = self.interactions[other_id]
        if action == 'cooperate':
            new_val = current * 0.9 + 0.1 * 1.0
        else:
            new_val = current * 0.9 + 0.1 * 0.0
        self.interactions[other_id] = new_val

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation rates per opponent
        self.coop_counts = {}
        self.total_counts = {}
        # Track recent defections (opponent_id -> round number)
        self.defection_history = {}
        # Track own actions per opponent
        self.my_actions = {}
        # Generation counter to implement forgiveness cycles
        self.generation = 0
        self.round_in_generation = 0
        # Current opponent
        self._ctx_opponent_id = None
        # Probability to forgive after a defection (starts moderate)
        self.forgiveness_prob = 0.15
        # Track overall cooperation tendency
        self.my_coop_total = 0
        self.my_actions_total = 0
        # NEW: Track reputation scores for third-party observations
        self.reputation = {}
        # NEW: Use a deque to store recent opponent actions for sliding window
        self.recent_opp_actions = {}  # opponent_id -> deque of actions

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        # Default: cooperate
        decision = True
        try:
            # Update round counter
            self.round_in_generation += 1
            if self.round_in_generation > 30:
                self.round_in_generation = 1
                self.generation += 1
                # Occasionally increase forgiveness over generations
                if self.generation % 5 == 0:
                    self.forgiveness_prob = min(0.4, self.forgiveness_prob + 0.05)

            # Retrieve history
            opp_coop = self.coop_counts.get(opponent, 0)
            opp_total = self.total_counts.get(opponent, 0)
            opp_defect = opp_total - opp_coop

            my_coop = self.my_actions.get(opponent, [True, True])  # default: cooperate
            # my_actions stores [coops, total] for this opponent
            my_coop_count = my_coop[0]
            my_total_count = my_coop[1]

            # If no history, cooperate
            if opp_total == 0:
                decision = True
            else:
                # Calculate opponent cooperation rate using sliding window if available
                if opponent in self.recent_opp_actions and len(self.recent_opp_actions[opponent]) > 0:
                    window_actions = self.recent_opp_actions[opponent]
                    coop_rate = sum(1 for a in window_actions if a == 'cooperate') / len(window_actions)
                else:
                    coop_rate = opp_coop / opp_total
                # Check recent defection (within last 2 rounds)
                recent_defect = False
                if opponent in self.defection_history:
                    if self.round_in_generation - self.defection_history[opponent] <= 2:
                        recent_defect = True

                # Strategy: Tit-for-tat with forgiveness and occasional probing
                if recent_defect:
                    # If they recently defected, sometimes forgive, else defect
                    if random.random() < self.forgiveness_prob:
                        decision = True
                    else:
                        decision = False
                else:
                    # If they've been cooperative, cooperate
                    if coop_rate >= 0.5:
                        decision = True
                    else:
                        # If they are generally uncooperative, defect unless we've never defected against them
                        if my_total_count == 0:
                            decision = True  # initial trust
                        else:
                            # If we've been cooperating and they haven't, defect
                            decision = False

                # Occasionally probe with defection to test if opponent is forgiving
                # Only when we have a long cooperative relationship and we haven't defected recently
                if opp_total >= 10 and coop_rate > 0.8 and my_total_count >= 5:
                    if random.random() < 0.05:  # 5% chance to probe
                        decision = False

            # NEW: Incorporate reputation into decision
            # If we have a reputation for this opponent and it's low, be more likely to defect
            if opponent in self.reputation:
                rep = self.reputation[opponent]
                if rep < -0.2 and decision:
                    # Slight chance to defect if reputation is bad
                    if random.random() < 0.15:
                        decision = False
                elif rep > 0.2 and not decision:
                    # Slight chance to cooperate if reputation is good
                    if random.random() < 0.1:
                        decision = True
        except Exception:
            decision = True
        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update self observations
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                # Determine opponent and their action
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action
                    opp_action = recipient_action
                else:
                    opponent = donor_id
                    my_action = recipient_action
                    opp_action = donor_action

                # Update my actions
                if opponent not in self.my_actions:
                    self.my_actions[opponent] = [0, 0]
                if my_action == 'cooperate':
                    self.my_actions[opponent][0] += 1
                self.my_actions[opponent][1] += 1
                self.my_coop_total += 1 if my_action == 'cooperate' else 0
                self.my_actions_total += 1

                # Update opponent's action counts
                if opponent not in self.coop_counts:
                    self.coop_counts[opponent] = 0
                    self.total_counts[opponent] = 0
                if opp_action == 'cooperate':
                    self.coop_counts[opponent] += 1
                self.total_counts[opponent] += 1

                # Track defection history
                if opp_action == 'defect':
                    self.defection_history[opponent] = self.round_in_generation

                # NEW: Update sliding window for opponent actions
                if opponent not in self.recent_opp_actions:
                    self.recent_opp_actions[opponent] = deque(maxlen=10)
                self.recent_opp_actions[opponent].append(opp_action)
            else:
                # Third-party observation: update opponent reputation
                # Only observe if we have interacted with either party before
                if donor_id in self.total_counts or recipient_id in self.total_counts:
                    # Update reputation for both parties based on their actions
                    for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                        if pid in self.total_counts:  # only track if we know them
                            if pid not in self.coop_counts:
                                self.coop_counts[pid] = 0
                            if action == 'cooperate':
                                self.coop_counts[pid] += 1
                            self.total_counts[pid] += 1
                            # NEW: Update reputation score
                            if pid not in self.reputation:
                                self.reputation[pid] = 0
                            # Cooperate increases reputation, defect decreases
                            if action == 'cooperate':
                                self.reputation[pid] += 0.1
                            else:
                                self.reputation[pid] -= 0.1
                            # Clamp reputation to [-1, 1]
                            self.reputation[pid] = max(-1.0, min(1.0, self.reputation[pid]))
        except Exception:
            pass

