        self.coop_entropy = {}
        self.entropy_window = 5
        self.entropy_bonus = 0.15
        self.entropy_penalty = 0.15
        # New mechanism: track opponent's generosity ratio (coop when they are donor)
        self.generosity = {}
        self.generosity_bonus = 0.2
