import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputations = {}
        self.interactions = {}
        self.my_actions = deque(maxlen=50)
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.alpha = 0.5
        self.beta = 0.5
        self.gamma = 0.3
        self.forgiveness = 0.05
        self.my_ko = 0.0
        self.partner_ko = {}
        self.last_actions = {}
        self.mood = 0.5
        self.mood_decay = 0.1

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.reputations.get(opponent, 0.5)
        exp = 0.5
        if opponent in self.interactions:
            exp = self.interactions[opponent]

        combined = self.alpha * rep + (1 - self.alpha) * exp

        # Incorporate mood: if mood is positive, more likely to cooperate
        combined = combined * (1 - self.mood_decay) + self.mood * self.mood_decay

        # Exploration
        if random.random() < 0.02:
            return random.random() < 0.5

        threshold = 0.55 - self.forgiveness * self.cooperation_count / max(1, self.cooperation_count + self.defection_count)

        # Add a "sucker" penalty: if opponent defected last time and I cooperated, lower threshold
        if opponent in self.last_actions:
            if self.last_actions[opponent] == 'defect' and self.my_actions and self.my_actions[-1] == 'cooperate':
                threshold += 0.1

        return combined >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round += 1

        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Track last actions of others
        if donor_id != self.agent_id:
            self.last_actions[donor_id] = donor_action
        if recipient_id != self.agent_id:
            self.last_actions[recipient_id] = recipient_action

        # If I'm involved, update personal memory and mood
        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            if donor_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            self.my_ko = self._calculate_ko(donor_id, donor_action, recipient_id, recipient_action)
            # Mood update: cooperating makes me happier, defecting makes me sadder
            if donor_action == 'cooperate':
                self.mood = min(1.0, self.mood + 0.1)
            else:
                self.mood = max(0.0, self.mood - 0.1)
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_action)
            if recipient_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            self.my_ko = self._calculate_ko(recipient_id, recipient_action, donor_id, donor_action)
            if recipient_action == 'cooperate':
                self.mood = min(1.0, self.mood + 0.1)
            else:
                self.mood = max(0.0, self.mood - 0.1)

        # Update partner Ko if I'm involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            partner_id = recipient_id if donor_id == self.agent_id else donor_id
            partner_action = recipient_action if donor_id == self.agent_id else donor_action
            self.partner_ko[partner_id] = self._calculate_ko(partner_id, partner_action, self.agent_id, donor_action if donor_id == self.agent_id else recipient_action)

        # Mood decays over time
        self.mood *= (1 - self.mood_decay)

        # Update interaction memory for third-party observations with a learning rate
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Learn from observing others: update reputation with a smaller step
            pass

    def _calculate_ko(self, agent_id, action, other_id, other_action):
        if action == 'cooperate':
            ko = 1.0
        else:
            ko = -1.0
        if other_action == 'cooperate' and action == 'defect':
            ko -= 0.5
        elif other_action == 'defect' and action == 'cooperate':
            ko += 0.5
        return ko

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.reputations.get(agent_id, 0.5)
        if action == 'cooperate':
            new_val = current + 0.1
        else:
            new_val = current - 0.15
        self.reputations[agent_id] = max(0.0, min(1.0, new_val))

        if agent_id in [self._ctx_opponent_id, self.agent_id]:
            pass

    def _update_interaction(self, other_id: int, action: str) -> None:
        if other_id not in self.interactions:
            self.interactions[other_id] = 0.5
        current = self.interactions[other_id]
        if action == 'cooperate':
            new_val = current * 0.9 + 0.1 * 1.0
        else:
            new_val = current * 0.9 + 0.1 * 0.0
        self.interactions[other_id] = new_val

