        exp = 0.5
        if opponent in self.interactions:
            exp = self.interactions[opponent]

        # Add a trust factor from recent observations of this opponent
        trust = self.trust_memory.get(opponent, 0.5)
        combined = self.alpha * rep + self.beta * exp + self.gamma * trust

        # Explore with small probability
        if random.random() < 0.02:
            return random.random() < 0.5

        threshold = 0.55 - self.forgiveness * self.cooperation_count / max(1, self.cooperation_count + self.defection_count)
        return combined >= threshold

