        if opponent in self.response_to_coop:
            response = self.response_to_coop[opponent]
            if response > 0.7:
                score += self.response_bonus
            elif response < 0.3:
                score -= self.response_penalty
        if opponent in self.temporal_history:
            hist = self.temporal_history[opponent]
            if len(hist) >= 2:
                weighted_sum = 0.0
                weight = 1.0
                total_weight = 0.0
                for action in hist:
                    if action == 'cooperate':
                        weighted_sum += weight
                    weight *= self.temporal_discount
                    total_weight += weight
                if total_weight > 0:
                    recent_ratio = weighted_sum / total_weight
                    if recent_ratio > 0.7:
                        score += self.temporal_bonus
                    elif recent_ratio < 0.3:
                        score -= self.temporal_penalty
        if opponent in self.coop_entropy:
            entropy = self.coop_entropy[opponent]
            if entropy < 0.5:
                score += self.entropy_bonus
            elif entropy > 1.5:
                score -= self.entropy_penalty
        if opponent in self.generosity:
            gen = self.generosity[opponent]
            if gen > 0.7:
                score += self.generosity_bonus * (gen - 0.7) * 2
            elif gen < 0.3:
                score -= self.generosity_penalty * (0.3 - gen) * 2
        # New mechanism: emotional memory adjustment
        if opponent in self.emotional_memory:
            emotion = self.emotional_memory[opponent]
            if emotion > 0.3:
                score += self.emotional_boost * emotion
            elif emotion < -0.3:
                score -= self.emotional_penalty * abs(emotion)
        # New mechanism: social influence adjustment
        if opponent in self.social_influence:
            social = self.social_influence[opponent]
            if social > 0.5:
                score += self.social_weight * social
        my_recent_coop = 0.5
        if len(self.my_history) > 0:
            my_recent_coop = sum(1 for a in self.my_history if a == 'cooperate') / len(self.my_history)
        reciprocity = 2 * my_recent_coop - 1
        score += self.reciprocity_bias * reciprocity
        if len(self.my_history) >= 5:
            recent_outcomes = self.my_history[-5:]
            coop_count = sum(1 for a in recent_outcomes if a == 'cooperate')
            if coop_count >= 4:
                self.base_cooperation_threshold = max(0.3, self.base_cooperation_threshold - self.adaptation_rate)
            elif coop_count <= 1:
                self.base_cooperation_threshold = min(0.7, self.base_cooperation_threshold + self.adaptation_rate)
        if opponent in self.pattern_memory and len(self.pattern_memory[opponent]) == self.pattern_length:
            pattern = self.pattern_memory[opponent]
            opp_forgiveness = self.opponent_forgiveness.get(opponent, self.forgiveness_base)
            if all(a == 'defect' for a in pattern):
                self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.1 * (1 - opp_forgiveness))
            elif all(a == 'cooperate' for a in pattern):
                self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.1 * (1 + opp_forgiveness))
        if opponent in self.betrayal_count and self.betrayal_count[opponent] >= self.betrayal_threshold:
            self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + self.betrayal_penalty * 0.5)
        if opponent in self.temporal_history:
            hist = self.temporal_history[opponent]
            if len(hist) >= 2:
                weighted_sum = 0.0
                weight = 1.0
                total_weight = 0.0
                for action in hist:
                    if action == 'cooperate':
                        weighted_sum += weight
                    weight *= self.temporal_discount
                    total_weight += weight
                if total_weight > 0:
                    recent_ratio = weighted_sum / total_weight
                    if recent_ratio > 0.7:
                        self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.05)
                    elif recent_ratio < 0.3:
                        self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.05)
        if opponent in self.generosity:
            gen = self.generosity[opponent]
            if gen > 0.7:
                self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.05)
            elif gen < 0.3:
                self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.05)
        if opponent in self.opponent_forgiveness_level:
            opp_forgiveness = self.opponent_forgiveness_level[opponent]
            self.base_cooperation_threshold = max(0.2, min(0.8, self.base_cooperation_threshold - (opp_forgiveness - 0.5) * 0.2))
        # New mechanism: emotional memory threshold adjustment
        if opponent in self.emotional_memory:
            emotion = self.emotional_memory[opponent]
            if emotion > 0.3:
                self.base_cooperation_threshold = max(0.2, self.base_cooperation_threshold - 0.03)
            elif emotion < -0.3:
                self.base_cooperation_threshold = min(0.8, self.base_cooperation_threshold + 0.03)
        # New mechanism: risk tolerance adjustment
        risk_tol = self.risk_tolerance.get(opponent, self.risk_base)
        threshold = self.base_cooperation_threshold - risk_tol
        if score >= threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            old_rep = self.reputation.get(donor_id, 0.5)
            if donor_action == 'cooperate':
                new_rep = old_rep * 0.85 + 0.15
            else:
                new_rep = old_rep * 0.85
            self.reputation[donor_id] = new_rep
            if donor_id not in self.reputation_volatility:
                self.reputation_volatility[donor_id] = 0.0
            self.reputation_volatility[donor_id] = self.volatility_decay * self.reputation_volatility[donor_id] + abs(new_rep - old_rep)
            if donor_id not in self.reputation_history:
                self.reputation_history[donor_id] = []
            self.reputation_history[donor_id].append(new_rep)
            if len(self.reputation_history[donor_id]) > self.trend_window:
                self.reputation_history[donor_id].pop(0)
            if donor_id in self.last_reputation:
                self.reputation_shift[donor_id] = new_rep - self.last_reputation[donor_id]
            self.last_reputation[donor_id] = new_rep

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round_num = 0
        self.generation = 0
        self._ctx_opponent_id = None

        # Reputation tracking: opponent_id -> (cooperate_count, defect_count, observations)
        self.reputation = {}

        # Personal interaction history: opponent_id -> deque of (my_action, their_action)
        self.interaction_history = {}

        # Cooperation probability per opponent based on reputation and history
        self.coop_prob = {}

        # Track own recent actions for adaptive behavior
        self.my_recent_actions = deque(maxlen=30)

        # Track overall trust level and cooperation propensity
        self.trust_level = 0.5
        self.cooperation_propensity = 0.5

        # New mechanism: forgiveness factor - how quickly we forgive past defections
        self.forgiveness = 0.3  # 0 = never forgive, 1 = instant forgiveness

        # Track number of times each opponent has defected against us recently
        self.defection_count = {}

        # Track whether we've been exploited recently (global to catch patterns)
        self.recent_exploitation = deque(maxlen=10)

        # New mechanism: social learning rate - how much we weight third-party observations
        self.social_learning_rate = 0.15  # Lower than parent's implicit 0.1 for trust updates

        # New mechanism: reputation volatility - track how much each agent's reputation fluctuates
        self.reputation_volatility = {}  # opponent_id -> deque of recent reputation scores

        # New mechanism: adaptive forgiveness based on own cooperation rate
        self.base_forgiveness = 0.3
        self.forgiveness = 0.3

        # New mechanism: memory decay factor for interaction history
        self.memory_decay = 0.95  # How much older interactions are weighted

        # New mechanism: track how often we've been the donor vs recipient
        self.donor_count = 0
        self.recipient_count = 0

        # NEW: Opponent-specific trust scores
        self.opponent_trust = {}  # opponent_id -> dynamic trust value

        # NEW: Contagion factor - how much we trust an opponent based on how much we trust their frequent partners
        self.contagion_factor = 0.2  # Weight of network-based trust

        # NEW: Track partner frequency for network analysis
        self.partner_frequency = {}  # opponent_id -> count of interactions

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Base probability from trust and propensity
        base_prob = 0.5 * self.trust_level + 0.3 * self.cooperation_propensity

        # Add opponent-specific trust if available
        if opponent in self.opponent_trust:
            base_prob += 0.2 * (self.opponent_trust[opponent] - 0.5)

        # Adjust based on opponent reputation if known
        if opponent in self.reputation:
            coop, defect, obs = self.reputation[opponent]
            total = coop + defect
            if total > 0:
                rep_score = coop / total
                # Weight reputation with forgiveness factor
                effective_rep = rep_score * self.forgiveness + (1 - self.forgiveness) * rep_score
                # More nuanced threshold adjustments
                if effective_rep < 0.3:
                    base_prob -= 0.35
                elif effective_rep < 0.5:
                    base_prob -= 0.2
                elif effective_rep > 0.7:
                    base_prob += 0.25
                else:
                    base_prob += 0.1

                # New mechanism: volatility penalty - if reputation is unstable, be more cautious
                if opponent in self.reputation_volatility and len(self.reputation_volatility[opponent]) >= 3:
                    scores = list(self.reputation_volatility[opponent])
                    volatility = max(scores) - min(scores)
                    if volatility > 0.4:  # High volatility
                        base_prob -= 0.15
                    elif volatility > 0.2:
                        base_prob -= 0.05

        # Adjust based on personal interaction history
        if opponent in self.interaction_history:
            history = self.interaction_history[opponent]
            if len(history) >= 3:
                # Apply memory decay: weight recent interactions more
                recent = list(history)[-3:]
                weights = [self.memory_decay ** i for i in range(len(recent)-1, -1, -1)]
                total_weight = sum(weights)
                their_coop_weighted = sum(w * (1 if their == 'cooperate' else 0) for w, (_, their) in zip(weights, recent)) / total_weight
                my_coop_weighted = sum(w * (1 if my == 'cooperate' else 0) for w, (my, _) in zip(weights, recent)) / total_weight
                # Stricter punishment for recent defections
                if their_coop_weighted < 0.2 and len(recent) >= 2:
                    base_prob -= 0.5  # Stronger punishment
                elif their_coop_weighted < 0.5:
                    base_prob -= 0.1  # Moderate punishment for mixed
                elif their_coop_weighted >= 0.7:
                    base_prob += 0.2
                if my_coop_weighted < 0.2 and len(recent) >= 2:
                    base_prob -= 0.15  # More self-punishment to encourage switching

        # New: punishment for repeated defections against us
        if opponent in self.defection_count:
            defections = self.defection_count[opponent]
            if defections >= 3:
                base_prob -= 0.2
            elif defections >= 2:
                base_prob -= 0.1

        # NEW: Contagion mechanism - if we have high trust in frequent partners of this opponent, boost trust
        if opponent in self.partner_frequency and self.partner_frequency[opponent] > 0:
            # Find agents we've seen interact with this opponent and have high trust in
            for other_id, trust in self.opponent_trust.items():
                if other_id != opponent and trust > 0.7:
                    # Check if we've seen this other agent interact with opponent
                    if other_id in self.interaction_history and opponent in self.interaction_history:
                        # Simple heuristic: if we trust other highly, assume some positive association
                        base_prob += self.contagion_factor * (trust - 0.5)
                        break

        # Add random noise for exploration
        prob = max(0.05, min(0.95, base_prob + random.uniform(-0.05, 0.05)))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track round and generation info (approximate)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1
            if self.round_num % 30 == 0:
                self.generation += 1
                self.round_num = 0
                # Decay old reputation slightly each generation
                for opp in list(self.reputation.keys()):
                    coop, defect, obs = self.reputation[opp]
                    self.reputation[opp] = (coop * 0.9, defect * 0.9, obs * 0.9)
                # Update propensity based on recent actions
                if len(self.my_recent_actions) > 0:
                    coop_rate = sum(1 for a in self.my_recent_actions if a) / len(self.my_recent_actions)
                    self.cooperation_propensity = 0.8 * self.cooperation_propensity + 0.2 * coop_rate
                    # Adaptive forgiveness: if we cooperate a lot, become more forgiving; if we defect a lot, be less forgiving
                    self.forgiveness = max(0.1, min(0.9, self.base_forgiveness + (coop_rate - 0.5) * 0.4))
                # Decay defection counts each generation (forgiveness mechanism)
                for opp in list(self.defection_count.keys()):
                    self.defection_count[opp] = max(0, self.defection_count[opp] - 1)
                # Decay recent exploitation
                self.recent_exploitation.clear()
                # Decay reputation volatility records
                for opp in list(self.reputation_volatility.keys()):
                    if len(self.reputation_volatility[opp]) > 0:
                        # Keep only recent volatility data
                        self.reputation_volatility[opp] = deque(list(self.reputation_volatility[opp])[-5:], maxlen=10)
                # NEW: Decay opponent-specific trust slightly
                for opp in list(self.opponent_trust.keys()):
                    self.opponent_trust[opp] = self.opponent_trust[opp] * 0.9 + 0.05  # Drift toward neutral
                # NEW: Decay partner frequency
                for opp in list(self.partner_frequency.keys()):
                    self.partner_frequency[opp] = max(0, self.partner_frequency[opp] - 1)

        # Update reputation for all observed interactions
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation
            if donor_id not in self.reputation:
                self.reputation[donor_id] = [0, 0, 0]
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = [0, 0, 0]

            if donor_action == 'cooperate':
                self.reputation[donor_id][0] += 1
            else:
                self.reputation[donor_id][1] += 1
            self.reputation[donor_id][2] += 1

            if recipient_action == 'cooperate':
                self.reputation[recipient_id][0] += 1
            else:
                self.reputation[recipient_id][1] += 1
            self.reputation[recipient_id][2] += 1

            # Update trust based on observed cooperation
            total_coop = self.reputation[donor_id][0] + self.reputation[recipient_id][0]
            total_obs = self.reputation[donor_id][2] + self.reputation[recipient_id][2]
            if total_obs > 0:
                # Modified: use social_learning_rate instead of fixed 0.1
                self.trust_level = (1 - self.social_learning_rate) * self.trust_level + self.social_learning_rate * (total_coop / total_obs)

            # New mechanism: update reputation volatility for observed agents
            for agent in [donor_id, recipient_id]:
                if agent not in self.reputation_volatility:
                    self.reputation_volatility[agent] = deque(maxlen=10)
                coop, defect, obs = self.reputation[agent]
                if obs > 0:
                    current_score = coop / obs
                    self.reputation_volatility[agent].append(current_score)

            # NEW: Update opponent-specific trust based on observed behavior
            # If donor cooperates, increase trust in donor; if defects, decrease
            for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent not in self.opponent_trust:
                    self.opponent_trust[agent] = 0.5
                if action == 'cooperate':
                    self.opponent_trust[agent] = min(1.0, self.opponent_trust[agent] + 0.05)
                else:
                    self.opponent_trust[agent] = max(0.0, self.opponent_trust[agent] - 0.1)

            # NEW: Track partner frequency (who interacts with whom)
            if donor_id not in self.partner_frequency:
                self.partner_frequency[donor_id] = 0
            if recipient_id not in self.partner_frequency:
                self.partner_frequency[recipient_id] = 0
            self.partner_frequency[donor_id] += 1
            self.partner_frequency[recipient_id] += 1

        # Update personal interaction history if we're involved
        if donor_id == self.agent_id:
            # We are donor
            self.donor_count += 1
            if recipient_id not in self.interaction_history:
                self.interaction_history[recipient_id] = deque(maxlen=10)
            self.interaction_history[recipient_id].append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.my_recent_actions.append(donor_action == 'cooperate')
            # NEW: Update opponent-specific trust based on our own action
            if recipient_id not in self.opponent_trust:
                self.opponent_trust[recipient_id] = 0.5
            if recipient_action == 'cooperate':
                self.opponent_trust[recipient_id] = min(1.0, self.opponent_trust[recipient_id] + 0.1)
            else:
                self.opponent_trust[recipient_id] = max(0.0, self.opponent_trust[recipient_id] - 0.2)
            # Track partner frequency
            if recipient_id not in self.partner_frequency:
                self.partner_frequency[recipient_id] = 0
            self.partner_frequency[recipient_id] += 1
        elif recipient_id == self.agent_id:
            # We are recipient
            self.recipient_count += 1
            if donor_id not in self.interaction_history:
                self.interaction_history[donor_id] = deque(maxlen=10)
            self.interaction_history[donor_id].append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.my_recent_actions.append(recipient_action == 'cooperate')
            # Track defections against us
            if donor_action == 'defect':
                if donor_id not in self.defection_count:
                    self.defection_count[donor_id] = 0
                self.defection_count[donor_id] += 1
                self.recent_exploitation.append(True)
            else:
                self.recent_exploitation.append(False)
            # NEW: Update opponent-specific trust based on their action toward us
            if donor_id not in self.opponent_trust:
                self.opponent_trust[donor_id] = 0.5
            if donor_action == 'cooperate':
                self.opponent_trust[donor_id] = min(1.0, self.opponent_trust[donor_id] + 0.15)
            else:
                self.opponent_trust[donor_id] = max(0.0, self.opponent_trust[donor_id] - 0.3)
            # Track partner frequency
            if donor_id not in self.partner_frequency:
                self.partner_frequency[donor_id] = 0
            self.partner_frequency[donor_id] += 1

        # Update trust level with direct interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            their_action = recipient_action if donor_id == self.agent_id else donor_action
            if my_action == 'cooperate' and their_action == 'cooperate':
                self.trust_level = min(1.0, self.trust_level + 0.1)
            elif my_action == 'defect' and their_action == 'defect':
                self.trust_level = max(0.0, self.trust_level - 0.05)
            elif their_action == 'defect':
                self.trust_level = max(0.0, self.trust_level - 0.15)
                # If we've been exploited a lot recently, become more cautious
                if sum(self.recent_exploitation) >= 3:
                    self.trust_level = max(0.0, self.trust_level - 0.1)

