        self.learning_rate = 0.2

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # If in tit-for-tat mode, mimic their last action
        if self.tit_for_tat_mode and opponent in self.last_their_action:
            if self.last_their_action[opponent] == 'defect':
                return False
            else:
                return True

        # NEW: Exploration - occasionally try a different action to gather info
        if random.random() < self.exploration_rate:
            # Explore: flip our usual decision tendency
            return random.random() < 0.5

        # Base probability from trust and propensity
        base_prob = 0.5 * self.trust_level + 0.3 * self.cooperation_propensity

        # Add opponent-specific trust if available
        if opponent in self.opponent_trust:
            base_prob += 0.2 * (self.opponent_trust[opponent] - 0.5)

        # Adjust based on opponent reputation if known
