        if opponent in self.defection_count:
            defections = self.defection_count[opponent]
            if defections >= 3:
                base_prob -= 0.2
            elif defections >= 2:
                base_prob -= 0.1

        # Contagion mechanism
        if opponent in self.partner_frequency and self.partner_frequency[opponent] > 0:
            for other_id, trust in self.opponent_trust.items():
                if other_id != opponent and trust > 0.7:
                    if other_id in self.interaction_history and opponent in self.interaction_history:
                        base_prob += self.contagion_factor * (trust - 0.5)
                        break

        # Self-perception adjustment
        if self.self_reputation < 0.3:
            base_prob -= 0.1

        # Reputation asymmetry adjustment
        if opponent in self.reputation_donor and opponent in self.reputation_recipient:
            donor_coop, donor_defect = self.reputation_donor[opponent]
            rec_coop, rec_defect = self.reputation_recipient[opponent]
            donor_total = donor_coop + donor_defect
            rec_total = rec_coop + rec_defect
            if donor_total > 0 and rec_total > 0:
                donor_rate = donor_coop / donor_total
                rec_rate = rec_coop / rec_total
                if donor_rate > 0.7 and rec_rate < 0.3:
