            if opponent not in self.reputation:
                self.reputation[opponent] = 0.5
            if opponent not in self.partner_history:
                self.partner_history[opponent] = []

            # Simple strategy: cooperate if opponent's reputation is decent
            # and we haven't had too many defections with them recently
            rep = self.reputation.get(opponent, 0.5)
            if rep >= 0.6:
                return True
            elif rep >= 0.4:
                # Check recent interactions
                recent = self.partner_history.get(opponent, [])[-3:]
                if recent.count(False) <= 1:
                    return True
                else:
                    return False
            else:
                # Low reputation, defect
                return False
        except Exception:
            return True

    def observe(
        self,
        donor_id: int,
