        self.trust_level = 0.5
        self.cooperation_propensity = 0.5

        # New mechanism: forgiveness factor - how quickly we forgive past defections
        self.forgiveness = 0.3  # 0 = never forgive, 1 = instant forgiveness

        # Track number of times each opponent has defected against us recently
        self.defection_count = {}

        # Track whether we've been exploited recently (global to catch patterns)
        self.recent_exploitation = deque(maxlen=10)

        # New mechanism: social learning rate - how much we weight third-party observations
        self.social_learning_rate = 0.15

        # New mechanism: reputation volatility - track how much each agent's reputation fluctuates
        self.reputation_volatility = {}

        # New mechanism: adaptive forgiveness based on own cooperation rate
        self.base_forgiveness = 0.3
        self.forgiveness = 0.3

        # New mechanism: memory decay factor for interaction history
        self.memory_decay = 0.95

        # New mechanism: track how often we've been the donor vs recipient
        self.donor_count = 0
        self.recipient_count = 0

        # NEW: Opponent-specific trust scores
        self.opponent_trust = {}

        # NEW: Contagion factor - how much we trust an opponent based on how much we trust their frequent partners
        self.contagion_factor = 0.2

        # NEW: Track partner frequency for network analysis
        self.partner_frequency = {}

        # NEW: Track our own reputation as observed by others (self-perception)
        self.self_reputation = 0.5

        # NEW: Reciprocity threshold - how much we require mutual cooperation before trusting
        self.reciprocity_threshold = 0.6

        # NEW: Strategy switch - if we've been exploited heavily, switch to tit-for-tat for a few rounds
        self.tit_for_tat_mode = False
        self.tit_for_tat_rounds_left = 0

        # NEW: Track last action against each opponent for tit-for-tat
        self.last_their_action = {}

        # NEW: Exploration rate - probability of random action regardless of computed probability
        self.exploration_rate = 0.1

        # NEW: Reputation threshold for cooperation - stricter than parent
        self.cooperation_threshold = 0.5

        # NEW: Pessimism bias - how strongly we weigh negative observations vs positive
        self.pessimism_bias = 0.3  # 0 = symmetric, 1 = only negative matters

        # NEW: Suspicion accumulation - if an opponent defects, we remember for longer
        self.suspicion_memory = {}  # opponent_id -> accumulated suspicion score

        # NEW: Max suspicion threshold - above this, we always defect
        self.max_suspicion = 5.0

        # NEW: Restoration rate - how quickly suspicion decays when opponent cooperates
        self.restoration_rate = 0.2

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # If in tit-for-tat mode, mimic their last action
        if self.tit_for_tat_mode and opponent in self.last_their_action:
            if self.last_their_action[opponent] == 'defect':
                return False
            else:
                return True

        # Base probability from trust and propensity
        base_prob = 0.5 * self.trust_level + 0.3 * self.cooperation_propensity

        # Add opponent-specific trust if available
        if opponent in self.opponent_trust:
            base_prob += 0.2 * (self.opponent_trust[opponent] - 0.5)

        # Adjust based on opponent reputation if known
        if opponent in self.reputation:
            coop, defect, obs = self.reputation[opponent]
            total = coop + defect
            if total > 0:
                rep_score = coop / total
                # Weight reputation with forgiveness factor
                effective_rep = rep_score * self.forgiveness + (1 - self.forgiveness) * rep_score
                # Stricter threshold: only cooperate if reputation is above threshold
                if effective_rep < self.cooperation_threshold:
                    base_prob -= 0.45
                elif effective_rep > 0.7:
                    base_prob += 0.25
                else:
                    base_prob += 0.1

                # New mechanism: volatility penalty - if reputation is unstable, be more cautious
                if opponent in self.reputation_volatility and len(self.reputation_volatility[opponent]) >= 3:
                    scores = list(self.reputation_volatility[opponent])
                    volatility = max(scores) - min(scores)
                    if volatility > 0.4:
                        base_prob -= 0.15
                    elif volatility > 0.2:
                        base_prob -= 0.05

        # NEW: Suspicion override - if suspicion is very high, always defect
        if opponent in self.suspicion_memory:
            suspicion = self.suspicion_memory[opponent]
            if suspicion >= self.max_suspicion:
                return False
            elif suspicion > 2.0:
                base_prob -= 0.3
            elif suspicion > 1.0:
                base_prob -= 0.15

        # Adjust based on personal interaction history
        if opponent in self.interaction_history:
            history = self.interaction_history[opponent]
            if len(history) >= 3:
                # Apply memory decay: weight recent interactions more
                recent = list(history)[-3:]
                weights = [self.memory_decay ** i for i in range(len(recent)-1, -1, -1)]
                total_weight = sum(weights)
                their_coop_weighted = sum(w * (1 if their == 'cooperate' else 0) for w, (_, their) in zip(weights, recent)) / total_weight
                my_coop_weighted = sum(w * (1 if my == 'cooperate' else 0) for w, (my, _) in zip(weights, recent)) / total_weight
                # Stricter punishment for recent defections
                if their_coop_weighted < 0.2 and len(recent) >= 2:
                    base_prob -= 0.5
                elif their_coop_weighted < 0.5:
                    base_prob -= 0.1
                elif their_coop_weighted >= 0.7:
                    base_prob += 0.2
                if my_coop_weighted < 0.2 and len(recent) >= 2:
                    base_prob -= 0.15

                # NEW: Reciprocity check - if we cooperate but they defect often, punish more
                if len(recent) >= 5:
                    my_coop = sum(1 for my, _ in recent if my)
                    their_coop = sum(1 for _, their in recent if their)
                    if my_coop > 0 and their_coop / len(recent) < self.reciprocity_threshold:
                        base_prob -= 0.1

        # New: punishment for repeated defections against us
        if opponent in self.defection_count:
            defections = self.defection_count[opponent]
            if defections >= 3:
                base_prob -= 0.2
            elif defections >= 2:
                base_prob -= 0.1

        # NEW: Contagion mechanism - if we have high trust in frequent partners of this opponent, boost trust
        if opponent in self.partner_frequency and self.partner_frequency[opponent] > 0:
            for other_id, trust in self.opponent_trust.items():
                if other_id != opponent and trust > 0.7:
                    if other_id in self.interaction_history and opponent in self.interaction_history:
                        base_prob += self.contagion_factor * (trust - 0.5)
                        break

        # NEW: Self-perception adjustment - if we think others see us as untrustworthy, be more cautious
        if self.self_reputation < 0.3:
            base_prob -= 0.1

        # NEW: Exploration - occasionally act randomly to discover new strategies
        if random.random() < self.exploration_rate:
            return random.random() < 0.5

        # Add random noise for exploration
        prob = max(0.05, min(0.95, base_prob + random.uniform(-0.05, 0.05)))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track round and generation info (approximate)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1
            if self.round_num % 30 == 0:
                self.generation += 1
                self.round_num = 0
                # Decay old reputation slightly each generation
                for opp in list(self.reputation.keys()):
                    coop, defect, obs = self.reputation[opp]
                    self.reputation[opp] = (coop * 0.9, defect * 0.9, obs * 0.9)
                # Update propensity based on recent actions
                if len(self.my_recent_actions) > 0:
                    coop_rate = sum(1 for a in self.my_recent_actions if a) / len(self.my_recent_actions)
                    self.cooperation_propensity = 0.8 * self.cooperation_propensity + 0.2 * coop_rate
                    # Adaptive forgiveness: if we cooperate a lot, become more forgiving; if we defect a lot, be less forgiving
                    self.forgiveness = max(0.1, min(0.9, self.base_forgiveness + (coop_rate - 0.5) * 0.4))
                # Decay defection counts each generation (forgiveness mechanism)
                for opp in list(self.defection_count.keys()):
                    self.defection_count[opp] = max(0, self.defection_count[opp] - 1)
                # Decay recent exploitation
                self.recent_exploitation.clear()
                # Decay reputation volatility records
                for opp in list(self.reputation_volatility.keys()):
                    if len(self.reputation_volatility[opp]) > 0:
                        self.reputation_volatility[opp] = deque(list(self.reputation_volatility[opp])[-5:], maxlen=10)
                # NEW: Decay opponent-specific trust slightly
                for opp in list(self.opponent_trust.keys()):
                    self.opponent_trust[opp] = self.opponent_trust[opp] * 0.9 + 0.05
                # NEW: Decay partner frequency
                for opp in list(self.partner_frequency.keys()):
                    self.partner_frequency[opp] = max(0, self.partner_frequency[opp] - 1)
                # NEW: Decay self-reputation
                self.self_reputation = self.self_reputation * 0.9 + 0.05
                # NEW: Update tit-for-tat mode
                if self.tit_for_tat_rounds_left > 0:
                    self.tit_for_tat_rounds_left -= 1
                    if self.tit_for_tat_rounds_left == 0:
                        self.tit_for_tat_mode = False
                # NEW: Adjust exploration rate based on success - more exploration early, less later
                self.exploration_rate = max(0.02, 0.1 * (1 - self.generation / 30))
                # NEW: Decay suspicion memory each generation (slow decay)
                for opp in list(self.suspicion_memory.keys()):
                    self.suspicion_memory[opp] *= 0.8
                    if self.suspicion_memory[opp] < 0.1:
                        del self.suspicion_memory[opp]

        # Update reputation for all observed interactions
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation
            if donor_id not in self.reputation:
                self.reputation[donor_id] = [0, 0, 0]
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = [0, 0, 0]

            if donor_action == 'cooperate':
                self.reputation[donor_id][0] += 1
            else:
                self.reputation[donor_id][1] += 1
            self.reputation[donor_id][2] += 1

            if recipient_action == 'cooperate':
                self.reputation[recipient_id][0] += 1
            else:
                self.reputation[recipient_id][1] += 1
            self.reputation[recipient_id][2] += 1

            # Update trust based on observed cooperation
            total_coop = self.reputation[donor_id][0] + self.reputation[recipient_id][0]
            total_obs = self.reputation[donor_id][2] + self.reputation[recipient_id][2]
            if total_obs > 0:
                # Modified: use social_learning_rate instead of fixed 0.1
                self.trust_level = (1 - self.social_learning_rate) * self.trust_level + self.social_learning_rate * (total_coop / total_obs)

            # New mechanism: update reputation volatility for observed agents
            for agent in [donor_id, recipient_id]:
                if agent not in self.reputation_volatility:
                    self.reputation_volatility[agent] = deque(maxlen=10)
                coop, defect, obs = self.reputation[agent]
                if obs > 0:
                    current_score = coop / obs
                    self.reputation_volatility[agent].append(current_score)

            # NEW: Update opponent-specific trust based on observed behavior with pessimism bias
            for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent not in self.opponent_trust:
                    self.opponent_trust[agent] = 0.5
                if action == 'cooperate':
                    # Positive observation has less weight due to pessimism
                    self.opponent_trust[agent] = min(1.0, self.opponent_trust[agent] + 0.05 * (1 - self.pessimism_bias))
                else:
                    # Negative observation gets extra weight
                    self.opponent_trust[agent] = max(0.0, self.opponent_trust[agent] - 0.1 * (1 + self.pessimism_bias))

            # NEW: Track partner frequency (who interacts with whom)
            if donor_id not in self.partner_frequency:
                self.partner_frequency[donor_id] = 0
            if recipient_id not in self.partner_frequency:
                self.partner_frequency[recipient_id] = 0
            self.partner_frequency[donor_id] += 1
            self.partner_frequency[recipient_id] += 1

            # NEW: Update suspicion for observed defections (third-party)
            for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if action == 'defect':
                    if agent not in self.suspicion_memory:
                        self.suspicion_memory[agent] = 0.0
                    self.suspicion_memory[agent] += 0.3  # Third-party observations carry less weight

        # Update personal interaction history if we're involved
        if donor_id == self.agent_id:
            # We are donor
            self.donor_count += 1
            if recipient_id not in self.interaction_history:
                self.interaction_history[recipient_id] = deque(maxlen=10)
            self.interaction_history[recipient_id].append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.my_recent_actions.append(donor_action == 'cooperate')
            # NEW: Update opponent-specific trust based on our own action
            if recipient_id not in self.opponent_trust:
                self.opponent_trust[recipient_id] = 0.5
            if recipient_action == 'cooperate':
                self.opponent_trust[recipient_id] = min(1.0, self.opponent_trust[recipient_id] + 0.1)
                # NEW: Cooperation reduces suspicion
                if recipient_id in self.suspicion_memory:
                    self.suspicion_memory[recipient_id] = max(0.0, self.suspicion_memory[recipient_id] - self.restoration_rate)
            else:
                self.opponent_trust[recipient_id] = max(0.0, self.opponent_trust[recipient_id] - 0.2)
                # NEW: Defection increases suspicion strongly
                if recipient_id not in self.suspicion_memory:
                    self.suspicion_memory[recipient_id] = 0.0

import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.observation_count = {}
        self.history_with_opponent = {}
        self.global_coop_rate = 0.5
        self.total_observations = 0
        self.rounds_played = 0
        self.randomizer = random.Random(agent_id * 7 + 13)
        # New: track a sliding window of recent action outcomes per opponent
        self.recent_outcomes = {}
        self.window_size = 5

    def _get_reputation(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, 0.0)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        self.observation_count[agent_id] = self.observation_count.get(agent_id, 0) + 1
        delta = 1.0 if action == "cooperate" else -1.0
        current = self.reputation.get(agent_id, 0.0)
        # Use a faster learning rate initially, then slower but not as fast decay
        alpha = 1.0 / (1.0 + math.sqrt(self.observation_count[agent_id]))
        new_rep = current * (1 - alpha) + delta * alpha
        self.reputation[agent_id] = max(-1.0, min(1.0, new_rep))

    def decide(self) -> bool:
        opponent_id = getattr(self, "_ctx_opponent_id", None)
        self.rounds_played += 1

        if opponent_id is None:
            return True

        opp_rep = self._get_reputation(opponent_id)

        # Add a momentum term based on recent outcomes with this opponent
        if opponent_id in self.recent_outcomes:
            outcomes = self.recent_outcomes[opponent_id]
            if len(outcomes) > 0:
                # Momentum: if mostly cooperative recently, boost rep; if defector, penalize
                coop_ratio = sum(1 for o in outcomes if o) / len(outcomes)
                # Stronger effect when we have more data
                momentum = (coop_ratio - 0.5) * 0.3 * min(1.0, len(outcomes) / self.window_size)
                opp_rep += momentum

        # Also adjust based on global cooperation rate (similar to parent)
        global_bias = (self.global_coop_rate - 0.5) * 0.2

        score = opp_rep + global_bias

        # Decision threshold: slightly more lenient than parent (-0.05 instead of -0.1)
        base_cooperate = score >= -0.05

        # Exploration: different schedule - more initial exploration, then decay
        if self.rounds_played < 15:
            if self.randomizer.random() < 0.15:
                return not base_cooperate
        elif self.rounds_played < 60:
            if self.randomizer.random() < 0.05:
                return not base_cooperate
        else:
            if self.randomizer.random() < 0.02:
                return not base_cooperate

        return base_cooperate

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Update recent outcomes for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                self.recent_outcomes.setdefault(agent_id, deque(maxlen=self.window_size))
                self.recent_outcomes[agent_id].append(action == "cooperate")

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opp_id = recipient_id if donor_id == self.agent_id else donor_id
            our_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            key = (self.agent_id, opp_id)
            self.history_with_opponent.setdefault(key, []).append(
                (our_action == "cooperate", opp_action == "cooperate")
            )
            if len(self.history_with_opponent[key]) > 20:
                self.history_with_opponent[key] = self.history_with_opponent[key][-20:]

        self.total_observations += 1
        coop_count = (1 if donor_action == "cooperate" else 0) + (1 if recipient_action == "cooperate" else 0)
        self.global_coop_rate = self.global_coop_rate * 0.99 + (coop_count / 2.0) * 0.01
